insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-001', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'la-pression--le-poids-de-leau-au-dessus-de-vous', 'En descendant sous l''eau, de combien la pression augmente-t-elle environ tous les 10 mètres ?', 'L''eau est environ 800 fois plus dense que l''air : il suffit de descendre 10 mètres pour que la colonne d''eau ajoute 1 bar de pression. C''est la règle d''or de toute la physique de la plongée. Les réponses 0,1 bar et 10 bars correspondent à des erreurs d''un facteur 10, et 2 bars serait la valeur pour 20 mètres, pas pour 10.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-001', 'a', '0,1 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-001', 'b', '1 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-001', 'c', '10 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-001', 'd', '2 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-002', 'n1-flottabilite-pression', 'n1', 'physique', 'calcul', 'pression-atmosphérique-relative-et-absolue', 'Quelle est la pression absolue subie par un plongeur à 20 m de profondeur en mer ?', 'La pression absolue est la somme de la pression atmosphérique (1 bar) et de la pression relative due à l''eau (1 bar tous les 10 m, soit 2 bars à 20 m) : $P_{abs} = 1 + 20/10 = 3$ bars. Répondre 2 bars est l''erreur classique qui consiste à oublier le bar atmosphérique ; 20 bars confond profondeur et pression, et 1 bar est la pression en surface.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-002', 'a', '2 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-002', 'b', '3 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-002', 'c', '20 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-002', 'd', '1 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-003', 'n1-flottabilite-pression', 'n1', 'physique', 'calcul', 'pression-atmosphérique-relative-et-absolue', 'À 15 m de profondeur, quelle est la pression absolue ?', 'La pression relative à 15 m vaut $15/10 = 1{,}5$ bar ; en ajoutant la pression atmosphérique de 1 bar, on obtient $P_{abs} = 1 + 1{,}5 = 2{,}5$ bars. La réponse 1,5 bar oublie l''atmosphère, 2 bars correspondrait à 10 m et 3 bars à 20 m : la formule fonctionne aussi pour les profondeurs intermédiaires.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-003', 'a', '1,5 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-003', 'b', '2 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-003', 'c', '2,5 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-003', 'd', '3 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-004', 'n1-flottabilite-pression', 'n1', 'physique', 'calcul', 'pression-atmosphérique-relative-et-absolue', 'Quelle est la pression relative (hydrostatique) exercée par l''eau seule sur un plongeur à 30 m ?', 'La pression relative est le poids de la seule colonne d''eau : $P_{rel} = 30/10 = 3$ bars. La réponse 4 bars est la pression absolue (3 + 1 bar d''atmosphère), qu''il ne faut pas confondre avec la pression relative demandée ici ; 30 bars confond mètres et bars.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-004', 'a', '3 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-004', 'b', '4 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-004', 'c', '30 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-004', 'd', '1 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-005', 'n1-flottabilite-pression', 'n1', 'physique', 'vrai-faux', 'pression-atmosphérique-relative-et-absolue', 'Entre la surface et 10 m de profondeur, la pression absolue double.', 'C''est vrai : la pression absolue passe de 1 bar en surface à 2 bars à 10 m, soit une augmentation de 100 %. Aucune autre tranche de 10 m ne produit une variation relative aussi forte (de 30 à 40 m, la pression ne gagne que 25 %) : c''est pourquoi la zone proche de la surface est celle où le corps est le plus sollicité.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-005', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-005', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-006', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'pression-atmosphérique-relative-et-absolue', 'Dans quelle zone les variations **relatives** de pression sont-elles les plus fortes ?', 'Entre 0 et 10 m, la pression absolue double (de 1 à 2 bars, +100 %), alors qu''en profondeur chaque tranche de 10 m représente une part de plus en plus faible de la pression totale. Les volumes d''air varient donc le plus vite près de la surface : c''est là que surviennent la plupart des barotraumatismes, et non en grande profondeur comme on pourrait l''imaginer intuitivement.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-006', 'a', 'Près de la surface (0 à 10 m)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-006', 'b', 'Entre 20 et 30 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-006', 'c', 'Au-delà de 40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-006', 'd', 'Elles sont identiques à toutes les profondeurs', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-007', 'n1-flottabilite-pression', 'n1', 'physique', 'vrai-faux', 'lair-se-comprime-leau-non', 'L''eau, comme l''air, se comprime lorsqu''on descend en profondeur.', 'C''est faux : l''air est compressible mais l''eau ne l''est pas, comme le montre l''expérience de la seringue bouchée. Le corps humain, essentiellement composé d''eau, ne craint donc rien de la pression directe ; seules les poches d''air (oreilles, sinus, poumons, masque, gilet) voient leur volume changer avec la profondeur, et ce sont elles qui posent problème.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-007', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-007', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-008', 'n1-flottabilite-pression', 'n1', 'physique', 'calcul', 'lair-se-comprime-leau-non', 'Un ballon souple contient 6 litres d''air en surface. Quel volume occupe-t-il à 10 m de profondeur ?', 'À 10 m, la pression absolue passe de 1 à 2 bars : elle double, donc le volume d''air est divisé par deux, soit $6/2 = 3$ L. La réponse 2 L correspondrait à 20 m (3 bars), 12 L supposerait que l''air se dilate à la descente (c''est l''inverse), et 6 L supposerait un volume constant, ce qui n''est vrai que pour un récipient rigide.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-008', 'a', '6 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-008', 'b', '3 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-008', 'c', '2 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-008', 'd', '12 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-009', 'n1-flottabilite-pression', 'n1', 'physique', 'calcul', 'lair-se-comprime-leau-non', 'Un ballon souple contient 2 litres d''air à 20 m. Quel volume occupera cet air une fois revenu en surface ?', 'À 20 m la pression absolue est de 3 bars ; en surface elle n''est que de 1 bar. Le volume est donc multiplié par 3 : $2 \times 3 = 6$ L. La réponse 4 L correspondrait à un facteur 2 (erreur d''oubli du bar atmosphérique), et 1 L supposerait que l''air se comprime à la remontée alors qu''il se dilate. Ce mécanisme de dilatation est exactement celui qui menace les poumons d''un plongeur qui bloquerait sa respiration.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-009', 'a', '2 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-009', 'b', '4 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-009', 'c', '6 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-009', 'd', '1 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-010', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'la-poussée-darchimède-racontée-simplement', 'Qu''est-ce que la poussée d''Archimède ?', 'Tout corps plongé dans l''eau reçoit une poussée verticale dirigée du bas vers le haut, égale au poids du volume d''eau qu''il déplace : c''est le principe d''Archimède. La force vers le bas est le poids, pas la poussée ; le courant et le gilet n''ont rien à voir avec ce principe, même si le gilet exploite Archimède en augmentant le volume du plongeur.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-010', 'a', 'Une poussée vers le haut égale au poids du volume d''eau déplacé', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-010', 'b', 'Une force vers le bas due au poids de l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-010', 'c', 'La force du courant qui pousse le plongeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-010', 'd', 'La pression exercée par l''air du gilet', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-011', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'la-poussée-darchimède-racontée-simplement', 'Un plongeur en flottabilité neutre :', 'La flottabilité neutre correspond à l''équilibre parfait entre le poids (vers le bas) et la poussée d''Archimède (vers le haut) : le plongeur reste immobile entre deux eaux, comme un poisson. S''il remonte, sa flottabilité est positive ; s''il coule, elle est négative. C''est cet équilibre que le plongeur recherche en permanence pour évoluer sans effort.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-011', 'a', 'remonte lentement vers la surface', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-011', 'b', 'reste stable entre deux eaux, sans monter ni descendre', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-011', 'c', 'coule doucement vers le fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-011', 'd', 'flotte obligatoirement en surface', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-012', 'n1-flottabilite-pression', 'n1', 'physique', 'vrai-faux', 'la-poussée-darchimède-racontée-simplement', 'On flotte mieux en eau de mer qu''en eau douce.', 'C''est vrai : l''eau de mer, plus dense à cause du sel, pousse plus fort vers le haut à volume déplacé égal. Conséquence pratique : un plongeur équilibré en piscine ou en lac devra ajouter du plomb en passant en mer, car la poussée y est plus forte — le lestage se réajuste à chaque changement de milieu.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-012', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-012', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-013', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'le-plongeur--un-équilibre-qui-change-pendant-la-plongée', 'Que devient la combinaison en néoprène quand le plongeur descend en profondeur ?', 'Le néoprène est rempli de milliers de microbulles de gaz qui, comme toute poche d''air, s''écrasent avec la pression : la combinaison perd du volume, donc de la poussée d''Archimède, et le plongeur devient plus « lourd » en descendant. C''est pourquoi il faut injecter de l''air dans le gilet au fil de la descente. Le néoprène n''est ni incompressible ni plus isolant sous pression — il isole au contraire moins bien une fois écrasé.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-013', 'a', 'Elle gonfle et fait remonter le plongeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-013', 'b', 'Ses microbulles s''écrasent : elle perd de la flottabilité', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-013', 'c', 'Elle ne change pas, le néoprène est incompressible', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-013', 'd', 'Elle devient plus isolante grâce à la pression', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-014', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'le-plongeur--un-équilibre-qui-change-pendant-la-plongée', 'Comment utiliser ses poumons comme « réglage fin » de la flottabilité (poumon-ballast) ?', 'Les poumons sont une poche d''air dont le volume varie avec la respiration : une inspiration ample augmente le volume, donc la poussée d''Archimède, et fait légèrement monter ; une expiration prolongée fait descendre. La réponse c inverse le mécanisme, et bloquer sa respiration est exactement le geste interdit en plongée (risque de surpression pulmonaire à la remontée).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-014', 'a', 'Inspirer amplement pour monter légèrement, expirer longuement pour descendre', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-014', 'b', 'Bloquer sa respiration pour rester stable', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-014', 'c', 'Expirer pour monter, inspirer pour descendre', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-014', 'd', 'Respirer très vite pour rester entre deux eaux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-015', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'le-plongeur--un-équilibre-qui-change-pendant-la-plongée', 'Pourquoi faut-il purger régulièrement son gilet pendant la remontée ?', 'À la remontée, la pression diminue et l''air du gilet se dilate : la flottabilité augmente, la vitesse aussi, donc l''air se dilate encore plus — un cercle vicieux qui transforme le gilet en « fusée ». Purger régulièrement casse cet emballement et maintient une vitesse lente. L''air se comprime à la descente, pas à la remontée, et la purge n''a rien à voir avec l''économie d''air ni avec une entrée d''eau.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-015', 'a', 'Parce que l''air du gilet se dilate et accélère dangereusement la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-015', 'b', 'Parce que l''air du gilet se comprime et fait couler', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-015', 'c', 'Pour économiser l''air du bloc', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-015', 'd', 'Pour éviter que le gilet ne se remplisse d''eau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-016', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'le-plongeur--un-équilibre-qui-change-pendant-la-plongée', 'Quelles sont les conséquences d''un surlestage (trop de plombs) ? Plusieurs réponses possibles.', 'Le surlestage est un faux ami : pour compenser l''excès de plomb, il faut gonfler davantage le gilet, dont le volume varie alors plus fortement avec la profondeur — la stabilisation devient instable, le plongeur lutte, se fatigue et consomme plus d''air. Il ne fait en rien « mieux descendre » en sécurité : le bon lestage se vérifie en surface avec l''aide du moniteur.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-016', 'a', 'Il oblige à gonfler davantage le gilet', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-016', 'b', 'Il rend la stabilisation instable et fatigante', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-016', 'c', 'Il augmente la consommation d''air', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-016', 'd', 'Il améliore la descente et la sécurité', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-017', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'le-plongeur--un-équilibre-qui-change-pendant-la-plongée', 'Comment vérifie-t-on un bon lestage en surface ?', 'Le critère du bon lestage : gilet vide et poumons à mi-capacité, le plongeur flotte au niveau des yeux et s''immerge sur une simple expiration. Couler immédiatement traduit un surlestage, dangereux et fatigant ; tester gilet gonflé ne renseigne en rien sur le lestage puisque le gilet compense n''importe quel excès de plomb.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-017', 'a', 'Gilet vide et poumons à mi-capacité, on flotte au niveau des yeux et on s''immerge sur une expiration', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-017', 'b', 'Gilet gonflé à fond, on doit flotter la tête haute', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-017', 'c', 'On doit couler immédiatement dès l''entrée dans l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-017', 'd', 'On doit pouvoir rester en surface sans palmer, gilet vide et poumons pleins d''air bloqué', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-physique-018', 'n1-flottabilite-pression', 'n1', 'physique', 'qcm', 'ce-que-la-pression-change-concrètement-dans-votre-plongée', 'Pourquoi la bouteille se vide-t-elle plus vite à 20 m qu''en surface ?', 'À 20 m, la pression absolue est de 3 bars : le détendeur délivre l''air à cette pression, et chaque litre inspiré prélève l''équivalent de trois litres d''air détendu sur le bloc. La consommation triple donc même à ventilation identique. Le détendeur ne fuit pas en profondeur et le froid ne suffit pas à expliquer ce phénomène ; le rythme respiratoire peut s''ajouter, mais la cause principale est physique.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-018', 'a', 'Parce que chaque litre d''air respiré à 3 bars « contient » trois fois plus d''air qu''en surface', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-018', 'b', 'Parce que le détendeur fuit en profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-018', 'c', 'Parce que le froid contracte l''air du bloc', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-physique-018', 'd', 'Parce qu''on respire plus vite au fond, uniquement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-001', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'un-mécanisme-commun-à-tous-les-barotraumatismes', 'Quel est le mécanisme commun à tous les barotraumatismes ?', 'Un barotraumatisme survient quand une cavité aérienne ne communique plus avec l''extérieur : la différence de pression entre l''intérieur et l''extérieur tire ou comprime les tissus (tympan, muqueuses, poumons), comme une bouteille en plastique fermée qui s''écrase à la descente. L''excès d''azote dissous correspond à l''accident de désaturation, un mécanisme totalement différent, et il ne s''agit ni d''une infection ni d''un manque d''oxygène.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-001', 'a', 'Une différence de pression entre une cavité d''air fermée et le milieu extérieur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-001', 'b', 'Une infection due à l''eau de mer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-001', 'c', 'Un excès d''azote dissous dans les tissus', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-001', 'd', 'Un manque d''oxygène dans le sang', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-002', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'un-mécanisme-commun-à-tous-les-barotraumatismes', 'Quels barotraumatismes surviennent principalement à la **descente** ? Plusieurs réponses possibles.', 'À la descente, les cavités se retrouvent « en dépression » et les tissus sont aspirés vers l''intérieur : ce mécanisme touche les oreilles, les sinus et le masque. La surpression pulmonaire est au contraire l''accident typique de la remontée : l''air enfermé dans les poumons se dilate et distend les alvéoles quand le plongeur bloque sa respiration.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-002', 'a', 'Les oreilles', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-002', 'b', 'Le plaquage de masque', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-002', 'c', 'La surpression pulmonaire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-002', 'd', 'Les sinus', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-003', 'n1-barotraumatismes', 'n1', 'physiologie', 'vrai-faux', 'un-mécanisme-commun-à-tous-les-barotraumatismes', 'Les barotraumatismes de la descente surviennent surtout dans les 10 premiers mètres.', 'C''est vrai : les variations relatives de pression sont maximales près de la surface (la pression absolue double entre 0 et 10 m), donc les volumes d''air y varient le plus vite. C''est pour cette raison que les oreilles font mal dès les premiers mètres, et que le risque de surpression pulmonaire reste présent jusqu''au dernier mètre de la remontée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-003', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-003', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-004', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-oreilles--le-barotraumatisme-le-plus-fréquent', 'Par quel canal l''oreille moyenne communique-t-elle avec l''arrière-nez ?', 'L''oreille moyenne est une caisse d''air fermée par le tympan, reliée au pharynx par la trompe d''Eustache, normalement fermée au repos : c''est par elle que la manœuvre de Valsalva envoie l''air qui rééquilibre les pressions. Le conduit auditif externe est du côté extérieur du tympan et n''intervient pas dans l''équilibrage ; le canal lacrymal et les sinus n''ont aucun lien avec l''oreille moyenne.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-004', 'a', 'Le conduit auditif externe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-004', 'b', 'La trompe d''Eustache', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-004', 'c', 'Le canal lacrymal', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-004', 'd', 'Les sinus frontaux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-005', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-oreilles--le-barotraumatisme-le-plus-fréquent', 'En quoi consiste la manœuvre de Valsalva ?', 'Le Valsalva consiste à pincer le nez, bouche fermée, et à souffler doucement dans le nez : l''air remonte par les trompes d''Eustache et « regonfle » l''oreille moyenne. C''est la manœuvre enseignée au Niveau 1, efficace à condition de souffler en douceur. La déglutition aide certains plongeurs mais ce n''est pas le Valsalva, et souffler dans le détendeur ou se boucher les oreilles n''équilibre rien du tout.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-005', 'a', 'Pincer le nez, bouche fermée, et souffler doucement comme pour se moucher', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-005', 'b', 'Avaler sa salive en apnée profonde', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-005', 'c', 'Souffler fort par la bouche dans le détendeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-005', 'd', 'Se boucher les oreilles avec les doigts et déglutir', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-006', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-oreilles--le-barotraumatisme-le-plus-fréquent', 'Quand faut-il équilibrer ses oreilles à la descente ?', 'La règle d''or est d''équilibrer dès la mise à l''eau, tous les mètres au début, et surtout avant que la douleur n''apparaisse : une trompe d''Eustache déjà comprimée par la différence de pression devient très difficile à ouvrir. Attendre la douleur ou n''équilibrer qu''au fond, c''est laisser le tympan se déformer ; et c''est précisément dans les 10 premiers mètres, pas en dessous, que l''équilibrage est le plus sollicité.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-006', 'a', 'Tôt, souvent, et avant d''avoir mal', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-006', 'b', 'Uniquement quand la douleur apparaît', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-006', 'c', 'Une seule fois, arrivé au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-006', 'd', 'Seulement en dessous de 10 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-007', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-oreilles--le-barotraumatisme-le-plus-fréquent', 'À la descente, votre oreille « ne passe pas » malgré un Valsalva doux. Que faites-vous ?', 'La conduite correcte est de stopper la descente, remonter légèrement pour réduire la différence de pression, puis réessayer sans forcer ; si l''oreille ne passe toujours pas, on fait le signe « ça ne va pas » en montrant l''oreille et la plongée s''arrête — ce n''est jamais un échec. Forcer expose à une lésion de l''oreille interne, continuer à descendre mène à la déchirure du tympan, et retirer son masque n''a aucun effet sur l''oreille moyenne.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-007', 'a', 'Je force le Valsalva jusqu''à ce que ça passe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-007', 'b', 'Je stoppe la descente, je remonte d''un ou deux mètres et je réessaie calmement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-007', 'c', 'Je continue la descente, la douleur finira par disparaître', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-007', 'd', 'Je retire mon masque pour équilibrer', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-008', 'n1-barotraumatismes', 'n1', 'physiologie', 'vrai-faux', 'les-oreilles--le-barotraumatisme-le-plus-fréquent', 'À la remontée, il faut faire des manœuvres de Valsalva régulières pour protéger ses oreilles.', 'C''est faux, et c''est même une règle de sécurité majeure : à la remontée, l''air en excès sort tout seul des oreilles par les trompes d''Eustache. Un Valsalva ajouterait de la pression dans une oreille déjà en surpression et pourrait léser l''oreille interne (vertiges, surdité, acouphènes, parfois définitifs). Le Valsalva est un geste de descente uniquement.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-008', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-008', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-009', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-oreilles--le-barotraumatisme-le-plus-fréquent', 'Pourquoi ne faut-il pas plonger enrhumé, même avec un spray décongestionnant ?', 'Enrhumé, les trompes d''Eustache et les canaux des sinus sont encombrés : l''équilibrage devient impossible et le barotraumatisme guette. Les sprays décongestionnants sont une fausse solution : leur effet peut se dissiper pendant la plongée et piéger l''air dans les cavités à la remontée, provoquant l''accident qu''on voulait éviter. Il ne s''agit ni d''une interdiction réglementaire ni d''un problème de contagion : c''est un mécanisme purement physique.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-009', 'a', 'Parce que les trompes d''Eustache encombrées ne laissent pas passer l''air, et l''effet du spray peut cesser au fond et piéger l''air à la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-009', 'b', 'Parce que le rhume s''aggrave toujours avec la pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-009', 'c', 'Parce que le spray est interdit par le Code du sport', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-009', 'd', 'Parce qu''on risque de contaminer sa palanquée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-010', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-oreilles--le-barotraumatisme-le-plus-fréquent', 'Quel risque fait courir un Valsalva trop fort et prolongé ?', 'Un Valsalva doit rester un souffle doux et bref : souffler fort et longtemps transmet une surpression brutale à l''oreille interne et peut provoquer vertiges, surdité et acouphènes, avec des lésions parfois irréversibles. L''idée que « plus on force, mieux ça passe » est exactement le réflexe dangereux à combattre ; il ne s''agit ni d''un simple mal de tête ni d''un essoufflement.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-010', 'a', 'Une lésion de l''oreille interne (vertiges, surdité, acouphènes), parfois définitive', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-010', 'b', 'Aucun : plus on souffle fort, mieux l''oreille passe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-010', 'c', 'Un simple mal de tête passager', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-010', 'd', 'Un essoufflement immédiat', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-011', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-sinus-et-les-dents', 'Une douleur vive au front ou sous les yeux pendant la descente évoque :', 'Les sinus sont des cavités creusées dans les os du front et des pommettes : quand leurs canaux sont bouchés (rhume, sinusite), la descente crée une dépression douloureuse à ces endroits précis, parfois avec un petit saignement de nez. Le plaquage de masque donne une sensation de ventouse sur le visage et les yeux, pas une douleur osseuse localisée ; la narcose ne survient pas à ces profondeurs au N1 et l''ADD se déclare après la plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-011', 'a', 'Un barotraumatisme des sinus', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-011', 'b', 'Un début de narcose', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-011', 'c', 'Un plaquage de masque', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-011', 'd', 'Un accident de désaturation', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-012', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-sinus-et-les-dents', 'Comment une dent peut-elle être le siège d''un barotraumatisme ?', 'Une carie ou un soin défectueux peut emprisonner une microbulle d''air : comprimée à la descente puis dilatée à la remontée, elle met la pulpe dentaire sous tension et provoque une douleur localisée. La prévention passe par une bonne hygiène dentaire et par le fait de signaler sa pratique de la plongée à son dentiste. L''émail ne se dissout pas, le froid n''éclate pas les dents et la pression ne peut pas « écraser » la mâchoire, qui ne contient pas de cavité d''air en temps normal.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-012', 'a', 'Une minuscule bulle d''air piégée sous un plombage défectueux ou dans une carie subit les variations de pression', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-012', 'b', 'L''émail se dissout dans l''eau de mer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-012', 'c', 'Le froid de l''air détendu fait éclater la dent', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-012', 'd', 'La pression écrase directement la mâchoire', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-013', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'le-plaquage-de-masque', 'Comment prévenir le plaquage de masque à la descente ?', 'À la descente, l''air du masque se comprime et le transforme en ventouse ; il suffit de souffler régulièrement un peu d''air par le nez pour rétablir la pression — c''est précisément pour cela que le masque de plongée englobe le nez. Serrer la sangle aggrave l''effet ventouse, retenir sa respiration n''a aucun effet sur le volume du masque, et le remplir d''eau supprimerait la vision nette qu''il procure.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-013', 'a', 'Souffler de temps en temps un peu d''air par le nez dans le masque', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-013', 'b', 'Serrer davantage la sangle du masque', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-013', 'c', 'Retenir sa respiration pendant la descente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-013', 'd', 'Mettre de l''eau dans le masque avant de descendre', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-014', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'le-plaquage-de-masque', 'Pourquoi ne plonge-t-on jamais en bouteille avec des lunettes de piscine ?', 'La compensation du plaquage se fait en soufflant de l''air par le nez dans le masque : des lunettes de piscine, qui laissent le nez à l''extérieur, ne permettent pas ce geste et se transforment en ventouses sur les yeux dès les premiers mètres. Le problème n''est ni la solidité du verre, ni la cagoule, ni l''optique : c''est bien l''impossibilité physique d''équilibrer leur volume d''air interne.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-014', 'a', 'Parce qu''elles n''englobent pas le nez : impossible de compenser leur volume d''air à la descente', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-014', 'b', 'Parce qu''elles ne tiennent pas avec une cagoule', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-014', 'c', 'Parce que leur verre n''est pas assez résistant à la pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-014', 'd', 'Parce qu''elles donnent une vision déformée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-015', 'n1-barotraumatismes', 'n1', 'physiologie', 'vrai-faux', 'le-plaquage-de-masque', 'À la remontée, il faut souffler par le nez dans son masque pour éviter qu''il ne se plaque.', 'C''est faux : le plaquage de masque est un accident de la descente, quand l''air du masque se comprime. À la remontée, l''air en excès se dilate et s''échappe tout seul sous la jupe souple du masque — il n''y a strictement rien à faire. Le geste de compensation par le nez ne s''impose donc qu''en descendant.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-015', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-015', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-016', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'la-surpression-pulmonaire--rare-mais-gravissime', 'Quelle est la cause de la surpression pulmonaire ?', 'Le détendeur délivre de l''air à la pression du fond ; si le plongeur remonte en bloquant sa respiration, cet air veut se dilater (loi des volumes) et distend les poumons jusqu''à déchirer les alvéoles, laissant l''air passer dans les tissus et la circulation. Inspirer profondément au fond est sans danger si l''on continue de respirer ; les bulles d''azote caractérisent l''accident de désaturation, et la descente rapide provoque des barotraumatismes des oreilles ou des sinus, pas des poumons.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-016', 'a', 'Le blocage de la respiration pendant la remontée : l''air des poumons se dilate et déchire les alvéoles', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-016', 'b', 'Une inspiration trop profonde au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-016', 'c', 'L''azote qui forme des bulles dans le sang', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-016', 'd', 'Une descente trop rapide sans équilibrer', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-017', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'la-surpression-pulmonaire--rare-mais-gravissime', 'Quelle est LA règle absolue de prévention de la surpression pulmonaire ?', 'La règle du Niveau 1 tient en une phrase : ne jamais bloquer sa respiration à la remontée — on respire normalement, en continu, et lors d''une remontée sans embout on expire doucement tout au long. L''expiration libre laisse l''air dilaté s''échapper et les poumons ne peuvent pas se surgonfler. Remonter en apnée est exactement le geste qui tue, la limite des 10 m ne protège pas (l''accident est possible à 2 m) et le Valsalva concerne les oreilles à la descente.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-017', 'a', 'Ne jamais bloquer sa respiration à la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-017', 'b', 'Ne jamais descendre au-delà de 10 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-017', 'c', 'Toujours remonter en apnée pour économiser l''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-017', 'd', 'Faire un Valsalva toutes les 30 secondes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-018', 'n1-barotraumatismes', 'n1', 'physiologie', 'vrai-faux', 'la-surpression-pulmonaire--rare-mais-gravissime', 'Une surpression pulmonaire peut survenir en piscine, à moins de 2 mètres de profondeur.', 'C''est vrai : c''est entre la surface et 10 m que le volume de l''air varie proportionnellement le plus vite, et quelques dixièmes de bar d''écart suffisent à léser les alvéoles. Un plongeur qui inspire au fond d''une piscine et remonte en bloquant sa respiration peut donc faire une surpression pulmonaire à moins de 2 m — raison pour laquelle cette règle est enseignée dès le baptême.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-018', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-018', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-019', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'la-surpression-pulmonaire--rare-mais-gravissime', 'Quels signes doivent faire évoquer une surpression pulmonaire après une remontée ? Plusieurs réponses possibles.', 'La déchirure des alvéoles provoque douleur thoracique, détresse respiratoire et crachats sanglants ; si l''air passe dans la circulation jusqu''au cerveau, s''y ajoutent des troubles neurologiques graves (perte de connaissance, paralysie) pouvant aller jusqu''à l''arrêt cardiaque. Une douleur d''oreille isolée évoque un barotraumatisme de l''oreille, sans rapport avec les poumons. Devant ces signes : sortir la victime de l''eau, alerter, oxygène par l''encadrement.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-019', 'a', 'Douleur thoracique brutale et difficulté à respirer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-019', 'b', 'Crachats sanglants', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-019', 'c', 'Troubles neurologiques (perte de connaissance, paralysie)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-019', 'd', 'Douleur d''oreille isolée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-020', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'la-surpression-pulmonaire--rare-mais-gravissime', 'Lors d''une remontée sans embout (exercice ou panne), que doit faire le plongeur ?', 'Sans embout, la seule conduite sûre est d''expirer doucement en continu : l''air pulmonaire, qui se dilate à mesure que la pression diminue, s''échappe librement et les poumons ne se surgonflent jamais. Bloquer sa respiration ou remonter en apnée inspiration bloquée crée exactement les conditions de la surpression pulmonaire, l''accident le plus grave de la plongée ; inspirer est de toute façon impossible sans embout.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-020', 'a', 'Expirer doucement et continûment tout au long de la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-020', 'b', 'Bloquer sa respiration pour garder de l''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-020', 'c', 'Inspirer par petites saccades', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-020', 'd', 'Remonter le plus vite possible en apnée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-021', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'la-surpression-pulmonaire--rare-mais-gravissime', 'Quels facteurs favorisent la surpression pulmonaire ? Plusieurs réponses possibles.', 'La panique conduit à remonter vite en bloquant l''inspiration, une toux ou un fou rire peuvent fermer la glotte au mauvais moment, et l''asthme non contrôlé peut piéger de l''air dans certaines zones du poumon — d''où l''importance de la visite médicale. Respirer calmement en continu est au contraire la protection même contre cet accident : l''air dilaté s''évacue à chaque expiration.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-021', 'a', 'Le stress et la panique (remontée précipitée en apnée)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-021', 'b', 'Une toux ou un fou rire pendant la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-021', 'c', 'L''asthme non contrôlé', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-021', 'd', 'Le fait de respirer calmement en continu', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-baro-022', 'n1-barotraumatismes', 'n1', 'physiologie', 'qcm', 'les-autres-cavités-et-le-récapitulatif', 'Comment limiter les douleurs digestives liées à la dilatation des gaz à la remontée ?', 'Les gaz de l''estomac et des intestins se dilatent à la remontée : d''éventuelles douleurs abdominales cèdent en ralentissant la remontée et en laissant les gaz s''évacuer naturellement, et se préviennent en évitant boissons gazeuses et aliments fermentescibles avant la plongée. Boire de l''eau gazeuse aggraverait le phénomène, l''apnée à la remontée est l''interdit majeur de la plongée, et serrer la ceinture ne ferait qu''augmenter l''inconfort.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-022', 'a', 'Éviter les boissons gazeuses et les aliments qui fermentent avant de plonger, et ralentir la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-022', 'b', 'Rester en apnée pendant la remontée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-022', 'c', 'Boire beaucoup d''eau gazeuse avant la mise à l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-baro-022', 'd', 'Serrer sa ceinture de lest au maximum', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-001', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'respirer-sous-leau-nest-pas-respirer-en-surface', 'Quelle est la bonne façon de respirer en plongée ?', 'Sous l''eau, l''air est plus dense et le détendeur ajoute une résistance : la ventilation doit être lente, ample et calme, en insistant sur l''expiration, car c''est elle qui chasse le CO₂ — le gaz dont l''accumulation déclenche l''essoufflement. Une respiration rapide et superficielle ventile mal le fond des poumons et prépare l''essoufflement ; les apnées sont interdites en plongée bouteille (risque de surpression pulmonaire à la remontée).', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-001', 'a', 'Lentement et amplement, en insistant sur l''expiration', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-001', 'b', 'Rapidement et superficiellement pour renouveler l''air souvent', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-001', 'c', 'En apnées courtes pour économiser l''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-001', 'd', 'En inspirant fort et en expirant à peine', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-002', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'respirer-sous-leau-nest-pas-respirer-en-surface', 'Quel gaz déclenche l''envie irrépressible de respirer lorsqu''il s''accumule ?', 'C''est l''accumulation de CO₂, le déchet de la respiration, qui commande l''envie de respirer : quand il monte, la ventilation s''accélère. C''est pourquoi une expiration insuffisante prépare l''essoufflement. L''oxygène est le gaz consommé (son manque ne déclenche pas d''alarme fiable), l''azote est neutre pour la commande respiratoire et l''hélium n''entre pas dans l''air respiré au Niveau 1.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-002', 'a', 'L''oxygène (O₂)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-002', 'b', 'L''azote (N₂)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-002', 'c', 'Le gaz carbonique (CO₂)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-002', 'd', 'L''hélium', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-003', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'lessoufflement--le-cercle-vicieux-du-co', 'Quelles situations peuvent déclencher un essoufflement ? Plusieurs réponses possibles.', 'Tout ce qui augmente la production de CO₂ ou dégrade son élimination peut lancer le cercle vicieux : effort intense (palmage contre le courant), frissons liés au froid, stress, surlestage qui oblige à lutter, détendeur mal réglé. Une expiration longue et calme est au contraire la meilleure protection : c''est elle qui évacue le CO₂ et casse le cercle vicieux.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-003', 'a', 'Un palmage rapide contre le courant', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-003', 'b', 'Le froid et le stress', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-003', 'c', 'Un lestage excessif qui oblige à lutter', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-003', 'd', 'Une expiration longue et calme', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-004', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'lessoufflement--le-cercle-vicieux-du-co', 'Vous vous sentez essoufflé en plongée. Quelle est la conduite à tenir, dans l''ordre ?', 'La conduite à tenir du Niveau 1 : j''arrête tout effort (je me tiens à un rocher, je me pose si possible), j''expire à fond plusieurs fois — c''est l''expiration forcée qui évacue le CO₂ et casse le cercle vicieux — et je fais le signe « je suis essoufflé » à l''encadrant. Accélérer la respiration aggrave l''essoufflement, remonter précipitamment expose à la surpression pulmonaire, et retirer son détendeur mène à la noyade.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-004', 'a', 'Stopper tout effort, forcer l''expiration, prévenir l''encadrant', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-004', 'b', 'Accélérer la respiration pour reprendre son souffle', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-004', 'c', 'Remonter immédiatement en surface le plus vite possible', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-004', 'd', 'Retirer son détendeur pour respirer plus librement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-005', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'lessoufflement--le-cercle-vicieux-du-co', 'À quels signes reconnaît-on un coéquipier en train de s''essouffler ? Plusieurs réponses possibles.', 'L''essoufflement se voit de l''extérieur : les expirations rapprochées produisent de gros bouillons quasi continus, le plongeur s''agite, passe en position verticale, écarquille les yeux et se crispe sur son détendeur. Face à ces signes : le signaler à l''encadrant, rester près du coéquipier et l''inciter au calme et à l''expiration. Un palmage lent avec des bulles espacées est au contraire le signe d''un plongeur détendu.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-005', 'a', 'Gros bouillons de bulles rapprochés', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-005', 'b', 'Yeux écarquillés, agitation, position verticale', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-005', 'c', 'Main crispée sur le détendeur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-005', 'd', 'Palmage lent et régulier, bulles espacées', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-006', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'vrai-faux', 'lessoufflement--le-cercle-vicieux-du-co', 'Pour casser un essoufflement, il faut inspirer plus vite et plus fort.', 'C''est faux, et c''est le piège même de l''essoufflement : le réflexe d''inspirer plus vite rend la respiration superficielle, ventile mal le fond des poumons et laisse le CO₂ s''accumuler encore plus. La seule issue est inverse : stopper tout effort et forcer l''expiration, longue et complète, pour évacuer le CO₂. L''expiration forcée est « le geste qui sauve ».', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-006', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-006', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-007', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'le-froid--un-ennemi-silencieux', 'Par rapport à l''air, l''eau refroidit le corps environ :', 'L''eau conduit la chaleur environ 25 fois mieux que l''air : même à 25 °C, elle refroidit le plongeur en permanence, d''où la nécessité d''une combinaison adaptée. Le chiffre 800 correspond au rapport de densité entre l''eau et l''air (utilisé pour expliquer la pression), pas à la conduction thermique — c''est une confusion classique entre les deux ordres de grandeur du cours.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-007', 'a', '2 fois plus vite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-007', 'b', '25 fois plus vite', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-007', 'c', '800 fois plus vite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-007', 'd', 'À la même vitesse', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-008', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'le-froid--un-ennemi-silencieux', 'En plongée, vous commencez à frissonner. Que faites-vous ?', 'Les frissons marquent le stade où le froid n''est plus une simple gêne : il augmente la consommation d''air, favorise l''essoufflement et dégrade l''attention. La bonne réponse est le signe « j''ai froid », qui entraîne la fin de plongée et un retour calme. Palmer plus fort mène à l''essoufflement, « serrer les dents » laisse le froid s''aggraver, et on ne quitte jamais sa palanquée pour remonter seul.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-008', 'a', 'Je fais le signe « j''ai froid » : la plongée se termine et on remonte calmement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-008', 'b', 'Je palme plus fort pour me réchauffer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-008', 'c', 'Je serre les dents, ça passera', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-008', 'd', 'Je remonte seul immédiatement sans prévenir', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-009', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'le-froid--un-ennemi-silencieux', 'Après une plongée où vous avez eu froid, quelle boisson est adaptée ?', 'Une fois sorti, on se sèche, on se couvre (bonnet compris, la tête perdant beaucoup de chaleur) et on boit une boisson chaude non alcoolisée. L''alcool est un faux ami : il donne une sensation de chaleur alors qu''il accélère en réalité le refroidissement, en plus de déshydrater. Une boisson glacée aggraverait le refroidissement, et bien s''hydrater après la plongée est au contraire recommandé.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-009', 'a', 'Une boisson chaude non alcoolisée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-009', 'b', 'Un alcool fort « pour se réchauffer »', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-009', 'c', 'Une boisson glacée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-009', 'd', 'Rien : il ne faut pas boire après une plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-010', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'le-froid--un-ennemi-silencieux', 'Comment prévenir le froid en plongée ? Plusieurs réponses possibles.', 'La prévention du froid combine une combinaison adaptée (épaisseur, cagoule) et bien ajustée, une protection contre le vent avant et après la plongée, et un organisme qui a du carburant : repas correct et bonne hydratation. Une combinaison trop grande est précisément le piège à éviter : elle laisse circuler l''eau le long du corps et isole très mal.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-010', 'a', 'Porter une combinaison adaptée à la température de l''eau et bien ajustée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-010', 'b', 'Se protéger du vent avant et après la plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-010', 'c', 'Manger correctement et être bien hydraté avant de plonger', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-010', 'd', 'Choisir une combinaison très ample pour être à l''aise', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-011', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'lazote--un-invité-qui-sincruste', 'Que devient l''azote de l''air respiré pendant une plongée ?', 'L''air contient environ 80 % d''azote, un gaz neutre que le corps ne consomme pas : sous pression, il se dissout dans le sang et les tissus, comme le gaz d''une bouteille d''eau gazeuse fermée — plus la plongée est profonde et longue, plus le corps se charge. Il n''est ni consommé ni transformé, et c''est justement parce qu''il ne ressort que lentement à la remontée qu''il impose des règles de remontée strictes.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-011', 'a', 'Il se dissout dans le sang et les tissus sous l''effet de la pression', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-011', 'b', 'Il est consommé par les muscles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-011', 'c', 'Il est transformé en oxygène', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-011', 'd', 'Il est intégralement rejeté à chaque expiration, sans effet', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-012', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'lazote--un-invité-qui-sincruste', 'Que risque-t-il de se passer si la remontée est trop rapide ?', 'Si la remontée est trop rapide, l''azote dissous fait comme le gaz d''une bouteille d''eau pétillante ouverte brutalement : il forme des bulles dans le sang et les tissus, qui peuvent bloquer la circulation ou comprimer des structures — c''est l''accident de désaturation (ADD), un accident grave. Expirer protège des barotraumatismes pulmonaires mais pas de l''ADD : les deux règles (expirer ET remonter lentement) sont complémentaires. La toxicité de l''oxygène n''apparaît qu''à des profondeurs hors du cadre N1.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-012', 'a', 'L''azote dissous forme des bulles dans le sang et les tissus : c''est l''accident de désaturation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-012', 'b', 'L''oxygène devient toxique', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-012', 'c', 'Rien, tant qu''on expire correctement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-012', 'd', 'Le bloc se vide plus vite', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-013', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'lazote--un-invité-qui-sincruste', 'À quoi sert le palier de quelques minutes vers 3 m parfois demandé par l''encadrant ?', 'Le palier est du temps offert à l''azote : en s''arrêtant quelques minutes à faible profondeur, le corps évacue tranquillement par la respiration l''azote dissous pendant la plongée, ce qui réduit le risque de formation de bulles. Ce n''est ni un contrôle du matériel, ni une économie d''air (on en consomme au contraire), ni un moment de réchauffement — l''eau y est d''ailleurs souvent plus fraîche qu''en surface.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-013', 'a', 'À laisser le temps à l''azote dissous de s''évacuer en douceur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-013', 'b', 'À vérifier le matériel avant de sortir', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-013', 'c', 'À économiser l''air du bloc', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-013', 'd', 'À se réchauffer avant la surface', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-014', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'après-la-plongée--les-règles-qui-protègent', 'Combien de temps faut-il attendre au minimum avant de prendre l''avion après une plongée unique ?', 'La cabine d''un avion est en dépression : l''azote résiduel encore présent dans les tissus peut y former des bulles. La règle enseignée : attendre au moins 12 heures après une plongée unique et 24 heures après des plongées répétées, en suivant la consigne la plus prudente donnée par l''encadrant. Deux heures sont très insuffisantes, la désaturation se poursuivant pendant des heures après la sortie ; 48 heures ne sont pas exigées, même si attendre plus longtemps ne nuit jamais.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-014', 'a', '2 heures', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-014', 'b', '12 heures (24 heures après des plongées répétées)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-014', 'c', '48 heures dans tous les cas', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-014', 'd', 'Aucun délai n''est nécessaire', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-015', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'après-la-plongée--les-règles-qui-protègent', 'Quels comportements sont à éviter juste après une plongée ? Plusieurs réponses possibles.', 'Après la plongée, le corps contient encore de l''azote excédentaire : l''effort violent favorise la formation de bulles, les descentes et remontées répétées de l''apnée brassent l''azote résiduel, et la montée en altitude reproduit le mécanisme de l''avion (baisse de pression ambiante). Boire de l''eau régulièrement est au contraire recommandé : la déshydratation épaissit le sang et gêne l''élimination de l''azote.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-015', 'a', 'Faire des efforts violents', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-015', 'b', 'Faire de l''apnée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-015', 'c', 'Monter en altitude (col routier, montagne)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-015', 'd', 'Boire de l''eau régulièrement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-risques-016', 'n1-risques-du-plongeur', 'n1', 'physiologie', 'qcm', 'après-la-plongée--les-règles-qui-protègent', 'Pourquoi la déshydratation est-elle un facteur de risque après la plongée ?', 'L''azote résiduel s''élimine par la circulation sanguine jusqu''aux poumons : un sang épaissi par la déshydratation circule moins bien et évacue moins efficacement ce gaz, ce qui augmente le risque de formation de bulles. C''est pourquoi on boit de l''eau régulièrement après la plongée et on proscrit l''alcool, qui déshydrate en plus de masquer les symptômes. La déshydratation ne change évidemment rien à la pression de l''eau.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-016', 'a', 'Elle épaissit le sang et gêne l''élimination de l''azote', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-016', 'b', 'Elle donne soif, ce qui distrait le plongeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-016', 'c', 'Elle augmente la pression de l''eau sur le corps', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-risques-016', 'd', 'Elle n''a aucun effet sur la désaturation', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-001', 'n1-materiel', 'n1', 'materiel', 'qcm', 'palmes-masque-tuba--le-trio-de-base', 'Comment vérifier qu''un masque est bien adapté à votre visage ?', 'Le test d''étanchéité se fait sans la sangle : on plaque le masque sur le visage et on inspire légèrement par le nez ; s''il tient tout seul par la dépression, la jupe épouse bien le visage. La sangle ne sert qu''à maintenir le masque en place — la serrer fort ne corrige pas un masque inadapté et favorise les fuites et l''inconfort. La taille se choisit selon la morphologie, pas « la plus grande ».', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-001', 'a', 'Le plaquer sur le visage sans la sangle et inspirer légèrement par le nez : il doit tenir tout seul', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-001', 'b', 'Serrer la sangle au maximum et vérifier qu''il ne bouge pas', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-001', 'c', 'Le remplir d''eau et vérifier qu''elle ne fuit pas', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-001', 'd', 'Choisir la plus grande taille disponible pour le confort', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-002', 'n1-materiel', 'n1', 'materiel', 'qcm', 'palmes-masque-tuba--le-trio-de-base', 'À quoi sert le tuba en plongée bouteille ?', 'Le tuba permet de respirer en surface la tête dans l''eau sans puiser dans le bloc : utile pour rejoindre le bateau, attendre ou observer. Il est évidemment inutilisable au fond — en cas de panne d''air, c''est l''octopus de l''équipier qui dépanne. Il n''a aucun rôle dans l''équilibrage des oreilles ni dans la signalisation de surface.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-002', 'a', 'À respirer en surface la tête dans l''eau sans consommer l''air du bloc', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-002', 'b', 'À respirer au fond en cas de panne d''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-002', 'c', 'À équilibrer les oreilles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-002', 'd', 'À signaler sa position au bateau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-003', 'n1-materiel', 'n1', 'materiel', 'qcm', 'palmes-masque-tuba--le-trio-de-base', 'D''où doit venir le mouvement d''un palmage efficace ?', 'Le palmage efficace part des hanches, jambes tendues mais souples : toute la palme travaille et propulse. Le pédalage des genoux est le défaut classique du débutant : il brasse de l''eau sans avancer et fatigue. Les bras restent le long du corps en plongée — les utiliser augmente la consommation sans propulser efficacement.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-003', 'a', 'Des hanches, jambes tendues et souples, sans pédalage', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-003', 'b', 'Des genoux, en pédalant comme à vélo', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-003', 'c', 'Des chevilles uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-003', 'd', 'Des bras, qui aident à la propulsion', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-004', 'n1-materiel', 'n1', 'materiel', 'qcm', 'la-combinaison--votre-isolation-thermique', 'Comment fonctionne une combinaison humide en néoprène ?', 'La combinaison humide laisse pénétrer une fine couche d''eau que le corps réchauffe une fois pour toutes ; l''isolation vient du néoprène, rempli de microbulles de gaz. C''est la combinaison étanche — hors programme N1 — qui empêche l''eau d''entrer, et aucune combinaison classique ne chauffe activement. D''où l''importance de l''ajustement : trop grande, l''eau circule en permanence et l''effet isolant disparaît.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-004', 'a', 'Elle laisse entrer une fine couche d''eau que le corps réchauffe, et le néoprène isole grâce à ses microbulles de gaz', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-004', 'b', 'Elle empêche totalement l''eau de toucher la peau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-004', 'c', 'Elle chauffe électriquement le plongeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-004', 'd', 'Elle isole uniquement grâce à son épaisseur de tissu', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-005', 'n1-materiel', 'n1', 'materiel', 'vrai-faux', 'la-combinaison--votre-isolation-thermique', 'Une combinaison trop grande isole moins bien du froid.', 'C''est vrai : le principe de la combinaison humide repose sur une fine couche d''eau immobile que le corps réchauffe. Trop grande, la combinaison laisse l''eau circuler librement : la couche réchauffée est sans cesse remplacée par de l''eau froide et l''isolation s''effondre. L''ajustement est donc aussi important que l''épaisseur du néoprène.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-005', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-005', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-006', 'n1-materiel', 'n1', 'materiel', 'qcm', 'le-bloc-et-lair-comprimé', 'Que contient un bloc de plongée ?', 'Le bloc du plongeur loisir contient de l''air ordinaire — environ 20 % d''oxygène et 80 % d''azote — simplement filtré, séché et comprimé à environ 200 bars. L''oxygène pur est dangereux dès quelques mètres de profondeur et les mélanges à l''hélium relèvent de la plongée technique : ni l''un ni l''autre ne concernent le Niveau 1. Personne n''enrichit l''air en azote, qui est déjà le gaz majoritaire.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-006', 'a', 'De l''air ordinaire filtré et séché, comprimé à environ 200 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-006', 'b', 'De l''oxygène pur comprimé', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-006', 'c', 'Un mélange spécial d''oxygène et d''hélium', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-006', 'd', 'De l''air enrichi en azote', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-007', 'n1-materiel', 'n1', 'materiel', 'qcm', 'le-bloc-et-lair-comprimé', 'Quelles règles de bon sens s''appliquent à la manipulation d''un bloc ? Plusieurs réponses possibles.', 'Un bloc debout non surveillé peut tomber et endommager sa robinetterie ou blesser quelqu''un ; on le transporte couché, à l''abri du soleil et des chocs, et on ne graisse jamais les raccords (la graisse peut s''enflammer au contact d''air comprimé). En revanche, on ne stocke jamais un bloc complètement vide : une pression résiduelle empêche l''humidité d''entrer et de corroder l''intérieur.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-007', 'a', 'Ne jamais le laisser debout sans surveillance', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-007', 'b', 'Le transporter couché et le protéger du soleil et des chocs', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-007', 'c', 'Ne jamais graisser les raccords', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-007', 'd', 'Le vider complètement après chaque plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-008', 'n1-materiel', 'n1', 'materiel', 'qcm', 'le-détendeur--respirer-à-la-pression-du-fond', 'Quel est le rôle du premier étage du détendeur ?', 'Le détendeur travaille en deux temps : le premier étage, vissé sur la robinetterie, abaisse la haute pression du bloc à une moyenne pression d''environ 8 à 10 bars au-dessus de la pression ambiante ; c''est le deuxième étage, en bouche, qui délivre ensuite l''air à la pression ambiante, à la demande. Le filtrage de l''air est fait au gonflage, et la mesure de pression est le rôle du manomètre, simplement branché sur le premier étage.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-008', 'a', 'Réduire la haute pression du bloc (jusqu''à 200 bars) à une moyenne pression d''environ 8 à 10 bars au-dessus de la pression ambiante', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-008', 'b', 'Délivrer l''air directement dans la bouche du plongeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-008', 'c', 'Filtrer l''air pour le rendre respirable', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-008', 'd', 'Mesurer la pression restante dans le bloc', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-009', 'n1-materiel', 'n1', 'materiel', 'qcm', 'le-détendeur--respirer-à-la-pression-du-fond', 'À quelle pression le deuxième étage délivre-t-il l''air au plongeur ?', 'Le deuxième étage — l''embout en bouche — délivre l''air exactement à la pression ambiante, et seulement quand le plongeur inspire : c''est le système « à la demande », qui s''adapte automatiquement à la profondeur sans réglage. De l''air à 200 bars serait irrespirable et dangereux, les 8-10 bars correspondent à la moyenne pression interne entre les deux étages, et délivrer à 1 bar au fond rendrait l''inspiration impossible contre la pression de l''eau.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-009', 'a', 'À la pression ambiante de la profondeur, uniquement à l''inspiration', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-009', 'b', 'À 200 bars en continu', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-009', 'c', 'À 8-10 bars en continu', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-009', 'd', 'Toujours à 1 bar, comme en surface', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-010', 'n1-materiel', 'n1', 'materiel', 'qcm', 'le-détendeur--respirer-à-la-pression-du-fond', 'Qu''est-ce que l''« octopus » ?', 'L''octopus est un deuxième étage supplémentaire, branché sur le premier étage et souvent de couleur jaune pour être repérable : il permet de donner de l''air à un coéquipier en difficulté sans partager son propre embout. Ce n''est ni un instrument de mesure (profondimètre), ni le flexible du gilet (direct system), ni un éclairage.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-010', 'a', 'Un deuxième étage de secours, souvent jaune, qui permet de dépanner un coéquipier en air', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-010', 'b', 'Un instrument de mesure de la profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-010', 'c', 'Le flexible qui gonfle le gilet', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-010', 'd', 'Une lampe de plongée à huit faisceaux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-011', 'n1-materiel', 'n1', 'materiel', 'qcm', 'le-gilet-stabilisateur-et-le-lestage', 'Quelles sont les fonctions du gilet stabilisateur ? Plusieurs réponses possibles.', 'Le gilet cumule le portage du bloc, l''ajustement de la flottabilité en immersion (gonflage par le direct system, dégonflage par les purges) et la flottaison confortable en surface ; il facilite aussi une éventuelle assistance. En revanche, il ne constitue pas une réserve d''air respirable : en cas de panne, c''est l''octopus du coéquipier qui dépanne, jamais l''air du gilet.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-011', 'a', 'Porter le bloc sur le dos', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-011', 'b', 'Ajuster la flottabilité en immersion', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-011', 'c', 'Faire flotter le plongeur en surface sans effort', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-011', 'd', 'Fournir de l''air de secours en cas de panne', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-012', 'n1-materiel', 'n1', 'materiel', 'qcm', 'le-gilet-stabilisateur-et-le-lestage', 'Quelle caractéristique la ceinture de plombs doit-elle impérativement avoir ?', 'En cas de problème grave en surface, larguer sa ceinture garantit immédiatement la flottabilité : sa boucle doit donc pouvoir s''ouvrir d''une seule main, sans hésitation. Tout dispositif qui bloque le largage (cadenas, fixation indémontable) est un contresens de sécurité. Le poids, lui, se règle individuellement selon la morphologie, la combinaison et le milieu — il n''existe aucun minimum imposé.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-012', 'a', 'Une boucle largable d''une seule main', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-012', 'b', 'Un cadenas pour éviter de la perdre', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-012', 'c', 'Un poids d''au moins 10 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-012', 'd', 'Une fixation solidaire du gilet, impossible à détacher', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-013', 'n1-materiel', 'n1', 'materiel', 'qcm', 'les-instruments-et-lentretien-du-matériel', 'En plongée, votre manomètre indique 50 bars. Que faites-vous ?', 'Par convention, 50 bars marquent la réserve : on prévient l''encadrant avec le signe convenu, et la palanquée entame le retour ou la remontée — on ne finit jamais son bloc au fond. Continuer jusqu''à 0 bar mène à la panne d''air, remonter seul est interdit en plongée encadrée, et fermer la robinetterie couperait tout simplement l''air du détendeur.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-013', 'a', 'Je préviens l''encadrant : c''est la réserve, la palanquée entame le retour', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-013', 'b', 'Je continue la plongée jusqu''à 0 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-013', 'c', 'Je remonte seul immédiatement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-013', 'd', 'Je ferme la robinetterie pour économiser l''air', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-materiel-014', 'n1-materiel', 'n1', 'materiel', 'qcm', 'les-instruments-et-lentretien-du-matériel', 'Quelle est la règle d''or de l''entretien du détendeur après la plongée ?', 'La règle d''or : jamais d''eau dans le premier étage. On rince donc le détendeur à l''eau douce avec le bouchon de protection sec et bien vissé, sans appuyer sur le bouton de surpression sous l''eau (ce qui ouvrirait le circuit et ferait entrer l''eau). Le démontage relève du technicien lors de la révision périodique, et le séchage se fait à l''ombre : le soleil dégrade joints et flexibles.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-014', 'a', 'Rincer à l''eau douce avec le bouchon de protection sec et vissé : l''eau ne doit jamais entrer dans le premier étage', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-014', 'b', 'Le démonter entièrement pour le sécher', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-014', 'c', 'Le rincer en appuyant sur le bouton de surpression sous l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-materiel-014', 'd', 'Le laisser sécher en plein soleil', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-001', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'pourquoi-un-langage-codifié', 'Que doit faire un plongeur qui reçoit un signe de son encadrant ?', 'Premier principe de la communication subaquatique : un signe est un message qui exige une réponse. Quand l''encadrant demande « ça va ? », ne pas répondre laisse croire à un problème — le silence n''est jamais neutre sous l''eau. On répond donc immédiatement, face à l''émetteur, par « OK » ou par le signe adapté au problème ; un hochement de tête n''est pas un signe conventionnel et peut être mal interprété.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-001', 'a', 'Répondre immédiatement et clairement : un signe est un message qui exige une réponse', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-001', 'b', 'Ne répondre que si quelque chose ne va pas', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-001', 'c', 'Hocher la tête, cela suffit toujours', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-001', 'd', 'Attendre que le signe soit répété pour être sûr', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-002', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'les-signes-indispensables-du-niveau-1', 'Que signifie le pouce levé vers le haut en plongée ?', 'Le pouce levé signifie « on monte », rien d''autre : la réponse attendue est de répéter le signe puis d''entamer la remontée ensemble, au rythme de l''encadrant. Pour dire que tout va bien, on utilise le cercle pouce-index (« OK »). Cette confusion, héritée du langage courant, est le piège classique du débutant : un pouce levé « enthousiaste » peut être compris comme une demande de remontée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-002', 'a', '« Tout va bien »', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-002', 'b', '« On monte » / « Je demande à monter »', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-002', 'c', '« Super, j''adore cette plongée ! »', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-002', 'd', '« Regardez en haut »', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-003', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'les-signes-indispensables-du-niveau-1', 'Comment indique-t-on « ça va » / « tout va bien » sous l''eau ?', 'Le signe « OK » se fait en joignant le pouce et l''index en cercle, les autres doigts levés : il sert à la fois de question (« ça va ? ») et de réponse (« ça va »). Le pouce levé signifie « on monte », la main à plat qui bascule signifie « ça ne va pas », et le poing sur la poitrine évoque le signe d''essoufflement — autant de messages très différents qu''il ne faut jamais mélanger.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-003', 'a', 'Pouce et index joints en cercle, autres doigts levés', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-003', 'b', 'Pouce levé vers le haut', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-003', 'c', 'Main à plat balancée de gauche à droite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-003', 'd', 'Poing fermé sur la poitrine', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-004', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'les-signes-indispensables-du-niveau-1', 'Un plongeur fait le geste de « trancher » le cou avec la main. Que se passe-t-il ?', 'Le geste de trancher le cou signifie « je n''ai plus d''air » : c''est une urgence absolue, la réponse est de donner immédiatement une source d''air — l''octopus de l''encadrant ou du binôme. Le signe du froid se fait bras croisés en frottant les épaules, et la fin d''exercice ou le demi-tour ont leurs propres signes : confondre ces messages ferait perdre des secondes vitales.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-004', 'a', 'C''est une urgence absolue : il n''a plus d''air, il faut lui fournir immédiatement une source d''air (octopus)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-004', 'b', 'Il indique qu''il a froid au cou', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-004', 'c', 'Il signale la fin de l''exercice', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-004', 'd', 'Il demande à faire demi-tour', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-005', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'les-signes-indispensables-du-niveau-1', 'Comment signale-t-on une gêne non vitale (« ça ne va pas ») ?', 'Le signe « ça ne va pas » est une main à plat balancée de gauche à droite ; l''encadrant vient alors vers vous et vous montrez ensuite ce qui ne va pas (l''oreille par exemple). Le pouce baissé signifie « on descend », les grands gestes des bras sont le signe de détresse en surface, et se taire est le mauvais réflexe : signaler une gêne tôt permet une solution simple — c''est un principe de sécurité, pas une gêne pour le groupe.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-005', 'a', 'Main à plat, paume vers le bas, balancée de gauche à droite, puis on montre ce qui ne va pas', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-005', 'b', 'Pouce baissé vers le bas', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-005', 'c', 'Grands gestes des deux bras', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-005', 'd', 'On ne signale rien tant que ce n''est pas grave', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-006', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'les-signes-indispensables-du-niveau-1', 'L''encadrant fait le signe « on monte ». Quelle est la réponse correcte ?', 'À un signe directif comme « on monte », on répond en répétant le signe (preuve qu''il est compris) puis on l''applique : la palanquée remonte ensemble, lentement, au rythme de l''encadrant. Rester au fond ou ignorer la consigne brise la cohésion de la palanquée, et remonter précipitamment expose à la surpression pulmonaire et à l''accident de désaturation — la vitesse de remontée est toujours contrôlée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-006', 'a', 'Répéter le signe et entamer la remontée ensemble, au rythme de l''encadrant', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-006', 'b', 'Faire OK et rester au fond encore un peu', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-006', 'c', 'Remonter immédiatement le plus vite possible', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-006', 'd', 'Ignorer le signe si on a encore de l''air', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-007', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'les-signes-indispensables-du-niveau-1', 'Que déclenche le signe « j''ai froid » (bras croisés, mains frottant les épaules) ?', 'Le signe « j''ai froid » entraîne la fin de la plongée pour la palanquée, avec un retour calme vers la surface : poursuivre en frissonnant augmente la consommation, favorise l''essoufflement et l''accident de désaturation. Ce n''est donc pas une simple information à « accuser réception », et il n''existe pas de demi-mesure du type « on remonte un peu » : le froid ne fait que s''aggraver en immersion.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-007', 'a', 'La fin de la plongée : la palanquée remonte calmement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-007', 'b', 'Un simple accusé de réception, la plongée continue', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-007', 'c', 'Le passage à une profondeur plus faible uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-007', 'd', 'L''encadrant prête sa cagoule', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-008', 'n1-signes-communication', 'n1', 'environnement', 'vrai-faux', 'les-signes-indispensables-du-niveau-1', 'Sous l''eau, le pouce levé signifie « tout va bien ».', 'C''est faux : le pouce levé signifie « on monte » et rien d''autre — l''encadrant qui le voit comprend une demande de remontée. Pour dire que tout va bien, on fait le signe « OK » : pouce et index joints en cercle. Cette distinction est l''un des premiers réflexes à automatiser, car la confusion venue des habitudes terrestres est très fréquente chez le débutant.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-008', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-008', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-009', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'communiquer-sa-pression-dair', 'Quels signes doivent être émis spontanément, sans attendre d''être interrogé ? Plusieurs réponses possibles.', 'Quatre messages de sécurité s''émettent sans attendre d''être interrogé : le passage à la réserve, « ça ne va pas », « j''ai froid » et « je suis essoufflé ». Les émettre tôt permet à l''encadrant d''agir avant que la situation ne se dégrade — c''est un réflexe de sécurité, jamais une gêne pour le groupe. Montrer un poisson relève de la communication d''agrément : utile pour partager, mais en rien obligatoire ni prioritaire.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-009', 'a', '« Je suis à la réserve » (50 bars)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-009', 'b', '« Ça ne va pas » et « j''ai froid »', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-009', 'c', '« Je suis essoufflé »', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-009', 'd', '« Regardez ce poisson »', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-010', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'communiquer-sa-pression-dair', 'Quand faut-il annoncer son passage à la réserve (50 bars) ?', 'Le passage à la réserve ne se demande pas : il s''annonce spontanément dès que l''aiguille atteint 50 bars, et la palanquée fait alors demi-tour ou entame la remontée — on ne finit jamais son bloc au fond. Attendre la question de l''encadrant, la sortie de l''eau ou pire, le bloc vide, prive la palanquée d''une information de sécurité essentielle à la gestion collective de l''air.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-010', 'a', 'Spontanément, dès que l''aiguille du manomètre atteint 50 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-010', 'b', 'Uniquement si l''encadrant le demande', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-010', 'c', 'Une fois revenu au bateau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-010', 'd', 'Quand le bloc est complètement vide', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-011', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'communiquer-sa-pression-dair', 'L''encadrant vous demande votre pression. Quelle réponse est toujours acceptée ?', 'Montrer son manomètre cadran tourné vers l''encadrant est la réponse universelle, toujours acceptée quelle que soit la convention de chiffres adoptée au briefing — car les conventions de doigts varient d''un club à l''autre et « le briefing fait foi ». Le signe OK ne répond pas à la question posée, hausser les épaules n''est pas un signe conventionnel, et l''ordinateur n''affiche pas la pression du bloc (sauf modèles à gestion d''air, hors programme N1).', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-011', 'a', 'Montrer son manomètre, cadran tourné vers lui', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-011', 'b', 'Faire le signe OK', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-011', 'c', 'Hausser les épaules si on ne sait pas', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-011', 'd', 'Montrer son ordinateur de plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-012', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'en-surface--se-signaler-de-loin', 'Comment signale-t-on « tout va bien » au bateau depuis la surface ?', 'L''« OK surface » se fait avec les deux bras levés joints au-dessus de la tête en formant un cercle (ou un seul bras si l''autre est occupé) : c''est un signe visible de loin, à faire en émergeant vers le bateau ou la surveillance de surface. Le bras agité est au contraire le signe de détresse qui déclenche les secours, le petit cercle pouce-index est invisible à distance et la voix ne porte pas à plusieurs dizaines de mètres.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-012', 'a', 'Les deux bras levés joints au-dessus de la tête, formant un cercle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-012', 'b', 'Un bras agité de grands mouvements latéraux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-012', 'c', 'Le cercle pouce-index, comme sous l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-012', 'd', 'En criant « ça va ! »', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-013', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'en-surface--se-signaler-de-loin', 'En surface, un plongeur agite un bras de grands mouvements latéraux. Que signifie ce geste ?', 'Un bras levé agité de grands mouvements latéraux est le signe de détresse en surface : il signifie « j''ai besoin d''assistance immédiate » et déclenche les secours — raison pour laquelle on ne le fait jamais « pour rire » ni pour saluer. Le « tout va bien » de surface est un geste immobile : les bras joints en cercle au-dessus de la tête.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-013', 'a', 'Il a besoin d''une assistance immédiate : c''est le signe de détresse surface', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-013', 'b', 'Il salue le bateau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-013', 'c', 'Il indique que tout va bien', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-013', 'd', 'Il demande la direction du mouillage', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-014', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'vivre-en-palanquée--les-règles-de-communication', 'Vous réalisez que vous avez perdu votre palanquée. Quelle est la procédure classique ?', 'La consigne classique (rappelée à chaque briefing) : recherche visuelle brève autour de soi et vers la surface — moins d''une minute — puis remontée lente en respirant normalement, gilet gonflé en surface, signe OK vers le bateau et attente ; la palanquée applique la même procédure et tout le monde se retrouve en surface. Repartir seul au fond aggrave la séparation, remonter en apnée expose à la surpression pulmonaire, et attendre indéfiniment au fond consomme l''air sans résoudre rien.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-014', 'a', 'Chercher visuellement moins d''une minute, puis remonter lentement en respirant normalement, gonfler le gilet en surface, faire OK vers le bateau et attendre', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-014', 'b', 'Partir seul au fond dans la direction probable du groupe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-014', 'c', 'Remonter en apnée le plus vite possible', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-014', 'd', 'Rester sur place au fond jusqu''à ce qu''on vous retrouve', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-signes-015', 'n1-signes-communication', 'n1', 'environnement', 'qcm', 'vivre-en-palanquée--les-règles-de-communication', 'Quelles règles de vie en palanquée s''appliquent au plongeur Niveau 1 ? Plusieurs réponses possibles.', 'La palanquée fonctionne comme une cordée : on reste à quelques mètres de l''encadrant, visible, ni au-dessus ni en dessous du groupe sans consigne ; on surveille régulièrement son binôme (bulles, comportement) ; et tout problème se montre immédiatement — chaque situation vue en cours a son signe. « Explorer librement » n''existe pas en plongée encadrée : on descend ensemble, on évolue ensemble, on remonte ensemble.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-015', 'a', 'Rester proche de l''encadrant et dans son champ de vision', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-015', 'b', 'Jeter un œil régulier à son binôme (contrôle mutuel)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-015', 'c', 'Montrer immédiatement tout problème sans attendre', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-signes-015', 'd', 'Explorer librement à condition de revenir toutes les cinq minutes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-001', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'le-courant-la-houle-et-la-visibilité', 'Dans quel sens commence-t-on une plongée lorsqu''il y a du courant ?', 'On commence la plongée face au courant : à l''aller, on est frais et le courant freine ; au retour, fatigué et le bloc entamé, on se laisse porter vers le point de sortie. Partir dans le sens du courant est le piège classique : le retour se transforme en lutte épuisante, droit vers l''essoufflement. Le courant est infatigable — le plongeur, non.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-001', 'a', 'Face au courant : le retour se fait ensuite en se laissant porter', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-001', 'b', 'Dans le sens du courant, pour économiser ses forces à l''aller', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-001', 'c', 'Perpendiculairement au courant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-001', 'd', 'Peu importe, le courant ne change rien', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-002', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'le-courant-la-houle-et-la-visibilité', 'En surface, un courant fort vous empêche de rejoindre le bateau à la nage. Que faites-vous ?', 'La règle : ne jamais s''épuiser contre un courant fort en surface — gilet gonflé pour flotter sans effort, signe vers le bateau, et c''est le bateau qui vient. Nager contre le courant mène à l''épuisement et à la détresse ; larguer son matériel est une mesure extrême injustifiée ici ; et redescendre seul, en fin de plongée, à l''écart de la palanquée, cumulerait les dangers.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-002', 'a', 'Je garde mon gilet gonflé, je fais signe au bateau et j''attends qu''il vienne me chercher', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-002', 'b', 'Je nage de toutes mes forces contre le courant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-002', 'c', 'Je largue mon bloc pour nager plus vite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-002', 'd', 'Je redescends sous l''eau pour éviter le courant', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-003', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'les-bateaux--le-danger-vient-den-haut', 'Que signifie le pavillon Alpha (bicolore blanc et bleu) hissé sur un bateau ?', 'Le pavillon Alpha du code international des signaux, blanc et bleu à bord échancré, signale un bateau ayant des plongeurs en immersion : les autres navires doivent s''en écarter et réduire leur vitesse. Il ne signale ni une panne, ni une zone de baignade, ni une régate. En pratique, tous les plaisanciers ne le connaissent pas : la prudence du plongeur (remonter au mouillage, tour d''horizon) reste indispensable.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-003', 'a', '« J''ai des plongeurs en immersion : restez à distance et à vitesse réduite »', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-003', 'b', '« Le bateau est en panne »', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-003', 'c', '« Zone de baignade surveillée »', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-003', 'd', '« Régate en cours »', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-004', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'les-bateaux--le-danger-vient-den-haut', 'Quels réflexes protègent du trafic des bateaux en fin de plongée ? Plusieurs réponses possibles.', 'L''hélice d''un bateau qui ignore votre présence est l''un des dangers les plus sérieux du plongeur : on remonte le long du mouillage ou près de la bouée, on termine la remontée en regardant la surface et en écoutant les bruits d''hélice, avec un tour d''horizon avant d''émerger, puis on reste groupés gilet gonflé. Compter sur la seule obligation des bateaux de s''écarter est illusoire : beaucoup de plaisanciers ne connaissent pas la signalisation.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-004', 'a', 'Remonter le long du mouillage chaque fois que possible', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-004', 'b', 'Faire un tour d''horizon en regardant et en écoutant avant d''émerger', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-004', 'c', 'Rester groupés en surface, gilet gonflé, et rejoindre la zone du bateau', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-004', 'd', 'Remonter n''importe où : les bateaux sont tenus de nous éviter', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-005', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'la-faune--regarder-sans-toucher', 'Après une piqûre de vive ou de rascasse, quelle est la conduite à tenir ?', 'Le venin des vives et des rascasses est thermolabile : il est détruit par la chaleur. La conduite à tenir est donc d''approcher une source de chaleur (eau chaude supportable) de la piqûre, puis de consulter. La glace ne détruit pas le venin, l''incision aggrave la plaie et le risque d''infection, et frotter au sable également. En prévention : ne jamais poser mains ni genoux sur le fond, où la vive se tient ensablée.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-005', 'a', 'Approcher une source de chaleur (eau chaude) car le venin est thermolabile, puis consulter', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-005', 'b', 'Appliquer de la glace immédiatement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-005', 'c', 'Inciser la plaie pour faire sortir le venin', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-005', 'd', 'Frotter énergiquement avec du sable', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-006', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'la-faune--regarder-sans-toucher', 'Après un contact avec une méduse, que faut-il faire ?', 'On rince à l''eau de mer — surtout pas à l''eau douce, qui fait éclater les cellules urticantes restées sur la peau et aggrave la brûlure — puis on retire les filaments sans frotter et on consulte en cas de réaction importante. Frotter déclenche les cellules urticantes encore intactes. Rappel de prévention : on ne touche pas les méduses, même échouées sur la plage, car elles restent urticantes.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-006', 'a', 'Rincer à l''eau de mer, retirer les filaments sans frotter, consulter si la réaction est importante', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-006', 'b', 'Rincer abondamment à l''eau douce', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-006', 'c', 'Frotter la zone avec une serviette', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-006', 'd', 'Ne rien faire, la brûlure disparaît toujours seule', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-007', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'la-faune--regarder-sans-toucher', 'Quelle est la règle d''or vis-à-vis de la faune sous-marine ?', 'La quasi-totalité des blessures liées à la faune sont des accidents de contact provoqué : une main posée au mauvais endroit, un animal saisi ou acculé. La règle d''or protège donc à la fois le plongeur et le milieu : on ne touche rien, on ne poursuit rien, on ne nourrit rien. Le nourrissage modifie les comportements et déséquilibre le milieu, et même un animal « inoffensif » ou lent souffre d''être manipulé.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-007', 'a', 'On ne touche rien, on ne poursuit rien, on ne nourrit rien', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-007', 'b', 'On peut toucher les animaux inoffensifs', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-007', 'c', 'On peut nourrir les poissons pour les approcher', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-007', 'd', 'On peut saisir les animaux lents comme les étoiles de mer', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-008', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'plonger-écoresponsable--les-gestes-qui-comptent-sous-leau', 'Quel est le geste écologique numéro un du plongeur ?', 'Un plongeur stabilisé ne laboure pas le fond, ne casse rien et ne soulève pas le sédiment : la maîtrise de la flottabilité est LE geste écologique numéro un — votre travail technique du Niveau 1 est aussi un acte de protection. Ramasser des coquillages est un prélèvement (souvent, une coquille « vide » abrite un occupant), le nourrissage déséquilibre le milieu, et palmer au ras du fond casse les organismes fixés et trouble l''eau.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-008', 'a', 'Maîtriser sa flottabilité pour ne jamais toucher le fond', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-008', 'b', 'Ramasser les coquillages pour les protéger', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-008', 'c', 'Nourrir les poissons avec des aliments naturels', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-008', 'd', 'Palmer près du fond pour observer de plus près', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-009', 'n1-milieu-naturel', 'n1', 'environnement', 'vrai-faux', 'plonger-écoresponsable--les-gestes-qui-comptent-sous-leau', 'Il est acceptable de remonter une coquille vide comme souvenir de plongée.', 'C''est faux : même une coquille apparemment vide abrite souvent un occupant (bernard-l''hermite, petits organismes), et le principe est de ne rien prélever du milieu — ni coquillage, ni étoile de mer, ni « souvenir ». La photo est le seul prélèvement qui ne laisse pas de trace. Dans les zones protégées, le prélèvement est de surcroît sanctionné.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-009', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-009', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-milieu-010', 'n1-milieu-naturel', 'n1', 'environnement', 'qcm', 'avant-et-après-la-plongée--lécoresponsabilité-continue-à-terre', 'Quels gestes écoresponsables s''appliquent avant et après la plongée ? Plusieurs réponses possibles.', 'L''écoresponsabilité continue à terre : certains filtres chimiques des crèmes solaires dégradent coraux et larves (d''où le choix de protections adaptées, ou mieux, de vêtements), rien ne passe par-dessus bord — un seul mégot pollue des centaines de litres d''eau — et signaler ses observations (pollution, filet perdu, espèce inhabituelle) alimente la protection du site. « Biodégradable » ne veut pas dire sans impact : aucun déchet ne va à la mer.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-010', 'a', 'Préférer une crème solaire respectueuse du milieu marin, appliquée longtemps avant la mise à l''eau', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-010', 'b', 'Ne rien jeter par-dessus bord, pas même un mégot', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-010', 'c', 'Signaler à l''encadrant une pollution ou un filet perdu observés en plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-milieu-010', 'd', 'Jeter les restes de pique-nique à la mer puisqu''ils sont biodégradables', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-001', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'le-brevet-niveau-1-et-laptitude-pe20', 'Que signifie l''aptitude PE20 attestée par le Niveau 1 ?', 'PE20 signifie « Plongeur Encadré à 20 mètres » : le titulaire évolue toujours au sein d''une palanquée conduite par un encadrant, dans l''espace de 0 à 20 m. L''autonomie à 20 m (PA20) est une aptitude du Niveau 2, et le sigle n''a rien à voir avec un nombre de plongées ou une taille d''équipe. Le « E » de « encadré » est le mot clé des prérogatives du N1.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-001', 'a', 'Plongeur Encadré jusqu''à 20 mètres', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-001', 'b', 'Plongeur Expérimenté, 20 plongées minimum', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-001', 'c', 'Plongeur Autonome jusqu''à 20 mètres', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-001', 'd', 'Plongée En équipe de 20 personnes maximum', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-002', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'le-brevet-niveau-1-et-laptitude-pe20', 'En exploration, qui conduit la palanquée d''un plongeur Niveau 1 ?', 'En exploration, la palanquée d''un N1 est menée par un guide de palanquée, c''est-à-dire un plongeur Niveau 4 au minimum ; en situation d''enseignement, c''est un moniteur (E2 minimum selon la profondeur). Un N2 n''a pas les prérogatives d''encadrement, et des N1 ne plongent jamais entre eux seuls : le « E » de PE20 signifie précisément « encadré ».', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-002', 'a', 'Un guide de palanquée, plongeur Niveau 4 au minimum', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-002', 'b', 'Le plongeur N1 le plus expérimenté du groupe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-002', 'c', 'N''importe quel plongeur Niveau 2', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-002', 'd', 'Personne : les N1 plongent entre eux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-003', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'le-brevet-niveau-1-et-laptitude-pe20', 'Quelle est la profondeur maximale de la plongée à l''air en France ?', 'La réglementation française limite la plongée à l''air à 60 mètres, tous niveaux confondus : c''est le plafond absolu de l''activité à l''air. Les 20 m correspondent à l''espace du plongeur PE20 (Niveau 1) et les 40 m à celui du PE40 (Niveau 2 encadré) : ce sont des prérogatives individuelles, pas la limite générale de l''air.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-003', 'a', '40 mètres', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-003', 'b', '60 mètres', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-003', 'c', '100 mètres', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-003', 'd', '20 mètres', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-004', 'n1-prerogatives', 'n1', 'reglementation', 'vrai-faux', 'le-brevet-niveau-1-et-laptitude-pe20', 'Deux plongeurs Niveau 1 peuvent plonger seuls ensemble, sans encadrant, jusqu''à 20 m.', 'C''est faux : le Niveau 1 est un plongeur encadré (PE20), qui évolue toujours en palanquée conduite par un guide de palanquée, jamais entre débutants seuls. La seule ouverture vers l''autonomie au N1 est la qualification PA12 (plongeurs majeurs, formation complémentaire, 0-12 m, sous l''autorité d''un DP) — mais elle ne permet en aucun cas de plonger à 20 m sans guide.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-004', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-004', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-005', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'la-palanquée--votre-cellule-de-plongée', 'Combien de plongeurs encadrés une palanquée peut-elle compter au maximum ?', 'Le Code du sport limite la palanquée encadrée à 4 plongeurs encadrés au maximum, plus le guide de palanquée (un plongeur autonome supplémentaire pouvant s''y joindre dans les conditions prévues par les textes). Cette taille n''est pas arbitraire : c''est le maximum qu''un encadrant peut surveiller efficacement. Aucune expérience du guide ne permet de dépasser cet effectif réglementaire.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-005', 'a', '4 plongeurs encadrés, plus le guide de palanquée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-005', 'b', '8 plongeurs encadrés', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-005', 'c', '2 plongeurs encadrés seulement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-005', 'd', 'Aucune limite si le guide est expérimenté', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-006', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'la-palanquée--votre-cellule-de-plongée', 'Qu''est-ce qu''une palanquée ?', 'La palanquée est la cellule de plongée : le petit groupe qui descend ensemble, évolue ensemble et remonte ensemble, avec les mêmes paramètres de profondeur, de durée et de trajet. Il n''y a pas de « je vous rejoins » ni de « je remonte seul ». L''ensemble des plongeurs du bateau se répartit en plusieurs palanquées, constituées par le directeur de plongée sur la fiche de sécurité.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-006', 'a', 'Le groupe de plongeurs qui effectuent ensemble la même plongée : mêmes profondeur, trajet et durée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-006', 'b', 'L''ensemble des plongeurs présents sur le bateau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-006', 'c', 'Le matériel collectif de secours', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-006', 'd', 'La liste d''inscription à la sortie club', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-007', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'la-palanquée--votre-cellule-de-plongée', 'Quelles sont les missions du guide de palanquée pendant la plongée ? Plusieurs réponses possibles.', 'Le guide de palanquée conduit la plongée : il choisit le parcours dans le cadre fixé par le DP, surveille chaque membre, gère la profondeur, la durée, l''air et la remontée, et prend en charge tout incident. Fixer les paramètres maximaux de chaque palanquée est en revanche la mission du directeur de plongée, qui organise l''activité depuis la surface — c''est la distinction classique GP/DP attendue à l''examen.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-007', 'a', 'Choisir le parcours dans le cadre fixé par le directeur de plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-007', 'b', 'Surveiller chaque membre et gérer profondeur, durée et remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-007', 'c', 'Prendre en charge tout incident', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-007', 'd', 'Fixer les paramètres maximaux de toutes les palanquées du bateau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-008', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'le-directeur-de-plongée-et-lorganisation-dune-sortie', 'Parmi ces missions, lesquelles relèvent du directeur de plongée (DP) ? Plusieurs réponses possibles.', 'Le DP est le responsable de l''organisation : il décide du site et des horaires (il peut annuler si les conditions l''exigent), fixe les paramètres maximaux de chaque palanquée selon les aptitudes, garantit la présence du matériel de secours (oxygénothérapie, trousse, moyen d''alerte, plan de secours) et fait remplir la fiche de sécurité qui liste qui est dans l''eau. Le portage du matériel relève de chacun — et n''a rien de réglementaire.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-008', 'a', 'Fixer pour chaque palanquée les paramètres maximaux (profondeur, durée)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-008', 'b', 'S''assurer de la présence du matériel de secours sur le site', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-008', 'c', 'Faire remplir la fiche de sécurité', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-008', 'd', 'Porter le bloc de chaque plongeur jusqu''au bateau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-009', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'le-directeur-de-plongée-et-lorganisation-dune-sortie', 'Qu''est-ce que la fiche de sécurité (ou feuille de palanquée) ?', 'La fiche de sécurité est le document réglementaire tenu par le DP : liste nominative des palanquées, aptitudes de chacun, fonction dans la palanquée, paramètres prévus puis réalisés (profondeurs, durées, heures). Elle permet de savoir à tout instant qui est dans l''eau — c''est pourquoi on annonce ses paramètres au DP en sortant. Ce n''est ni une notice, ni une assurance, ni un carnet personnel.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-009', 'a', 'La liste nominative des palanquées avec les aptitudes de chacun et les paramètres prévus et réalisés', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-009', 'b', 'La notice d''utilisation du matériel de secours', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-009', 'c', 'Le contrat d''assurance du club', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-009', 'd', 'Le carnet de plongée du directeur de plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-010', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'le-directeur-de-plongée-et-lorganisation-dune-sortie', 'Que doit faire le plongeur en sortant de l''eau après la plongée ?', 'Au retour, chaque palanquée annonce ses paramètres réalisés (profondeur maximale, durée) au DP, qui complète la fiche de sécurité : c''est ainsi que l''organisation sait que tout le monde est sorti de l''eau et dans quelles conditions. Partir ranger son matériel sans se signaler peut déclencher une recherche inutile ; l''information doit être transmise immédiatement, et c''est le DP qui tient le document.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-010', 'a', 'Annoncer ses paramètres (profondeur, durée) au DP pour la fiche de sécurité', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-010', 'b', 'Ranger son matériel sans rien dire à personne', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-010', 'c', 'Attendre le lendemain pour transmettre ses paramètres', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-010', 'd', 'Signer la fiche de sécurité à la place du DP', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-011', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'vos-documents-et-votre-matériel-obligatoire', 'Quels documents une structure demande-t-elle classiquement avant de vous faire plonger ? Plusieurs réponses possibles.', 'Le trio classique : carte de brevet qui atteste le niveau, licence fédérale (adhésion et assurance en responsabilité civile), et justificatif médical selon les règles en vigueur (certificat ou questionnaire de santé) — auxquels s''ajoute le carnet de plongée qui justifie l''expérience. Le permis bateau n''a rien à voir avec la pratique de la plongée : il concerne la conduite des navires.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-011', 'a', 'La carte de brevet (niveau)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-011', 'b', 'La licence fédérale en cours de validité', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-011', 'c', 'Le certificat médical ou questionnaire de santé selon les règles en vigueur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-011', 'd', 'Le permis bateau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-012', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'vos-documents-et-votre-matériel-obligatoire', 'Quelle assurance la licence fédérale FFESSM inclut-elle ?', 'La licence inclut une assurance en responsabilité civile : elle couvre les dommages que vous causez à autrui. Elle ne couvre pas vos propres dommages — frais de caisson, rapatriement, accidents corporels — qui relèvent des assurances individuelles complémentaires facultatives (type « loisir »), fortement conseillées, notamment à l''étranger. Le matériel personnel n''est pas davantage couvert par la licence.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-012', 'a', 'Une assurance en responsabilité civile (dommages causés à autrui)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-012', 'b', 'Une assurance tous risques couvrant le plongeur lui-même, caisson compris', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-012', 'c', 'Une assurance du matériel personnel', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-012', 'd', 'Aucune assurance', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-013', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'vos-documents-et-votre-matériel-obligatoire', 'Quel équipement le Code du sport impose-t-il au plongeur encadré en exploration ?', 'Le plongeur encadré doit disposer d''un gilet stabilisateur à gonflage au gaz et d''un détendeur avec manomètre (ou équivalent) pour contrôler sa pression. En zone PE20 encadrée, le contrôle des paramètres de plongée est assuré par le guide : l''ordinateur personnel n''est pas exigé. Les deux détendeurs complets et le parachute par palanquée concernent le plongeur autonome (PA), pas l''encadré du Niveau 1.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-013', 'a', 'Un gilet stabilisateur avec gonflage au gaz et un détendeur avec manomètre', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-013', 'b', 'Un ordinateur de plongée personnel obligatoire dès le Niveau 1', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-013', 'c', 'Un parachute de palier individuel', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-013', 'd', 'Deux détendeurs complets sur deux sorties indépendantes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-014', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'pa12-et-la-suite--vers-lautonomie', 'Quelles sont les conditions de l''aptitude PA12 ? Plusieurs réponses possibles.', 'Le PA12 (Plongeur Autonome à 12 mètres) permet de plonger sans guide entre plongeurs majeurs disposant de cette aptitude, dans l''espace 0-12 m, sous l''autorité d''un DP et à 3 plongeurs autonomes au maximum par palanquée ; à la FFESSM, il peut être délivré à un N1 majeur après une formation complémentaire (orientation, gestion de l''air, assistance). L''autonomie à 20 m est le PA20, une aptitude du Niveau 2 — pas du PA12.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-014', 'a', 'Être majeur et avoir suivi la formation complémentaire correspondante', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-014', 'b', 'Évoluer entre 0 et 12 m, sous l''autorité d''un directeur de plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-014', 'c', 'Palanquée limitée à 3 plongeurs autonomes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-014', 'd', 'Plonger jusqu''à 20 m sans guide', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n1-regl-015', 'n1-prerogatives', 'n1', 'reglementation', 'qcm', 'pa12-et-la-suite--vers-lautonomie', 'Vos prérogatives de plongeur sont :', 'Les prérogatives sont un plafond, pas un objectif : le DP peut toujours fixer des limites plus strictes (site difficile, conditions moyennes, plongeur peu récent), et vous pouvez toujours demander une plongée moins profonde ou renoncer si vous ne le sentez pas. On plonge dans le cadre le plus prudent entre les textes, les consignes du DP et son propre ressenti — les prérogatives ne sont ni un droit absolu ni une simple recommandation : les dépasser rend la plongée irrégulière.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-015', 'a', 'Un plafond : le DP peut fixer des limites plus strictes et vous pouvez toujours renoncer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-015', 'b', 'Un objectif à atteindre à chaque plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-015', 'c', 'Un droit absolu que personne ne peut restreindre', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n1-regl-015', 'd', 'Une simple recommandation sans valeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-001', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'pression-atmosphérique-relative-absolue', 'Quelle est la pression absolue à 26 m de profondeur ?', 'La pression relative à 26 m vaut $26/10 = 2{,}6$ bars ; la pression absolue ajoute le bar atmosphérique : $P_{abs} = 1 + 2{,}6 = 3{,}6$ bars. Répondre 2,6 bars est l''erreur d''examen la plus fréquente (oubli de la pression atmosphérique) ; 26 bars confond mètres et bars ; 4 bars correspondrait à 30 m.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-001', 'a', '2,6 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-001', 'b', '3,6 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-001', 'c', '26 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-001', 'd', '4 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-002', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'pression-atmosphérique-relative-absolue', 'Votre profondimètre indique une pression relative de 2,6 bars. À quelle profondeur êtes-vous ?', 'La règle « 1 bar tous les 10 m » s''inverse : une pression relative de 2,6 bars correspond à $2{,}6 \times 10 = 26$ m. Attention : le profondimètre mesure la pression relative (il affiche 0 en surface), il ne faut donc pas retrancher le bar atmosphérique — répondre 16 m serait cette erreur-là. La réponse 36 m ajouterait au contraire un bar indûment.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-002', 'a', '16 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-002', 'b', '26 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-002', 'c', '36 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-002', 'd', '2,6 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-003', 'n2-pression-mariotte', 'n2', 'physique', 'qcm', 'pression-atmosphérique-relative-absolue', 'Quelle pression le profondimètre mesure-t-il, et quelle pression utilisent les lois physiques (Mariotte, Dalton) ?', 'Le profondimètre mesure la pression relative (le poids de l''eau seule : il affiche 0 en surface), tandis que les lois physiques — Mariotte, Dalton — s''appliquent toujours avec la pression absolue, somme de la pression relative et du bar atmosphérique. L''erreur d''un bar dans un calcul d''examen vient presque toujours de cette confusion : utiliser 2 bars à 20 m au lieu de 3.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-003', 'a', 'Le profondimètre mesure la pression relative ; les lois physiques utilisent la pression absolue', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-003', 'b', 'Le profondimètre mesure la pression absolue ; les lois physiques utilisent la pression relative', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-003', 'c', 'Les deux utilisent la pression relative', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-003', 'd', 'Les deux utilisent la pression atmosphérique', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-004', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'pression-atmosphérique-relative-absolue', 'Un énoncé indique une pression absolue de 4 bars. À quelle profondeur le plongeur se trouve-t-il ?', 'On retranche d''abord la pression atmosphérique : $P_{rel} = 4 - 1 = 3$ bars, puis on convertit en profondeur : $3 \times 10 = 30$ m. Répondre 40 m revient à convertir directement la pression absolue sans retirer le bar d''atmosphère — le piège symétrique de l''oubli habituel. 20 m correspondrait à une pression absolue de 3 bars.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-004', 'a', '40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-004', 'b', '30 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-004', 'c', '26 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-004', 'd', '20 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-005', 'n2-pression-mariotte', 'n2', 'physique', 'qcm', 'la-loi-de-boyle-mariotte', 'Quel est l''énoncé correct de la loi de Boyle-Mariotte ?', 'La loi de Boyle-Mariotte énonce qu''à température constante, le produit pression × volume d''une masse de gaz reste constant : si la pression double, le volume est divisé par deux. La proposition b inverse la relation (elle est inversement, pas directement, proportionnelle) ; la proposition c est la loi de Dalton (pressions partielles) et la proposition d la loi de Henry (dissolution) — trois lois à ne pas confondre à l''examen.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-005', 'a', 'À température constante, le volume d''une masse de gaz est inversement proportionnel à la pression : $P_1 \times V_1 = P_2 \times V_2$', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-005', 'b', 'La pression d''un gaz est proportionnelle à son volume', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-005', 'c', 'Chaque gaz d''un mélange exerce une pression proportionnelle à son pourcentage', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-005', 'd', 'La quantité de gaz dissoute dans un liquide est proportionnelle à sa pression partielle', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-006', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'la-loi-de-boyle-mariotte', 'Un ballon souple contient 6 L d''air en surface. Quel est son volume à 20 m ?', 'États : $P_1 = 1$ bar, $V_1 = 6$ L en surface ; à 20 m, $P_2 = 1 + 20/10 = 3$ bars. Mariotte : $V_2 = \dfrac{P_1 \times V_1}{P_2} = \dfrac{1 \times 6}{3} = 2$ L. Répondre 3 L revient à diviser par 2 bars (oubli du bar atmosphérique) ; 18 L multiplierait au lieu de diviser (l''air se comprime à la descente) ; 6 L supposerait un récipient rigide.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-006', 'a', '3 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-006', 'b', '2 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-006', 'c', '18 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-006', 'd', '6 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-007', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'la-loi-de-boyle-mariotte', 'Un volume de 2 L d''air est pris à 20 m. Quel volume occupe-t-il de retour en surface ?', 'États : $P_1 = 3$ bars (20 m), $V_1 = 2$ L ; en surface $P_2 = 1$ bar. Mariotte : $V_2 = \dfrac{3 \times 2}{1} = 6$ L — le volume triple. Répondre 4 L correspond à un facteur 2 (pression relative au lieu d''absolue) ; 0,67 L inverserait le sens de variation, or un volume augmente toujours à la remontée. C''est exactement le mécanisme qui menace les poumons d''un plongeur qui bloque sa respiration.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-007', 'a', '4 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-007', 'b', '6 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-007', 'c', '2 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-007', 'd', '0,67 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-008', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'les-volumes-dair-du-plongeur--oreilles-masque-poumons-gilet', 'Vous injectez 3 L d''air dans votre gilet à 40 m. Sans purge, quel volume cet air occupe-t-il à 10 m ?', 'États : $P_1 = 5$ bars (40 m), $V_1 = 3$ L ; à 10 m, $P_2 = 2$ bars. Mariotte : $V_2 = \dfrac{5 \times 3}{2} = 7{,}5$ L — le volume a plus que doublé, d''où l''accélération dangereuse de la remontée si l''on ne purge pas. Répondre 12 L appliquerait un facteur 4 erroné (rapport des profondeurs), 6 L un facteur 2 approximatif, et 1,2 L inverse le sens de variation.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-008', 'a', '7,5 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-008', 'b', '12 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-008', 'c', '6 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-008', 'd', '1,2 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-009', 'n2-pression-mariotte', 'n2', 'physique', 'qcm', 'les-volumes-dair-du-plongeur--oreilles-masque-poumons-gilet', 'Pourquoi la remontée en bloquant sa respiration est-elle si dangereuse ?', 'Le détendeur délivre l''air à la pression ambiante du fond : un plongeur qui inspire à 20 m (3 bars) et remonte en bloquant sa respiration verrait ce volume tendre à tripler avant la surface — les alvéoles se déchirent bien avant : c''est la surpression pulmonaire, l''accident le plus grave de la plongée. La règle absolue : ne jamais bloquer sa respiration à la remontée. La syncope hypoxique concerne l''apnéiste, la dissolution d''azote la descente, et le détendeur ne se bloque pas.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-009', 'a', 'L''air pulmonaire, délivré à la pression du fond, tend à se dilater et peut déchirer les alvéoles : c''est la surpression pulmonaire', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-009', 'b', 'Le manque d''oxygène provoque une syncope immédiate', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-009', 'c', 'L''azote se dissout plus vite dans le sang', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-009', 'd', 'Le détendeur se bloque si l''on ne respire pas', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-010', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'la-bouteille-retournée--lexpérience-de-la-cloche-à-air', 'Une bouteille rigide de 1,5 L, retournée ouverture vers le bas et pleine d''air, est descendue à 30 m. Quel volume d''air reste-t-il dans la bouteille ?', 'États : $P_1 = 1$ bar, $V_1 = 1{,}5$ L ; à 30 m, $P_2 = 1 + 30/10 = 4$ bars. Mariotte : $V_2 = \dfrac{1 \times 1{,}5}{4} = 0{,}375$ L — l''eau a envahi les trois quarts de la bouteille. Répondre 0,5 L divise par 3 bars (oubli du bar atmosphérique), 0,25 L par 6 sans justification, et 1,5 L supposerait que l''eau ne peut pas entrer, alors que l''ouverture la laisse monter à mesure que l''air se comprime.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-010', 'a', '0,375 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-010', 'b', '0,5 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-010', 'c', '1,5 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-010', 'd', '0,25 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-011', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'le-bloc-de-plongée--de-lair-comprimé-en-grande-quantité', 'Quelle quantité d''air détendu contient un bloc de 12 L gonflé à 200 bars ?', 'Le bloc est une enceinte rigide : Mariotte donne le volume qu''occuperait son air ramené à 1 bar, soit $V_{détendu} = V_{bloc} \times P_{bloc} = 12 \times 200 = 2400$ L. La réponse 1200 L correspondrait à un bloc de 6 L ou à une pression de 100 bars, 212 L additionne au lieu de multiplier, et 24 000 L décale d''un facteur 10. Ce calcul est la porte d''entrée de tous les calculs d''autonomie.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-011', 'a', '1200 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-011', 'b', '2400 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-011', 'c', '212 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-011', 'd', '24 000 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-012', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'le-bloc-de-plongée--de-lair-comprimé-en-grande-quantité', 'Il reste 80 bars dans un bloc de 15 L. Quelle quantité d''air détendu contient-il encore ?', 'Même principe que pour un bloc plein : $V_{détendu} = 15 \times 80 = 1200$ L d''air ramené à la pression de surface. La réponse 95 additionne volume et pression, 800 L utiliserait un bloc de 10 L, et 3000 L correspondrait au bloc gonflé à 200 bars. Savoir refaire ce calcul avec la pression restante est indispensable pour estimer son air disponible en cours de plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-012', 'a', '1200 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-012', 'b', '95 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-012', 'c', '800 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-012', 'd', '3000 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-mariotte-013', 'n2-pression-mariotte', 'n2', 'physique', 'calcul', 'méthode-de-résolution-des-calculs-dexamen', 'Un parachute de relevage contient 10 L d''air à 40 m. On le laisse remonter sans purge. Quel est son volume en surface ?', 'À 40 m, $P_1 = 5$ bars et $V_1 = 10$ L, donc $P \times V = 50$ ; en surface ($P_2 = 1$ bar), $V_2 = 50/1 = 50$ L : le volume quintuple. Répondre 40 L applique le rapport des profondeurs au lieu du rapport des pressions absolues, et 25 L correspond au volume à 10 m ($50/2$), pas en surface. Notez que la moitié de l''expansion se produit dans les 10 derniers mètres : la zone proche de la surface est la plus dangereuse.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-013', 'a', '50 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-013', 'b', '40 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-013', 'c', '25 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-mariotte-013', 'd', '14 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-001', 'n2-archimede', 'n2', 'physique', 'qcm', 'le-principe-darchimède', 'Quel est l''énoncé correct du principe d''Archimède ?', 'Le principe d''Archimède : tout corps plongé dans un fluide reçoit une poussée verticale dirigée du bas vers le haut, égale au poids du volume de fluide déplacé — elle résulte de la différence de pression entre la face inférieure et la face supérieure de l''objet. La proposition b confond la poussée avec le poids du corps lui-même, la c décrit la loi de Mariotte appliquée aux gaz, et la d n''a aucun sens physique : c''est le rapport poids/volume qui décide, pas la masse seule.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-001', 'a', 'Tout corps plongé dans un fluide reçoit une poussée verticale, du bas vers le haut, égale au poids du volume de fluide déplacé', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-001', 'b', 'Tout corps plongé dans un fluide subit une force égale à son propre poids', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-001', 'c', 'Tout corps immergé voit son volume diminuer proportionnellement à la pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-001', 'd', 'Tout corps immergé flotte si sa masse est inférieure à 100 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-002', 'n2-archimede', 'n2', 'physique', 'calcul', 'le-principe-darchimède', 'Un bloc a un volume extérieur de 14 L. Quelle poussée d''Archimède reçoit-il, entièrement immergé en eau de mer (1,025 kg/L) ?', 'La poussée vaut le poids du volume d''eau déplacé : $P_{Arch} = V \times \rho = 14 \times 1{,}025 = 14{,}35$ kg. La réponse 14 kg utilise la masse volumique de l''eau douce (1 kg/L) au lieu de l''eau de mer ; 13,65 kg retranche au lieu de multiplier ; 1,025 kg oublie le volume. C''est le volume extérieur qui compte, pas le volume d''air intérieur du bloc.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-002', 'a', '14,35 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-002', 'b', '14 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-002', 'c', '13,65 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-002', 'd', '1,025 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-003', 'n2-archimede', 'n2', 'physique', 'calcul', 'poids-réel-poussée-poids-apparent', 'Une ancre pèse 30 kg pour un volume de 4 L. Quel est son poids apparent en eau de mer (1,025 kg/L) ?', 'Poussée : $P_{Arch} = 4 \times 1{,}025 = 4{,}1$ kg ; poids apparent : $P_{app} = P_{réel} - P_{Arch} = 30 - 4{,}1 = 25{,}9$ kg. Le poids apparent étant positif, l''ancre coule, mais la soulever sous l''eau ne demande « que » 25,9 kg d''effort. Répondre 34,1 kg additionne la poussée au lieu de la retrancher, 26 kg utilise l''eau douce (poussée 4 kg), et 30 kg ignore complètement la poussée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-003', 'a', '25,9 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-003', 'b', '34,1 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-003', 'c', '26 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-003', 'd', '30 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-004', 'n2-archimede', 'n2', 'physique', 'qcm', 'poids-réel-poussée-poids-apparent', 'Un corps immergé a un poids apparent négatif. Que fait-il ?', 'Le poids apparent est $P_{app} = P_{réel} - P_{Arch}$ : s''il est négatif, la poussée d''Archimède dépasse le poids et le corps remonte — flottabilité positive. Le piège d''examen est justement d''associer « négatif » à « qui coule » : c''est l''inverse. Un poids apparent positif fait couler, un poids apparent nul laisse le corps équilibré entre deux eaux.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-004', 'a', 'Il remonte : sa flottabilité est positive', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-004', 'b', 'Il coule : sa flottabilité est négative', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-004', 'c', 'Il reste équilibré entre deux eaux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-004', 'd', 'Il tourne sur lui-même', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-005', 'n2-archimede', 'n2', 'physique', 'qcm', 'le-plongeur--un-corps-à-flottabilité-réglable', 'Quel est le critère d''un bon lestage pour le plongeur Niveau 2 ?', 'Le lestage se vérifie dans la situation la plus défavorable : en fin de plongée, bloc presque vide (donc allégé d''environ 2 kg), le plongeur doit pouvoir tenir son palier à 3 m gilet vide, en respiration normale, sans remonter malgré lui. Couler dès la mise à l''eau poumons pleins signe un surlestage ; ne jamais avoir à gonfler le gilet au fond aussi ; et flotter en surface même en expirant signe un sous-lestage qui rendra le palier intenable.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-005', 'a', 'Pouvoir tenir son palier à 3 m en fin de plongée, bloc presque vide, gilet vide, en respiration normale', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-005', 'b', 'Couler rapidement dès la mise à l''eau, gilet vide et poumons pleins', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-005', 'c', 'Pouvoir descendre sans jamais gonfler le gilet au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-005', 'd', 'Flotter en surface même gilet vide et en expiration complète', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-006', 'n2-archimede', 'n2', 'physique', 'calcul', 'calculs-de-lestage-pas-à-pas', 'Un plongeur équipé (sans lest) pèse 80 kg pour un volume total de 82 L. Quel lestage pour l''équilibrer en eau de mer (1,025 kg/L) ?', 'Poussée : $82 \times 1{,}025 = 84{,}05$ kg ; poids apparent sans lest : $80 - 84{,}05 = -4{,}05$ kg, soit une flottabilité positive d''environ 4 kg. Pour l''équilibrer, on ajoute un lest qui annule cette flottabilité (le volume du plomb est négligé) : environ 4 kg. Répondre 2 kg correspond au même plongeur en eau douce (poussée 82 kg) — c''est le piège du milieu ; il ne coule pas puisque la poussée dépasse son poids.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-006', 'a', 'Environ 4 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-006', 'b', 'Environ 2 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-006', 'c', 'Aucun lest : il coule déjà', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-006', 'd', 'Environ 6 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-007', 'n2-archimede', 'n2', 'physique', 'calcul', 'calculs-de-lestage-pas-à-pas', 'Le même plongeur (80 kg, 82 L) plonge en eau douce (1 kg/L). Quel lestage lui faut-il pour être équilibré ?', 'En eau douce, la poussée vaut $82 \times 1 = 82$ kg et le poids apparent sans lest $80 - 82 = -2$ kg : il faut environ 2 kg de lest pour l''équilibrer. La comparaison avec l''eau de mer (4 kg) illustre la règle pratique : on se leste davantage en mer qu''en lac, car l''eau salée porte plus. Un plongeur qui passe de la carrière à la mer sans réajuster serait sous-lesté et incapable de tenir son palier.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-007', 'a', 'Environ 2 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-007', 'b', 'Environ 4 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-007', 'c', 'Environ 8 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-007', 'd', 'Aucun lest', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-008', 'n2-archimede', 'n2', 'physique', 'calcul', 'calculs-de-lestage-pas-à-pas', 'Un plongeur équipé et lesté pèse 92 kg et il est parfaitement équilibré en eau de mer (1,025 kg/L). Quel est son volume ?', 'À l''équilibre, le poids apparent est nul : $P_{réel} = P_{Arch}$, donc $92 = V \times 1{,}025$, d''où $V = 92 / 1{,}025 \approx 89{,}8$ L. Répondre 94,3 L multiplie au lieu de diviser, et 92 L suppose une masse volumique de 1 kg/L (eau douce). Cet exercice « inverse » est un classique d''examen : il faut savoir isoler chaque variable de la relation $P_{app} = P_{réel} - V \times \rho$.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-008', 'a', 'Environ 89,8 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-008', 'b', 'Environ 94,3 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-008', 'c', '92 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-008', 'd', 'Environ 82 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-009', 'n2-archimede', 'n2', 'physique', 'calcul', 'les-variations-de-flottabilité-pendant-la-plongée', 'Un plongeur consomme 1500 L d''air détendu pendant sa plongée (masse de l''air : 1,2 g/L). De combien sa flottabilité a-t-elle varié ?', 'L''air a une masse : $1500 \times 1{,}2 = 1800$ g $= 1{,}8$ kg. Le poids réel du plongeur a diminué de 1,8 kg sans changement de volume : son poids apparent a baissé d''autant, donc sa flottabilité a augmenté — il est devenu « positif » de 1,8 kg et devra purger ou se montrer vigilant au palier. L''idée que « l''air ne pèse rien » est le piège classique, et 18 kg décale d''un facteur 10. C''est la raison pour laquelle le lestage se vérifie bloc presque vide.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-009', 'a', 'Il s''est allégé d''environ 1,8 kg : sa flottabilité a augmenté d''autant', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-009', 'b', 'Il s''est alourdi de 1,8 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-009', 'c', 'Sa flottabilité n''a pas changé, l''air ne pèse rien', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-009', 'd', 'Il s''est allégé de 18 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-010', 'n2-archimede', 'n2', 'physique', 'qcm', 'les-variations-de-flottabilité-pendant-la-plongée', 'Pourquoi la flottabilité du plongeur varie-t-elle pendant la plongée ? Plusieurs réponses possibles.', 'Trois phénomènes modifient l''équilibre en permanence : les microbulles du néoprène s''écrasent en profondeur (perte de poussée à la descente), le bloc perd la masse de l''air consommé (environ 2 kg entre 200 et 50 bars pour un 12 L), et le volume du gilet suit la loi de Mariotte à chaque changement de profondeur. Le poids du corps du plongeur, lui, ne varie évidemment pas avec la profondeur — la pesanteur ne dépend pas de la pression.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-010', 'a', 'La combinaison s''écrase avec la profondeur et perd de la poussée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-010', 'b', 'Le bloc s''allège à mesure que l''air est consommé', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-010', 'c', 'L''air du gilet se comprime ou se dilate avec la pression', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-010', 'd', 'Le poids du plongeur lui-même augmente avec la profondeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-archimede-011', 'n2-archimede', 'n2', 'physique', 'qcm', 'archimède-au-service-de-la-sécurité', 'Pourquoi le palier à 3 m est-il la zone la plus difficile à tenir ?', 'À 3 m, tout se cumule : le néoprène a repris presque tout son volume (poussée maximale), le bloc s''est allégé d''environ 2 kg, et l''on se trouve dans la zone où la pression varie proportionnellement le plus vite — le volume du gilet y réagit fortement au moindre écart de profondeur. D''où la stratégie : lestage juste, gilet presque vide au palier et stabilisation au poumon-ballast. La pression est évidemment plus faible qu''au fond, et la narcose concerne les grandes profondeurs.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-011', 'a', 'La combinaison a repris son volume, le bloc est léger, et la moindre variation de profondeur fait fortement varier le volume du gilet', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-011', 'b', 'La pression y est la plus forte de la plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-011', 'c', 'Le courant y est toujours plus fort qu''au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-archimede-011', 'd', 'La narcose y est maximale', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-001', 'n2-dalton-henry', 'n2', 'physique', 'qcm', 'lair--un-mélange-de-gaz', 'Quelle est la composition conventionnelle de l''air utilisée pour les calculs de plongée ?', 'L''air réel contient environ 78 % d''azote, 21 % d''oxygène et 1 % de gaz rares et de CO₂ ; pour les calculs, on utilise la convention simplifiée 80 % de N₂ et 20 % d''O₂, le reste étant négligé. Inverser les deux gaz (réponse c) est l''erreur d''étourderie classique : l''azote est bien le gaz majoritaire. Chaque gaz joue un rôle différent : l''O₂ est consommé, le N₂ se dissout, le CO₂ commande la ventilation.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-001', 'a', '80 % d''azote et 20 % d''oxygène', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-001', 'b', '50 % d''azote et 50 % d''oxygène', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-001', 'c', '80 % d''oxygène et 20 % d''azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-001', 'd', '100 % d''oxygène', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-002', 'n2-dalton-henry', 'n2', 'physique', 'qcm', 'la-loi-de-dalton--les-pressions-partielles', 'Comment calcule-t-on la pression partielle d''un gaz dans un mélange ?', 'La loi de Dalton : chaque gaz d''un mélange exerce une pression proportionnelle à son pourcentage, comme s''il occupait seul tout le volume, soit $P_p = P_{abs} \times \%$ ; la somme des pressions partielles reconstitue la pression absolue. Utiliser la pression relative (réponse b) est le piège habituel de l''oubli du bar atmosphérique, et diviser par le pourcentage n''a pas de sens physique. C''est la pression partielle, pas le pourcentage, qui gouverne les effets d''un gaz sur l''organisme.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-002', 'a', '$P_p = P_{abs} \times \%_{gaz}$, et la somme des pressions partielles vaut la pression absolue', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-002', 'b', '$P_p = P_{rel} \times \%_{gaz}$', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-002', 'c', '$P_p = P_{abs} / \%_{gaz}$', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-002', 'd', 'La pression partielle est toujours égale au pourcentage du gaz', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-003', 'n2-dalton-henry', 'n2', 'physique', 'calcul', 'la-loi-de-dalton--les-pressions-partielles', 'Quelle est la pression partielle d''azote (80 %) respirée à 20 m ?', 'À 20 m, la pression absolue vaut $1 + 20/10 = 3$ bars ; Dalton donne $P_pN_2 = 3 \times 0{,}80 = 2{,}4$ bars. Répondre 1,6 bar revient à utiliser la pression relative (2 bars) au lieu de l''absolue : c''est l''erreur d''un bar la plus fréquente. 0,8 bar est la valeur en surface, et 3 bars est la pression absolue totale, pas la part de l''azote.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-003', 'a', '1,6 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-003', 'b', '2,4 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-003', 'c', '0,8 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-003', 'd', '3 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-004', 'n2-dalton-henry', 'n2', 'physique', 'calcul', 'la-loi-de-dalton--les-pressions-partielles', 'Quelle est la pression partielle d''oxygène (20 %) respirée à 40 m à l''air ?', 'À 40 m, $P_{abs} = 1 + 40/10 = 5$ bars, donc $P_pO_2 = 5 \times 0{,}20 = 1$ bar. Répondre 0,8 bar utilise la pression relative (4 bars) : oubli du bar atmosphérique ; 4 bars est la pression partielle d''azote à cette profondeur ; 0,2 bar est la valeur de surface. Retenez la lecture physiologique : à 40 m, chaque inspiration apporte cinq fois plus de molécules de chaque gaz qu''en surface.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-004', 'a', '0,8 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-004', 'b', '1 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-004', 'c', '4 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-004', 'd', '0,2 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-005', 'n2-dalton-henry', 'n2', 'physique', 'calcul', 'la-loi-de-dalton--les-pressions-partielles', 'Quelle est la pression partielle d''azote (80 %) respirée à 35 m ?', 'À 35 m, $P_{abs} = 1 + 35/10 = 4{,}5$ bars, donc $P_pN_2 = 4{,}5 \times 0{,}80 = 3{,}6$ bars. Répondre 2,8 bars utilise la pression relative (3,5 bars), 4,5 bars est la pression absolue totale, et 3,2 bars est le seuil d''apparition de la narcose — dépassé ici, ce qui confirme qu''à 35 m la narcose est une réalité à anticiper.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-005', 'a', '3,6 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-005', 'b', '2,8 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-005', 'c', '4,5 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-005', 'd', '3,2 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-006', 'n2-dalton-henry', 'n2', 'physique', 'calcul', 'la-loi-de-dalton--les-pressions-partielles', 'À quelle profondeur la pression partielle d''oxygène de l''air (20 %) atteint-elle 1,6 bar ?', 'On inverse Dalton : $P_{abs} = P_pO_2 / \%_{O_2} = 1{,}6 / 0{,}20 = 8$ bars, soit une pression relative de 7 bars et donc 70 m. Répondre 80 m oublie de retrancher le bar atmosphérique en convertissant les 8 bars ; 60 m est la limite réglementaire de la plongée à l''air en France (qui garde justement une marge sous ce seuil de toxicité) ; 16 m n''a pas de justification. Cette gymnastique « du seuil vers la profondeur » est un grand classique d''examen.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-006', 'a', '70 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-006', 'b', '60 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-006', 'c', '80 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-006', 'd', '16 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-007', 'n2-dalton-henry', 'n2', 'physique', 'calcul', 'dalton-appliquée--narcose-toxicité-de-loxygène-essoufflement', 'La narcose apparaît vers une pression partielle d''azote de 3,2 bars. À quelle profondeur ce seuil est-il atteint à l''air (80 % de N₂) ?', 'On inverse Dalton : $P_{abs} = 3{,}2 / 0{,}80 = 4$ bars, soit 3 bars de pression relative et donc 30 m. C''est pourquoi les premiers effets narcotiques (ralentissement, euphorie, troubles du raisonnement) apparaissent dans la zone des 30 mètres et s''accentuent au-delà. Répondre 40 m surestime le seuil (la narcose y est déjà bien présente), 32 m confond le seuil en bars avec la profondeur, et 22 m n''a pas de justification.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-007', 'a', '30 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-007', 'b', '40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-007', 'c', '22 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-007', 'd', '32 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-008', 'n2-dalton-henry', 'n2', 'physique', 'vrai-faux', 'dalton-appliquée--narcose-toxicité-de-loxygène-essoufflement', 'À 40 m, le pourcentage d''azote dans l''air respiré est plus élevé qu''en surface.', 'C''est faux : le pourcentage d''azote reste 80 % à toute profondeur — la composition de l''air ne change pas. Ce qui augmente, c''est la pression partielle (4 bars de N₂ à 40 m contre 0,8 bar en surface), donc la quantité de molécules délivrée à chaque inspiration. Cette nuance est exactement ce que l''examinateur veut entendre : un gaz agit par sa pression partielle, pas par son pourcentage.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-008', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-008', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-009', 'n2-dalton-henry', 'n2', 'physique', 'qcm', 'la-loi-de-henry--la-dissolution-des-gaz', 'Quel est l''énoncé correct de la loi de Henry ?', 'La loi de Henry décrit la dissolution : à température constante et à saturation, la quantité de gaz dissoute dans un liquide est proportionnelle à la pression partielle de ce gaz au contact du liquide — c''est le fondement de la saturation en azote du plongeur, illustrée par la bouteille d''eau gazeuse. La proposition b est la loi de Boyle-Mariotte et la c la loi de Dalton ; quant à la d, l''eau gazeuse prouve chaque jour le contraire.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-009', 'a', 'À température constante et à saturation, la quantité de gaz dissoute dans un liquide est proportionnelle à la pression partielle de ce gaz au contact du liquide', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-009', 'b', 'Le volume d''un gaz est inversement proportionnel à sa pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-009', 'c', 'Chaque gaz d''un mélange exerce une pression proportionnelle à son pourcentage', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-009', 'd', 'Un liquide ne peut jamais dissoudre de gaz', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-010', 'n2-dalton-henry', 'n2', 'physique', 'qcm', 'la-loi-de-henry--la-dissolution-des-gaz', 'On appelle T la tension d''azote dissous dans un tissu et Pp la pression partielle d''azote inspiré. Que se passe-t-il quand T est supérieure à Pp ?', 'Quand la tension du gaz dissous dépasse la pression partielle inspirée (T > Pp), le gradient s''inverse : le tissu restitue son azote — c''est la sursaturation, situation normale de la remontée et du retour en surface, qui doit rester dans des limites tolérables. T < Pp correspond à la charge (descente et séjour au fond) et T = Pp à la saturation (équilibre). L''azote ne se transforme évidemment jamais en oxygène.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-010', 'a', 'Le tissu se décharge de son azote : c''est la sursaturation, typique de la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-010', 'b', 'Le tissu se charge en azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-010', 'c', 'Le tissu est à l''équilibre, rien ne se passe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-010', 'd', 'L''azote se transforme en oxygène', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-011', 'n2-dalton-henry', 'n2', 'physique', 'qcm', 'de-henry-à-laccident-de-désaturation', 'Quelle chaîne logique relie les lois physiques à l''accident de désaturation ?', 'La chaîne complète attendue à l''examen : Dalton (la pression partielle d''azote augmente avec la profondeur) → Henry (l''azote se dissout proportionnellement dans le sang et les tissus) → à la remontée, sursaturation → si elle est trop rapide, l''azote reprend sa forme gazeuse en bulles → accident de désaturation. La proposition b décrit la surpression pulmonaire (accident barotraumatique, pas de désaturation), la c confond avec l''hyperoxie, et la d est fausse : le pourcentage ne change jamais.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-011', 'a', 'Dalton : la PpN₂ augmente avec la profondeur → Henry : l''azote se dissout dans les tissus → remontée trop rapide : sursaturation critique → bulles → ADD', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-011', 'b', 'Mariotte : l''air se dilate à la remontée → les poumons éclatent → ADD', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-011', 'c', 'Henry : l''oxygène devient toxique en profondeur → convulsions → ADD', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-011', 'd', 'Dalton : le pourcentage d''azote augmente au fond → intoxication → ADD', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-dalton-012', 'n2-dalton-henry', 'n2', 'physique', 'qcm', 'les-facteurs-qui-modifient-la-dissolution', 'Quels facteurs dégradent la qualité de la désaturation ? Plusieurs réponses possibles.', 'Tous ces facteurs s''expliquent par Henry : le froid ralentit la circulation périphérique par vasoconstriction et freine l''élimination de l''azote, la fatigue et la déshydratation dégradent la qualité de la désaturation, et les plongées répétées ajoutent l''azote résiduel des plongées précédentes (d''où la majoration des successives). Une bonne hydratation est au contraire un facteur protecteur — c''est l''un des conseils systématiques faits au plongeur N2.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-012', 'a', 'Le froid (vasoconstriction en fin de plongée)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-012', 'b', 'La fatigue et la déshydratation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-012', 'c', 'Les plongées répétées (azote résiduel)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-dalton-012', 'd', 'Une bonne hydratation avant et après la plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-001', 'n2-consommation-autonomie', 'n2', 'physique', 'calcul', 'la-consommation-en-surface--votre-point-de-départ', 'Un plongeur consomme 30 bars en 10 minutes à 10 m, stabilisé, avec un bloc de 12 L. Quelle est sa consommation équivalente en surface ?', 'Volume consommé : $30 \times 12 = 360$ L d''air détendu en 10 minutes, soit 36 L/min à 10 m. Or à 10 m la pression absolue est de 2 bars : la consommation équivalente en surface est $36 / 2 = 18$ L/min. Répondre 36 L/min oublie de ramener à la surface, 12 L/min divise par 3 sans justification, et 20 L/min est la valeur conventionnelle des énoncés, pas le résultat de cette mesure.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-001', 'a', '18 L/min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-001', 'b', '36 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-001', 'c', '12 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-001', 'd', '20 L/min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-002', 'n2-consommation-autonomie', 'n2', 'physique', 'calcul', 'la-consommation-augmente-avec-la-profondeur', 'Un plongeur consomme 20 L/min en surface. Que consomme-t-il à 40 m ?', 'La consommation en litres détendus est multipliée par la pression absolue : $C_{prof} = C_{surface} \times P_{abs} = 20 \times 5 = 100$ L/min, car à 40 m $P_{abs} = 1 + 40/10 = 5$ bars. Répondre 80 L/min utilise la pression relative (4 bars) — l''oubli du bar atmosphérique — et 20 L/min supposerait que la profondeur ne change rien, alors que le détendeur délivre l''air comprimé à la pression ambiante.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-002', 'a', '80 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-002', 'b', '100 L/min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-002', 'c', '40 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-002', 'd', '20 L/min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-003', 'n2-consommation-autonomie', 'n2', 'physique', 'calcul', 'la-consommation-augmente-avec-la-profondeur', 'Sur une base de 20 L/min en surface, quelle est la consommation à 25 m ?', 'À 25 m, $P_{abs} = 1 + 25/10 = 3{,}5$ bars, donc $C = 20 \times 3{,}5 = 70$ L/min. Répondre 50 L/min utilise la pression relative (2,5 bars), et 60 L/min correspond à 20 m (3 bars) : la formule fonctionne pour toute profondeur, pas seulement pour les valeurs rondes du tableau du cours.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-003', 'a', '50 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-003', 'b', '70 L/min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-003', 'c', '60 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-003', 'd', '45 L/min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-004', 'n2-consommation-autonomie', 'n2', 'physique', 'calcul', 'la-réserve--50-bars-intouchables', 'Bloc de 12 L gonflé à 200 bars, réserve de 50 bars. Quel volume d''air détendu est réellement disponible pour la plongée ?', 'On ne planifie jamais sur la totalité du bloc : $V_{disponible} = (P_{bloc} - P_{réserve}) \times V_{bloc} = (200 - 50) \times 12 = 1800$ L d''air détendu. Répondre 2400 L compte la réserve dans le calcul — l''erreur à éviter absolument ; 600 L est le volume de la seule réserve ($50 \times 12$) ; 1500 L correspondrait à un bloc de 10 L.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-004', 'a', '2400 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-004', 'b', '1800 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-004', 'c', '600 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-004', 'd', '1500 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-005', 'n2-consommation-autonomie', 'n2', 'physique', 'vrai-faux', 'la-réserve--50-bars-intouchables', 'Si la plongée se déroule bien, on peut consommer la réserve de 50 bars pour prolonger le temps au fond.', 'C''est faux : la réserve n''est pas un « bonus de fin de plongée » mais une marge de sécurité que l''on ne consomme pas en fonctionnement normal — elle couvre l''imprévu (assistance à un équipier, palier prolongé, recherche du mouillage). La remontée doit être entamée avant d''atteindre la réserve : arriver au bateau à 50 bars est une plongée bien gérée, entamer la remontée à 50 bars est déjà une plongée mal planifiée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-005', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-005', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-006', 'n2-consommation-autonomie', 'n2', 'physique', 'calcul', 'la-méthode-complète-de-calcul-dautonomie', 'Bloc 12 L à 200 bars, réserve 50 bars, consommation 20 L/min en surface. Quelle est l''autonomie théorique à 20 m ?', 'Méthode en trois étapes : 1) litres disponibles : $(200 - 50) \times 12 = 1800$ L ; 2) consommation au fond : $P_{abs} = 3$ bars à 20 m, donc $20 \times 3 = 60$ L/min ; 3) autonomie : $1800 / 60 = 30$ minutes. Répondre 40 minutes revient à compter la réserve ($2400/60$), et 45 minutes à utiliser la pression relative (2 bars, 40 L/min). C''est l''exemple étalon à savoir refaire de tête.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-006', 'a', '30 minutes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-006', 'b', '40 minutes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-006', 'c', '20 minutes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-006', 'd', '45 minutes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-007', 'n2-consommation-autonomie', 'n2', 'physique', 'calcul', 'la-méthode-complète-de-calcul-dautonomie', 'Même bloc (12 L, 200 bars, réserve 50 bars, 20 L/min en surface), mais à 40 m. Quelle est l''autonomie théorique ?', 'Les litres disponibles ne changent pas : 1800 L. À 40 m, $P_{abs} = 5$ bars et la consommation vaut $20 \times 5 = 100$ L/min, donc l''autonomie tombe à $1800 / 100 = 18$ minutes. Répondre 22,5 minutes utilise la pression relative (4 bars, soit 80 L/min) au lieu de la pression absolue, et 30 minutes est l''autonomie à 20 m : passer de 20 à 40 m ampute le temps au fond de 40 % — c''est tout l''enjeu de la gestion d''air dans l''espace 20-40 m.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-007', 'a', '18 minutes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-007', 'b', '22,5 minutes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-007', 'c', '30 minutes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-007', 'd', '9 minutes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-008', 'n2-consommation-autonomie', 'n2', 'physique', 'calcul', 'la-méthode-complète-de-calcul-dautonomie', 'Bloc de 15 L gonflé à 230 bars, réserve 50 bars, consommation 20 L/min en surface, profondeur 40 m. Quelle est l''autonomie théorique ?', '1) Litres disponibles : $(230 - 50) \times 15 = 2700$ L ; 2) consommation à 40 m : $20 \times 5 = 100$ L/min ; 3) autonomie : $2700 / 100 = 27$ minutes. Répondre 34,5 minutes compte la réserve ($3450/100$), et 18 minutes est le résultat du bloc de 12 L à 200 bars : le passage à un 15 L bien gonflé fait gagner la moitié du temps au fond, raison pour laquelle on privilégie les grands blocs en plongée profonde.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-008', 'a', '27 minutes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-008', 'b', '34,5 minutes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-008', 'c', '18 minutes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-008', 'd', '22 minutes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-009', 'n2-consommation-autonomie', 'n2', 'physique', 'qcm', 'la-méthode-complète-de-calcul-dautonomie', 'Pourquoi l''autonomie calculée par la méthode des trois étapes est-elle qualifiée de « théorique » ?', 'Le calcul suppose tout le volume disponible consommé à profondeur constante : il ignore la descente, la remontée, les paliers et les imprévus (effort, assistance). Le résultat est donc un majorant : la durée effective au fond doit être choisie en dessous, et confrontée à la courbe de sécurité ou aux tables. Ni la précision des manomètres, ni la validité de Mariotte, ni la salinité de l''eau ne sont en cause.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-009', 'a', 'Elle ne tient pas compte de l''air consommé pendant la descente, la remontée, les paliers ni d''un effort imprévu : c''est un majorant', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-009', 'b', 'Parce que les manomètres sont toujours faux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-009', 'c', 'Parce que la loi de Mariotte est une approximation grossière', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-009', 'd', 'Parce qu''elle ne vaut que pour l''eau douce', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-010', 'n2-consommation-autonomie', 'n2', 'physique', 'qcm', 'les-facteurs-qui-font-varier-la-consommation', 'Quels facteurs augmentent la consommation d''air ? Plusieurs réponses possibles.', 'La consommation réelle grimpe avec l''effort (elle peut doubler ou tripler), le froid (l''organisme brûle pour se chauffer), le stress (ventilation rapide et superficielle, peu efficace), l''essoufflement (cercle vicieux du CO₂) et un équipement inadapté — surlestage et gilet trop gonflé dégradent l''hydrodynamisme et imposent de lutter. Une ventilation ample et calme insistant sur l''expiration est au contraire la parade : un plongeur détendu descend nettement sous les 20 L/min.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-010', 'a', 'L''effort (palmage contre le courant) et le froid', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-010', 'b', 'Le stress et l''essoufflement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-010', 'c', 'Le surlestage et un gilet trop gonflé', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-010', 'd', 'Une ventilation ample et calme, insistant sur l''expiration', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-conso-011', 'n2-consommation-autonomie', 'n2', 'physique', 'qcm', 'gérer-lair-en-palanquée-autonome', 'En palanquée autonome, sur quel plongeur règle-t-on le profil et les demi-tours ?', 'La palanquée autonome règle son profil sur le plongeur qui consomme le plus : dès que sa pression atteint les seuils convenus au briefing (demi-tour, début de remontée, réserve), tout le monde applique. Se caler sur le plus économe ou sur une moyenne laisserait le gros consommateur descendre sous sa réserve — exactement ce que la discipline collective de l''air doit empêcher. L''expérience ne dispense personne de la règle.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-011', 'a', 'Sur celui qui consomme le plus : c''est sa pression qui déclenche le demi-tour et la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-011', 'b', 'Sur celui qui consomme le moins, pour profiter au maximum', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-011', 'c', 'Sur la moyenne des pressions de la palanquée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-conso-011', 'd', 'Sur le plongeur le plus expérimenté, quelle que soit sa pression', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-001', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'le-mécanisme-commun--mariotte-appliquée-au-corps-humain', 'Quelle loi physique explique le mécanisme de tous les barotraumatismes ?', 'Tous les barotraumatismes reposent sur la loi de Boyle-Mariotte : quand une cavité aérique ne communique plus avec l''extérieur, la variation de pression comprime son air à la descente (tissus aspirés) ou le dilate à la remontée (parois distendues). La loi de Henry explique la dissolution des gaz (accident de désaturation), Dalton les pressions partielles (narcose, hyperoxie) et Archimède la flottabilité : chaque accident a « sa » loi, et l''examinateur attend cette correspondance.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-001', 'a', 'La loi de Boyle-Mariotte : $P_1 \times V_1 = P_2 \times V_2$', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-001', 'b', 'La loi de Henry', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-001', 'c', 'La loi de Dalton', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-001', 'd', 'Le principe d''Archimède', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-002', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'synthèse-et-réflexes-de-prévention', 'Quels barotraumatismes surviennent typiquement à la **remontée** ? Plusieurs réponses possibles.', 'À la remontée, l''air enfermé se dilate : poumons (surpression pulmonaire, la plus grave), gaz digestifs (ballonnements, douleurs) et microbulle piégée sous un soin dentaire défectueux (douleur violente, typiquement à la remontée). Le plaquage de masque est au contraire un accident de la descente : l''air du masque se comprime et agit en ventouse — à la remontée, l''excès d''air s''échappe tout seul sous la jupe.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-002', 'a', 'La surpression pulmonaire', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-002', 'b', 'Le barotraumatisme digestif (estomac, intestins)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-002', 'c', 'Les dents', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-002', 'd', 'Le plaquage de masque', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-003', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'loreille--le-barotraumatisme-le-plus-fréquent', 'Quels facteurs favorisent le barotraumatisme de l''oreille ? Plusieurs réponses possibles.', 'Le rhume obstrue la trompe d''Eustache et rend l''équilibrage impossible ; une descente rapide (surtout tête en bas, où la pression augmente plus vite qu''on ne compense) et une compensation tardive ou brutale laissent le tympan se déformer. Compenser doucement dès le premier mètre est au contraire la prévention même : tôt, souvent, sans forcer — c''est la règle enseignée dès le Niveau 1 et approfondie au Niveau 2.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-003', 'a', 'Un rhume ou une inflammation ORL', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-003', 'b', 'Une descente rapide, surtout tête en bas', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-003', 'c', 'Une compensation tardive ou brutale', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-003', 'd', 'Une compensation douce dès le premier mètre', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-004', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'loreille--le-barotraumatisme-le-plus-fréquent', 'Pourquoi une rupture du tympan en plongée peut-elle provoquer des vertiges ?', 'Après une déchirure du tympan, l''eau froide envahit l''oreille moyenne et crée une stimulation thermique brutale de l''oreille interne toute proche : le plongeur est pris de vertiges, souvent après une accalmie trompeuse de la douleur. C''est dangereux par la désorientation qu''il provoque en immersion. Le tympan lui-même n''est pas l''organe de l''équilibre (c''est le vestibule de l''oreille interne), et l''azote n''a rien à voir avec ce mécanisme purement thermique et mécanique.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-004', 'a', 'L''entrée d''eau froide dans l''oreille moyenne stimule brutalement l''oreille interne', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-004', 'b', 'La douleur fait perdre connaissance', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-004', 'c', 'L''azote se dissout dans le liquide de l''oreille interne', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-004', 'd', 'Le tympan sert d''organe de l''équilibre', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-005', 'n2-barotraumatismes', 'n2', 'physiologie', 'vrai-faux', 'loreille--le-barotraumatisme-le-plus-fréquent', 'La manœuvre de Valsalva doit être pratiquée à la descente comme à la remontée.', 'C''est faux : le Valsalva est un geste de descente uniquement. À la remontée, l''oreille moyenne est déjà en surpression et l''air s''évacue passivement ; un Valsalva y ajouterait de la pression et pourrait léser l''oreille interne. En cas de gêne à la remontée (vertige alternobarique), la conduite correcte est de redescendre légèrement, déglutir, puis remonter lentement.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-005', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-005', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-006', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'loreille--le-barotraumatisme-le-plus-fréquent', 'Après la plongée, une douleur d''oreille persiste avec une baisse d''audition. Que faire ?', 'Des symptômes persistants après la plongée (douleur, hypoacousie, vertiges) évoquent une lésion du tympan ou de l''oreille moyenne : la conduite à tenir est une consultation ORL sans délai et l''arrêt de la plongée jusqu''à avis médical. Replonger sur une oreille lésée aggrave les lésions et expose à la rupture ; l''automédication et l''attente exposent à des séquelles auditives évitables.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-006', 'a', 'Consulter un ORL sans délai et ne pas replonger avant avis médical', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-006', 'b', 'Replonger le lendemain pour « rééquilibrer » l''oreille', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-006', 'c', 'Mettre des gouttes et replonger si la douleur diminue', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-006', 'd', 'Attendre une semaine : cela passe toujours tout seul', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-007', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'sinus-dents-et-plaquage-de-masque', 'Pourquoi la seule prévention efficace du barotraumatisme des sinus est-elle de ne pas plonger enrhumé ?', 'Les sinus sains s''équilibrent tout seuls par leurs fins canaux reliés aux fosses nasales : il n''existe aucun geste volontaire pour les « compenser ». Si un canal est obstrué (rhume, sinusite, polype), l''accident est inévitable en cas de descente : la seule prévention est donc de ne pas plonger enrhumé. Les sinus contiennent bien de l''air (c''est tout le problème), et ils peuvent être touchés dès les premiers mètres, pas seulement en profondeur.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-007', 'a', 'Parce qu''il n''existe aucune manœuvre volontaire pour compenser un sinus', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-007', 'b', 'Parce que les sinus ne contiennent pas d''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-007', 'c', 'Parce que le Valsalva compense les sinus mais est interdit', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-007', 'd', 'Parce que les sinus ne sont touchés qu''au-delà de 40 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-008', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'sinus-dents-et-plaquage-de-masque', 'Une douleur dentaire violente survient à la remontée. Quelle est la conduite à tenir ?', 'La douleur vient d''une microbulle d''air dilatée sous un soin défectueux : redescendre légèrement recomprime cette bulle et calme la douleur, puis on remonte très progressivement pour laisser l''air s''échapper, avant une consultation dentaire. Remonter vite augmente la dilatation et peut aller jusqu''à l''éclatement de la dent ou une syncope douloureuse ; le Valsalva concerne les oreilles et n''a aucun effet sur une dent.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-008', 'a', 'Ralentir la remontée, redescendre légèrement jusqu''à sédation, puis remonter très progressivement ; consultation dentaire ensuite', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-008', 'b', 'Remonter le plus vite possible pour sortir de l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-008', 'c', 'Faire un Valsalva puissant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-008', 'd', 'Serrer les dents et terminer la remontée normalement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-009', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'la-surpression-pulmonaire--laccident-le-plus-grave', 'À partir de quelle profondeur une surpression pulmonaire est-elle possible ?', 'Quelques dixièmes de bar d''écart suffisent à distendre puis déchirer les alvéoles : l''accident est possible dès 2 ou 3 mètres, typiquement en piscine ou lors d''un exercice mal maîtrisé — c''est même la zone la plus dangereuse, car les variations relatives de pression y sont maximales. Croire que seule la profondeur crée le risque est le contresens classique : la surpression pulmonaire ne nécessite ni profondeur ni durée, seulement un blocage de la respiration à la remontée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-009', 'a', 'Dès 2 à 3 mètres, notamment en piscine', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-009', 'b', 'Uniquement au-delà de 20 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-009', 'c', 'Uniquement au-delà de 40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-009', 'd', 'Jamais au-dessus de 10 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-010', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'la-surpression-pulmonaire--laccident-le-plus-grave', 'Qu''est-ce que l''aéroembolisme, forme la plus grave de la surpression pulmonaire ?', 'Quand les alvéoles se déchirent, l''air peut gagner les vaisseaux pulmonaires, le cœur gauche puis les artères cérébrales : c''est l''aéroembolisme, forme neurologique gravissime de la surpression pulmonaire (troubles visuels, convulsions, hémiplégie, perte de connaissance). L''air sous la peau du cou est l''emphysème sous-cutané, une autre destination de l''air mais moins dramatique ; les bulles d''azote articulaires relèvent de l''accident de désaturation, mécanisme différent.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-010', 'a', 'Le passage d''air des alvéoles déchirées vers la circulation, jusqu''aux artères cérébrales', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-010', 'b', 'L''accumulation d''air sous la peau du cou', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-010', 'c', 'Une infection pulmonaire due à l''air comprimé', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-010', 'd', 'La formation de bulles d''azote dans les articulations', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-011', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'la-surpression-pulmonaire--laccident-le-plus-grave', 'Quelle est la conduite à tenir devant une suspicion de surpression pulmonaire ? Plusieurs réponses possibles.', 'La conduite à tenir est celle d''un accident grave : sortie de l''eau, repos strict (demi-assise si elle respire, PLS si inconsciente et ventilante, RCP si arrêt), oxygène normobare à 15 L/min en continu, protection thermique, alerte au DP et aux secours, évacuation vers un centre hyperbare. La réimmersion est une interdiction absolue : la recompression ne se fait qu''en caisson, sous contrôle médical — improviser un « palier thérapeutique » aggrave l''accident.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-011', 'a', 'Sortir la victime de l''eau et la mettre au repos strict', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-011', 'b', 'Oxygène normobare 15 L/min au masque haute concentration', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-011', 'c', 'Alerter (CROSS VHF 16 en mer, 15/112 à terre) et organiser l''évacuation vers un centre hyperbare', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-011', 'd', 'Réimmerger la victime à 3 m pour recomprimer l''air', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-012', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'la-surpression-pulmonaire--laccident-le-plus-grave', 'Pourquoi ne faut-il jamais donner de l''air à un apnéiste au fond ?', 'L''apnéiste descend avec l''air inspiré en surface : son volume pulmonaire se comprime puis se re-dilate exactement à l''identique en remontant. S''il inspire de l''air comprimé au fond, ses poumons sont pleins à la pression du fond : en remontant — réflexe naturel de l''apnéiste qui bloque sa respiration — cet air se dilate et crée les conditions exactes de la surpression pulmonaire. C''est un piège d''examen classique : le danger n''est ni la consommation ni une « toxicité », mais la loi de Mariotte.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-012', 'a', 'Parce qu''en remontant après avoir inspiré de l''air comprimé au fond, il risque la surpression pulmonaire', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-012', 'b', 'Parce que cela viderait trop vite le bloc', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-012', 'c', 'Parce que l''apnéiste n''a pas de détendeur adapté', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-012', 'd', 'Parce que l''air comprimé est toxique pour un apnéiste', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-baro-013', 'n2-barotraumatismes', 'n2', 'physiologie', 'qcm', 'barotraumatismes-digestifs-et-vertige-alternobarique', 'Un vertige bref survient à la remontée (vertige alternobarique). Quelle est la conduite à tenir ?', 'Le vertige alternobarique vient d''une asymétrie de pression entre les deux oreilles moyennes à la remontée : on s''arrête, on se stabilise (mouillage ou binôme), on déglutit et on redescend légèrement jusqu''à disparition du vertige, avant de reprendre une remontée lente. Accélérer aggrave l''asymétrie et le risque de panique ou de remontée incontrôlée ; le Valsalva est justement interdit à la remontée ; et continuer désorienté expose à perdre le contrôle de sa profondeur.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-013', 'a', 'S''arrêter, se stabiliser, déglutir, redescendre d''un mètre ou deux jusqu''à disparition, puis remonter lentement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-013', 'b', 'Accélérer la remontée pour sortir de l''eau au plus vite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-013', 'c', 'Faire un Valsalva énergique pour équilibrer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-baro-013', 'd', 'Fermer les yeux et continuer à remonter au même rythme', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-001', 'n2-add', 'n2', 'physiologie', 'qcm', 'saturation--la-loi-de-henry-appliquée-au-plongeur', 'Pourquoi parle-t-on de tissus « rapides » et de tissus « lents » pour la saturation en azote ?', 'La vitesse de charge et de décharge en azote dépend de la vascularisation : le sang et le cerveau, très irrigués, se saturent et se désaturent vite ; les articulations, la moelle et la graisse, peu vascularisées, sont lentes dans les deux sens. Cette notion de « compartiments » est le fondement même des tables de plongée. Il s''agit bien de l''azote, pas de l''oxygène, et la typologie musculaire (fibres rapides/lentes) n''a aucun rapport.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-001', 'a', 'Les tissus très irrigués (sang, cerveau) se chargent et se déchargent vite ; les tissus peu vascularisés ou graisseux (articulations, moelle, graisse) sont lents', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-001', 'b', 'Certains tissus absorbent l''oxygène plus vite que d''autres', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-001', 'c', 'Les muscles rapides se saturent plus vite que les muscles lents', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-001', 'd', 'Cette distinction n''existe pas : tous les tissus se saturent à la même vitesse', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-002', 'n2-add', 'n2', 'physiologie', 'qcm', 'saturation--la-loi-de-henry-appliquée-au-plongeur', 'Combien de temps la désaturation se poursuit-elle après la sortie de l''eau ?', 'À la sortie de l''eau, les tissus contiennent encore de l''azote excédentaire qui s''élimine progressivement par la ventilation : la désaturation se poursuit pendant plusieurs heures. C''est ce qui justifie les règles d''après-plongée (pas d''effort, pas d''apnée, délai avant l''avion) et explique que la plupart des ADD se déclarent après la sortie. Croire la désaturation « terminée » en surface est l''erreur conceptuelle qui fait négliger ces règles.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-002', 'a', 'Plusieurs heures', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-002', 'b', 'Elle est terminée dès la sortie de l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-002', 'c', 'Quelques secondes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-002', 'd', 'Une semaine entière', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-003', 'n2-add', 'n2', 'physiologie', 'qcm', 'le-mécanisme-de-laccident--la-formation-des-bulles', 'Dans quelles circonstances l''azote dissous forme-t-il des bulles dans l''organisme ?', 'Tant que la remontée est lente et les paliers respectés, l''azote reste dissous et s''évacue par la ventilation. Si la pression ambiante chute plus vite que les tissus ne se déchargent, la sursaturation devient critique et l''azote repasse brutalement à l''état gazeux dans le sang et les tissus — comme l''eau gazeuse ouverte brutalement. Les bulles ne se forment pas à la descente (phase de charge), et l''oxygène n''est pas en cause dans l''ADD.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-003', 'a', 'Quand la remontée est trop rapide ou les paliers supprimés : la sursaturation devient excessive', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-003', 'b', 'À chaque plongée, quelle que soit la remontée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-003', 'c', 'Uniquement pendant la descente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-003', 'd', 'Quand le plongeur respire trop d''oxygène', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-004', 'n2-add', 'n2', 'physiologie', 'qcm', 'le-mécanisme-de-laccident--la-formation-des-bulles', 'Par quels mécanismes les bulles d''azote sont-elles pathogènes ? Plusieurs réponses possibles.', 'Les bulles agissent de trois façons : elles bloquent la circulation dans les vaisseaux (mécanisme des atteintes neurologiques), elles compriment les structures voisines dans les tissus peu extensibles, et elles déclenchent au contact du sang des réactions en chaîne qui aggravent l''accident — c''est notamment pourquoi l''hydratation et, selon protocole, l''aspirine figurent dans la conduite à tenir. L''azote reste chimiquement inerte : il n''y a aucune transformation toxique.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-004', 'a', 'Obstruction mécanique d''un vaisseau (ischémie en aval)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-004', 'b', 'Compression locale des tissus peu extensibles (moelle, articulations)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-004', 'c', 'Réactions sanguines secondaires (agrégation plaquettaire, épaississement du sang)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-004', 'd', 'Transformation chimique de l''azote en gaz toxique', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-005', 'n2-add', 'n2', 'physiologie', 'qcm', 'le-mécanisme-de-laccident--la-formation-des-bulles', 'Quand la majorité des accidents de désaturation se déclarent-ils ?', 'L''ADD se prépare silencieusement au fond mais se déclare le plus souvent après la sortie de l''eau : dans les minutes à quelques heures (le plus souvent moins d''une heure), presque toujours en moins de 24 heures. C''est un point d''examen classique et une règle pratique : tout symptôme anormal après une plongée est un ADD jusqu''à preuve du contraire. Il ne survient ni à la descente ni au fond, phases où les tissus se chargent sans buller.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-005', 'a', 'Dans les minutes à quelques heures après la sortie de l''eau, presque toujours en moins de 24 h', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-005', 'b', 'Pendant la descente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-005', 'c', 'Au fond, pendant le séjour', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-005', 'd', 'Au moins 48 h après la plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-006', 'n2-add', 'n2', 'physiologie', 'qcm', 'les-facteurs-favorisants', 'Quels profils de plongée favorisent l''ADD ? Plusieurs réponses possibles.', 'Côté profil, les facteurs favorisants sont les remontées rapides et paliers écourtés ou supprimés, les profils en yo-yo qui brassent l''azote et favorisent le dégazage anarchique, et les plongées successives rapprochées qui cumulent l''azote résiduel. Une remontée à 15 m/min avec paliers respectés est précisément la procédure MN90 correcte — c''est la prévention, pas un facteur de risque.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-006', 'a', 'Les profils inversés ou en yo-yo (montées-descentes répétées)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-006', 'b', 'Les plongées successives rapprochées', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-006', 'c', 'Les remontées rapides et paliers écourtés', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-006', 'd', 'Une remontée à 15 m/min avec paliers respectés', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-007', 'n2-add', 'n2', 'physiologie', 'qcm', 'les-facteurs-favorisants', 'Qu''est-ce que le foramen ovale perméable, cité parmi les facteurs favorisants de l''ADD ?', 'Le foramen ovale perméable est une petite communication entre les deux oreillettes du cœur, présente chez une partie de la population : elle peut laisser passer des bulles veineuses — normalement filtrées par les poumons — directement dans la circulation artérielle, vers le cerveau. C''est un facteur favorisant individuel de l''ADD, sans rapport avec les poumons eux-mêmes, les trompes d''Eustache (oreilles) ou la moelle épinière (qui est une cible de l''accident, pas sa cause).', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-007', 'a', 'Une petite communication cardiaque qui permet aux bulles veineuses de passer dans la circulation artérielle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-007', 'b', 'Une malformation des poumons qui retient l''azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-007', 'c', 'Un rétrécissement des trompes d''Eustache', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-007', 'd', 'Une lésion de la moelle épinière préexistante', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-008', 'n2-add', 'n2', 'physiologie', 'qcm', 'les-symptômes--formes-de-type-i-et-de-type-ii', 'Que sont les « bends » ?', 'Les bends sont la forme ostéo-arthro-musculaire de type I : douleur articulaire profonde, tenace, augmentant progressivement, touchant surtout l''épaule (puis coude, hanche), avec une position antalgique caractéristique. Les démangeaisons correspondent à la forme cutanée (« puces » et « moutons »), les vertiges rotatoires à la forme cochléo-vestibulaire de type II, et les crampes de froid ne sont pas un ADD. Attention : une forme apparemment mineure peut précéder une forme grave — la conduite à tenir est la même.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-008', 'a', 'Des douleurs articulaires profondes et tenaces (épaule surtout), forme de type I de l''ADD', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-008', 'b', 'Des démangeaisons cutanées', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-008', 'c', 'Des vertiges rotatoires', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-008', 'd', 'Des crampes musculaires dues au froid', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-009', 'n2-add', 'n2', 'physiologie', 'qcm', 'les-symptômes--formes-de-type-i-et-de-type-ii', 'Quels symptômes évoquent un ADD médullaire (moelle épinière), forme de type II ? Plusieurs réponses possibles.', 'L''atteinte médullaire associe fourmillements des membres, faiblesse ou paralysie des jambes, troubles urinaires et parfois douleur « en ceinture » : c''est une urgence absolue, le pronostic fonctionnel se jouant dans les premières heures. Un fourmillement « qui va passer » ou une envie d''uriner impossible à satisfaire sont des débuts d''ADD réellement observés — le déni de la victime est fréquent. La douleur dentaire relève du barotraumatisme, pas de l''ADD.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-009', 'a', 'Fourmillements des membres inférieurs', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-009', 'b', 'Faiblesse ou paralysie des jambes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-009', 'c', 'Troubles urinaires (envie impérieuse ou impossibilité d''uriner)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-009', 'd', 'Douleur dentaire localisée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-010', 'n2-add', 'n2', 'physiologie', 'qcm', 'les-symptômes--formes-de-type-i-et-de-type-ii', 'Une heure après une plongée, un plongeur présente des vertiges rotatoires intenses avec nausées et sifflements d''oreille. Quelle est l''hypothèse prioritaire ?', 'Des vertiges rotatoires intenses avec signes cochléaires (sifflements, surdité brusque) survenant après la plongée évoquent en priorité un ADD de l''oreille interne, forme de type II qui impose la conduite à tenir complète (O₂ 15 L/min, alerte, évacuation vers un caisson). Le mal de mer ou la fatigue sont des diagnostics « rassurants » dangereux : tout symptôme anormal après une plongée est un ADD jusqu''à preuve du contraire. La narcose, elle, disparaît dès la remontée et ne persiste jamais en surface.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-010', 'a', 'Un ADD cochléo-vestibulaire (oreille interne), forme de type II : conduite à tenir ADD immédiate', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-010', 'b', 'Une simple fatigue passagère', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-010', 'c', 'Le mal de mer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-010', 'd', 'Une narcose résiduelle', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-011', 'n2-add', 'n2', 'physiologie', 'qcm', 'les-symptômes--formes-de-type-i-et-de-type-ii', 'Quels signes d''appel « trompeurs » peuvent annoncer un ADD neurologique ? Plusieurs réponses possibles.', 'Les signes d''appel de l''ADD sont volontiers banalisés : une fatigue anormalement intense, une anxiété ou une pâleur inexpliquées peuvent annoncer un accident neurologique, et une « simple » douleur d''épaule mise sur le compte du portage est le début typique d''un bend. Le binôme et le DP doivent savoir imposer la prise en charge face au déni de la victime. Avoir faim après l''effort, en revanche, n''a rien d''inquiétant.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-011', 'a', 'Une fatigue intense et inhabituelle après la plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-011', 'b', 'Une anxiété et une pâleur inexpliquées', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-011', 'c', 'Une douleur d''épaule attribuée au portage du bloc', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-011', 'd', 'Une faim marquée au retour de plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-012', 'n2-add', 'n2', 'physiologie', 'qcm', 'la-conduite-à-tenir--chaque-minute-compte', 'Quel est le geste qui change le pronostic d''un ADD, à mettre en œuvre immédiatement ?', 'L''oxygène normobare à 15 L/min au masque à haute concentration, administré immédiatement et sans interruption jusqu''aux secours, accélère l''élimination de l''azote et oxygène les tissus ischémiés : c''est le geste qui change le pronostic. L''aspirine est limitée à 500 mg maximum et conditionnée au protocole ; la douche chaude est déconseillée après la plongée ; et la réimmersion est une interdiction absolue — la recompression ne se fait qu''en caisson.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-012', 'a', 'L''oxygène normobare à 15 L/min au masque haute concentration, en continu', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-012', 'b', 'L''aspirine à forte dose', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-012', 'c', 'Une douche chaude pour relancer la circulation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-012', 'd', 'La réimmersion à 3 m pour un palier de rattrapage', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-013', 'n2-add', 'n2', 'physiologie', 'qcm', 'la-conduite-à-tenir--chaque-minute-compte', 'Dans quelles conditions l''aspirine peut-elle être donnée à une victime d''ADD suspecté ?', 'Le protocole classique : 500 mg maximum en une seule prise, chez l''adulte conscient, en l''absence d''allergie, de contre-indication ou de saignement, et si le plan de secours de la structure le prévoit — dans le doute, on suit l''avis des secours médicalisés. On ne dépasse jamais cette dose et on ne donne rien d''autre. Donner un médicament à une victime inconsciente est un interdit absolu (fausse route), et l''aspirine n''est pas « interdite » : elle est encadrée.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-013', 'a', '500 mg maximum en une prise, victime adulte et consciente, sans allergie ni contre-indication, si le protocole de la structure le prévoit', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-013', 'b', '1 g toutes les heures jusqu''à l''arrivée des secours', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-013', 'c', 'Toujours, même si la victime est inconsciente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-013', 'd', 'Jamais : l''aspirine est strictement interdite en plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-014', 'n2-add', 'n2', 'physiologie', 'qcm', 'la-conduite-à-tenir--chaque-minute-compte', 'Pourquoi la réimmersion d''une victime d''ADD pour un « palier de rattrapage » est-elle formellement interdite ?', 'Une victime d''ADD a besoin d''une recompression longue, contrôlée et médicalisée, avec de l''oxygène : seul un caisson hyperbare le permet. La réimmerger l''expose au froid, à l''impossibilité de la surveiller et de la traiter, à une nouvelle charge d''azote et à la noyade en cas d''aggravation — le tout en retardant l''évacuation. Le ressenti de la victime ne change rien (le déni est fréquent), et la question de l''air ou du contenu des tables est hors sujet : c''est un interdit médical absolu.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-014', 'a', 'La recompression ne se fait qu''en caisson sous contrôle médical : réimmerger aggrave l''état (froid, impossibilité de surveiller, nouvelle charge d''azote)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-014', 'b', 'Parce que cela coûte trop d''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-014', 'c', 'Elle est autorisée si la victime se sent capable de replonger', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-014', 'd', 'Parce que les tables ne prévoient pas de palier à 3 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-add-015', 'n2-add', 'n2', 'physiologie', 'qcm', 'la-prévention--avant-pendant-après', 'Comment alerter les secours en mer pour un accident de plongée, et quel délai respecter avant l''avion ?', 'En mer, l''alerte passe par le CROSS sur VHF canal 16 (ou le 196 par téléphone) ; à terre, le 15 ou le 112 — en transmettant lieu, symptômes, profil de plongée et heure de sortie. Côté prévention, on attend 12 à 24 h avant l''avion ou l''altitude, et 24 h après des plongées multiples : la baisse de pression en cabine relance la formation de bulles. Enfin, l''amélioration sous oxygène ne dispense jamais de l''alerte et de l''évacuation : elle peut masquer une aggravation secondaire.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-015', 'a', 'CROSS par VHF canal 16 (ou 196 par téléphone) ; avion : 12 à 24 h d''attente, 24 h après plongées multiples', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-015', 'b', 'Appeler le 18 uniquement ; avion possible dès le soir même', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-015', 'c', 'VHF canal 9 ; avion : une semaine d''attente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-add-015', 'd', 'Aucune alerte nécessaire si les symptômes régressent sous oxygène', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-001', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'la-narcose-à-lazote', 'À partir de quelle profondeur les premiers effets de la narcose peuvent-ils apparaître à l''air ?', 'Les premiers effets mesurables de la narcose apparaissent vers 30 m — profondeur où la pression partielle d''azote atteint environ 3,2 bars — avec une sensibilité très variable d''un plongeur à l''autre et, chez le même plongeur, d''un jour à l''autre. À 40 m, limite de l''espace PE40 du N2, c''est une réalité à anticiper. Elle ne survient pas à 10 m et n''attend pas 60 m ; et elle existe bel et bien à l''air, l''azote en étant le responsable.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-001', 'a', 'Vers 30 m, avec une sensibilité très variable selon les individus et les jours', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-001', 'b', 'Dès 10 m chez tous les plongeurs', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-001', 'c', 'Uniquement au-delà de 60 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-001', 'd', 'La narcose n''existe pas à l''air', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-002', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'la-narcose-à-lazote', 'Quels signes peuvent trahir une narcose chez un équipier ? Plusieurs réponses possibles.', 'La narcose ressemble à une ivresse : ralentissement des gestes et du raisonnement, euphorie ou angoisse, difficulté à lire ses instruments, réponses lentes aux signes, comportement inhabituel — et le plongeur narcosé ne s''en rend généralement pas compte lui-même : c''est le binôme ou le guide qui détecte. La douleur thoracique n''est pas un signe de narcose : elle évoque une surpression pulmonaire ou un ADD pulmonaire, accidents tout autres.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-002', 'a', 'Réponses lentes ou anarchiques aux signes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-002', 'b', 'Regard fixe, comportement inhabituel', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-002', 'c', 'Difficulté à lire ses instruments ou à faire un calcul simple', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-002', 'd', 'Douleur thoracique violente', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-003', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'la-narcose-à-lazote', 'Quelle est la conduite à tenir face à une narcose ?', 'La narcose est totalement réversible par la remontée : dès les premiers signes, on interrompt la descente et on remonte de quelques mètres à vitesse normale, en restant en contact avec l''équipier — les symptômes régressent rapidement et sans séquelle, puis on réévalue la plongée. Descendre aggrave la narcose (la PpN₂ augmente), il n''existe pas d''« accoutumance » en cours de plongée, attendre sur place laisse le trouble s''installer, et l''oxygénothérapie n''a aucun sens sous l''eau ici.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-003', 'a', 'Remonter de quelques mètres à vitesse normale : les signes disparaissent rapidement, sans séquelle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-003', 'b', 'Descendre pour s''habituer à la profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-003', 'c', 'Administrer de l''oxygène au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-003', 'd', 'Attendre sur place que cela passe', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-004', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'lessoufflement-et-le-cercle-vicieux-du-co', 'Pourquoi une ventilation rapide et superficielle aggrave-t-elle l''essoufflement ?', 'Une ventilation courte et rapide fait surtout circuler l''air de l''espace mort (le volume qui fait l''aller-retour sans atteindre les alvéoles) : le CO₂ n''est pas éliminé, sa pression partielle monte, la commande respiratoire s''emballe encore — c''est le cercle vicieux de l''essoufflement, que seule l''expiration longue et forcée peut casser. Le problème n''est ni la consommation d''oxygène, ni la température, ni l''azote : c''est un accident du CO₂.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-004', 'a', 'Elle ne renouvelle que l''espace mort et n''élimine pas le CO₂, qui continue de monter', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-004', 'b', 'Elle consomme trop d''oxygène', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-004', 'c', 'Elle refroidit les poumons', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-004', 'd', 'Elle augmente la pression partielle d''azote', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-005', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'lessoufflement-et-le-cercle-vicieux-du-co', 'Votre équipier s''essouffle à 20 m. Que faites-vous ? Plusieurs réponses possibles.', 'Pour l''équipier : stopper l''effort de la victime en la saisissant et en la stabilisant, la rassurer par le contact et le regard, l''inciter à expirer par un geste ample, puis remonter doucement de quelques mètres — l''air moins dense y facilite la ventilation — et mettre fin à la plongée en respectant la procédure de remontée. Le laisser seul est l''inverse de la bonne conduite : l''essoufflement non pris en charge mène à la panique, à la surpression pulmonaire ou à la noyade.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-005', 'a', 'Stopper son effort : le saisir, le stabiliser', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-005', 'b', 'Le rassurer par le contact et le regard, l''inciter à expirer amplement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-005', 'c', 'Remonter doucement de quelques mètres puis mettre fin à la plongée en respectant la procédure', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-005', 'd', 'Le laisser gérer seul pour ne pas le stresser davantage', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-006', 'n2-autres-accidents', 'n2', 'physiologie', 'vrai-faux', 'lessoufflement-et-le-cercle-vicieux-du-co', 'L''essoufflement est un accident d''inspiration : il faut inspirer plus fort pour le vaincre.', 'C''est faux : l''essoufflement est un accident d''expiration. Le réflexe naturel — inspirer plus fort et plus vite — aggrave le phénomène car il rend la ventilation superficielle et laisse le CO₂ s''accumuler. La seule issue est de stopper tout effort et de forcer l''expiration, longue et profonde, pour éliminer le CO₂. C''est aussi un facteur déclenchant majeur d''accidents graves : surpression pulmonaire en cas de remontée panique, et noyade.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-006', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-006', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-007', 'n2-autres-accidents', 'n2', 'physiologie', 'calcul', 'hyperoxie-et-hypoxie--loxygène-ni-trop-ni-trop-peu', 'À quelle profondeur l''oxygène pur (100 %) atteint-il le seuil de toxicité de 1,6 bar de PpO₂ ?', 'Avec de l''oxygène pur, $P_pO_2 = P_{abs} \times 1$ : le seuil de 1,6 bar est atteint quand la pression absolue vaut 1,6 bar, soit une pression relative de 0,6 bar et donc 6 m de profondeur. C''est pourquoi l''oxygène pur est dangereux dès 6 m (risque de crise convulsive type effet Paul Bert). Les 66 m correspondent au seuil à l''air (21 % d''O₂), et 16 m ou 1,6 m confondent bars et mètres.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-007', 'a', '6 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-007', 'b', '16 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-007', 'c', '66 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-007', 'd', '1,6 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-008', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'hyperoxie-et-hypoxie--loxygène-ni-trop-ni-trop-peu', 'Pourquoi l''hyperventilation avant une apnée est-elle dangereuse ?', 'L''envie de respirer est déclenchée par la montée du CO₂ : l''hyperventilation abaisse ce signal d''alarme sans augmenter notablement la réserve d''oxygène. L''apnéiste dépasse alors ses limites sans alerte et perd connaissance — typiquement à la remontée, quand la PpO₂ chute avec la pression : c''est la syncope hypoxique, sans prodrome. D''où les règles : jamais d''hyperventilation, jamais d''apnée seul, jamais d''apnée après une plongée bouteille. L''azote et le seuil hyperoxique ne sont pas en cause ici.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-008', 'a', 'Elle abaisse le CO₂ (signal d''alarme de la ventilation) sans augmenter notablement l''O₂ : l''apnéiste peut perdre connaissance sans ressentir le besoin de respirer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-008', 'b', 'Elle sature le sang en azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-008', 'c', 'Elle fatigue les muscles respiratoires avant l''effort', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-008', 'd', 'Elle augmente la pression partielle d''oxygène jusqu''au seuil toxique', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-009', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'le-froid', 'Quel signe indique que le froid devient une hypothermie débutante, donc une situation grave ?', 'Le frisson est un mécanisme actif de lutte contre le froid : quand il cesse alors que le froid persiste, c''est que l''organisme n''a plus les ressources pour lutter — apathie, désintérêt et troubles du jugement signent l''hypothermie débutante, une situation grave (oxygène, alerte, évacuation si la conscience s''altère). Chair de poule et envie d''uriner sont les premiers signes bénins, et des frissons intenses montrent au contraire que la lutte est encore active.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-009', 'a', 'Les frissons cessent alors que le froid persiste, avec apathie et troubles du jugement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-009', 'b', 'L''apparition de la chair de poule', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-009', 'c', 'Une envie d''uriner', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-009', 'd', 'Des frissons de plus en plus intenses', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-010', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'le-froid', 'Comment réchauffer correctement un plongeur qui a eu froid ? Plusieurs réponses possibles.', 'Le réchauffement est progressif : sécher, couvrir en incluant la tête (grande zone de perte de chaleur), vêtements chauds et boisson chaude sucrée non alcoolisée. L''alcool et la douche brûlante sont les deux pièges classiques : ils provoquent une vasodilatation périphérique qui accélère en réalité le refroidissement du noyau central et peuvent aggraver l''état — sans compter que le réchauffement brutal est déconseillé après la plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-010', 'a', 'Sécher, couvrir (bonnet compris) et mettre des vêtements chauds', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-010', 'b', 'Donner une boisson chaude sucrée non alcoolisée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-010', 'c', 'Réchauffer progressivement, jamais brutalement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-010', 'd', 'Proposer un alcool fort et une douche brûlante', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-011', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'hydrocution-et-noyade', 'Quels facteurs favorisent l''hydrocution (choc thermo-différentiel) ? Plusieurs réponses possibles.', 'L''hydrocution résulte d''un écart thermique brutal entre un corps surchauffé et une eau froide : l''exposition au soleil (pont du bateau, combinaison enfilée trop tôt), l''effort et la transpiration, la digestion d''un repas copieux, l''alcool et l''entrée brutale dans l''eau en sont les facteurs favorisants — la réaction réflexe peut aller jusqu''à la syncope, donc à la noyade. La mise à l''eau progressive en se mouillant la nuque et le visage est précisément la prévention, pas un facteur de risque.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-011', 'a', 'Une exposition prolongée au soleil avant la mise à l''eau', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-011', 'b', 'Un repas copieux ou de l''alcool avant de plonger', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-011', 'c', 'Une mise à l''eau brutale dans une eau froide', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-011', 'd', 'Une mise à l''eau progressive en se mouillant la nuque et le visage', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-accidents-012', 'n2-autres-accidents', 'n2', 'physiologie', 'qcm', 'hydrocution-et-noyade', 'Pourquoi dit-on qu''en plongée la noyade est presque toujours un accident « secondaire » ?', 'En scaphandre, on ne se noie pas « spontanément » : la noyade est presque toujours la conséquence finale d''un autre accident — panique, essoufflement, syncope (hydrocution, hypoxie de l''apnéiste, crise hyperoxique), narcose profonde ou panne d''air mal gérée. La prévenir, c''est donc casser la chaîne au premier maillon. Elle n''a rien d''anodin : la conduite à tenir impose sortie rapide de l''eau, oxygène 15 L/min, RCP si besoin, alerte et hospitalisation systématique, même si la victime semble récupérer.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-012', 'a', 'Elle est l''aboutissement d''un autre problème : panique, essoufflement, syncope, narcose profonde, panne d''air mal gérée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-012', 'b', 'Elle ne survient qu''à la deuxième plongée de la journée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-012', 'c', 'Elle est moins grave que les autres accidents', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-accidents-012', 'd', 'Elle ne touche que les plongeurs de niveau secondaire', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-001', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'doù-viennent-les-tables-mn90-et-quand-sappliquent-elles', 'Dans quelles conditions les tables MN90 sont-elles valables ? Plusieurs réponses possibles.', 'Les tables MN90 ont été validées pour un cadre précis : plongée à l''air au niveau de la mer, profondeur maximale de 60 m (limite de la plongée à l''air en France), deux plongées maximum par 24 heures, vitesse de remontée de 15 à 17 m/min et effort modéré. En dehors de ce cadre — nitrox, altitude — elles ne garantissent plus rien : des procédures spécifiques existent pour ces situations, hors programme N2.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-001', 'a', 'Plongée à l''air, au niveau de la mer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-001', 'b', 'Deux plongées maximum par 24 heures', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-001', 'c', 'Profondeur maximale de 60 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-001', 'd', 'Plongée au nitrox en altitude', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-002', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'doù-viennent-les-tables-mn90-et-quand-sappliquent-elles', 'Quelles sont les vitesses de remontée prévues par les tables MN90 ?', 'La procédure MN90 : remontée du fond au premier palier à 15-17 m/min, puis 6 m/min entre les paliers et du dernier palier à la surface. Inverser les deux vitesses (réponse b) est le piège classique : c''est bien près de la surface, là où les variations relatives de pression sont maximales, que l''on ralentit le plus. Une remontée à 30 m/min est une remontée rapide, qui impose une procédure de rattrapage.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-002', 'a', '15 à 17 m/min du fond au premier palier, puis 6 m/min entre les paliers et vers la surface', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-002', 'b', '6 m/min du fond au premier palier, puis 15 à 17 m/min ensuite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-002', 'c', '30 m/min sur toute la remontée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-002', 'd', '10 m/min sur toute la remontée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-003', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'doù-viennent-les-tables-mn90-et-quand-sappliquent-elles', 'Comment la « durée de plongée » est-elle définie pour l''entrée dans les tables MN90 ?', 'La durée de plongée court de l''immersion au début de la remontée à vitesse normale (15-17 m/min) ; la profondeur retenue est la profondeur maximale atteinte, même brièvement. Compter jusqu''au retour en surface ajouterait la remontée et les paliers (c''est la DTR, une autre notion), et ne compter que le temps au fond sous-estimerait la charge en azote de la descente et des évolutions intermédiaires.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-003', 'a', 'De l''immersion au début de la remontée à vitesse normale', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-003', 'b', 'De l''immersion au retour en surface', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-003', 'c', 'Du départ du fond à la fin du dernier palier', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-003', 'd', 'Le temps passé à la profondeur maximale uniquement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-004', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'doù-viennent-les-tables-mn90-et-quand-sappliquent-elles', 'Qu''est-ce que le GPS dans le vocabulaire des tables MN90 ?', 'Le GPS (groupe de plongée successive) est la lettre de A à P lue dans le tableau I à la fin d''une plongée : elle code la quantité d''azote résiduel emportée en surface, et sert d''entrée au tableau II en cas de plongée successive. Rien à voir avec la géolocalisation. La durée totale de remontée est la DTR, et la profondeur maximale du jour est fixée par le directeur de plongée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-004', 'a', 'Le groupe de plongée successive : une lettre de A à P qui code la charge d''azote résiduelle en fin de plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-004', 'b', 'Le système de géolocalisation du bateau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-004', 'c', 'La profondeur maximale autorisée du jour', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-004', 'd', 'La durée totale de remontée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-005', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'les-deux-règles-dor-de-la-lecture--arrondir-vers-la-sécurité', 'Vos paramètres (profondeur, durée) ne figurent pas exactement dans la table. Comment les arrondir ?', 'La règle d''or de la lecture du tableau I : profondeur et durée s''arrondissent toujours à la valeur immédiatement supérieure, jamais l''inférieure — entre deux lignes, on choisit celle qui décompresse le plus. L''arrondi « au plus proche » des mathématiques est exactement ce qu''il ne faut pas faire : les tables s''arrondissent toujours dans le sens de la sécurité. Seul l''intervalle de surface (tableau II) s''arrondit vers le bas, pour la même raison conservatrice.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-005', 'a', 'Profondeur et durée à la valeur immédiatement supérieure', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-005', 'b', 'Profondeur et durée à la valeur immédiatement inférieure', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-005', 'c', 'Profondeur au-dessus, durée en dessous', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-005', 'd', 'À la valeur la plus proche, comme en mathématiques', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-006', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'les-deux-règles-dor-de-la-lecture--arrondir-vers-la-sécurité', 'Votre profondeur maximale a été de 17,5 m. Quelle table de profondeur utilisez-vous ?', '17,5 m ne figure pas dans les profondeurs de table : on prend la valeur immédiatement supérieure, soit la table 20 m, qui impose une décompression au moins aussi prudente que la profondeur réelle. Lire la table 15 m sous-estimerait la charge d''azote (arrondi dangereux), la table « 18 m » n''existe pas, et on n''interpole jamais entre deux tables.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-006', 'a', 'La table 20 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-006', 'b', 'La table 15 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-006', 'c', 'La table 18 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-006', 'd', 'La moyenne des tables 15 et 20 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-007', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Plongée simple : 20 m pendant 40 min. Que donne la lecture de la table MN90 ?', 'Les paramètres 20 m et 40 min figurent exactement dans la table : ligne 40 min de la table 20 m → aucun palier obligatoire, GPS H. C''est la dernière ligne de la courbe de sécurité pour 20 m. La lecture « 4 min à 3 m, GPS I » correspond à la ligne 45 min, et « 9 min à 3 m » à la ligne 50 min : arrondir au-delà du nécessaire pénalise inutilement. Le palier « de principe » de 3 min à 3 m reste recommandé, mais il n''est pas obligatoire ici.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-007', 'a', 'Aucun palier obligatoire, GPS H', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-007', 'b', '4 min à 3 m, GPS I', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-007', 'c', '9 min à 3 m, GPS I', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-007', 'd', '3 min à 3 m, GPS G', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-008', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Plongée simple : profondeur maximale 17 m, durée 48 min. Quels paliers et quel GPS ?', 'Arrondis vers la sécurité : 17 m → table 20 m ; 48 min → ligne 50 min. Lecture : palier de 9 min à 3 m, GPS I. Répondre « 4 min à 3 m » lirait la ligne 45 min (arrondi de la durée vers le bas, interdit), « aucun palier » la ligne 40 min, et « 13 min, GPS J » la ligne 55 min, au-delà du nécessaire. La double règle d''arrondi supérieur sur la profondeur ET la durée est le cœur de la lecture du tableau I.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-008', 'a', '9 min à 3 m, GPS I', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-008', 'b', '4 min à 3 m, GPS I', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-008', 'c', 'Aucun palier, GPS H', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-008', 'd', '13 min à 3 m, GPS J', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-009', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Plongée simple : 32 m pendant 27 min. Quels paliers et quel GPS ?', 'Arrondis : 32 m → table 35 m ; 27 min → ligne 30 min. Lecture : paliers de 5 min à 6 m puis 22 min à 3 m, GPS I. La réponse « 17 min à 3 m, GPS H » correspond à la table 30 m ligne 30 min : c''est l''erreur d''arrondi de profondeur vers le bas, dangereuse. « 2 min à 6 m et 23 min à 3 m » est la ligne 35 min de la table 30 m — mauvaise table — et « 9 min à 3 m » la ligne 25 min de la table 30 m. On remonte du fond au palier de 6 m à 15-17 m/min, puis à 6 m/min.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-009', 'a', '5 min à 6 m puis 22 min à 3 m, GPS I', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-009', 'b', '17 min à 3 m, GPS H', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-009', 'c', '2 min à 6 m et 23 min à 3 m, GPS I', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-009', 'd', '9 min à 3 m, GPS G', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-010', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Plongée simple : 28 m pendant 28 min. Quels paliers et quel GPS ?', 'Arrondis : 28 m → table 30 m ; 28 min → ligne 30 min. Lecture : palier de 17 min à 3 m, GPS H. Répondre « 9 min à 3 m, GPS G » lirait la ligne 25 min (durée arrondie vers le bas, interdit) ; « 6 min à 3 m » vient de la table 25 m ligne 30 min (profondeur arrondie vers le bas) ; et « 2 min à 6 m + 23 min à 3 m » est la ligne 35 min, au-delà du nécessaire.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-010', 'a', '17 min à 3 m, GPS H', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-010', 'b', '9 min à 3 m, GPS G', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-010', 'c', '6 min à 3 m, GPS G', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-010', 'd', '2 min à 6 m et 23 min à 3 m, GPS I', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-011', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Plongée simple : 21 m pendant 33 min. Quels paliers et quel GPS ?', 'Arrondis : 21 m → table 25 m ; 33 min → ligne 35 min. Lecture : palier de 12 min à 3 m, GPS H. Répondre « 6 min à 3 m, GPS G » lirait la ligne 30 min (durée vers le bas), « aucun palier » viendrait de la table 20 m (profondeur vers le bas — à 20 m/35 min il n''y a pas de palier), et « 19 min à 3 m » est la ligne 40 min de la table 25 m. Un mètre au-delà de 20 m suffit à changer de table : la profondeur max se lit sur l''instrument, pas « au jugé ».', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-011', 'a', '12 min à 3 m, GPS H', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-011', 'b', '6 min à 3 m, GPS G', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-011', 'c', 'Aucun palier, GPS G', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-011', 'd', '19 min à 3 m, GPS I', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-012', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Plongée simple : 38 m pendant 22 min. Quels paliers et quel GPS ?', 'Arrondis : 38 m → table 40 m ; 22 min → ligne 25 min. Lecture : paliers de 5 min à 6 m puis 19 min à 3 m, GPS I. La réponse « 2 min à 6 m + 13 min à 3 m, GPS G » est la ligne 20 min (durée arrondie vers le bas, interdit), « 10 min à 3 m » vient de la table 35 m ligne 20 min (double arrondi vers le bas), et « 9 min à 6 m + 26 min à 3 m » est la ligne 30 min, au-delà du nécessaire.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-012', 'a', '5 min à 6 m puis 19 min à 3 m, GPS I', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-012', 'b', '2 min à 6 m puis 13 min à 3 m, GPS G', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-012', 'c', '10 min à 3 m, GPS G', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-012', 'd', '9 min à 6 m puis 26 min à 3 m, GPS J', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-013', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Plongée simple : 24 m pendant 18 min. Que donne la lecture de la table ?', 'Arrondis : 24 m → table 25 m ; 18 min → ligne 20 min. Lecture : aucun palier obligatoire, GPS E — la plongée est dans la courbe de sécurité (20 min à 25 m). La réponse « 2 min à 3 m, GPS F » correspond à la ligne 25 min, « GPS D » à la ligne 15 min (durée vers le bas, interdit), et « 6 min à 3 m, GPS G » à la ligne 30 min. Même sans palier obligatoire, le palier de principe de 3 min à 3 m reste recommandé.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-013', 'a', 'Aucun palier obligatoire, GPS E', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-013', 'b', '2 min à 3 m, GPS F', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-013', 'c', 'Aucun palier, GPS D', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-013', 'd', '6 min à 3 m, GPS G', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-014', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Plongée à 17 m pendant 48 min (lecture : table 20 m, 50 min → 9 min à 3 m). Quelle est la DTR (durée totale de remontée) approximative ?', 'La DTR cumule tout : remontée de 17 m à 3 m, soit 14 m à 15 m/min ≈ 1 min ; palier de 9 min ; puis 3 m à 6 m/min ≈ 0,5 min. Total ≈ 10,5 min, arrondi à 11 min. Répondre 9 min ne compte que le palier en oubliant les trajets, 2 min ne compte que les trajets sans le palier, et 20 min n''a pas de justification. La DTR sert au chronométrage de l''heure de sortie, systématiquement demandé à l''examen.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-014', 'a', 'Environ 11 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-014', 'b', 'Environ 9 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-014', 'c', 'Environ 20 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-014', 'd', 'Environ 2 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-015', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'lire-une-plongée-simple-pas-à-pas', 'Immersion à 9 h 00, durée de plongée 48 min, DTR 11 min. Quelle est l''heure de sortie ?', 'Heure de sortie = heure d''immersion + durée de plongée + DTR : 9 h 00 + 48 min = 9 h 48 (début de la remontée), puis + 11 min de DTR = 9 h 59. Répondre 9 h 48 oublie la DTR (c''est l''heure du début de remontée), et 10 h 11 ajouterait la DTR deux fois ou confondrait les composantes. Ce petit chronométrage est systématiquement demandé dans les exercices d''examen.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-015', 'a', '9 h 59', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-015', 'b', '9 h 48', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-015', 'c', '10 h 11', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-015', 'd', '9 h 55', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-016', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'la-courbe-de-sécurité', 'Qu''est-ce que la courbe de sécurité ?', 'Pour chaque profondeur, il existe une durée maximale au-delà de laquelle un palier devient obligatoire : l''ensemble de ces couples profondeur-durée forme la courbe de sécurité. Rester à l''intérieur, c''est conserver la possibilité de remonter directement (à vitesse contrôlée) sans palier obligatoire — une marge de sécurité considérable. Ce n''est ni une trajectoire de remontée, ni une limite de prérogatives, ni une courbe de consommation.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-016', 'a', 'L''ensemble des couples profondeur-durée pour lesquels aucun palier n''est obligatoire', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-016', 'b', 'La trajectoire idéale de la remontée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-016', 'c', 'La limite de profondeur de chaque niveau de plongeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-016', 'd', 'Le graphique de consommation d''air en fonction de la profondeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-017', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-courbe-de-sécurité', 'Quelle est la durée maximale sans palier obligatoire à 20 m (courbe de sécurité) ?', 'À 20 m, la table autorise 40 min sans palier obligatoire : c''est l''un des couples de la courbe de sécurité à connaître par cœur (12 m : 2 h 15 ; 15 m : 1 h 15 ; 20 m : 40 min ; 25 m : 20 min ; 30 m : 10 min ; 35 m : 5 min). Les 20 min correspondent à 25 m, 1 h 15 à 15 m et 10 min à 30 m. Remarquez la chute rapide de ces durées avec la profondeur — et même dans la courbe, le palier de principe reste recommandé.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-017', 'a', '40 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-017', 'b', '20 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-017', 'c', '1 h 15', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-017', 'd', '10 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-018', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-courbe-de-sécurité', 'Quelle est la durée maximale sans palier obligatoire à 30 m ?', 'À 30 m, la courbe de sécurité n''accorde que 10 min : au-delà, un palier devient obligatoire (à 15 min, la table impose déjà 2 min à 3 m). Les 20 min correspondent à 25 m et les 5 min à 35-40 m. La comparaison est parlante : à 20 m on dispose de 40 minutes, à 30 m de 10 minutes seulement — la marge sans palier fond très vite avec la profondeur.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-018', 'a', '10 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-018', 'b', '20 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-018', 'c', '5 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-018', 'd', '15 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-019', 'n2-tables-mn90', 'n2', 'tables-deco', 'vrai-faux', 'la-courbe-de-sécurité', 'À 25 m, on peut rester 20 minutes sans palier obligatoire.', 'C''est vrai : le couple 25 m / 20 min appartient à la courbe de sécurité — la table 25 m, ligne 20 min, n''impose aucun palier (GPS E). Dès la ligne suivante (25 min), un palier de 2 min à 3 m apparaît. Ces valeurs sont à connaître par cœur pour l''examen et à vérifier sur la table officielle ; même dans la courbe, le palier de principe de 3 min à 3 m reste recommandé.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-019', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-019', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-020', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Quand une plongée est-elle dite « successive » ?', 'Une plongée successive débute entre 15 minutes et 12 heures après la précédente : l''azote résiduel de la première s''ajoute à la charge de la seconde, et il faut le comptabiliser via les tableaux II et III. Moins de 15 minutes, c''est une plongée consécutive (considérée comme la même plongée) ; plus de 12 heures, l''azote est revenu au niveau de base et la plongée redevient simple.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-020', 'a', 'Quand elle débute entre 15 minutes et 12 heures après la précédente', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-020', 'b', 'Quand elle débute moins de 15 minutes après la précédente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-020', 'c', 'Quand elle débute plus de 12 heures après la précédente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-020', 'd', 'Quand elle a lieu le même mois que la précédente', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-021', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Quel est l''ordre correct de la procédure de plongée successive ?', 'La procédure se déroule toujours dans le même ordre : 1) noter le GPS de la première plongée ; 2) croiser GPS et intervalle de surface dans le tableau II pour lire l''azote résiduel ; 3) croiser azote résiduel et profondeur prévue dans le tableau III pour lire la majoration ; 4) entrer dans le tableau I avec la profondeur réelle et la durée fictive (durée réelle + majoration). Additionner les durées est la procédure de la plongée consécutive (moins de 15 min), pas de la successive, et les profondeurs ne s''additionnent jamais.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-021', 'a', 'GPS de la 1ʳᵉ plongée → tableau II (azote résiduel) → tableau III (majoration) → durée fictive = durée réelle + majoration dans le tableau I', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-021', 'b', 'Tableau III → tableau II → GPS → tableau I', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-021', 'c', 'On ajoute simplement les durées des deux plongées', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-021', 'd', 'On lit directement le tableau I avec la profondeur cumulée des deux plongées', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-022', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Dans la procédure de plongée successive, dans quels sens s''effectuent les arrondis ?', 'Trois arrondis, tous conservateurs : l''intervalle de surface s''arrondit à la valeur immédiatement inférieure du tableau II (moins de temps en surface = plus d''azote résiduel retenu), tandis que l''azote résiduel et la profondeur s''arrondissent aux valeurs immédiatement supérieures dans le tableau III (majoration plus grande). Le principe unificateur : chaque arrondi se fait dans le sens de la sécurité, jamais dans le sens qui allégerait la décompression.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-022', 'a', 'Intervalle de surface vers le bas ; azote résiduel et profondeur du tableau III vers le haut', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-022', 'b', 'Tous les arrondis vers le haut', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-022', 'c', 'Tous les arrondis vers le bas', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-022', 'd', 'Intervalle vers le haut ; azote résiduel vers le bas', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-023', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Première plongée : GPS H. Intervalle de surface : 2 h (120 min). Quel azote résiduel lit-on dans le tableau II ?', 'L''intervalle de 120 min figure exactement dans le tableau II : ligne H, colonne 120 min → azote résiduel 0,97. La valeur 1,01 correspond à la colonne 90 min (arrondi excessif), 1,06 à la ligne H colonne 60 min, et 0,89 à la ligne H colonne 240 min : un intervalle mal reporté fausse toute la suite du calcul. Cette lecture est la deuxième étape de la procédure de successive, avant le tableau III.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-023', 'a', '0,97', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-023', 'b', '1,01', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-023', 'c', '1,06', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-023', 'd', '0,89', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-024', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Première plongée : GPS I. Intervalle de surface : 3 h (180 min). Quel azote résiduel lit-on dans le tableau II ?', 'Ligne I du tableau II, colonne 180 min → azote résiduel 0,94. La valeur 1,00 est la lecture de la ligne I à 120 min, 1,04 celle à 90 min, et 0,90 correspond à la ligne I à 240 min : il faut croiser précisément la bonne ligne (GPS) et la bonne colonne (intervalle), l''intervalle s''arrondissant à la valeur inférieure s''il ne figure pas dans le tableau.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-024', 'a', '0,94', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-024', 'b', '1,00', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-024', 'c', '0,90', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-024', 'd', '1,04', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-025', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Azote résiduel lu : 0,97. Seconde plongée prévue à 20 m. Quelle majoration lit-on dans le tableau III ?', 'Dans le tableau III, on prend l''azote immédiatement supérieur à 0,97, soit la ligne 1,01, croisée avec la profondeur 20 m → majoration de 16 min. Répondre 11 min lirait la ligne 0,95 (arrondi de l''azote vers le bas, interdit), 21 min la ligne 1,07, et 29 min la colonne 12 m de la ligne 1,01 : il faut croiser la bonne ligne d''azote ET la bonne colonne de profondeur, toutes deux arrondies vers le haut.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-025', 'a', '16 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-025', 'b', '11 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-025', 'c', '21 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-025', 'd', '29 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-026', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Majoration : 16 min. La seconde plongée dure réellement 25 min à 20 m. Que donne la lecture finale du tableau I ?', 'Durée fictive = durée réelle + majoration = $25 + 16 = 41$ min ; on entre dans la table 20 m avec 41 min, arrondi à la ligne supérieure 45 min → palier de 4 min à 3 m, GPS I. Tout se passe comme si la plongée avait commencé 16 minutes avant l''immersion réelle. Lire la ligne 40 min arrondirait la durée vers le bas (interdit), ignorer la majoration (réponse c) est l''erreur la plus grave, et la ligne 50 min pénalise au-delà du nécessaire.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-026', 'a', 'Durée fictive 41 min → table 20 m, ligne 45 min : 4 min à 3 m, GPS I', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-026', 'b', 'Durée fictive 41 min → table 20 m, ligne 40 min : aucun palier, GPS H', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-026', 'c', 'On lit 25 min : aucun palier, GPS E', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-026', 'd', 'Durée fictive 41 min → table 20 m, ligne 50 min : 9 min à 3 m, GPS I', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-027', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Première plongée : GPS J. Intervalle de surface : 50 min. Quel azote résiduel retenir (tableau II) ?', '50 min ne figure pas dans les intervalles du tableau II (15, 30, 45, 60, 90...) : on arrondit à la valeur immédiatement inférieure, soit 45 min — ligne J → azote résiduel 1,17. Lire 60 min (1,13) arrondirait l''intervalle vers le haut, ce qui sous-estimerait l''azote restant : c''est l''arrondi interdit. On n''interpole jamais entre deux colonnes, et 1,22 correspond à 30 min, arrondi inutilement pénalisant.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-027', 'a', '1,17 (lecture à l''intervalle 45 min)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-027', 'b', '1,13 (lecture à l''intervalle 60 min)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-027', 'c', '1,22 (lecture à l''intervalle 30 min)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-027', 'd', '1,15 (interpolation entre 45 et 60 min)', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-028', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Première plongée : GPS G, intervalle 1 h (60 min), seconde plongée prévue à 20 m. Quelle majoration retenir ?', 'Tableau II : ligne G, colonne 60 min → azote résiduel 1,02. Tableau III : azote immédiatement supérieur = ligne 1,07, croisée avec 20 m → majoration de 21 min. Répondre 16 min lirait la ligne 1,01 alors que 1,02 la dépasse (l''arrondi de l''azote se fait vers le haut), 27 min correspond à la ligne 1,13 (20 m), et 11 min à la ligne 0,95. La chaîne complète tableau II puis tableau III doit être déroulée sans sauter d''étape.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-028', 'a', '21 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-028', 'b', '16 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-028', 'c', '27 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-028', 'd', '11 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-029', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'la-plongée-successive--intervalle-azote-résiduel-majoration', 'Plus de 12 heures se sont écoulées depuis la plongée précédente. Comment traiter la nouvelle plongée ?', 'Au-delà de 12 heures d''intervalle, les tables considèrent que l''azote résiduel est revenu au niveau de base (0,81 bar) : la plongée redevient simple et se lit directement dans le tableau I, sans majoration. La successive concerne les intervalles de 15 min à 12 h, la consécutive les intervalles de moins de 15 min. Aucune interdiction de replonger après 12 h — c''est au contraire la situation la plus favorable.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-029', 'a', 'Comme une plongée simple : l''azote résiduel est revenu au niveau de base', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-029', 'b', 'Comme une successive avec la majoration maximale', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-029', 'c', 'Comme une consécutive', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-029', 'd', 'Elle est interdite avant 24 heures', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-030', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'la-plongée-consécutive--moins-de-15-minutes-dintervalle', 'Comment traite-t-on une plongée consécutive (ré-immersion moins de 15 minutes après la sortie) ?', 'Moins de 15 minutes après la sortie, les tables considèrent qu''il s''agit de la même plongée : durée retenue = somme des durées des deux plongées, profondeur retenue = profondeur maximale atteinte au cours des deux. Les tableaux II et III ne servent que pour la successive (15 min à 12 h), traiter les plongées comme indépendantes sous-estimerait gravement la charge d''azote, et les profondeurs ne s''additionnent jamais — cas typique : redescendre décrocher un mouillage juste après la plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-030', 'a', 'Comme une seule plongée : durées additionnées, profondeur maximale des deux plongées', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-030', 'b', 'Avec la procédure des tableaux II et III', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-030', 'c', 'Comme deux plongées simples indépendantes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-030', 'd', 'En additionnant les profondeurs des deux plongées', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-031', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'la-plongée-consécutive--moins-de-15-minutes-dintervalle', 'Plongée à 18 m pendant 30 min, sortie, puis ré-immersion 10 min plus tard à 15 m pendant 20 min. Quelle lecture de table pour la fin de la seconde plongée ?', 'L''intervalle de 10 min (< 15 min) fait de la seconde plongée une consécutive : durée cumulée $30 + 20 = 50$ min, profondeur maximale 18 m → table 20 m, ligne 50 min → palier de 9 min à 3 m (à faire à la fin de la seconde plongée), GPS I. Lire la seule seconde plongée (réponse b) ou la seule première (réponse c) ignore le cumul, et additionner les profondeurs (réponse d) est un contresens : on retient le maximum, jamais la somme.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-031', 'a', 'Table 20 m, 50 min → 9 min à 3 m, GPS I', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-031', 'b', 'Table 15 m, 20 min → aucun palier, GPS B', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-031', 'c', 'Table 20 m, 30 min → aucun palier, GPS F', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-031', 'd', 'Table 35 m (18 + 15 arrondi), 50 min → paliers profonds', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-032', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'les-remontées-anormales--lente-et-rapide', 'Comment les tables MN90 traitent-elles une remontée lente (moins de 15 m/min, par exemple en suivant un tombant) ?', 'La règle MN90 : la durée de plongée est comptée jusqu''au moment où l''on entame la remontée à vitesse normale (15-17 m/min). Une remontée lente en exploration reste donc un temps de charge pour les tissus lents : elle s''ajoute à la durée de plongée, la profondeur retenue restant la profondeur maximale. Exemple du cours : 20 min à 25 m + 10 min de remontée lente → lecture 25 m / 30 min. On ne retranche jamais ce temps et on n''utilise jamais de profondeur moyenne.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-032', 'a', 'Le temps de remontée lente s''ajoute à la durée de plongée ; la profondeur retenue reste la profondeur maximale', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-032', 'b', 'La remontée lente est interdite par les tables', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-032', 'c', 'On retranche le temps de remontée lente de la durée de plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-032', 'd', 'On lit la table à la profondeur moyenne de la remontée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-033', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'les-remontées-anormales--lente-et-rapide', 'Quelle est la procédure de rattrapage après une remontée rapide (plus de 17 m/min) ?', 'La procédure, à connaître par cœur : redescendre dans les 3 minutes à la moitié de la profondeur maximale, y rester 5 minutes, puis remonter à vitesse normale en effectuant les paliers recalculés (durée comptée de l''immersion à la fin du palier à mi-profondeur, profondeur = maximale), avec au minimum 2 min à 3 m ; ensuite, surveillance de toute la palanquée et pas de nouvelle immersion. Redescendre au fond aggraverait la charge, et un simple palier de principe ne compense pas le dégazage anarchique. Si la redescente est impossible ou hors délai : conduite à tenir ADD.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-033', 'a', 'Redescendre dans les 3 minutes à la moitié de la profondeur maximale, y rester 5 minutes, puis remonter en effectuant les paliers recalculés (minimum 2 min à 3 m)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-033', 'b', 'Rester en surface et surveiller les symptômes, rien d''autre', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-033', 'c', 'Redescendre à la profondeur maximale et refaire toute la plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-033', 'd', 'Faire un palier de 3 min à 3 m et considérer l''incident clos', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-034', 'n2-tables-mn90', 'n2', 'tables-deco', 'calcul', 'les-remontées-anormales--lente-et-rapide', 'Plongée à 30 m ; au bout de 17 min, remontée rapide accidentelle. La palanquée redescend en 2 min à 15 m et y reste 5 min. Quelle lecture de table pour les paliers ?', 'La durée à retenir court de l''immersion à la fin du palier à mi-profondeur : $17 + 2 + 5 = 24$ min, avec la profondeur maximale (30 m) → table 30 m, ligne 25 min → palier de 9 min à 3 m, GPS G. Ne compter que les 17 min initiales (réponse b) ignore la redescente ; lire la table 15 m (réponse c) confond mi-profondeur et profondeur de lecture ; et 22 min (réponse d) oublie la redescente de 2 min — le résultat est ici identique par l''arrondi, mais la méthode est fausse et peut coûter cher sur d''autres valeurs.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-034', 'a', 'Durée 17 + 2 + 5 = 24 min → table 30 m, ligne 25 min : 9 min à 3 m, GPS G', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-034', 'b', 'Durée 17 min → table 30 m, ligne 20 min : 4 min à 3 m, GPS F', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-034', 'c', 'Durée 24 min → table 15 m : aucun palier', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-034', 'd', 'Durée 22 min → table 30 m, ligne 25 min : 9 min à 3 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-tables-035', 'n2-tables-mn90', 'n2', 'tables-deco', 'qcm', 'le-palier-interrompu', 'Votre palier de 9 min à 3 m est interrompu à la 6ᵉ minute (vous êtes remonté accidentellement en surface). Que faites-vous ?', 'La règle du palier interrompu : redescendre à la profondeur du palier dans les 3 minutes et le refaire en entier — 9 minutes complètes, pas seulement le temps restant, car l''interruption a relancé un dégazage anarchique. Les paliers plus profonds déjà effectués n''ont pas à être refaits. Si la redescente est impossible dans les 3 minutes, ou au moindre symptôme : conduite à tenir ADD (oxygène, alerte), jamais de ré-immersion improvisée plus tard.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-035', 'a', 'Redescendre à 3 m en moins de 3 minutes et refaire le palier de 9 minutes en entier', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-035', 'b', 'Redescendre et faire uniquement les 3 minutes restantes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-035', 'c', 'Rester en surface : 6 minutes suffisent', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-tables-035', 'd', 'Redescendre à 6 m et refaire tous les paliers de la plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-001', 'n2-materiel', 'n2', 'materiel', 'qcm', 'le-détendeur--principe-des-deux-étages', 'À quelle pression le premier étage du détendeur délivre-t-il la moyenne pression (MP) ?', 'Le premier étage abaisse la haute pression du bloc à une moyenne pression asservie à la pression ambiante : environ 8 à 10 bars **au-dessus** de celle-ci, car sa chambre humide communique avec l''eau. C''est ce qui permet au deuxième étage de délivrer un air facile à inspirer à toute profondeur. Une MP fixe en valeur absolue (réponse b) rendrait l''inspiration de plus en plus dure en descendant ; la pression ambiante seule est le rôle du deuxième étage ; et 200 bars est la pression du bloc.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-001', 'a', 'Environ 8 à 10 bars au-dessus de la pression ambiante', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-001', 'b', 'Exactement 8 à 10 bars absolus, quelle que soit la profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-001', 'c', 'À la pression ambiante', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-001', 'd', 'À 200 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-002', 'n2-materiel', 'n2', 'materiel', 'qcm', 'le-détendeur--principe-des-deux-étages', 'Sur quelles sorties du premier étage branche-t-on le manomètre, l''octopus et le direct system du gilet ?', 'Le manomètre doit lire la pression du bloc : il se branche sur une sortie haute pression (HP). L''octopus (deuxième étage de secours) et le direct system du gilet ont besoin d''air à moyenne pression : ils se branchent sur des sorties MP. Brancher un deuxième étage sur une sortie HP est dangereux (l''appareil n''est pas conçu pour 200 bars) et les filetages sont d''ailleurs différenciés pour l''empêcher.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-002', 'a', 'Manomètre sur une sortie HP ; octopus et direct system sur des sorties MP', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-002', 'b', 'Manomètre sur une sortie MP ; octopus sur une sortie HP', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-002', 'c', 'Tous sur des sorties HP', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-002', 'd', 'Tous sur des sorties MP', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-003', 'n2-materiel', 'n2', 'materiel', 'qcm', 'pannes-du-détendeur-et-conduite-à-tenir', 'Pourquoi dit-on que le détendeur tombe en panne « du bon côté » ?', 'Le détendeur est conçu pour défaillir en s''ouvrant : givrage, impureté sous le clapet ou joint usé provoquent un débit continu — il fournit trop d''air, pas zéro. On peut respirer sur un détendeur en débit continu (embout non serré, l''excédent fuit), signaler la panne, passer sur le secours de l''équipier et remonter, car la réserve fond très vite. Aucun détendeur ne se « coupe » ni ne sonne : la vraie panne d''air est presque toujours une panne de gestion, un manomètre non consulté.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-003', 'a', 'En cas de défaillance, il passe en débit continu (trop d''air) plutôt qu''en blocage (plus d''air), et l''on peut respirer sur un détendeur en débit continu', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-003', 'b', 'Il ne tombe jamais en panne', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-003', 'c', 'Il se coupe automatiquement pour économiser l''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-003', 'd', 'Il prévient par une alarme sonore', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-004', 'n2-materiel', 'n2', 'materiel', 'qcm', 'pannes-du-détendeur-et-conduite-à-tenir', 'Quels comportements favorisent le givrage du détendeur en eau froide ? Plusieurs réponses possibles.', 'La détente de l''air refroidit fortement le premier étage : tout ce qui augmente le débit (purge prolongée, respiration forte, essoufflement, gonflage simultané du gilet) accentue ce refroidissement et peut geler le mécanisme, provoquant un débit continu. Respirer sur le détendeur à l''air libre par temps froid introduit en plus de l''humidité qui gèlera. Le détendeur à membrane compensée adapté à l''eau froide est au contraire la prévention : son mécanisme est isolé de l''eau.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-004', 'a', 'Purger longuement le détendeur en surface par temps froid', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-004', 'b', 'Respirer sur le détendeur hors de l''eau avant la mise à l''eau en hiver', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-004', 'c', 'Solliciter un débit important (essoufflement, gonflage du gilet en respirant fort)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-004', 'd', 'Utiliser un détendeur à membrane compensée adapté à l''eau froide', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-005', 'n2-materiel', 'n2', 'materiel', 'qcm', 'le-bloc--fabrication-et-marquages', 'Que signifient les marquages PS et PE gravés sur un bloc ?', 'La PS (pression de service) est la pression maximale de gonflage, par exemple 200 ou 230 bars : un bloc ne doit jamais être gonflé au-dessus. La PE (pression d''épreuve) est la pression du test hydraulique réalisé lors des requalifications, égale à 1,5 fois la PS — soit 300 bars pour une PS de 200 bars. Ces marquages gravés, avec le numéro de série, le volume et les poinçons d''épreuve, constituent la carte d''identité réglementaire du bloc.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-005', 'a', 'PS : pression de service (gonflage maximal) ; PE : pression d''épreuve, égale à 1,5 fois la PS', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-005', 'b', 'PS : pression de sécurité ; PE : pression d''entrée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-005', 'c', 'PS : poids sec ; PE : poids en eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-005', 'd', 'PS : pression de sortie ; PE : pression d''équilibre', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-006', 'n2-materiel', 'n2', 'materiel', 'qcm', 'le-bloc--fabrication-et-marquages', 'Quelle différence de comportement en flottabilité existe-t-il entre un bloc acier et un bloc aluminium ?', 'L''aluminium est moins dense que l''acier : à volume égal, le bloc alu est plus léger (avec des parois plus épaisses) et sa flottabilité peut devenir positive en fin de plongée, une fois l''air consommé — ce qui modifie l''équilibrage et se compense au lestage. Le bloc acier, plus lourd, reste négatif ; il est en revanche plus sensible à la corrosion. La différence de matériau a donc des conséquences très concrètes sur le lestage du plongeur.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-006', 'a', 'Le bloc aluminium, plus léger à volume égal, peut devenir positif en fin de plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-006', 'b', 'Le bloc acier flotte toujours, même plein', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-006', 'c', 'Il n''y a aucune différence entre les deux matériaux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-006', 'd', 'Le bloc aluminium est toujours plus lourd que l''acier', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-007', 'n2-materiel', 'n2', 'materiel', 'qcm', 'la-réglementation-des-blocs--inspections-et-requalifications', 'Quel est le régime réglementaire de suivi des blocs de plongée en France ?', 'Le suivi comprend l''inspection visuelle annuelle — réalisée en structure fédérale par un TIV (Technicien en Inspection Visuelle), avec autocollant daté — et la requalification périodique par un organisme habilité, incluant l''épreuve hydraulique à 1,5 fois la PS : périodicité de droit commun de 2 ans, portée à 6 ans en régime dérogatoire fédéral avec TIV annuel (valeurs à vérifier dans les textes en vigueur). Un bloc choqué, corrodé ou vidé complètement en immersion doit être présenté sans attendre l''échéance. Le milieu d''utilisation ne dispense d''aucun contrôle.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-007', 'a', 'Inspection visuelle annuelle (TIV en club) ; requalification tous les 2 ans, portée à 6 ans pour les blocs suivis en cadre fédéral avec TIV annuel', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-007', 'b', 'Une simple vérification tous les 10 ans', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-007', 'c', 'Aucun contrôle si le bloc est utilisé en eau douce', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-007', 'd', 'Requalification tous les 6 mois pour tous les blocs', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-008', 'n2-materiel', 'n2', 'materiel', 'qcm', 'la-réglementation-des-blocs--inspections-et-requalifications', 'Pourquoi ne faut-il jamais stocker un bloc complètement vide ?', 'Une pression résiduelle maintient le bloc « en surpression » par rapport à l''extérieur : rien ne peut y entrer. Complètement vide, l''air humide ambiant peut pénétrer et amorcer une corrosion interne, invisible de l''extérieur et redoutable pour un équipement sous pression — un bloc vidé en immersion doit d''ailleurs être présenté à l''inspection. Un bloc ne risque pas d''imploser à pression atmosphérique, la règle vaut pour tous les matériaux, et le marquage gravé ne disparaît évidemment pas.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-008', 'a', 'Sans pression résiduelle, l''humidité peut entrer et corroder l''intérieur du bloc', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-008', 'b', 'Un bloc vide risque d''imploser', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-008', 'c', 'C''est interdit uniquement pour les blocs en aluminium', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-008', 'd', 'Un bloc vide perd son marquage de conformité', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-009', 'n2-materiel', 'n2', 'materiel', 'qcm', 'le-gilet-stabilisateur', 'Par où l''air s''évacue-t-il quand on purge un gilet stabilisateur ?', 'L''air monte : il ne peut s''évacuer que par une purge située au point haut du gilet dans la position du moment — purge haute en position verticale, purge basse en position tête en bas. Purger avec la mauvaise purge ne vide rien et fait perdre de précieuses secondes lors d''une remontée qui s''emballe. Il faut connaître l''emplacement de toutes les purges de son gilet et de celui de son équipier (assistance), et ne jamais utiliser le gilet comme ascenseur.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-009', 'a', 'Par la purge située au point le plus haut du gilet dans la position du moment', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-009', 'b', 'Par n''importe quelle purge, quelle que soit la position', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-009', 'c', 'Toujours par la purge basse', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-009', 'd', 'Par le détendeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-materiel-010', 'n2-materiel', 'n2', 'materiel', 'qcm', 'les-instruments-du-plongeur-autonome', 'Quel équipement spécifique le plongeur autonome PA20 doit-il posséder ? Plusieurs réponses possibles.', 'L''équipement du plongeur autonome comprend deux détendeurs complets sur deux sorties indépendantes (pour donner de l''air sans partager son embout), un manomètre, un moyen de contrôler la plongée et la remontée (ordinateur, ou tables avec profondimètre et montre) et, par palanquée, au moins un parachute de palier qui signale la position en surface et sécurise le palier dans le bleu. Le scooter est un équipement de loisir, en rien obligatoire.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-010', 'a', 'Deux détendeurs complets, montés sur deux sorties indépendantes quand la robinetterie le permet', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-010', 'b', 'Un moyen de contrôler la plongée et la remontée (ordinateur, ou tables + profondimètre + montre)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-010', 'c', 'Un parachute de palier au minimum par palanquée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-materiel-010', 'd', 'Un scooter sous-marin', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-001', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'le-cadre--le-code-du-sport-et-la-ffessm', 'Quelle est la différence entre un brevet et une aptitude ?', 'Le brevet (ex. Niveau 2 FFESSM) est une certification de compétences acquise à vie ; les aptitudes (PE40, PA20...) sont le vocabulaire du Code du sport : ce que vous êtes autorisé à faire dans une structure, en fonction de votre brevet, de votre expérience récente et de la décision du directeur de plongée. Cette distinction permet de faire correspondre les brevets des différentes écoles. Ni le brevet n''expire, ni l''aptitude n''est automatique : elle s''apprécie plongée par plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-001', 'a', 'Le brevet est une certification acquise à vie ; l''aptitude (PE40, PA20...) est ce que le Code du sport autorise en structure, selon le brevet, l''expérience récente et la décision du DP', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-001', 'b', 'Ce sont deux mots pour la même chose', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-001', 'c', 'L''aptitude est acquise à vie, le brevet expire chaque année', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-001', 'd', 'Le brevet ne vaut qu''en France, l''aptitude qu''à l''étranger', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-002', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'les-prérogatives-du-niveau-2--pa20-et-pe40', 'Quelles sont les conditions de l''aptitude PA20 du plongeur Niveau 2 ? Plusieurs réponses possibles.', 'Le PA20 (Plongeur Autonome à 20 m) exige de réunir toutes les conditions : majorité, palanquée de 2 ou 3 plongeurs autonomes, équipement conforme et décision du directeur de plongée — qui accorde l''autonomie plongée par plongée, au vu des conditions du jour et de l''expérience de chacun. La présence d''un guide dans l''eau est précisément ce qui distingue la plongée encadrée (PE40) de l''autonomie : en PA20, il n''y a pas de guide.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-002', 'a', 'Être majeur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-002', 'b', 'Une palanquée de 2 ou 3 plongeurs autonomes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-002', 'c', 'L''autorisation du directeur de plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-002', 'd', 'La présence d''un guide de palanquée dans l''eau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-003', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'les-prérogatives-du-niveau-2--pa20-et-pe40', 'Que signifie l''aptitude PE40 du plongeur Niveau 2 ?', 'PE40 signifie « Plongeur Encadré à 40 mètres » : dans l''espace 0-40 m, le Niveau 2 évolue sous la responsabilité d''un guide de palanquée qui conduit la plongée. L''autonomie du N2 est limitée à 20 m (PA20) : il n''existe pas de « PA40 » pour ce niveau — l''autonomie à 40 m est une prérogative du Niveau 3. Le sigle n''a rien à voir avec une durée ni avec de l''encadrement d''élèves.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-003', 'a', 'Plongeur Encadré jusqu''à 40 m, en palanquée conduite par un guide de palanquée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-003', 'b', 'Plongeur Autonome jusqu''à 40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-003', 'c', 'Plongée limitée à 40 minutes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-003', 'd', 'Plongeur Encadrant de 40 élèves', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-004', 'n2-reglementation', 'n2', 'reglementation', 'vrai-faux', 'les-prérogatives-du-niveau-2--pa20-et-pe40', 'Un plongeur Niveau 2 mineur peut plonger en autonomie à 20 m si le directeur de plongée l''y autorise.', 'C''est faux : l''autonomie exige la majorité, sans dérogation possible — même le directeur de plongée ne peut pas l''accorder à un mineur. Un Niveau 2 mineur plonge uniquement encadré (PE40) jusqu''à sa majorité. C''est l''une des conditions cumulatives de l''autonomie : brevet, majorité, décision du DP et équipement conforme ; il suffit qu''une seule manque pour que la plongée soit irrégulière.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-004', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-004', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-005', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'les-prérogatives-du-niveau-2--pa20-et-pe40', 'Quels sont les espaces d''évolution définis par le Code du sport ?', 'Le Code du sport définit les espaces d''évolution 0-6 m, 0-12 m, 0-20 m, 0-40 m et 0-60 m, qui servent de vocabulaire commun aux aptitudes (PE20, PA12, PA20, PE40...) ; la profondeur maximale de la plongée à l''air en exploration est fixée à 60 m. Ces bornes sont réglementaires et identiques pour tous : aucun club ne peut définir ses propres espaces.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-005', 'a', '0-6 m, 0-12 m, 0-20 m, 0-40 m et 0-60 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-005', 'b', '0-10 m, 0-30 m et 0-50 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-005', 'c', '0-15 m, 0-35 m et 0-55 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-005', 'd', 'Ils sont librement fixés par chaque club', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-006', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'la-palanquée-et-le-directeur-de-plongée', 'Quels sont les effectifs maximaux d''une palanquée selon le Code du sport ?', 'Le piège d''examen classique : la palanquée autonome compte au maximum 3 plongeurs (sans guide), la palanquée encadrée 4 plongeurs encadrés plus le guide de palanquée (et éventuellement un plongeur supplémentaire apte selon les cas prévus par les textes). Inverser les deux chiffres (réponse b) est l''erreur la plus fréquente. Ces effectifs correspondent à ce qu''un guide peut surveiller et à ce qu''une équipe autonome peut gérer en assistance mutuelle.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-006', 'a', 'Palanquée autonome : 3 plongeurs max ; palanquée encadrée : 4 plongeurs encadrés max, plus le guide', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-006', 'b', 'Palanquée autonome : 4 plongeurs ; palanquée encadrée : 3 plus le guide', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-006', 'c', '5 plongeurs dans tous les cas', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-006', 'd', '2 plongeurs maximum, autonomes ou encadrés', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-007', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'la-palanquée-et-le-directeur-de-plongée', 'Quelles missions relèvent du directeur de plongée ? Plusieurs réponses possibles.', 'Le DP fixe site, profondeur maximale, durée et consignes, constitue les palanquées selon les aptitudes, décide de l''autonomie, s''assure du matériel de secours, organise la sécurité surface, remplit la fiche de sécurité et déclenche le plan de secours en cas d''accident. Il ne conduit pas chaque palanquée sous l''eau : c''est le rôle des guides de palanquée — le DP organise et supervise l''activité depuis la surface.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-007', 'a', 'Fixer les caractéristiques de la plongée et constituer les palanquées', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-007', 'b', 'Autoriser (ou non) l''autonomie des plongeurs qui y prétendent', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-007', 'c', 'Remplir la fiche de sécurité et organiser la sécurité surface', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-007', 'd', 'Conduire chaque palanquée sous l''eau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-008', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'le-matériel-obligatoire', 'Quel matériel de secours doit être présent sur le site, sous la responsabilité du DP ? Plusieurs réponses possibles.', 'Sur le site doivent se trouver les moyens du plan de secours : oxygénothérapie de capacité adaptée, moyen d''alerte, trousse de secours, eau douce non gazeuse, couverture isothermique et fiche d''évacuation. Le plongeur n''en est pas responsable mais doit savoir où ils se trouvent et comment les utiliser. Le caisson hyperbare, lui, est une installation médicale hospitalière vers laquelle on évacue : il n''existe pas de version « portable » réglementaire sur les bateaux de plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-008', 'a', 'Une oxygénothérapie (bouteille d''O₂ avec détendeur et masque)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-008', 'b', 'Un plan de secours et un moyen de communication pour alerter', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-008', 'c', 'Une trousse de secours, de l''eau douce non gazeuse, une couverture isothermique et une fiche d''évacuation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-008', 'd', 'Un caisson hyperbare portable', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-009', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'les-documents-du-plongeur', 'Quel document atteste votre niveau de plongée auprès de toute structure, en France comme à l''étranger ?', 'La carte de certification — dite « carte CMAS » pour la reconnaissance internationale — atteste votre niveau auprès de toute structure. La licence matérialise l''adhésion fédérale et l''assurance en responsabilité civile, le certificat médical atteste l''absence de contre-indication, et la fiche de sécurité est le document d''organisation tenu par le DP : chacun de ces documents a un rôle distinct, et le DP s''appuie en plus sur le carnet de plongée pour évaluer l''expérience récente.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-009', 'a', 'La carte de certification (carte brevet double face FFESSM/CMAS)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-009', 'b', 'La licence fédérale', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-009', 'c', 'Le certificat médical', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-009', 'd', 'La fiche de sécurité', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-regl-010', 'n2-reglementation', 'n2', 'reglementation', 'qcm', 'devoirs-et-responsabilités-du-plongeur-autonome', 'En autonomie, votre palanquée perd le contact avec un équipier. Quelle est la procédure convenue classique ?', 'La conduite en cas de perte de contact fait partie de la planification que la palanquée autonome convient avant l''immersion : se chercher environ une minute, puis remonter en respectant la procédure de désaturation et se retrouver en surface. Continuer la plongée abandonne l''équipier, se disperser multiplie les perdus, et remonter sans paliers troque un problème d''organisation contre un risque d''accident de désaturation.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-010', 'a', 'Se chercher environ une minute, puis remonter en respectant la procédure de désaturation et se retrouver en surface', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-010', 'b', 'Continuer la plongée : il finira par revenir', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-010', 'c', 'Se disperser dans toutes les directions pour le retrouver au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-regl-010', 'd', 'Remonter en urgence sans paliers', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-milieu-001', 'n2-orientation-milieu', 'n2', 'environnement', 'qcm', 'sorienter--une-compétence-de-sécurité', 'Quand le travail d''orientation d''une plongée commence-t-il ?', 'L''orientation commence au briefing : écouter la description du site (profondeur, topographie, courant, position du mouillage), mémoriser le plan de plongée et noter le cap général, puis prendre des repères de surface (position du bateau, soleil) avant l''immersion. Attendre d''être au fond — ou pire, d''être perdu — pour s''en préoccuper conduit aux remontées dans le bleu, à la dérive en surface et au palmage épuisant tout équipé.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-001', 'a', 'Avant la mise à l''eau, au briefing : topographie du site, sens du courant, position du mouillage, plan de la plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-001', 'b', 'Une fois arrivé au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-001', 'c', 'Uniquement quand on est perdu', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-001', 'd', 'Au moment de la remontée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-milieu-002', 'n2-orientation-milieu', 'n2', 'environnement', 'qcm', 'lorientation-sans-instruments', 'Comment les rides de sable (ripple marks) aident-elles à s''orienter ?', 'Les rides de sable sont créées par le va-et-vient de la houle : elles s''alignent parallèlement à la côte. Les traverser perpendiculairement fait donc gagner ou perdre de la distance à la terre — un repère naturel précieux sur les fonds sableux sans relief. Elles n''ont aucun lien avec le nord magnétique (c''est le rôle du compas), ni avec la position du bateau, et c''est la houle, pas le courant, qui les façonne.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-002', 'a', 'Formées par la houle, elles sont parallèles à la côte : les traverser perpendiculairement mène vers le large ou vers la terre', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-002', 'b', 'Elles pointent toujours vers le nord', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-002', 'c', 'Elles indiquent la position du bateau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-002', 'd', 'Elles suivent la direction du courant de fond', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-milieu-003', 'n2-orientation-milieu', 'n2', 'environnement', 'qcm', 'lorientation-sans-instruments', 'Quels repères naturels servent à s''orienter sans instrument ? Plusieurs réponses possibles.', 'Le milieu fournit des repères fiables : le soleil (partir avec le soleil dans le dos, revenir face à lui), la pente et les isobathes (suivre une ligne de sonde permet de refaire le trajet en sens inverse), le courant noté au départ et trois ou quatre balises visuelles mémorisées le long du trajet. Le « sens de nage des poissons » n''est pas un repère : les anthias se tiennent face au courant, mais les poissons ne « vont » certainement pas tous vers la côte.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-003', 'a', 'La position du soleil, stable à l''échelle d''une plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-003', 'b', 'La pente du fond (un fond qui descend à l''aller remonte au retour)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-003', 'c', 'Le courant noté au départ et des « balises » visuelles mémorisées (roche remarquable, herbier...)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-003', 'd', 'Le sens de nage des poissons, qui vont toujours vers la côte', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-milieu-004', 'n2-orientation-milieu', 'n2', 'environnement', 'calcul', 'lorientation-avec-instruments--le-compas', 'Vous avez suivi un cap 300° à l''aller. Quel cap inverse prendre pour revenir ?', 'Le cap inverse s''obtient en ajoutant ou retranchant 180° : $300 - 180 = 120°$. On retranche ici car $300 + 180 = 480$ dépasse 360° (la réponse 480° n''existe pas sur un compas). Les réponses 60° et 240° correspondent à des erreurs de calcul mental courantes ; l''astuce pratique : si le cap est supérieur à 180°, on retranche 180 ; s''il est inférieur, on ajoute 180.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-004', 'a', '120°', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-004', 'b', '480°', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-004', 'c', '60°', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-004', 'd', '240°', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-milieu-005', 'n2-orientation-milieu', 'n2', 'environnement', 'qcm', 'lorientation-avec-instruments--le-compas', 'Quels pièges faussent l''utilisation du compas en plongée ? Plusieurs réponses possibles.', 'Trois pièges classiques : les masses métalliques (bloc, lampe, épave) dévient l''aiguille — il faut écarter le compas des objets ferreux ; un compas incliné voit son aiguille frotter et se bloquer — il se tient horizontal, dans l''axe du corps ; et le courant fait « crabe » : la trajectoire dérive même à cap constant, d''où l''intérêt de combiner compas, profondeur et repères naturels. La profondeur, en revanche, n''a aucun effet sur le champ magnétique terrestre.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-005', 'a', 'Les masses métalliques proches (bloc, lampe, épave) qui dévient l''aiguille', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-005', 'b', 'L''inclinaison du compas, qui bloque l''aiguille', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-005', 'c', 'Le courant, qui fait dériver la trajectoire même si le cap est bien tenu', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-005', 'd', 'La profondeur, qui inverse le nord magnétique', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-milieu-006', 'n2-orientation-milieu', 'n2', 'environnement', 'qcm', 'matelotage--les-nœuds-et-le-mouillage', 'Quel nœud réalise une boucle fixe qui ne serre pas et se défait facilement même après une forte tension ?', 'Le nœud de chaise forme une boucle fixe en bout de cordage — pour amarrer, hisser ou saisir un anneau — qui ne serre pas sous charge et se défait facilement même après une forte tension : c''est le nœud emblématique du matelotage. Le nœud plat sert à réunir deux bouts de même diamètre, le nœud en huit est un nœud d''arrêt en extrémité, et le cabestan sert à frapper un bout sur une barre ou un anneau.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-006', 'a', 'Le nœud de chaise', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-006', 'b', 'Le nœud plat', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-006', 'c', 'Le nœud en huit', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-006', 'd', 'Le nœud de cabestan', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-milieu-007', 'n2-orientation-milieu', 'n2', 'environnement', 'qcm', 'matelotage--les-nœuds-et-le-mouillage', 'Quelle longueur de mouillage file-t-on au minimum, et pourquoi le plongeur ne doit-il pas remonter l''ancre juste après sa plongée ?', 'On file au moins trois fois la hauteur d''eau (davantage par vent fort) : l''ancre tient par son crochage et par le poids de la chaîne qui travaille à l''horizontale — un mouillage trop court tire l''ancre vers le haut et la fait déraper. Quant à remonter l''ancre, c''est un effort intense : juste après une plongée, l''effort favorise la formation de bulles d''azote (facteur d''ADD) — cette tâche revient à ceux qui n''ont pas plongé, ou attend.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-007', 'a', 'Au moins 3 fois la hauteur d''eau ; remonter l''ancre est un effort violent qui favorise l''ADD après la plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-007', 'b', 'Exactement la hauteur d''eau ; l''ancre est trop sale pour un plongeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-007', 'c', '10 fois la hauteur d''eau ; l''ancre est trop lourde réglementairement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-007', 'd', 'La longueur importe peu si l''ancre est lourde', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n2-milieu-008', 'n2-orientation-milieu', 'n2', 'environnement', 'qcm', 'le-milieu-vivant--méditerranée-et-atlantique', 'Qu''est-ce que la posidonie ?', 'La posidonie est une plante à fleurs — et non une algue — qui forme les vastes herbiers de Méditerranée jusqu''à 30-40 m : véritable poumon et nurserie de la mer, elle est protégée (interdiction d''y mouiller pour les bateaux équipés, interdiction d''arracher ou de dégrader). Les grandes algues brunes des fonds atlantiques sont les laminaires, son « équivalent » comme zone de vie ; le coralligène désigne les concrétions calcaires des tombants méditerranéens.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-008', 'a', 'Une plante à fleurs protégée qui forme les grands herbiers de Méditerranée, nurserie et poumon de la mer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-008', 'b', 'Une algue brune des côtes atlantiques', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-008', 'c', 'Un corail des tombants profonds', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n2-milieu-008', 'd', 'Une méduse urticante', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-001', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'pressions--les-fondations-du-raisonnement', 'Quelle est la pression absolue à 60 m en eau de mer ?', 'La pression absolue vaut $P_{abs}=P_{atm}+P_{rel}=1+60/10=7$ bar. L''erreur classique (6 bar) oublie l''atmosphère et ne compte que la pression relative ; 70 bar confond bar et mètres.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-001', 'a', '6 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-001', 'b', '7 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-001', 'c', '6,5 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-001', 'd', '70 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-002', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'pressions--les-fondations-du-raisonnement', 'À quelle profondeur en mer correspond une pression absolue de 4,8 bar ?', 'On isole la profondeur : $(P_{abs}-1)\times 10=(4{,}8-1)\times 10=38$ m. On retire d''abord la pression atmosphérique (1 bar) puis on multiplie par 10 ; oublier le -1 donne l''erreur 48 m.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-002', 'a', '48 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-002', 'b', '58 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-002', 'c', '38 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-002', 'd', '4,8 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-003', 'n3-physique-appliquee', 'n3', 'physique', 'qcm', 'pressions--les-fondations-du-raisonnement', 'Où la variation relative de pression est-elle la plus forte ?', 'Entre 0 et 10 m la pression double (+100 %), alors qu''entre 50 et 60 m elle ne croît que d''environ 17 %. C''est pourquoi les variations de flottabilité et les barotraumatismes sont les plus brutaux près de la surface.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-003', 'a', 'Entre 50 et 60 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-003', 'b', 'Entre 0 et 10 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-003', 'c', 'Entre 30 et 40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-003', 'd', 'Elle est constante à toute profondeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-004', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'boyle-mariotte--volumes-blocs-et-quantités-de-gaz', 'Un bloc de 15 L gonflé à 220 bar contient quel volume d''air ramené à la surface ?', 'Par Boyle-Mariotte, la quantité d''air détendu vaut volume × pression = 15 × 220 = 3300 L. C''est cette quantité en litres, et non la pression seule, qui détermine l''autonomie.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-004', 'a', '220 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-004', 'b', '3300 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-004', 'c', '15 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-004', 'd', '1500 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-005', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'boyle-mariotte--volumes-blocs-et-quantités-de-gaz', 'Un parachute contient 12 L d''air à 40 m (5 bar). Quel volume tend-il à occuper à 10 m (2 bar), sans purge ?', 'À température constante $P_1V_1=P_2V_2$, donc $V_2=(5\times 12)/2=30$ L. Le gaz se dilate en remontant : d''où l''obligation de purger tout volume gazeux (gilet, parachute, poumons) à la remontée.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-005', 'a', '24 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-005', 'b', '30 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-005', 'c', '6 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-005', 'd', '60 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-006', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'boyle-mariotte--volumes-blocs-et-quantités-de-gaz', 'Combien d''air détendu contient un bloc de 12 L gonflé à 200 bar ?', '12 × 200 = 2400 L d''air ramenés à la pression atmosphérique. Confondre pression et quantité (répondre 200) est l''erreur type : deux blocs à 200 bar ne contiennent pas la même chose si leurs volumes diffèrent.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-006', 'a', '2400 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-006', 'b', '200 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-006', 'c', '1200 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-006', 'd', '2000 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-007', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'dalton--les-pressions-partielles-aux-profondeurs-du-n3', 'À 60 m (7 bar), quelle est la pression partielle d''azote dans l''air (79 % de N₂) ?', 'Loi de Dalton : $P_pN_2=P_{abs}\times\%N_2=7\times0{,}79=5{,}53$ bar. Cette valeur, très supérieure au seuil de narcose (~3,2 bar), explique l''altération quasi systématique du jugement à 60 m.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-007', 'a', '5,53 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-007', 'b', '0,79 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-007', 'c', '1,47 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-007', 'd', '7 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-008', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'dalton--les-pressions-partielles-aux-profondeurs-du-n3', 'À 60 m (7 bar), quelle est la pression partielle d''oxygène dans l''air (21 % d''O₂) ?', '$P_pO_2=7\times0{,}21=1{,}47$ bar. On est proche du seuil de toxicité neurologique (~1,6 bar) : la limite réglementaire des 60 m à l''air conserve une marge, mais réduite.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-008', 'a', '1,47 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-008', 'b', '0,21 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-008', 'c', '5,53 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-008', 'd', '2,1 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-009', 'n3-physique-appliquee', 'n3', 'physique', 'qcm', 'dalton--les-pressions-partielles-aux-profondeurs-du-n3', 'À partir de quelle pression partielle d''azote la narcose devient-elle sensible chez la plupart des plongeurs ?', 'La narcose devient sensible dès une $P_pN_2$ d''environ 3,2 bar, atteinte vers 30 m à l''air. 1,6 bar est le seuil de toxicité de l''oxygène, pas celui de la narcose.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-009', 'a', 'Environ 1,6 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-009', 'b', 'Environ 3,2 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-009', 'c', 'Environ 5,5 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-009', 'd', 'Environ 7 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-010', 'n3-physique-appliquee', 'n3', 'physique', 'vrai-faux', 'dalton--les-pressions-partielles-aux-profondeurs-du-n3', 'Toute comparaison physiologique entre deux gaz ou deux profondeurs doit se faire en pressions partielles, jamais en pourcentages ou en profondeurs brutes.', 'Vrai : c''est la pression partielle, produit de la pression absolue par la fraction, qui gouverne les effets d''un gaz. Comparer des pourcentages ou des profondeurs sans les convertir en $P_p$ conduit à des erreurs de raisonnement.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-010', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-010', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-011', 'n3-physique-appliquee', 'n3', 'physique', 'qcm', 'henry--dissolution-des-gaz-et-gradients', 'Selon la loi de Henry, de quoi dépend la quantité d''azote dissoute à saturation dans un tissu ?', 'À saturation, la quantité de gaz dissoute est proportionnelle à la pression partielle de ce gaz au contact du liquide. La profondeur agit via la pression partielle, mais elle n''est pas le seul facteur : durée, température et nature du tissu comptent aussi.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-011', 'a', 'De la seule profondeur maximale', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-011', 'b', 'De la pression partielle d''azote au contact', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-011', 'c', 'De la température de l''eau uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-011', 'd', 'Du volume du bloc utilisé', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-012', 'n3-physique-appliquee', 'n3', 'physique', 'qcm', 'henry--dissolution-des-gaz-et-gradients', 'Qu''est-ce qui pilote la vitesse des échanges d''azote entre les alvéoles et les tissus ?', 'Le moteur des échanges est le gradient de pression : plus l''écart entre la $P_pN_2$ alvéolaire et la tension dissoute dans les tissus est grand, plus l''échange est rapide. La descente crée un gradient entrant, la remontée un gradient sortant.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-012', 'a', 'Le gradient de pression partielle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-012', 'b', 'La couleur de la combinaison', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-012', 'c', 'La marque de l''ordinateur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-012', 'd', 'Le volume résiduel des poumons', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-013', 'n3-physique-appliquee', 'n3', 'physique', 'vrai-faux', 'henry--dissolution-des-gaz-et-gradients', 'Les tissus gras dissolvent davantage d''azote que les tissus aqueux.', 'Vrai : la graisse dissout plus d''azote que l''eau, ce qui explique que deux plongeurs ne se chargent pas de la même façon pour un même profil. C''est l''une des raisons des marges de sécurité systématiques.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-013', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-013', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-014', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'archimède--flottabilité-lestage-et-levage', 'Un plongeur équipé pèse 95 kg pour un volume total de 94 L, gilet vide, en eau de mer (1,025 kg/L). Quel est son poids apparent ?', 'Poussée = 94 × 1,025 ≈ 96,4 kgf ; poids apparent = 95 − 96,4 = −1,4 kg. Le poids apparent négatif signifie que la poussée l''emporte : le plongeur flotte et devra ajouter un peu de lest.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-014', 'a', '+1,4 kg (il coule)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-014', 'b', '−1,4 kg (il flotte)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-014', 'c', '0 kg (équilibré)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-014', 'd', '−94 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-015', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'archimède--flottabilité-lestage-et-levage', 'On remonte un moteur de 60 kg occupant 20 L, posé à 40 m en eau de mer (1,025 kg/L). Quel est son poids apparent au fond ?', 'Poussée sur l''objet = 20 × 1,025 = 20,5 kgf ; poids apparent = 60 − 20,5 = 39,5 kg. C''est cette valeur qu''il faudra compenser par la poussée du parachute de levage.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-015', 'a', '39,5 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-015', 'b', '60 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-015', 'c', '20,5 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-015', 'd', '80,5 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-016', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'archimède--flottabilité-lestage-et-levage', 'Pour équilibrer un poids apparent de 39,5 kg en eau de mer (1,025 kg/L), quel volume d''air doit contenir le parachute de levage ?', 'Le volume de flotteur nécessaire est 39,5 / 1,025 ≈ 38,5 L (on choisira un parachute de 40 L ou plus). 193 L est la quantité d''air détendu à injecter à 40 m, pas le volume du parachute au fond.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-016', 'a', '≈ 38,5 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-016', 'b', '≈ 20 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-016', 'c', '≈ 60 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-016', 'd', '≈ 193 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-017', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'archimède--flottabilité-lestage-et-levage', 'Quel volume d''air détendu faut-il pour remplir un parachute de 38,5 L à 40 m (5 bar) ?', 'À 40 m la pression est de 5 bar, donc il faut 38,5 × 5 ≈ 193 L d''air détendu (par Boyle-Mariotte). Ce volume, près de 13 bar d''un bloc de 15 L, doit être intégré au calcul d''autonomie.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-017', 'a', '≈ 193 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-017', 'b', '38,5 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-017', 'c', '≈ 77 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-017', 'd', '≈ 8 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-018', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'enchaîner-les-lois--la-méthode-des-calculs-complets', 'Un plongeur (20 L/min en surface) descend à 60 m avec un bloc de 12 L à 200 bar, réserve 50 bar. Quelle est son autonomie approximative au fond ?', 'Air utilisable = 12 × (200 − 50) = 1800 L ; consommation à 60 m (7 bar) = 20 × 7 = 140 L/min ; autonomie = 1800 / 140 ≈ 12,8 min. Ce chiffre très court résume l''exigence de la plongée profonde.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-018', 'a', '≈ 12,8 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-018', 'b', '≈ 90 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-018', 'c', '≈ 25 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-018', 'd', '≈ 7 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-019', 'n3-physique-appliquee', 'n3', 'physique', 'calcul', 'enchaîner-les-lois--la-méthode-des-calculs-complets', 'Deux plongeurs (20 L/min) descendent à 50 m avec des blocs de 15 L à 230 bar. Quelle durée de fond s''ils veulent entamer la remontée à 90 bar ?', 'Air utilisable = 15 × (230 − 90) = 2100 L ; consommation à 50 m (6 bar) = 20 × 6 = 120 L/min ; durée = 2100 / 120 = 17,5 min, arrondie par sécurité à 17 min. Chaque résultat intermédiaire doit avoir un sens physique.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-019', 'a', '≈ 17 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-019', 'b', '≈ 35 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-019', 'c', '≈ 8 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-019', 'd', '≈ 26 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-phys-020', 'n3-physique-appliquee', 'n3', 'physique', 'qcm', 'enchaîner-les-lois--la-méthode-des-calculs-complets', 'Quelle est la bonne méthode pour un calcul complet de plongée ?', 'La méthode consiste à convertir les profondeurs en pressions absolues, appliquer les lois une à une en écrivant chaque étape, puis contrôler l''ordre de grandeur. Sauter la conversion ou ne pas vérifier le résultat mène aux erreurs classiques.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-020', 'a', 'Convertir d''abord les profondeurs en pressions absolues puis appliquer une loi par étape', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-020', 'b', 'Multiplier directement la profondeur par la consommation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-020', 'c', 'Raisonner uniquement en pression, jamais en litres', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-phys-020', 'd', 'Ignorer le contrôle de l''ordre de grandeur du résultat', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-001', 'n3-planification-air', 'n3', 'physique', 'calcul', 'connaître-sa-consommation-individuelle', 'À 20 m (3 bar), un plongeur consomme 50 bar d''un bloc de 12 L en 10 min. Quelle est sa consommation ramenée à la surface ?', 'Air consommé = 50 × 12 = 600 L ; débit à 20 m = 600 / 10 = 60 L/min ; consommation surface = 60 / 3 = 20 L/min. On ramène toujours le débit mesuré à 1 bar en divisant par la pression absolue.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-001', 'a', '20 L/min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-001', 'b', '60 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-001', 'c', '5 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-001', 'd', '50 L/min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-002', 'n3-planification-air', 'n3', 'physique', 'qcm', 'connaître-sa-consommation-individuelle', 'Quelle valeur de consommation faut-il retenir pour la planification ?', 'On planifie sur une valeur majorée, car la consommation double avec l''effort, le froid, le stress ou le courant. Retenir son meilleur chiffre expose à manquer d''air dans les conditions réelles.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-002', 'a', 'Votre record de sobriété', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-002', 'b', 'Une valeur majorée mesurée sur vos plongées réelles', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-002', 'c', 'La valeur théorique de 15 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-002', 'd', 'La moitié de votre consommation mesurée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-003', 'n3-planification-air', 'n3', 'physique', 'qcm', 'la-consommation-déquipe--planifier-sur-le-plus-consommateur', 'Sur quel plongeur dimensionne-t-on la plongée d''une palanquée autonome ?', 'La palanquée remontant ensemble, c''est le plongeur le plus consommateur qui dimensionne la plongée. Planifier sur la moyenne laisse le plus consommateur à court d''air alors que tout le groupe doit remonter avec lui.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-003', 'a', 'Le plus expérimenté', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-003', 'b', 'Le plus gros consommateur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-003', 'c', 'La moyenne de l''équipe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-003', 'd', 'Le chef de palanquée uniquement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-004', 'n3-planification-air', 'n3', 'physique', 'vrai-faux', 'la-consommation-déquipe--planifier-sur-le-plus-consommateur', 'La marge de gaz d''un équipier autonome doit pouvoir ramener deux plongeurs en surface avec paliers en cas de panne d''air.', 'Vrai : l''air de secours partagé fait partie du plan. La réserve d''un autonome n''est pas un confort personnel, c''est le gaz de sauvetage de son binôme en cas de panne d''air.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-004', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-004', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-005', 'n3-planification-air', 'n3', 'physique', 'qcm', 'réserve-demi-tour-et-règle-des-tiers-adaptée-au-loisir', 'Quelle est la pression de réserve conventionnelle en surface en fin de plongée ?', 'Par convention d''enseignement, on prévoit d''arriver en surface avec 50 bar de réserve, jamais budgétés. Ce gaz couvre l''imprévu de dernière minute (palier prolongé, assistance, recherche du mouillage).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-005', 'a', '50 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-005', 'b', '10 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-005', 'c', '100 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-005', 'd', '0 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-006', 'n3-planification-air', 'n3', 'physique', 'qcm', 'réserve-demi-tour-et-règle-des-tiers-adaptée-au-loisir', 'En quoi consiste la règle des tiers, héritée de la plongée sous plafond ?', 'La règle des tiers réserve un tiers du gaz pour l''aller, un tiers pour le retour et un tiers intouchable. En milieu ouvert loisir elle s''adapte, mais redevient la référence stricte sur un site à retour obligatoire.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-006', 'a', '1/3 aller, 1/3 retour, 1/3 intouchable', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-006', 'b', '1/2 aller, 1/2 retour', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-006', 'c', '1/3 réserve, 2/3 exploration', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-006', 'd', 'Tout l''air pour l''aller', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-007', 'n3-planification-air', 'n3', 'physique', 'calcul', 'réserve-demi-tour-et-règle-des-tiers-adaptée-au-loisir', 'Bloc de 15 L à 220 bar (3300 L). Remontée et paliers estimés à 400 L, réserve de 50 bar. Quel est l''air disponible pour l''exploration ?', 'Réserve = 50 × 15 = 750 L ; air d''exploration = 3300 − 400 − 750 = 2150 L. On retranche toujours d''abord la remontée, les paliers et la réserve du volume total avant de budgéter l''exploration.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-007', 'a', '2150 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-007', 'b', '2900 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-007', 'c', '3300 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-007', 'd', '750 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-008', 'n3-planification-air', 'n3', 'physique', 'calcul', 'chiffrer-le-profil-complet--lexemple-corrigé-de-référence', 'Palanquée de deux (planification 22 L/min), bloc de 15 L à 220 bar, réserve 50 bar. Quel air est utilisable ?', 'Air utilisable = 15 × (220 − 50) = 2550 L. On déduit la réserve dès le départ pour ne budgéter que le gaz réellement exploitable.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-008', 'a', '2550 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-008', 'b', '3300 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-008', 'c', '2200 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-008', 'd', '1700 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-009', 'n3-planification-air', 'n3', 'physique', 'calcul', 'chiffrer-le-profil-complet--lexemple-corrigé-de-référence', 'À 40 m (5 bar), une consommation de planification de 22 L/min donne quel débit au fond ?', 'Consommation au fond = consommation surface × pression absolue = 22 × 5 = 110 L/min. C''est ce débit, cinq fois celui de la surface, qui rend le temps de fond si coûteux à 40 m.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-009', 'a', '110 L/min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-009', 'b', '22 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-009', 'c', '88 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-009', 'd', '220 L/min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-010', 'n3-planification-air', 'n3', 'physique', 'calcul', 'chiffrer-le-profil-complet--lexemple-corrigé-de-référence', 'Air utilisable 2550 L ; consommation au fond 110 L/min à 40 m ; déco ≈ 385 L. Combien de minutes de fond restent après déduction de la déco ?', 'Après déco : 2550 − 385 = 2165 L disponibles pour le fond ; 2165 / 110 ≈ 19,7 min, soit environ 19 min. On réserve toujours l''air de la décompression avant de calculer le temps de fond.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-010', 'a', '≈ 19 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-010', 'b', '≈ 23 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-010', 'c', '≈ 12 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-010', 'd', '≈ 35 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-011', 'n3-planification-air', 'n3', 'physique', 'qcm', 'construire-le-profil--profond-dabord-remonter-proprement', 'Quelle vitesse de remontée retenir du fond au premier palier (référence MN90) ?', 'La référence MN90 est de 15 à 17 m/min du fond au premier palier, puis 6 m/min entre les paliers et vers la surface. Une remontée plus rapide crée une sursaturation dangereuse.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-011', 'a', '15 à 17 m/min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-011', 'b', '30 m/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-011', 'c', '6 m/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-011', 'd', '5 m/min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-012', 'n3-planification-air', 'n3', 'physique', 'qcm', 'construire-le-profil--profond-dabord-remonter-proprement', 'Comment doit se dérouler le profil d''une plongée bien construite ?', 'On atteint la profondeur maximale en début de plongée puis on évolue vers le haut ; un profil descendant en fin recharge les tissus rapides au pire moment. Les yo-yo répétés sont proscrits.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-012', 'a', 'Profondeur maximale en début de plongée, puis évolution vers le haut', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-012', 'b', 'Profondeur maximale en fin de plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-012', 'c', 'Une succession de yo-yo pour explorer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-012', 'd', 'À profondeur constante toute la plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-013', 'n3-planification-air', 'n3', 'physique', 'vrai-faux', 'construire-le-profil--profond-dabord-remonter-proprement', 'Le palier de principe de 3 min à 3 m fait partie du plan, même quand aucun palier n''est obligatoire.', 'Vrai : le palier de principe coûte moins de 100 L d''air et réduit fortement la charge en bulles circulantes. Il est systématique et fait partie du plan, pas des options.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-013', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-013', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-014', 'n3-planification-air', 'n3', 'physique', 'qcm', 'pendant-la-plongée--le-plan-vit', 'Si la consommation dépasse le plan pendant la plongée (courant, effort, froid), que fait-on ?', 'En cas de surconsommation, on raccourcit la plongée et jamais la décompression ni la réserve. Écourter la déco ou entamer la réserve transforme un simple contretemps en risque d''accident.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-014', 'a', 'On raccourcit la plongée, jamais la décompression ni la réserve', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-014', 'b', 'On puise dans la réserve', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-014', 'c', 'On supprime le palier', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-014', 'd', 'On descend plus profond', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-015', 'n3-planification-air', 'n3', 'physique', 'vrai-faux', 'pendant-la-plongée--le-plan-vit', 'Toute décision qui peut être prise en surface doit l''être en surface, car le fond altère le jugement (narcose, euphorie).', 'Vrai : les décisions prises au fond sont altérées par la narcose et l''euphorie du site. Le fond est un lieu d''exécution du plan, pas de délibération.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-015', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-015', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-plan-016', 'n3-planification-air', 'n3', 'physique', 'qcm', 'pendant-la-plongée--le-plan-vit', 'Qui déclenche le demi-tour dans une palanquée autonome ?', 'Le premier qui atteint la pression de demi-tour déclenche le retour pour toute la palanquée. Attendre le dernier expose le plus consommateur à manquer d''air pendant la remontée commune.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-016', 'a', 'Le premier qui atteint la pression de demi-tour', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-016', 'b', 'Le dernier à atteindre sa réserve', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-016', 'c', 'Le plus expérimenté quand il le souhaite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-plan-016', 'd', 'Personne, on remonte à l''air', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-001', 'n3-tables-avancees', 'n3', 'tables-deco', 'qcm', 'le-cadre-mn90--conditions-de-validité-et-vocabulaire', 'Quelles sont les conditions de validité des tables MN90 ?', 'Les MN90 sont valides pour la plongée à l''air, au niveau de la mer, jusqu''à 60 m, deux plongées par 24 h au plus, avec les vitesses de remontée réglementaires. Sortir de ce cadre (altitude, nitrox, 3e plongée) invalide la lecture directe.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-001', 'a', 'Plongée à l''air, au niveau de la mer, 60 m maximum, 2 plongées par 24 h', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-001', 'b', 'Plongée au nitrox, en altitude, sans limite de profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-001', 'c', 'Trois plongées par 24 h autorisées', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-001', 'd', 'Uniquement au-delà de 60 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-002', 'n3-tables-avancees', 'n3', 'tables-deco', 'qcm', 'le-cadre-mn90--conditions-de-validité-et-vocabulaire', 'Comment classe-t-on une seconde plongée dont l''intervalle de surface est de 10 minutes ?', 'Un intervalle inférieur à 15 min classe la plongée en consécutive : les tissus n''ont presque rien restitué, on traite les deux immersions comme une seule. De 15 min à 12 h, ce serait une successive.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-002', 'a', 'Consécutive', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-002', 'b', 'Successive', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-002', 'c', 'Simple', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-002', 'd', 'Interdite', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-003', 'n3-tables-avancees', 'n3', 'tables-deco', 'vrai-faux', 'le-cadre-mn90--conditions-de-validité-et-vocabulaire', 'La profondeur retenue pour la table est la profondeur maximale atteinte, même un court instant.', 'Vrai : on retient toujours la profondeur maximale atteinte, même brièvement, car c''est elle qui a chargé le plus les tissus. Prendre la profondeur moyenne sous-estimerait dangereusement la décompression.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-003', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-003', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-004', 'n3-tables-avancees', 'n3', 'tables-deco', 'qcm', 'le-cadre-mn90--conditions-de-validité-et-vocabulaire', 'Dans quel sens arrondit-on l''intervalle de surface dans le tableau II ?', 'L''intervalle de surface s''arrondit à la valeur immédiatement inférieure du tableau II, ce qui va dans le sens de la sécurité (on suppose moins de dégazage). Profondeur, durée, azote résiduel et profondeur de successive s''arrondissent, eux, au-dessus.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-004', 'a', 'À la valeur immédiatement inférieure', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-004', 'b', 'À la valeur immédiatement supérieure', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-004', 'c', 'À la valeur la plus proche', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-004', 'd', 'On n''arrondit jamais', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-005', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-simple--lecture-experte-et-dtr', 'Plongée à 32 m pendant 27 min. Quels arrondis de table appliquer ?', 'On arrondit toujours au-dessus : 32 m → table 35 m, 27 min → ligne 30 min. Arrondir vers le bas (30 m / 25 min) sous-estimerait la décompression.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-005', 'a', 'Table 35 m, ligne 30 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-005', 'b', 'Table 30 m, ligne 25 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-005', 'c', 'Table 32 m, ligne 27 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-005', 'd', 'Table 30 m, ligne 30 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-006', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-simple--lecture-experte-et-dtr', 'Plongée lue en table 35 m / 30 min. Quels paliers et quel GPS donne la table du site ?', 'La table 35 m / 30 min donne un palier de 5 min à 6 m puis 22 min à 3 m, GPS I. Les paliers profonds se font toujours avant les paliers moins profonds, du plus profond au moins profond.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-006', 'a', '5 min à 6 m et 22 min à 3 m, GPS I', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-006', 'b', '22 min à 3 m seulement, GPS H', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-006', 'c', 'aucun palier, GPS G', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-006', 'd', '9 min à 3 m, GPS J', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-007', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-simple--lecture-experte-et-dtr', 'Plongée à 20 m pendant 45 min. Que donne la table du site ?', 'La table 20 m / 45 min impose un palier de 4 min à 3 m et un GPS I. À 40 min il n''y avait encore aucun palier (GPS H) : c''est entre 40 et 45 min que le palier apparaît.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-007', 'a', 'Palier de 4 min à 3 m, GPS I', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-007', 'b', 'Aucun palier, GPS H', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-007', 'c', '9 min à 3 m, GPS I', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-007', 'd', '13 min à 3 m, GPS J', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-008', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-simple--lecture-experte-et-dtr', 'Quel est le GPS d''une plongée à 30 m pendant 25 min ?', 'La table 30 m / 25 min donne un palier de 9 min à 3 m et un GPS G. Le GPS code l''azote résiduel qui servira au calcul d''une éventuelle plongée successive.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-008', 'a', 'G', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-008', 'b', 'H', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-008', 'c', 'F', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-008', 'd', 'I', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-009', 'n3-tables-avancees', 'n3', 'tables-deco', 'qcm', 'plongée-successive--la-méthode-des-deux-tableaux', 'Quelle est la bonne séquence de calcul d''une plongée successive ?', 'On lit le GPS de la première plongée, l''azote résiduel au tableau II, la majoration au tableau III, puis on relit la table I avec la durée réelle plus la majoration. La majoration s''ajoute à la durée, elle ne se soustrait jamais.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-009', 'a', 'GPS → tableau II (azote résiduel) → tableau III (majoration) → table I avec durée réelle + majoration', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-009', 'b', 'Tableau III → tableau II → GPS → table I', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-009', 'c', 'Table I directement avec la durée réelle', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-009', 'd', 'GPS → majoration soustraite de la durée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-010', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-successive--la-méthode-des-deux-tableaux', 'Première plongée 20 m / 40 min (GPS H), intervalle 3 h, replongée à 20 m. Quel azote résiduel lit-on au tableau II ?', 'Le tableau II à l''intersection du GPS H et de l''intervalle 180 min donne un azote résiduel de 0,92. L''intervalle de 3 h (180 min) tombe pile sur une colonne du tableau.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-010', 'a', '0,92', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-010', 'b', '1,17', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-010', 'c', '0,85', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-010', 'd', '0,81', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-011', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-successive--la-méthode-des-deux-tableaux', 'Azote résiduel 0,92, seconde plongée à 20 m. Quelle majoration lit-on au tableau III ?', 'On arrondit l''azote 0,92 à la colonne 0,95 (valeur immédiatement supérieure) et on croise la profondeur 20 m : la majoration est de 11 min. Cette majoration est un temps fictif ajouté à la durée réelle.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-011', 'a', '11 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-011', 'b', '6 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-011', 'c', '16 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-011', 'd', '20 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-012', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-successive--la-méthode-des-deux-tableaux', 'Seconde plongée à 20 m, durée réelle 29 min, majoration 11 min. Quelle ligne de table lit-on ?', 'Durée fictive = 29 + 11 = 40 min, donc on lit la table 20 m / 40 min (aucun palier obligatoire, GPS H). La majoration s''ajoute avant la lecture de la table, mais ne compte ni dans l''air ni dans l''heure de sortie.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-012', 'a', '20 m / 40 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-012', 'b', '20 m / 29 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-012', 'c', '20 m / 11 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-012', 'd', '20 m / 50 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-013', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-successive--la-méthode-des-deux-tableaux', 'Première plongée 32 m / 27 min (GPS I), intervalle 2 h 30. À quel intervalle arrondi lit-on le tableau II ?', '150 min s''arrondit à la valeur immédiatement inférieure du tableau II, soit 120 min. Cet arrondi vers le bas de l''intervalle va dans le sens de la sécurité.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-013', 'a', '120 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-013', 'b', '150 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-013', 'c', '180 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-013', 'd', '90 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-014', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'plongée-successive--la-méthode-des-deux-tableaux', 'GPS I, intervalle arrondi à 120 min : azote résiduel 1,00. Seconde plongée prévue à 18 m, 30 min. Quelle majoration lit-on ?', 'On arrondit l''azote 1,00 à la ligne 1,01 et la profondeur 18 m à la colonne 20 m : la majoration est de 16 min. Durée fictive = 30 + 16 = 46 min, lue en table 20 m / 50 min.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-014', 'a', '16 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-014', 'b', '11 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-014', 'c', '22 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-014', 'd', '9 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-015', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'la-plongée-consécutive', 'Plongée 30 min à 20 m, retour surface 10 min, ré-immersion 20 min à 15 m. Quelle lecture de table (consécutive) ?', 'L''intervalle de 10 min (moins de 15 min) impose une consécutive : profondeur = maximum (20 m), durée = somme (30 + 20 = 50 min), soit table 20 m / 50 min. On additionne les durées et on retient la profondeur la plus grande.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-015', 'a', '20 m / 50 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-015', 'b', '15 m / 50 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-015', 'c', '20 m / 20 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-015', 'd', '15 m / 30 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-016', 'n3-tables-avancees', 'n3', 'tables-deco', 'qcm', 'la-plongée-consécutive', 'Comment traite-t-on une plongée consécutive (intervalle inférieur à 15 min) ?', 'En consécutive, on retient la somme des durées et la profondeur maximale atteinte, car les tissus n''ont presque rien restitué en moins de 15 min. On ne passe pas par les tableaux II et III, réservés aux successives.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-016', 'a', 'Durée = somme des durées, profondeur = maximum des deux', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-016', 'b', 'Durée = celle de la seconde seulement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-016', 'c', 'Comme deux plongées simples indépendantes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-016', 'd', 'Avec le tableau III et une majoration', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-017', 'n3-tables-avancees', 'n3', 'tables-deco', 'qcm', 'remontée-rapide--la-procédure-exacte', 'Quelle est la procédure de remontée rapide (vitesse supérieure à 17 m/min) ?', 'La procédure MN90 impose de redescendre à la mi-profondeur dans les 3 minutes, d''y rester 5 minutes, puis d''effectuer les paliers de la table pour la profondeur maximale et une durée allant de l''immersion à la fin du passage à mi-profondeur. Toute la palanquée redescend, jamais un plongeur seul.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-017', 'a', 'Redescendre à la mi-profondeur dans les 3 min, y rester 5 min, puis paliers de la table', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-017', 'b', 'Refaire toute la plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-017', 'c', 'Attendre 24 h puis replonger au même profil', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-017', 'd', 'Rester en surface sans rien faire', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-018', 'n3-tables-avancees', 'n3', 'tables-deco', 'calcul', 'remontée-rapide--la-procédure-exacte', 'Plongée à 40 m ; à la 17e minute, remontée incontrôlée en surface, redescente en 1 min à 20 m puis 5 min. Quelle durée retenir et quelle table ?', 'Durée retenue = 17 + 1 + 5 = 23 min, arrondie à la table 40 m / 25 min (paliers 5 min à 6 m puis 19 min à 3 m, GPS I). On compte du début de l''immersion à la fin des 5 min passées à mi-profondeur.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-018', 'a', '23 min → table 40 m / 25 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-018', 'b', '17 min → table 40 m / 20 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-018', 'c', '5 min → table 20 m / 5 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-018', 'd', '40 min → table 40 m / 40 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-019', 'n3-tables-avancees', 'n3', 'tables-deco', 'qcm', 'remontée-lente-et-palier-interrompu', 'Que fait-on du temps passé en remontée lente le long d''un tombant ?', 'Le temps de remontée lente s''ajoute à la durée de plongée jusqu''à la reprise d''une vitesse normale ; la profondeur retenue reste la profondeur maximale. Ignorer ce temps sous-estimerait la charge en azote.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-019', 'a', 'On l''ajoute à la durée de plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-019', 'b', 'On le retranche de la durée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-019', 'c', 'On l''ignore', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-019', 'd', 'On le compte comme un palier', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-020', 'n3-tables-avancees', 'n3', 'tables-deco', 'qcm', 'remontée-lente-et-palier-interrompu', 'Que faire en cas de palier interrompu (plongeur envoyé en surface) ?', 'On redescend dans les 3 minutes à la profondeur du palier et on le recommence intégralement, le temps déjà effectué étant perdu. Un palier interrompu non rattrapé est une décompression incomplète, donc un accident potentiel.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-020', 'a', 'Redescendre dans les 3 min et recommencer intégralement le palier', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-020', 'b', 'Reprendre le palier là où il s''était arrêté', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-020', 'c', 'Supprimer le reste du palier', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-020', 'd', 'Descendre au fond initial', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-021', 'n3-tables-avancees', 'n3', 'tables-deco', 'vrai-faux', 'plongées-inversées-profils-à-risque-et-bonnes-pratiques', 'La règle de l''autonome est de faire la plongée la plus profonde en premier dans la journée.', 'Vrai : la plongée la plus profonde se fait en premier, comme le profil descendant puis remontant au sein d''une même plongée. Les plongées inversées cumulent majoration lourde et désaturation entamée sur des tissus déjà chargés.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-021', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-021', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-001', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'ce-que-calcule-un-ordinateur--la-décompression-en-temps-réel', 'Que mesure réellement un ordinateur de plongée en permanence ?', 'L''ordinateur mesure la pression ambiante (donc la profondeur) et le temps ; il en déduit par un modèle la charge en azote de compartiments théoriques. Il ne mesure jamais directement l''azote de vos tissus.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-001', 'a', 'La pression ambiante et le temps', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-001', 'b', 'La quantité d''azote dans vos tissus', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-001', 'c', 'La taille des bulles dans votre sang', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-001', 'd', 'Votre fréquence cardiaque', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-002', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'ce-que-calcule-un-ordinateur--la-décompression-en-temps-réel', 'Quelle est la différence de fond entre un ordinateur et les tables MN90 ?', 'L''ordinateur intègre le profil réel minute par minute, alors que les tables supposent toute la plongée passée à la profondeur maximale (profil carré). C''est pourquoi l''ordinateur affiche souvent des durées sans palier plus généreuses.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-002', 'a', 'L''ordinateur intègre le profil réel, les tables raisonnent en profil carré', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-002', 'b', 'L''ordinateur ignore la profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-002', 'c', 'Les tables intègrent le profil réel minute par minute', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-002', 'd', 'Il n''y a aucune différence', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-003', 'n3-ordinateurs', 'n3', 'tables-deco', 'vrai-faux', 'des-modèles-pas-des-mesures--bühlmann-rgbm-et-les-autres', 'Deux ordinateurs de modèles différents peuvent afficher des résultats différents sur la même plongée, et c''est normal.', 'Vrai : chaque ordinateur exécute un modèle mathématique (Bühlmann, RGBM…) qui est une représentation prudente de la physiologie, pas une mesure. Des modèles différents donnent légitimement des affichages différents ; la palanquée suit le plus contraignant.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-003', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-003', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-004', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'des-modèles-pas-des-mesures--bühlmann-rgbm-et-les-autres', 'Sur quel affichage plonge une palanquée équipée d''ordinateurs différents ?', 'On plonge toujours sur l''ordinateur le plus contraignant du moment, jamais sur le plus permissif. Suivre le plus généreux exposerait le plongeur dont la machine est plus prudente à une décompression insuffisante.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-004', 'a', 'Le plus contraignant du moment', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-004', 'b', 'Le plus permissif', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-004', 'c', 'La moyenne des deux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-004', 'd', 'Celui du chef de palanquée uniquement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-005', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'des-modèles-pas-des-mesures--bühlmann-rgbm-et-les-autres', 'Le modèle Bühlmann ZHL-16 est un modèle :', 'Le Bühlmann ZHL-16 est un modèle haldéen à gaz dissous, avec 16 compartiments dotés chacun d''une sursaturation maximale tolérée. Les modèles à bulles (RGBM, VPM) intègrent en plus la mécanique des micro-bulles.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-005', 'a', 'Haldéen (à gaz dissous), à 16 compartiments', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-005', 'b', 'Qui mesure les bulles en temps réel', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-005', 'c', 'Sans aucune marge de sécurité', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-005', 'd', 'Réservé au nitrox', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-006', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'les-gradient-factors-en-notion', 'Que règlent les gradient factors (par exemple GF 40/85) sur un ordinateur ?', 'Les gradient factors sont des curseurs de marge de sécurité : le GF bas fixe la fraction de sursaturation tolérée au premier palier, le GF haut celle admise en surface. On les durcit avec la fatigue ou le froid, jamais pour gagner du temps de fond.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-006', 'a', 'Le conservatisme : la marge de sécurité appliquée au modèle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-006', 'b', 'La profondeur maximale autorisée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-006', 'c', 'La consommation d''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-006', 'd', 'L''heure de la plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-007', 'n3-ordinateurs', 'n3', 'tables-deco', 'vrai-faux', 'les-gradient-factors-en-notion', 'Un GF bas fait commencer les paliers plus profond.', 'Vrai : plus le GF bas est faible, plus le premier palier commence profond. GF 100/100 reviendrait au modèle Bühlmann sans marge, GF 30/70 donne une décompression nettement plus prudente.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-007', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-007', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-008', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'ordinateur-et-tables--deux-logiques-à-ne-pas-mélanger', 'Peut-on passer des tables à l''ordinateur (ou l''inverse) en cours de plongée ?', 'On ne panache jamais les moyens de décompression : une plongée commencée à l''ordinateur se termine à l''ordinateur, et un jeu tables + profondimètre + montre se suit intégralement. Le profil réel n''est pas reconstituable de tête pour repasser aux tables.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-008', 'a', 'Non, on ne panache jamais les moyens de décompression', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-008', 'b', 'Oui, à tout moment', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-008', 'c', 'Oui, mais seulement à la remontée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-008', 'd', 'Oui, si l''ordinateur est en panne', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-009', 'n3-ordinateurs', 'n3', 'tables-deco', 'vrai-faux', 'ordinateur-et-tables--deux-logiques-à-ne-pas-mélanger', 'Un ordinateur de plongée est strictement personnel : il ne se prête ni ne s''échange entre deux plongées.', 'Vrai : l''ordinateur mémorise votre historique de saturation. Le prêter entre deux plongées, ou en emprunter un « vierge » de votre première plongée, fausse tout le calcul de successive.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-009', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-009', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-010', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'successives-désaturation-résiduelle-et-avion', 'Que signifie le temps d''interdiction de vol affiché par l''ordinateur ?', 'Tant que ce compte à rebours court, pas d''avion ni de séjour en altitude, car la baisse de pression en cabine relancerait le dégazage. En complément, on attend au moins 12 h après une plongée unique sans palier et 24 h après des plongées multiples ou avec paliers.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-010', 'a', 'La durée pendant laquelle on ne doit ni prendre l''avion ni monter en altitude', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-010', 'b', 'Le temps avant la prochaine plongée possible', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-010', 'c', 'La durée du palier restant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-010', 'd', 'Le temps de désaturation totale', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-011', 'n3-ordinateurs', 'n3', 'tables-deco', 'vrai-faux', 'successives-désaturation-résiduelle-et-avion', 'À l''ordinateur, les bonnes pratiques des tables (plongée la plus profonde en premier, pas de yo-yo, palier de principe) restent valables.', 'Vrai : le modèle calcule une moyenne statistique, et vos marges couvrent votre écart à cette moyenne. La plongée la plus profonde en premier, l''absence de yo-yo et le palier de principe restent des règles de sécurité à l''ordinateur comme aux tables.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-011', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-011', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-012', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'limites-pannes-et-conduite-à-tenir', 'Que faire en cas de panne d''ordinateur en pleine plongée ?', 'Une panne d''ordinateur signe la fin de la plongée : on remonte à vitesse contrôlée avec son équipier en suivant son instrument, avec un palier de sécurité prolongé. Sans aucun moyen fiable dans la palanquée, remontée prudente puis 24 h sans plonger.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-012', 'a', 'La plongée est terminée : remonter avec l''équipier en suivant son instrument, palier de sécurité prolongé', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-012', 'b', 'Continuer normalement de mémoire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-012', 'c', 'Redescendre pour recalibrer l''appareil', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-012', 'd', 'Retirer sa combinaison', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-013', 'n3-ordinateurs', 'n3', 'tables-deco', 'vrai-faux', 'limites-pannes-et-conduite-à-tenir', 'En autonomie profonde, disposer d''un second moyen de décompression (redondance) est un investissement raisonnable.', 'Vrai : un second ordinateur ou un jeu tables + profondimètre + montre offre une redondance précieuse. Le Code du sport impose d''ailleurs que chaque plongeur autonome puisse contrôler personnellement les caractéristiques de sa plongée et de sa remontée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-013', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-013', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-014', 'n3-ordinateurs', 'n3', 'tables-deco', 'qcm', 'limites-pannes-et-conduite-à-tenir', 'Après une violation (palier manqué) qui verrouille l''ordinateur, quelle est la priorité ?', 'Le verrouillage n''est pas le problème : la décompression écourtée l''est. On applique la logique MN90 (surveillance, oxygène et alerte au moindre signe, pas de replongée) au lieu de chercher à contourner l''appareil.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-014', 'a', 'Appliquer la logique des procédures MN90 : surveillance, oxygène et alerte au moindre signe', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-014', 'b', 'Ruser avec l''appareil pour lever le verrouillage', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-014', 'c', 'Ignorer, le verrouillage n''a pas d''importance', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-014', 'd', 'Replonger immédiatement pour compenser', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-001', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'lautonomie-change-la-donne', 'Quelles questions la palanquée autonome doit-elle avoir réglées avant la mise à l''eau ?', 'La palanquée autonome est sa propre première équipe de secours : elle doit savoir qui surveille qui, où est l''oxygène et qui sait l''utiliser, comment on alerte depuis ce site et vers où on évacue. Hors structure, ce plan de secours, c''est elle qui l''écrit.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-001', 'a', 'Qui surveille qui, où est l''oxygène, comment alerter, vers où évacuer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-001', 'b', 'La couleur des combinaisons', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-001', 'c', 'Le nombre de poissons attendus', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-001', 'd', 'La marque des palmes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-002', 'n3-accidents-secours', 'n3', 'physiologie', 'vrai-faux', 'lautonomie-change-la-donne', 'L''accident de désaturation survient le plus souvent dans les minutes ou heures après la sortie de l''eau.', 'Vrai : l''ADD apparaît le plus souvent après la sortie, parfois avec des signes trompeurs et fluctuants, alors que la surpression pulmonaire éclate pendant ou juste après la remontée. Dans le doute, on traite : un accident négligé coûte une moelle épinière.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-002', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-002', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-003', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'reconnaître-vite--add-et-surpression-pulmonaire', 'Quels signes orientent vers un ADD médullaire, urgence majeure ?', 'Les fourmillements, la perte de force ou de sensibilité et les troubles urinaires signent une atteinte médullaire, urgence majeure qui se joue en minutes. Ces signes imposent oxygène immédiat et alerte, sans attendre.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-003', 'a', 'Fourmillements, perte de force ou de sensibilité, difficulté à uriner', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-003', 'b', 'Simple fatigue passagère', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-003', 'c', 'Léger mal de tête isolé', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-003', 'd', 'Faim après la plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-004', 'n3-accidents-secours', 'n3', 'physiologie', 'vrai-faux', 'reconnaître-vite--add-et-surpression-pulmonaire', 'Tout signe anormal après une plongée est un accident de plongée jusqu''à preuve médicale du contraire, même après un profil « dans les règles ».', 'Vrai : les signes peuvent être retardés jusqu''à 12-24 h et la victime a tendance à minimiser. On ne banalise jamais un symptôme post-plongée, même après un profil respecté.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-004', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-004', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-005', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'la-conduite-à-tenir--un-déroulé-unique', 'Quel est le squelette de la conduite à tenir face à un accident de plongée ?', 'Quel que soit l''accident suspecté, on protège, examine, oxygène, alerte et surveille. La réimmersion est un interdit absolu (elle aggrave hypothermie et risque de noyade) et on ne laisse jamais la victime seule.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-005', 'a', 'Protéger, examiner, oxygéner, alerter, surveiller', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-005', 'b', 'Réimmerger la victime pour recomprimer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-005', 'c', 'La laisser se reposer seule', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-005', 'd', 'Lui donner de l''alcool', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-006', 'n3-accidents-secours', 'n3', 'physiologie', 'vrai-faux', 'la-conduite-à-tenir--un-déroulé-unique', 'On ne réimmerge jamais un accidenté et le reste de la palanquée ne replonge pas.', 'Vrai : la recompression dans l''eau aggrave l''hypothermie et le risque de noyade, et le reste de la palanquée est potentiellement exposé au même profil. Ce sont deux interdits absolus de la conduite à tenir.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-006', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-006', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-007', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'la-conduite-à-tenir--un-déroulé-unique', 'Peut-on faire boire une victime consciente d''un accident de plongée ?', 'On peut faire boire 0,5 à 1 L d''eau plate en petites quantités si la victime est parfaitement consciente, sans nausée ni trouble de la déglutition. Ni alcool ni café, et aucun médicament sans avis du médecin régulateur.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-007', 'a', 'Oui, de l''eau plate en petites quantités si elle est parfaitement consciente, sans nausée ni trouble de déglutition', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-007', 'b', 'Oui, de l''alcool pour la réchauffer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-007', 'c', 'Oui, du café bien fort', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-007', 'd', 'Jamais, en aucun cas', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-008', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'loxygénothérapie-normobare--le-matériel', 'À quel débit administre-t-on l''oxygène normobare à une victime qui ventile ?', 'On administre l''oxygène au débit maximal, soit 15 L/min, au masque à haute concentration avec sac réservoir. L''objectif est de remplacer l''azote alvéolaire par de l''oxygène pour accélérer la dénitrogénation.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-008', 'a', '15 L/min au masque à haute concentration', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-008', 'b', '2 L/min aux lunettes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-008', 'c', '5 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-008', 'd', 'Le débit importe peu', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-009', 'n3-accidents-secours', 'n3', 'physiologie', 'calcul', 'loxygénothérapie-normobare--le-matériel', 'Une bouteille d''oxygène de 5 L gonflée à 200 bar, débit 15 L/min : quelle autonomie approximative ?', 'Volume d''O₂ détendu = 5 × 200 = 1000 L ; autonomie = 1000 / 15 ≈ 66 min. D''où la règle : vérifier la pression de la bouteille d''O₂ avant de partir et dimensionner la capacité au délai réel d''évacuation.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-009', 'a', '≈ 66 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-009', 'b', '≈ 200 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-009', 'c', '≈ 13 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-009', 'd', '≈ 30 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-010', 'n3-accidents-secours', 'n3', 'physiologie', 'calcul', 'loxygénothérapie-normobare--le-matériel', 'Une bouteille d''oxygène de 5 L n''est plus qu''à 150 bar. Quelle autonomie à 15 L/min ?', 'Volume d''O₂ = 5 × 150 = 750 L ; autonomie = 750 / 15 = 50 min. Un contrôle de pression avant la plongée évite de découvrir une bouteille à demi vide au moment où elle doit servir.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-010', 'a', '≈ 50 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-010', 'b', '≈ 66 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-010', 'c', '≈ 10 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-010', 'd', '≈ 100 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-011', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'loxygénothérapie--mise-en-œuvre', 'Que faire si les signes de la victime régressent sous oxygène ?', 'La régression des signes sous oxygène est fréquente et ne dispense jamais de l''évacuation : on maintient l''inhalation en continu jusqu''à la prise en charge médicale. Interrompre l''oxygène « pour voir » ferait rechuter la victime.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-011', 'a', 'Poursuivre l''oxygène en continu jusqu''à la prise en charge médicale et maintenir l''évacuation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-011', 'b', 'Arrêter l''oxygène, le problème est résolu', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-011', 'c', 'Renoncer à l''alerte', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-011', 'd', 'Faire replonger la victime', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-012', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'lalerte--joindre-les-secours-vite-et-bien', 'Quel canal VHF veillé par le CROSS utilise-t-on pour une alerte en mer ?', 'En mer, l''alerte se donne sur la VHF canal 16, canal de détresse veillé par le CROSS qui coordonne les secours maritimes. Depuis un téléphone, le 196 joint directement le CROSS.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-012', 'a', 'Le canal 16', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-012', 'b', 'Le canal 6', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-012', 'c', 'Le canal 72', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-012', 'd', 'Le canal 10', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-013', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'lalerte--joindre-les-secours-vite-et-bien', 'Que doit contenir un message d''alerte pour un accident de plongée ?', 'Le message doit donner la position exacte, la nature de l''accident (« accident de plongée »), le nombre et l''état des victimes, les gestes entrepris et un moyen de rappel — et on ne raccroche jamais en premier. Ces informations orientent la régulation vers la médecine hyperbare.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-013', 'a', 'Position précise, nature de l''accident, nombre et état des victimes, gestes entrepris, moyen de rappel', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-013', 'b', 'Seulement le nom du bateau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-013', 'c', 'Uniquement la profondeur de la plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-013', 'd', 'La météo du lendemain', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-014', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'la-chaîne-des-secours-et-lévacuation', 'Quel est le traitement de fond de l''accident de désaturation ?', 'Le traitement de fond de l''ADD est la recompression thérapeutique en caisson hyperbare, qui dissout les bulles et restaure la perfusion. L''oxygène et l''alerte précoces préparent ce traitement en gagnant les minutes qui comptent.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-014', 'a', 'La recompression en caisson hyperbare', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-014', 'b', 'Le repos allongé', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-014', 'c', 'Un anti-douleur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-014', 'd', 'Une nouvelle plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-015', 'n3-accidents-secours', 'n3', 'physiologie', 'vrai-faux', 'la-chaîne-des-secours-et-lévacuation', 'L''ordinateur de plongée de la victime doit partir avec elle vers l''hôpital.', 'Vrai : l''ordinateur renseigne le profil réel de la plongée (profondeurs, durées, paliers) et oriente le médecin. Avec la fiche d''évacuation complète, il fait partie des éléments qui accélèrent la prise en charge.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-015', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-015', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-016', 'n3-accidents-secours', 'n3', 'physiologie', 'qcm', 'prévenir--les-règles-de-lautonome', 'Quels facteurs favorisants de l''ADD se gèrent avant et après la plongée ?', 'Hydratation, sommeil, absence d''alcool, bonne forme et pas d''effort intense ni d''apnée après la plongée réduisent le risque d''ADD. S''y ajoutent les vitesses de remontée respectées, le palier de principe et le délai avant l''avion.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-016', 'a', 'Hydratation, sommeil, absence d''alcool, forme physique, pas d''effort intense après la plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-016', 'b', 'La couleur de l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-016', 'c', 'La marque du détendeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-016', 'd', 'Le nombre de plongeurs sur le site', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-secours-017', 'n3-accidents-secours', 'n3', 'physiologie', 'vrai-faux', 'prévenir--les-règles-de-lautonome', 'Annoncer à sa palanquée un foramen ovale connu, une méforme ou un doute relève de l''honnêteté d''équipe.', 'Vrai : l''honnêteté d''équipe permet à la palanquée d''adapter le profil et la surveillance. Taire un facteur de risque prive le groupe de sa principale force, l''anticipation.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-017', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-secours-017', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-001', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'le-parc-du-plongeur-autonome--ce-que-la-réglementation-impose', 'Quel matériel le Code du sport impose-t-il à chaque plongeur autonome ?', 'L''autonome doit disposer d''un gilet à gonflage au gaz, d''un bloc à deux sorties alimentant deux détendeurs complets, d''un manomètre et d''un moyen de contrôle de la plongée et de la remontée. Un parachute de palier est exigé par palanquée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-001', 'a', 'Gilet, 2 sorties + 2 détendeurs complets, manomètre, moyen de contrôle de la plongée/remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-001', 'b', 'Un seul détendeur et une lampe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-001', 'c', 'Uniquement un ordinateur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-001', 'd', 'Palmes, masque et tuba seulement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-002', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'le-parc-du-plongeur-autonome--ce-que-la-réglementation-impose', 'Combien de parachutes de palier le Code du sport impose-t-il en autonomie ?', 'Le parachute de palier est obligatoire à raison d''un par palanquée autonome. Il signale la remontée aux embarcations et matérialise l''axe de remontée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-002', 'a', 'Un par palanquée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-002', 'b', 'Un par plongeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-002', 'c', 'Aucun', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-002', 'd', 'Deux par plongeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-003', 'n3-materiel-entretien', 'n3', 'materiel', 'calcul', 'les-blocs--identification-et-marquages', 'Quelle est la pression d''épreuve d''un bloc dont la pression de service est de 200 bar ?', 'La pression d''épreuve vaut 1,5 fois la pression de service, soit 1,5 × 200 = 300 bar. C''est la pression à laquelle le bloc est éprouvé hydrauliquement lors de la requalification, jamais une pression d''utilisation.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-003', 'a', '300 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-003', 'b', '200 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-003', 'c', '400 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-003', 'd', '250 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-004', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'les-blocs--identification-et-marquages', 'Quelle est la différence entre pression de service et pression d''épreuve ?', 'La pression de service est la pression maximale d''utilisation, au-delà de laquelle on ne gonfle jamais ; la pression d''épreuve (1,5 × service) est celle du test hydraulique de requalification. On ne gonfle jamais à la pression d''épreuve.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-004', 'a', 'La pression de service est le maximum d''utilisation ; la pression d''épreuve est celle du test hydraulique', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-004', 'b', 'Ce sont deux noms pour la même chose', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-004', 'c', 'La pression de service est supérieure à la pression d''épreuve', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-004', 'd', 'La pression d''épreuve est la pression de gonflage courante', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-005', 'n3-materiel-entretien', 'n3', 'materiel', 'vrai-faux', 'les-blocs--identification-et-marquages', 'Un bloc ne doit jamais être stocké complètement vide.', 'Vrai : un bloc doit conserver une pression résiduelle positive pour éviter l''entrée d''humidité et la corrosion interne, ennemi principal des blocs. On le stocke debout, attaché, à l''abri de la chaleur.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-005', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-005', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-006', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'inspection-visuelle-et-tiv--le-suivi-annuel', 'À quelle fréquence et par qui se fait l''inspection visuelle des blocs dans le cadre fédéral ?', 'L''inspection visuelle est annuelle, réalisée par un Technicien en Inspection Visuelle (TIV) formé par la FFESSM, et tracée (registre, macaron). C''est ce suivi qui autorise l''espacement des requalifications.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-006', 'a', 'Tous les ans, par un TIV, avec traçabilité', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-006', 'b', 'Tous les cinq ans, par le plongeur lui-même', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-006', 'c', 'À chaque plongée, par le club', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-006', 'd', 'Jamais, ce n''est pas obligatoire', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-007', 'n3-materiel-entretien', 'n3', 'materiel', 'vrai-faux', 'inspection-visuelle-et-tiv--le-suivi-annuel', 'Un N3 est habilité à réaliser lui-même l''inspection visuelle et à démonter la robinetterie de son bloc.', 'Faux : le N3 n''est pas TIV. Le démontage de la robinetterie et l''inspection visuelle sont des gestes de TIV ou de technicien ; le N3 doit seulement savoir lire le suivi (dates d''IV et de requalification).', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-007', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-007', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-008', 'n3-materiel-entretien', 'n3', 'materiel', 'calcul', 'la-requalification-périodique', 'Un bloc suivi par une inspection visuelle annuelle d''un TIV en structure fédérale bénéficie d''un intervalle de requalification de :', 'En régime général la requalification est tous les 2 ans, mais un bloc suivi par une IV annuelle d''un TIV en structure fédérale (registre à jour) voit son intervalle porté à 6 ans. Ces intervalles doivent toujours être vérifiés dans les textes en vigueur.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-008', 'a', '6 ans', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-008', 'b', '2 ans', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-008', 'c', '1 an', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-008', 'd', '10 ans', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-009', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'la-requalification-périodique', 'En quoi consiste la requalification périodique d''un bloc ?', 'La requalification comprend une inspection complète, une épreuve hydraulique à la pression d''épreuve et un nouveau poinçon daté, dans un organisme habilité. Un bloc qui échoue est réformé.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-009', 'a', 'Inspection complète et épreuve hydraulique à la pression d''épreuve, nouveau poinçon daté', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-009', 'b', 'Un simple rinçage à l''eau douce', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-009', 'c', 'Un changement de robinet uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-009', 'd', 'Un gonflage à la pression de service', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-010', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'détendeurs-gilet-instruments--lentretien-préventif', 'Comment entretenir un détendeur après chaque plongée ?', 'On rince à l''eau douce avec le bouchon de protection en place, sans appuyer sur le bouton de purge sous l''eau (l''eau remonterait dans le premier étage), puis on sèche à l''ombre. La révision par un technicien reste annuelle ou toutes les 100 plongées.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-010', 'a', 'Rincer à l''eau douce, bouchon de protection en place, sans appuyer sur la purge sous l''eau', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-010', 'b', 'Le laisser sécher au soleil sans rincer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-010', 'c', 'Appuyer sur la purge en le rinçant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-010', 'd', 'Le démonter entièrement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-011', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'détendeurs-gilet-instruments--lentretien-préventif', 'À quelle fréquence réviser un détendeur chez un technicien agréé ?', 'La révision périodique se fait usuellement une fois par an ou toutes les 100 plongées selon les préconisations du fabricant : remplacement des joints, membranes et sièges, contrôle des pressions. Un carnet d''entretien par équipement transforme l''entretien en système.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-011', 'a', 'Une fois par an ou toutes les 100 plongées, selon le fabricant', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-011', 'b', 'Tous les cinq ans', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-011', 'c', 'Jamais, s''il fonctionne', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-011', 'd', 'À chaque plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-012', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'le-gonflage--stations-compresseurs-et-air-respirable', 'Quelle norme fixe la qualité de l''air respirable délivré par une station de gonflage ?', 'L''air respirable doit répondre à la norme EN 12021, qui limite strictement les teneurs en monoxyde de carbone, dioxyde de carbone, huile et vapeur d''eau. La position de la prise d''air, loin de tout échappement, est essentielle.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-012', 'a', 'La norme EN 12021', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-012', 'b', 'La norme MN90', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-012', 'c', 'La norme ISO 9001', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-012', 'd', 'Aucune norme', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-013', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'le-gonflage--stations-compresseurs-et-air-respirable', 'Pourquoi gonfler un bloc lentement ?', 'L''air comprimé s''échauffe (loi de Charles) : un gonflage rapide donne un bloc chaud dont la pression retombe en refroidissant, laissant le bloc sous-gonflé. On contrôle donc la pression une fois le bloc revenu à température.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-013', 'a', 'Parce que l''air comprimé s''échauffe ; un gonflage rapide donne un bloc « chaud » dont la pression retombe en refroidissant', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-013', 'b', 'Pour économiser de l''électricité', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-013', 'c', 'Parce que la loi l''interdit au-delà de 1 bar/s', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-013', 'd', 'Pour éviter le bruit', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-014', 'n3-materiel-entretien', 'n3', 'materiel', 'vrai-faux', 'le-gonflage--stations-compresseurs-et-air-respirable', 'Une intoxication au monoxyde de carbone d''un air de gonflage pollué est indétectable au goût et d''autant plus dangereuse en profondeur.', 'Vrai : le CO est inodore et sans goût, et la pression multiplie sa toxicité en profondeur, ce qui le rend potentiellement mortel. D''où l''importance de la position de la prise d''air et de l''entretien des filtres.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-014', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-014', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-mat-015', 'n3-materiel-entretien', 'n3', 'materiel', 'qcm', 'le-parc-du-plongeur-autonome--ce-que-la-réglementation-impose', 'Que doit-on vérifier avant d''emprunter ou de faire gonfler un bloc ?', 'Avant d''emprunter ou de faire gonfler un bloc, on vérifie les dates d''inspection visuelle et de requalification. Une station de gonflage sérieuse refuse un bloc hors délai, et elle a raison.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-015', 'a', 'La date de la dernière inspection visuelle et celle de la requalification', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-015', 'b', 'La couleur du bloc uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-015', 'c', 'La marque du fabricant seulement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-mat-015', 'd', 'Rien, tout bloc est utilisable', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-001', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'le-cadre-juridique--le-code-du-sport-et-les-établissements-daps', 'Quelle est la profondeur maximale de la plongée à l''air en exploration en France ?', 'La plongée à l''air en exploration est limitée à 60 m par le Code du sport, avec une tolérance encadrée en cas de dépassement accidentel. C''est aussi la profondeur maximale des prérogatives PA60 du Niveau 3.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-001', 'a', '60 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-001', 'b', '40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-001', 'c', '50 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-001', 'd', '70 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-002', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'aptitudes-et-brevets--où-se-situe-le-n3', 'À quelle aptitude correspond le brevet Niveau 3 ?', 'Le Niveau 3 atteste l''aptitude PA60 : plongeur autonome jusqu''à 60 m. Le PA60 englobe les aptitudes inférieures : un N3 peut plonger encadré ou en autonomie à toute profondeur jusqu''à 60 m.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-002', 'a', 'PA60 — autonome jusqu''à 60 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-002', 'b', 'PA20 — autonome jusqu''à 20 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-002', 'c', 'PE40 — encadré jusqu''à 40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-002', 'd', 'PE20 — encadré jusqu''à 20 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-003', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'le-n3-en-structure--sous-lautorité-du-directeur-de-plongée', 'Combien de plongeurs compte au maximum une palanquée autonome en structure ?', 'Une palanquée autonome compte 2 ou 3 plongeurs au maximum (trois autonomes au plus). Le directeur de plongée peut fixer des paramètres plus restrictifs, jamais plus permissifs que vos prérogatives.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-003', 'a', '2 ou 3 autonomes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-003', 'b', '4 autonomes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-003', 'c', '5 autonomes', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-003', 'd', '1 seul plongeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-004', 'n3-reglementation', 'n3', 'reglementation', 'vrai-faux', 'le-n3-en-structure--sous-lautorité-du-directeur-de-plongée', 'En structure, le directeur de plongée peut fixer des paramètres plus restrictifs que les prérogatives du plongeur, mais jamais plus permissifs.', 'Vrai : le DP fixe les caractéristiques de la plongée (site, profondeur, temps, consignes) qui peuvent restreindre vos prérogatives, jamais les élargir. Refuser une consigne du DP ou plonger hors fiche de sécurité, c''est sortir du cadre.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-004', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-004', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-005', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'le-n3-en-structure--sous-lautorité-du-directeur-de-plongée', 'Quel document consigne l''organisation de chaque plongée en structure ?', 'La fiche de sécurité (feuille de palanquée) consigne l''identité des plongeurs, leurs aptitudes, leur fonction et les paramètres prévus puis réalisés. Elle fait foi de l''organisation et pèse lourd dans l''analyse des responsabilités en cas d''accident.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-005', 'a', 'La fiche de sécurité (feuille de palanquée)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-005', 'b', 'Le carnet de plongée personnel uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-005', 'c', 'La licence', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-005', 'd', 'Le certificat médical', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-006', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'le-n3-hors-structure--la-liberté-et-son-prix', 'Que peut faire un N3 majeur hors de toute structure ?', 'Hors établissement, des plongeurs majeurs titulaires du PA60 choisissent librement le lieu, l''organisation et les modalités, sans directeur de plongée. Cette liberté transfère intégralement sur eux la responsabilité qu''assumait la structure.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-006', 'a', 'Organiser librement ses plongées, sans directeur de plongée, avec responsabilité entière', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-006', 'b', 'Rien, la plongée hors structure est interdite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-006', 'c', 'Plonger sans aucune limite de profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-006', 'd', 'Encadrer des débutants', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-007', 'n3-reglementation', 'n3', 'reglementation', 'vrai-faux', 'le-n3-hors-structure--la-liberté-et-son-prix', '« Hors structure » signifie « hors du droit » : aucune réglementation ne s''applique.', 'Faux : la responsabilité civile et pénale demeure, les réglementations locales (navigation, pavillon, zones interdites, préfet maritime) s''appliquent, et l''assurance peut exclure certaines pratiques. La liberté du N3 s''exerce dans le droit commun.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-007', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-007', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-008', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'les-documents-du-plongeur', 'Quels documents un N3 doit-il pouvoir présenter pour exercer ses prérogatives ?', 'Le N3 doit disposer de sa carte de brevet, d''une licence en cours (qui inclut la RC), d''un certificat médical selon les règles en vigueur et d''un carnet de plongée. La qualification RIFA Plongée est d''ailleurs exigée pour la délivrance du N3.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-008', 'a', 'Carte de brevet, licence en cours, certificat médical, carnet de plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-008', 'b', 'Uniquement sa licence', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-008', 'c', 'Seulement le carnet de plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-008', 'd', 'Aucun document n''est nécessaire', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-009', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'responsabilité-civile-responsabilité-pénale', 'Que vise la responsabilité civile ?', 'La responsabilité civile répare : elle indemnise le dommage causé à autrui par une faute, une imprudence ou une négligence. C''est ce risque financier que couvre l''assurance en responsabilité civile incluse dans la licence.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-009', 'a', 'Réparer le dommage causé à autrui, via une indemnisation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-009', 'b', 'Punir par une amende ou une peine de prison', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-009', 'c', 'Retirer le brevet', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-009', 'd', 'Interdire la plongée à vie', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-010', 'n3-reglementation', 'n3', 'reglementation', 'vrai-faux', 'responsabilité-civile-responsabilité-pénale', 'La responsabilité pénale est personnelle et non assurable.', 'Vrai : la responsabilité pénale punit (mise en danger d''autrui, blessures ou homicide involontaires) et aucune assurance ne purge une condamnation pénale. Elle est strictement personnelle.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-010', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-010', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-011', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'responsabilité-civile-responsabilité-pénale', 'Laquelle de ces situations expose particulièrement la responsabilité d''un N3 autonome ?', 'Entraîner un équipier au-delà de ses aptitudes, ignorer les consignes du DP ou négliger l''assistance due à un équipier expose fortement. À l''inverse, briefing sérieux, paramètres respectés et carnet à jour sont les meilleures preuves de diligence.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-011', 'a', 'Entraîner un équipier au-delà de ses aptitudes ou de sa forme du jour', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-011', 'b', 'Respecter les paramètres briefés', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-011', 'c', 'Tenir son carnet à jour', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-011', 'd', 'Prévoir un plan de secours réel', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-012', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'les-assurances--ce-qui-est-couvert-ce-qui-ne-lest-pas', 'Que couvre l''assurance en responsabilité civile incluse dans la licence ?', 'La RC de la licence couvre les dommages causés à des tiers dans le cadre des activités fédérales, pas vos propres dommages. Ceux-ci relèvent de l''assurance individuelle complémentaire facultative (frais de recherche, caisson, rapatriement).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-012', 'a', 'Les dommages que vous causez à des tiers dans le cadre des activités fédérales', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-012', 'b', 'Vos propres frais de caisson et de rapatriement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-012', 'c', 'Le remplacement de votre matériel perdu', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-012', 'd', 'Toutes vos dépenses personnelles', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-013', 'n3-reglementation', 'n3', 'reglementation', 'vrai-faux', 'les-assurances--ce-qui-est-couvert-ce-qui-ne-lest-pas', 'Avant une pratique autonome régulière, il faut lire les plafonds, franchises et exclusions de son assurance complémentaire.', 'Vrai : les exclusions peuvent porter sur les profondeurs, la pratique hors structure ou certains pays. C''est au moment de l''accident qu''on découvre les contrats mal choisis, et c''est trop tard.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-013', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-013', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-014', 'n3-reglementation', 'n3', 'reglementation', 'qcm', 'le-n3-en-structure--sous-lautorité-du-directeur-de-plongée', 'Quel est le niveau minimal du directeur de plongée en exploration dans le cursus fédéral ?', 'En exploration, le directeur de plongée est titulaire au minimum de la qualification P5 (Niveau 5) dans le cursus fédéral. Il est présent sur le site et responsable de l''organisation et de la sécurité.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-014', 'a', 'Niveau 5 (P5)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-014', 'b', 'Niveau 3', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-014', 'c', 'Niveau 4', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-014', 'd', 'Niveau 1', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-regl-015', 'n3-reglementation', 'n3', 'reglementation', 'vrai-faux', 'aptitudes-et-brevets--où-se-situe-le-n3', 'Le PA60 englobe les aptitudes inférieures : un N3 peut plonger encadré ou en autonomie à toute profondeur jusqu''à 60 m.', 'Vrai : le brevet Niveau 3 (PA60) englobe les aptitudes inférieures. La progressivité vers les profondeurs reste toutefois de la responsabilité du DP et du plongeur, car l''aptitude administrative ne crée pas l''expérience.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-015', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-regl-015', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-tables-022', 'n3-tables-avancees', 'n3', 'tables-deco', 'vrai-faux', 'le-cadre-mn90--conditions-de-validité-et-vocabulaire', 'Les arrondis de table se font toujours dans le sens de la sécurité.', 'Vrai : profondeur et durée s''arrondissent à la valeur immédiatement supérieure, l''intervalle de surface à la valeur inférieure, l''azote résiduel et la profondeur de successive au-dessus. Tous ces arrondis vont dans le sens de la sécurité.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-022', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-tables-022', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n3-ordi-015', 'n3-ordinateurs', 'n3', 'tables-deco', 'vrai-faux', 'ce-que-calcule-un-ordinateur--la-décompression-en-temps-réel', 'Un ordinateur crédite une plongée qui touche 40 m trois minutes puis évolue à 20 m d''une charge moindre que « 40 m tout du long ».', 'Vrai : l''ordinateur intègre le profil réel minute par minute, alors que les tables supposent toute la plongée à la profondeur maximale (profil carré). Cette prise en compte du profil réel explique ses durées sans palier plus généreuses.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-015', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n3-ordi-015', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-001', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'rappel-des-pressions-et-unités', 'Quelle est la pression absolue à 30 m en eau de mer ?', '$P_{abs}=P_{atm}+profondeur/10=1+30/10=4$ bar. Répondre 3 bar confond pression relative (3 bar) et pression absolue ; l''examinateur sanctionne cette confusion.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-001', 'a', '4 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-001', 'b', '3 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-001', 'c', '30 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-001', 'd', '5 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-002', 'n4-pressions-gaz', 'n4', 'physique', 'qcm', 'rappel-des-pressions-et-unités', 'Combien vaut approximativement 1 bar en pascals ?', '1 bar vaut environ $10^5$ pascals, soit la pression exercée par l''atmosphère au niveau de la mer. Chaque tranche de 10 m d''eau ajoute 1 bar, car une colonne d''eau de 10 m sur 1 cm² pèse environ 1 kg.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-002', 'a', '$10^5$ Pa', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-002', 'b', '$10^3$ Pa', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-002', 'c', '$10^2$ Pa', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-002', 'd', '$10^7$ Pa', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-003', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'la-loi-de-boyle-mariotte-et-sa-démonstration', 'Une cloche ouverte par le bas contient 12 L d''air à 20 m (3 bar). Quel volume à 40 m (5 bar) ?', 'Par Boyle-Mariotte $V_{40}=(P_{20}\times V_{20})/P_{40}=(3\times 12)/5=7{,}2$ L. Le gaz se comprime en descendant ; en surface il occuperait $3\times12/1=36$ L.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-003', 'a', '7,2 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-003', 'b', '20 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-003', 'c', '4,8 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-003', 'd', '36 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-004', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'la-loi-de-boyle-mariotte-et-sa-démonstration', 'La cloche de 12 L d''air à 20 m (3 bar) remonte en surface. Quel volume tend-il à occuper ?', 'En surface (1 bar), $V=(3\times 12)/1=36$ L : le gaz triple de volume et s''échappe par le bas de la cloche. La détente est maximale près de la surface, zone la plus dangereuse pour un volume gazeux emprisonné.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-004', 'a', '36 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-004', 'b', '12 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-004', 'c', '4 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-004', 'd', '24 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-005', 'n4-pressions-gaz', 'n4', 'physique', 'qcm', 'la-loi-de-boyle-mariotte-et-sa-démonstration', 'Dans quelle tranche d''eau la détente d''un volume gazeux emprisonné est-elle la plus violente ?', 'De 0 à 10 m la pression double (le volume est divisé par deux), alors que de 30 à 40 m elle ne passe que de 4 à 5 bar (+25 %). C''est pourquoi les barotraumatismes et la surpression pulmonaire sont les plus redoutables dans les derniers mètres.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-005', 'a', 'De 0 à 10 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-005', 'b', 'De 30 à 40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-005', 'c', 'De 50 à 60 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-005', 'd', 'Elle est identique partout', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-006', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'compressibilité-gonflage-et-transvasement', 'Quelle capacité en air a un bloc de 12 L gonflé à 200 bar ?', 'La capacité en air est le produit du volume par la pression : $12\times 200=2400$ L ramenés à la pression atmosphérique. C''est cette quantité, et non les 12 L de contenance, qui détermine l''autonomie.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-006', 'a', '2400 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-006', 'b', '200 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-006', 'c', '1200 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-006', 'd', '2000 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-007', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'compressibilité-gonflage-et-transvasement', 'On relie un bloc de 15 L à 200 bar à un bloc de 10 L vide. Quelle pression d''équilibre ?', 'La quantité totale se conserve et se répartit dans le volume total : $P_{eq}=(200\times 15+0\times 10)/(15+10)=3000/25=120$ bar. Ce calcul de conservation de la quantité de gaz est un classique de l''épreuve.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-007', 'a', '120 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-007', 'b', '100 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-007', 'c', '200 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-007', 'd', '150 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-008', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'compressibilité-gonflage-et-transvasement', 'Un bloc de 12 L est à 50 bar ; on veut le porter à 200 bar. Quel volume d''air (à la pression atmosphérique) faut-il apporter ?', 'Il faut $12\times(200-50)=1800$ L d''air ramenés à la pression atmosphérique. À un débit de compresseur de 300 L/min, le gonflage dure environ 6 minutes, hors échauffement.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-008', 'a', '1800 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-008', 'b', '2400 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-008', 'c', '150 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-008', 'd', '600 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-009', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'la-loi-de-dalton-et-les-pressions-partielles', 'À 40 m (5 bar), quelle est la pression partielle d''azote de l''air (convention 80 % N₂) ?', '$P_pN_2=P_{abs}\times\%N_2=5\times 0{,}80=4$ bar. La convention du Niveau 4 pour l''air est 80 % d''azote et 20 % d''oxygène. C''est la pression partielle, non le pourcentage, qui gouverne les effets d''un gaz.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-009', 'a', '4 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-009', 'b', '1 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-009', 'c', '0,8 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-009', 'd', '5 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-010', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'la-loi-de-dalton-et-les-pressions-partielles', 'À 40 m (5 bar), quelle est la pression partielle d''oxygène de l''air (convention 20 % O₂) ?', '$P_pO_2=5\times 0{,}20=1$ bar. La somme des pressions partielles ($4+1=5$ bar) reconstitue bien la pression absolue, conformément à la loi de Dalton.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-010', 'a', '1 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-010', 'b', '0,2 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-010', 'c', '4 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-010', 'd', '5 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-011', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'la-loi-de-dalton-et-les-pressions-partielles', 'À quelle profondeur à l''air (80/20) atteint-on le seuil d''hyperoxie de $P_pO_2=1{,}6$ bar ?', '$P_{abs}=P_pO_2/\%O_2=1{,}6/0{,}20=8$ bar, soit $(8-1)\times 10=70$ m. Comme la plongée à l''air est interdite au-delà de 60 m, la marge avant l''hyperoxie est faible : cela justifie la limite réglementaire.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-011', 'a', '70 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-011', 'b', '60 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-011', 'c', '80 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-011', 'd', '66 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-012', 'n4-pressions-gaz', 'n4', 'physique', 'qcm', 'la-loi-de-dalton-et-les-pressions-partielles', 'À quelle profondeur à l''air apparaissent les premiers effets de la narcose ($P_pN_2\approx 3{,}2$ bar) ?', 'Les premiers effets de la narcose apparaissent vers $P_pN_2\approx 3{,}2$ bar, soit environ 30 m à l''air. Le nitrox, qui ne change pas la teneur en azote à profondeur donnée, ne recule jamais ce seuil.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-012', 'a', '≈ 30 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-012', 'b', '≈ 10 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-012', 'c', '≈ 60 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-012', 'd', '≈ 70 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-013', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'notions-de-nitrox', 'Pour un nitrox 40 % avec limite $P_pO_2=1{,}6$ bar, quelle est la profondeur maximale d''utilisation (MOD) ?', '$P_{abs}=P_pO_2^{limite}/\%O_2=1{,}6/0{,}40=4$ bar, soit $(4-1)\times 10=30$ m. Le nitrox réduit la profondeur admissible mais allonge le temps sans palier en abaissant la $P_pN_2$.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-013', 'a', '30 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-013', 'b', '40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-013', 'c', '20 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-013', 'd', '50 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-014', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'notions-de-nitrox', 'Quel est le meilleur mélange pour 30 m ($P_{abs}=4$ bar) avec une limite $P_pO_2=1{,}4$ bar ?', 'Le meilleur mélange atteint tout juste la limite à la profondeur voulue : $\%O_2=P_pO_2^{limite}/P_{abs}=1{,}4/4=0{,}35$, soit 35 %. Au-delà de cette richesse, la $P_pO_2$ dépasserait la limite à 30 m.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-014', 'a', '35 %', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-014', 'b', '40 %', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-014', 'c', '32 %', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-014', 'd', '28 %', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-015', 'n4-pressions-gaz', 'n4', 'physique', 'vrai-faux', 'notions-de-nitrox', 'Le nitrox repousse la limite de narcose puisqu''il contient moins d''azote qu''à profondeur maximale.', 'Faux : à profondeur égale, la $P_pN_2$ du nitrox est certes plus faible qu''à l''air, mais l''intérêt du nitrox est de gagner sur la décompression, pas sur la narcose. La narcose dépend de l''azote respiré à la profondeur atteinte, et le nitrox impose surtout une vigilance accrue sur l''hyperoxie.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-015', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-015', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-016', 'n4-pressions-gaz', 'n4', 'physique', 'qcm', 'la-loi-de-henry-et-la-désaturation', 'Que dit la loi de Henry ?', 'La loi de Henry énonce qu''à température constante et à l''équilibre, la quantité de gaz dissoute est proportionnelle à la pression partielle au contact du liquide. Les autres énoncés sont respectivement Mariotte, Dalton et Archimède.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-016', 'a', 'À l''équilibre, la quantité de gaz dissoute dans un liquide est proportionnelle à sa pression partielle au contact', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-016', 'b', 'Le volume d''un gaz est inversement proportionnel à sa pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-016', 'c', 'La somme des pressions partielles égale la pression absolue', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-016', 'd', 'La poussée égale le poids du fluide déplacé', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-017', 'n4-pressions-gaz', 'n4', 'physique', 'qcm', 'la-loi-de-henry-et-la-désaturation', 'Un tissu dont la tension d''azote $T$ dépasse la pression partielle ambiante $P_p$ est :', 'Quand $T>P_p$, le tissu est en sursaturation et se décharge : c''est la situation de la remontée. Si $T<P_p$ le tissu se charge (descente, fond) et si $T=P_p$ il est saturé.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-017', 'a', 'En sursaturation, il se décharge (désaturation)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-017', 'b', 'En cours de charge', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-017', 'c', 'exactement saturé', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-017', 'd', 'insensible à la pression', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-018', 'n4-pressions-gaz', 'n4', 'physique', 'vrai-faux', 'la-loi-de-henry-et-la-désaturation', 'Une sursaturation excessive fait passer l''azote dissous à l''état de bulles, mécanisme de l''accident de désaturation.', 'Vrai : au-delà d''un rapport critique entre tension du tissu et pression ambiante, l''azote ne peut plus s''évacuer en solution et forme des bulles. Les paliers servent précisément à maintenir le gradient de sursaturation sous le seuil dangereux.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-018', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-018', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-019', 'n4-pressions-gaz', 'n4', 'physique', 'vrai-faux', 'rappel-des-pressions-et-unités', 'La pression relative (hydrostatique) à 25 m est de 2,5 bar.', 'Vrai : la pression relative est due à la seule colonne d''eau, égale à la profondeur divisée par 10, soit $25/10=2{,}5$ bar. La pression absolue à 25 m serait de $1+2{,}5=3{,}5$ bar.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-019', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-019', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-020', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'compressibilité-gonflage-et-transvasement', 'Deux blocs identiques de 10 L, l''un à 180 bar, l''autre à 40 bar, sont reliés. Quelle pression d''équilibre ?', '$P_{eq}=(180\times 10+40\times 10)/(10+10)=2200/20=110$ bar. Pour des volumes égaux, la pression d''équilibre est simplement la moyenne des deux pressions.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-020', 'a', '110 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-020', 'b', '220 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-020', 'c', '90 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-020', 'd', '140 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-021', 'n4-pressions-gaz', 'n4', 'physique', 'calcul', 'la-loi-de-dalton-et-les-pressions-partielles', 'À 50 m (6 bar), quelle est la pression partielle d''azote de l''air (80 % N₂) ?', '$P_pN_2=6\times 0{,}80=4{,}8$ bar, très au-dessus du seuil de narcose de 3,2 bar. La narcose est donc marquée à 50 m et impose une progressivité rigoureuse.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-021', 'a', '4,8 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-021', 'b', '1,2 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-021', 'c', '6 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-021', 'd', '5 bar', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gaz-022', 'n4-pressions-gaz', 'n4', 'physique', 'qcm', 'notions-de-nitrox', 'Quel est l''avantage principal du nitrox sur la décompression, à profondeur et durée égales ?', 'En abaissant la fraction d''azote respirée, le nitrox réduit la $P_pN_2$ à profondeur égale : les tissus se chargent moins et le temps sans palier s''allonge. La contrepartie est une profondeur maximale plus faible (hyperoxie).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-022', 'a', 'Il abaisse la PpN₂, donc la charge d''azote, et allonge le temps sans palier', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-022', 'b', 'Il supprime tout risque d''accident', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-022', 'c', 'Il permet de descendre plus profond qu''à l''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gaz-022', 'd', 'Il élimine la narcose', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-001', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'qcm', 'le-théorème-darchimède', 'Que dit le théorème d''Archimède ?', 'Le théorème d''Archimède énonce qu''un corps immergé subit une poussée verticale, dirigée de bas en haut, égale au poids du volume de fluide déplacé. Les autres énoncés correspondent à Mariotte et Henry.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-001', 'a', 'Tout corps immergé subit une poussée verticale vers le haut égale au poids du volume de fluide déplacé', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-001', 'b', 'La pression est proportionnelle à la profondeur uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-001', 'c', 'Le volume d''un gaz est inversement proportionnel à la pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-001', 'd', 'La quantité de gaz dissoute est proportionnelle à la pression partielle', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-002', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'calcul', 'le-théorème-darchimède', 'Quelle poussée subit un objet de 10 L totalement immergé en eau de mer (1,026 kg/L) ?', 'La poussée exprimée en kg vaut le volume immergé multiplié par la masse volumique : $10\times 1{,}026\approx 10{,}26$ kg. En eau douce (1 kg/L), la même poussée vaudrait 10 kg.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-002', 'a', '≈ 10,26 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-002', 'b', '10 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-002', 'c', '1,026 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-002', 'd', '≈ 100 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-003', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'qcm', 'le-théorème-darchimède', 'Comment définit-on le poids apparent d''un corps immergé ?', 'Le poids apparent est la différence entre le poids réel et la poussée. S''il est positif le corps coule, s''il est nul il reste entre deux eaux, s''il est négatif il flotte.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-003', 'a', 'Poids réel moins la poussée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-003', 'b', 'Poids réel plus la poussée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-003', 'c', 'Poussée moins poids réel', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-003', 'd', 'Poids réel multiplié par la poussée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-004', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'vrai-faux', 'le-théorème-darchimède', 'Un plongeur flotte légèrement mieux en eau de mer qu''en eau douce.', 'Vrai : la masse volumique de l''eau de mer (≈ 1,026 kg/L) dépasse celle de l''eau douce (1 kg/L), donc la poussée est plus forte en mer. Cela impose un léger surlestage en mer.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-004', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-004', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-005', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'calcul', 'calculs-de-lestage-et-de-flottabilité', 'Un plongeur équipé pèse 90 kg et déplace 88 L d''eau de mer (1,026 kg/L). Quel est son poids apparent ?', 'Poussée = $88\times 1{,}026\approx 90{,}3$ kg ; poids apparent = $90-90{,}3=-0{,}3$ kg. Le poids apparent négatif signifie qu''il flotte légèrement et devra ajouter un peu de plomb.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-005', 'a', '≈ −0,3 kg (il flotte)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-005', 'b', '≈ +0,3 kg (il coule)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-005', 'c', '0 kg (équilibré)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-005', 'd', '≈ −2 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-006', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'calcul', 'calculs-de-lestage-et-de-flottabilité', 'Un plongeur pèse 80 kg et déplace 82 L en eau douce (1 kg/L). Quel lestage pour l''équilibrer ?', 'Poussée = $82\times 1=82$ kg ; poids apparent = $80-82=-2$ kg : il flotte de 2 kg et doit ajouter environ 2 kg de plomb. En pratique on leste un peu plus pour compenser l''allègement du bloc en fin de plongée.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-006', 'a', '≈ 2 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-006', 'b', '≈ 82 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-006', 'c', '≈ 0 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-006', 'd', '≈ 10 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-007', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'qcm', 'calculs-de-lestage-et-de-flottabilité', 'Pourquoi un surlestage initial est-il dangereux ?', 'Un plongeur surlesté doit compenser par un gros volume d''air dans le gilet, qui se dilate à la remontée (Mariotte) et provoque des remontées incontrôlées. Le contrôle de la flottabilité doit rester permanent.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-007', 'a', 'Il oblige à gonfler beaucoup le gilet, source de remontées incontrôlées', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-007', 'b', 'Il améliore la stabilité en profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-007', 'c', 'Il diminue la consommation d''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-007', 'd', 'Il n''a aucune conséquence', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-008', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'calcul', 'relevage-dun-objet-immergé', 'Une ancre en fonte de 30 kg, volume 4 L, repose à 20 m en eau de mer (1,026 kg/L). Quel est son poids apparent ?', 'Poussée = $4\times 1{,}026\approx 4{,}1$ kg ; poids apparent = $30-4{,}1\approx 25{,}9$ kg. Il faut donc développer une poussée supplémentaire d''au moins 26 kg pour décoller l''ancre.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-008', 'a', '≈ 25,9 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-008', 'b', '30 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-008', 'c', '≈ 4,1 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-008', 'd', '≈ 34 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-009', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'calcul', 'relevage-dun-objet-immergé', 'Un parachute contient 25 L d''air à 20 m (3 bar). Quel volume tend-il à occuper en surface, sans purge ?', 'Par Mariotte $V=(3\times 25)/1=75$ L : l''air triple de volume, la poussée augmente et la remontée s''emballe. On purge l''excédent au fur et à mesure et on ne se place jamais au-dessus de la charge.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-009', 'a', '75 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-009', 'b', '25 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-009', 'c', '50 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-009', 'd', '12,5 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-010', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'qcm', 'relevage-dun-objet-immergé', 'Pourquoi un relevage au parachute s''accélère-t-il tout seul ?', 'L''air injecté suit Mariotte : en remontant il se détend, le volume augmente, donc la poussée augmente et la remontée s''accélère — c''est l''emballement. On purge en continu et on ne reste jamais dans l''axe de la charge.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-010', 'a', 'L''air du parachute se dilate à la remontée (Mariotte), augmentant la poussée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-010', 'b', 'La poussée d''Archimède diminue en remontant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-010', 'c', 'Le poids de l''objet augmente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-010', 'd', 'L''eau devient plus dense en surface', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-011', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'qcm', 'loptique--la-réfraction', 'Quel est l''effet de la réfraction à l''interface eau-air du masque ?', 'L''eau étant plus réfringente que l''air, les objets paraissent environ un tiers plus gros et à peu près aux trois quarts de leur distance réelle. À la prise d''objet, on tend donc la main un peu plus loin que là où on croit voir la cible.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-011', 'a', 'Les objets paraissent plus gros (×4/3) et plus proches (≈ ×3/4 de la distance réelle)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-011', 'b', 'Les objets paraissent plus petits et plus loin', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-011', 'c', 'Aucun changement de taille ni de distance', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-011', 'd', 'Les objets disparaissent', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-012', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'vrai-faux', 'loptique--la-réfraction', 'Le masque est indispensable car, sans lame d''air devant l''œil, l''image se formerait très loin derrière la rétine et la vision serait extrêmement floue.', 'Vrai : sans masque, l''absence d''interface air-cornée empêche l''œil d''accommoder et la vision devient très floue. Le masque restaure une interface plane compatible avec l''accommodation.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-012', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-012', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-013', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'qcm', 'champ-visuel-couleurs-et-luminosité', 'Dans quel ordre les couleurs disparaissent-elles avec la profondeur ?', 'L''eau absorbe d''abord les grandes longueurs d''onde : le rouge s''éteint vers 5-10 m, puis l''orange, le jaune, le vert, et le bleu persiste le plus longtemps. D''où la dominante bleu-vert des profondeurs ; une lampe restitue les couleurs.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-013', 'a', 'Rouge d''abord (5-10 m), puis orange, jaune, vert ; le bleu persiste', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-013', 'b', 'Bleu d''abord, puis vert, jaune, rouge', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-013', 'c', 'Toutes en même temps', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-013', 'd', 'Le vert d''abord, puis le rouge', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-014', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'vrai-faux', 'champ-visuel-couleurs-et-luminosité', 'Le masque réduit le champ visuel, obligeant le plongeur à compenser par des mouvements de tête.', 'Vrai : la vitre et la jupe cachent la périphérie et la réfraction rétrécit l''angle utile, donnant une vision « en tunnel ». C''est un point de sécurité pour le guide qui doit surveiller toute sa palanquée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-014', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-014', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-015', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'calcul', 'lacoustique--le-son-sous-leau', 'À quelle vitesse approximative le son se propage-t-il dans l''eau ?', 'Le son se propage à environ 1500 m/s dans l''eau, contre 340 m/s dans l''air, soit un rapport d''environ 4,3. Cette propagation rapide fait que les sons portent loin et fort.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-015', 'a', '≈ 1500 m/s', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-015', 'b', '≈ 340 m/s', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-015', 'c', '≈ 150 m/s', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-015', 'd', '≈ 3000 m/s', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-016', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'qcm', 'lacoustique--le-son-sous-leau', 'Pourquoi ne peut-on pas localiser une source sonore sous l''eau ?', 'La localisation dans l''air repose sur le décalage de temps d''arrivée entre les deux oreilles ; sous l''eau, la vitesse du son supprime ce décalage et le son se transmet par les os du crâne. On entend le bateau fort mais sans savoir d''où il vient.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-016', 'a', 'Le son va si vite qu''il atteint les deux oreilles quasi simultanément, supprimant le décalage utile à la localisation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-016', 'b', 'Le son ne se propage pas dans l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-016', 'c', 'L''oreille ne fonctionne pas sous l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-016', 'd', 'Le son est trop faible', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-017', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'vrai-faux', 'lacoustique--le-son-sous-leau', 'Entendre un bateau sous l''eau renseigne sur sa direction, ce qui permet de l''éviter à la remontée.', 'Faux : on entend le danger sans pouvoir le localiser. La remontée doit toujours être protégée par un parachute, en tournant sur soi et en levant la tête, sans jamais se fier à l''oreille pour situer un bateau.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-017', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-017', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-018', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'calcul', 'relevage-dun-objet-immergé', 'Un objet de 20 kg, volume 3 L, repose en eau douce (1 kg/L). Quel est son poids apparent ?', 'Poussée = $3\times 1=3$ kg ; poids apparent = $20-3=17$ kg. En eau douce, un litre immergé déplace exactement 1 kg, ce qui simplifie le calcul.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-018', 'a', '17 kg', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-018', 'b', '20 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-018', 'c', '3 kg', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-018', 'd', '23 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-019', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'qcm', 'calculs-de-lestage-et-de-flottabilité', 'Que devient la flottabilité d''une combinaison néoprène en profondeur ?', 'Les bulles du néoprène se compriment en profondeur (Mariotte) : la poussée chute, le plongeur équilibré en surface devient lourd au fond et doit gonfler son gilet. À la remontée, l''inverse se produit.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-019', 'a', 'Elle diminue car le néoprène se comprime (Mariotte)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-019', 'b', 'Elle augmente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-019', 'c', 'Elle reste constante', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-019', 'd', 'Elle disparaît totalement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-001', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'anatomie-de-lappareil-respiratoire', 'Où commence la zone d''échange gazeux de l''appareil respiratoire ?', 'La zone d''échange commence aux alvéoles, où la membrane alvéolo-capillaire très fine autorise la diffusion des gaz. Les voies de conduction (trachée, bronches) amènent l''air sans réaliser d''échange.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-001', 'a', 'Aux alvéoles pulmonaires, tapissées de capillaires', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-001', 'b', 'Dans la trachée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-001', 'c', 'Dans le larynx', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-001', 'd', 'Dans les bronches souches', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-002', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'anatomie-de-lappareil-respiratoire', 'Quel est le principal muscle inspiratoire ?', 'Le diaphragme, muscle en forme de coupole séparant le thorax de l''abdomen, est le principal moteur de la ventilation. Sa contraction abaisse le plancher thoracique et fait entrer l''air.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-002', 'a', 'Le diaphragme', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-002', 'b', 'Le cœur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-002', 'c', 'Les abdominaux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-002', 'd', 'Les cordes vocales', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-003', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'anatomie-de-lappareil-respiratoire', 'Quel est l''ordre de grandeur de la surface d''échange alvéolaire totale ?', 'La surface d''échange totale est d''environ 70 à 100 m², l''équivalent d''un court de tennis replié dans le thorax. Cette immense surface permet des échanges gazeux rapides.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-003', 'a', '70 à 100 m²', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-003', 'b', '1 à 2 m²', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-003', 'c', '10 m²', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-003', 'd', '500 m²', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-004', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'calcul', 'volumes-et-capacités-pulmonaires', 'Quelle est la valeur moyenne du volume courant (VC) au repos ?', 'Le volume courant, air mobilisé à chaque cycle au repos, vaut environ 0,5 L. La capacité vitale vaut environ 4,5 L et la capacité pulmonaire totale environ 6 L.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-004', 'a', '≈ 0,5 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-004', 'b', '≈ 4,5 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-004', 'c', '≈ 1,2 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-004', 'd', '≈ 6 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-005', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'volumes-et-capacités-pulmonaires', 'Que représente le volume résiduel (VR) ?', 'Le volume résiduel (≈ 1,2 L) est l''air restant après une expiration forcée, qu''on ne peut jamais expulser. Il maintient les poumons partiellement déployés et joue un rôle protecteur en apnée profonde.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-005', 'a', 'L''air restant après expiration forcée, jamais expulsable', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-005', 'b', 'L''air mobilisé à chaque cycle', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-005', 'c', 'La totalité de l''air des poumons', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-005', 'd', 'L''air inspirable après une inspiration normale', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-006', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'calcul', 'volumes-et-capacités-pulmonaires', 'Capacité vitale = VC + VRI + VRE, avec VC ≈ 0,5 L, VRI ≈ 2,5 L, VRE ≈ 1,5 L. Quelle valeur ?', 'Capacité vitale = 0,5 + 2,5 + 1,5 = 4,5 L, l''air mobilisable au maximum. En ajoutant le volume résiduel (≈ 1,2 L), on obtient la capacité pulmonaire totale d''environ 6 L.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-006', 'a', '≈ 4,5 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-006', 'b', '≈ 6 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-006', 'c', '≈ 3 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-006', 'd', '≈ 1,2 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-007', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'lespace-mort', 'Quel est l''ordre de grandeur de l''espace mort anatomique ?', 'L''espace mort anatomique, volume des voies de conduction qui ne participe pas aux échanges, vaut environ 150 mL. Sur les 500 mL d''un cycle de repos, seuls 350 mL environ atteignent réellement les alvéoles.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-007', 'a', '≈ 150 mL', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-007', 'b', '≈ 500 mL', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-007', 'c', '≈ 1,2 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-007', 'd', '≈ 50 mL', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-008', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'vrai-faux', 'lespace-mort', 'Une ventilation rapide et superficielle est inefficace car une large part de l''air reste dans l''espace mort.', 'Vrai : en respirant par petits volumes, une grande fraction ne dépasse pas l''espace mort et l''oxygénation chute — c''est le piège de l''essoufflement. La consigne est toujours une ventilation ample avec expiration complète.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-008', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-008', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-009', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'lespace-mort', 'Pourquoi un tuba trop long ou de gros diamètre est-il dangereux ?', 'Un tuba trop volumineux ajoute un espace mort supplémentaire qui rend la ventilation inefficace et favorise l''accumulation de CO₂. C''est pourquoi les tubas ont des dimensions normalisées.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-009', 'a', 'Il augmente l''espace mort et favorise l''accumulation de CO₂', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-009', 'b', 'Il augmente la flottabilité', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-009', 'c', 'Il réduit la vision', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-009', 'd', 'Il n''a aucun effet', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-010', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'la-mécanique-ventilatoire', 'Comment se déroulent l''inspiration et l''expiration de repos ?', 'L''inspiration est active : le diaphragme se contracte et les intercostaux soulèvent les côtes. L''expiration de repos est passive, assurée par l''élasticité des poumons et de la cage thoracique.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-010', 'a', 'Inspiration active (diaphragme, intercostaux) ; expiration de repos passive (élasticité)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-010', 'b', 'Inspiration passive ; expiration active', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-010', 'c', 'Les deux sont actives', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-010', 'd', 'Les deux sont passives', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-011', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'vrai-faux', 'la-mécanique-ventilatoire', 'En profondeur, l''air plus dense (Mariotte) augmente le travail ventilatoire.', 'Vrai : la densité de l''air augmente avec la profondeur, rendant l''écoulement dans les bronches plus difficile et accroissant le travail respiratoire. Ajouté à la résistance du détendeur, cela explique qu''un effort mal géré au fond mène vite à l''essoufflement.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-011', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-011', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-012', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'les-échanges-gazeux-et-le-transport-des-gaz', 'Comment les gaz traversent-ils la membrane alvéolo-capillaire ?', 'Les gaz diffusent passivement de la zone de forte pression partielle vers la faible, jusqu''à l''équilibre. L''oxygène passe de l''alvéole vers le sang veineux, le gaz carbonique fait le trajet inverse.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-012', 'a', 'Par diffusion passive, de la forte vers la faible pression partielle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-012', 'b', 'Par transport actif consommant de l''énergie', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-012', 'c', 'Par pompage musculaire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-012', 'd', 'Ils ne la traversent pas', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-013', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'les-échanges-gazeux-et-le-transport-des-gaz', 'Comment l''oxygène est-il majoritairement transporté dans le sang ?', 'L''oxygène est transporté à près de 98 % fixé sur l''hémoglobine (oxyhémoglobine), et pour une faible part dissous dans le plasma. C''est pourquoi une intoxication au CO, qui bloque l''hémoglobine, est si grave.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-013', 'a', 'Fixé à près de 98 % sur l''hémoglobine des globules rouges', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-013', 'b', 'Uniquement dissous dans le plasma', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-013', 'c', 'Sous forme de bicarbonates', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-013', 'd', 'Combiné à l''azote', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-014', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'la-commande-ventilatoire--le-rôle-du-co', 'Qu''est-ce qui déclenche principalement l''envie de respirer ?', 'Contrairement à l''intuition, c''est l''augmentation de la $P_pCO_2$ sanguine, détectée par des chémorécepteurs, qui commande la ventilation, non le manque d''oxygène. Cette régulation par le CO₂ a des conséquences majeures en plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-014', 'a', 'L''augmentation du gaz carbonique (CO₂) dans le sang', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-014', 'b', 'Le manque d''oxygène', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-014', 'c', 'L''augmentation de l''azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-014', 'd', 'La baisse de la température', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-015', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'la-commande-ventilatoire--le-rôle-du-co', 'Pourquoi l''hyperventilation avant une apnée est-elle dangereuse ?', 'L''hyperventilation abaisse artificiellement le CO₂ : le signal d''alarme est retardé et l''apnéiste peut consommer tout son oxygène et perdre connaissance avant de ressentir le besoin de respirer. C''est la syncope hypoxique.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-015', 'a', 'Elle abaisse le CO₂ et retarde le signal d''alarme, exposant à la syncope hypoxique', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-015', 'b', 'Elle augmente le CO₂ et provoque un essoufflement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-015', 'c', 'Elle sature les poumons d''azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-015', 'd', 'Elle n''a aucun effet', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-016', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'qcm', 'la-commande-ventilatoire--le-rôle-du-co', 'Quelle est la conduite face à un plongeur qui s''essouffle ?', 'L''essoufflement est un cercle vicieux d''accumulation de CO₂ : on cesse l''effort, on stabilise et on insiste sur une expiration ample. On n''entame pas une remontée en pleine crise sans avoir stabilisé la ventilation, sauf danger majeur.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-016', 'a', 'Cesser tout effort, stabiliser, ralentir et surtout expirer amplement pour évacuer le CO₂', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-016', 'b', 'Accélérer la ventilation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-016', 'c', 'Remonter immédiatement en pleine crise', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-016', 'd', 'Retenir sa respiration', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-017', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'vrai-faux', 'volumes-et-capacités-pulmonaires', 'Le volume résiduel peut être entièrement expiré lors d''une expiration forcée.', 'Faux : le volume résiduel (≈ 1,2 L) n''est jamais expulsé, même lors d''une expiration forcée. C''est justement ce qui le distingue du volume de réserve expiratoire.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-017', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-017', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-001', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'le-cœur--anatomie-et-fonctionnement', 'Comment est organisé le cœur ?', 'Le cœur est une pompe à quatre cavités : une oreillette et un ventricule de chaque côté, séparés par une cloison étanche. Le cœur droit propulse le sang veineux, le cœur gauche, plus puissant, le sang artériel.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-001', 'a', 'Quatre cavités : deux oreillettes et deux ventricules, séparés en cœur droit et cœur gauche', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-001', 'b', 'Deux cavités seulement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-001', 'c', 'Une seule cavité musculaire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-001', 'd', 'Trois oreillettes et un ventricule', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-002', 'n4-circulation-oreille', 'n4', 'physiologie', 'calcul', 'le-cœur--anatomie-et-fonctionnement', 'Quel est l''ordre de grandeur du débit cardiaque au repos ?', 'Le débit cardiaque au repos est d''environ 5 L/min, avec une fréquence de 60 à 80 battements par minute. Il est largement modulable à l''effort.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-002', 'a', '≈ 5 L/min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-002', 'b', '≈ 1 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-002', 'c', '≈ 20 L/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-002', 'd', '≈ 0,5 L/min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-003', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'les-deux-circulations', 'Quel est le trajet de la petite circulation (pulmonaire) ?', 'La petite circulation part du ventricule droit, gagne les poumons où le sang se recharge en oxygène, et revient à l''oreillette gauche. La grande circulation, elle, part du ventricule gauche vers le corps et revient au cœur droit.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-003', 'a', 'Ventricule droit → poumons → oreillette gauche', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-003', 'b', 'Ventricule gauche → corps → oreillette droite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-003', 'c', 'Oreillette droite → corps → ventricule gauche', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-003', 'd', 'Poumons → cœur droit → corps', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-004', 'n4-circulation-oreille', 'n4', 'physiologie', 'vrai-faux', 'les-deux-circulations', 'L''artère pulmonaire transporte du sang veineux (pauvre en oxygène).', 'Vrai : l''appellation des vaisseaux suit le sens du flux (partant ou revenant au cœur), pas la richesse en oxygène. L''artère pulmonaire transporte du sang veineux vers les poumons, et les veines pulmonaires du sang artériel vers le cœur gauche.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-004', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-004', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-005', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'les-deux-circulations', 'Quel rôle jouent les poumons vis-à-vis des bulles veineuses de désaturation ?', 'Les poumons filtrent normalement les petites bulles veineuses formées à la désaturation, les empêchant de gagner la circulation artérielle. Un foramen ovale perméable peut court-circuiter ce filtre.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-005', 'a', 'Ils agissent comme un filtre qui piège normalement les petites bulles veineuses', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-005', 'b', 'Ils produisent les bulles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-005', 'c', 'Ils envoient directement les bulles vers le cerveau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-005', 'd', 'Ils n''ont aucun rôle', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-006', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'le-foramen-ovale-perméable', 'Qu''est-ce que le foramen ovale perméable (FOP) ?', 'Le foramen ovale, ouverture fœtale entre les oreillettes, reste partiellement perméable chez environ 25 % des sujets. En temps normal la pression plus élevée à gauche maintient le clapet fermé.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-006', 'a', 'Une communication résiduelle entre les deux oreillettes, présente chez environ un quart de la population', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-006', 'b', 'Une malformation des ventricules', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-006', 'c', 'Un défaut des valves cardiaques', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-006', 'd', 'Une pathologie de l''oreille interne', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-007', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'le-foramen-ovale-perméable', 'Comment un FOP peut-il provoquer un ADD neurologique « immérité » ?', 'Lors d''un effort à glotte fermée (Valsalva puissant, port de charge), la pression du cœur droit dépasse celle du gauche et ouvre le passage : les bulles veineuses passent en artériel (shunt droit-gauche) et peuvent gagner cerveau ou moelle. D''où un ADD neurologique malgré une déco respectée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-007', 'a', 'Un effort à glotte fermée ouvre le passage et fait shunter des bulles veineuses vers la circulation artérielle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-007', 'b', 'Il augmente la consommation d''oxygène', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-007', 'c', 'Il bloque l''hémoglobine', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-007', 'd', 'Il comprime la trachée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-008', 'n4-circulation-oreille', 'n4', 'physiologie', 'vrai-faux', 'le-foramen-ovale-perméable', 'En prévention d''un FOP, on évite les efforts violents et les Valsalva puissants à la remontée.', 'Vrai : éviter les efforts et Valsalva forts à la remontée limite l''ouverture du shunt, et des procédures de décompression prudentes réduisent la charge en bulles veineuses. La recherche du FOP est proposée après un accident inexpliqué.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-008', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-008', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-009', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'loreille-externe-et-moyenne', 'Quelle est la particularité de l''oreille moyenne ?', 'L''oreille moyenne est une cavité à air, derrière le tympan, contenant les trois osselets et reliée à l''arrière-nez par la trompe d''Eustache. C''est par cette trompe qu''on fait entrer de l''air pour équilibrer à la descente.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-009', 'a', 'C''est une cavité remplie d''air, reliée au rhinopharynx par la trompe d''Eustache', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-009', 'b', 'Elle est remplie de liquide', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-009', 'c', 'Elle contient la cochlée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-009', 'd', 'Elle est ouverte sur l''extérieur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-010', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'loreille-externe-et-moyenne', 'Quelle est la règle d''équilibrage de l''oreille moyenne à la descente ?', 'On équilibre tôt, souvent et sans forcer, dès les premiers mètres, car un équilibrage tardif ou violent lèse le tympan. On ne descend jamais enrhumé, la trompe d''Eustache étant alors bouchée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-010', 'a', 'Équilibrer tôt, souvent et sans forcer, dès les premiers mètres', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-010', 'b', 'Attendre la douleur pour équilibrer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-010', 'c', 'Équilibrer une seule fois au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-010', 'd', 'Ne jamais équilibrer', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-011', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'loreille-interne--cochlée-et-vestibule', 'Quels sont les deux organes de l''oreille interne et leurs fonctions ?', 'L''oreille interne, remplie de liquide, abrite la cochlée (limaçon) pour l''audition et le vestibule avec ses canaux semi-circulaires pour l''équilibre. Sous l''eau, privé de repères visuels, le plongeur dépend fortement de son vestibule.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-011', 'a', 'La cochlée (audition) et le vestibule (équilibre)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-011', 'b', 'Le tympan (audition) et les osselets (équilibre)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-011', 'c', 'La trompe d''Eustache (audition) et la cochlée (équilibre)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-011', 'd', 'Le pavillon (équilibre) et le conduit (audition)', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-012', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'loreille-interne--cochlée-et-vestibule', 'Qu''est-ce que le vertige alterno-barique ?', 'Le vertige alterno-barique survient quand les deux oreilles ne s''équilibrent pas à la même vitesse à la remontée, créant une asymétrie de pression transitoire heureusement réversible. Tout vertige en plongée reste préoccupant car il désoriente et favorise la panique.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-012', 'a', 'Un vertige dû à un équilibrage inégal des deux oreilles à la remontée, généralement réversible', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-012', 'b', 'Un accident de désaturation de la moelle', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-012', 'c', 'Une surpression pulmonaire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-012', 'd', 'Une intoxication au CO', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-013', 'n4-circulation-oreille', 'n4', 'physiologie', 'vrai-faux', 'loreille-interne--cochlée-et-vestibule', 'Le barotraumatisme de l''oreille interne, survenant lors d''un Valsalva forcé, est une urgence ORL.', 'Vrai : un équilibrage violent ou dissymétrique peut léser les structures de l''oreille interne, entraînant vertiges, acouphènes et baisse d''audition durable — une urgence ORL. On équilibre donc toujours en douceur.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-013', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-013', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-014', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'loreille-externe-et-moyenne', 'Que ferme le fond du conduit auditif de l''oreille externe ?', 'Le conduit auditif est fermé au fond par le tympan, membrane qui vibre au passage du son. Le conduit est normalement ouvert sur l''extérieur, donc l''eau y pénètre et la pression s''équilibre seule.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-014', 'a', 'Le tympan', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-014', 'b', 'La cochlée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-014', 'c', 'La trompe d''Eustache', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-014', 'd', 'L''étrier', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-015', 'n4-circulation-oreille', 'n4', 'physiologie', 'vrai-faux', 'le-cœur--anatomie-et-fonctionnement', 'Le cœur gauche est plus puissant que le cœur droit car il propulse le sang dans tout l''organisme.', 'Vrai : le cœur gauche propulse le sang artériel dans toute la grande circulation, ce qui exige une pression bien plus élevée que celle du cœur droit, limité aux poumons. Sa paroi musculaire est donc plus épaisse.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-015', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-015', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-circ-016', 'n4-circulation-oreille', 'n4', 'physiologie', 'qcm', 'les-deux-circulations', 'Par quel réseau l''azote dissous est-il distribué aux tissus puis évacué ?', 'L''azote dissous voyage par la circulation : chargé aux poumons pendant la plongée, distribué aux tissus, puis évacué en sens inverse et éliminé par les poumons à la remontée. C''est aussi par cette voie que circulent les bulles en cas d''accident.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-016', 'a', 'La circulation sanguine, chargé aux poumons puis éliminé par eux à la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-016', 'b', 'Le système lymphatique uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-016', 'c', 'Le système nerveux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-circ-016', 'd', 'La trompe d''Eustache', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-001', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'laccident-de-désaturation--cinétique-des-bulles', 'Quel est le mécanisme de l''accident de désaturation ?', 'L''ADD résulte de la formation de bulles d''azote lorsque la sursaturation dépasse le seuil tolérable à la remontée. Si la remontée respecte le gradient critique, l''azote s''évacue en solution ; sinon il change de phase et forme des bulles.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-001', 'a', 'La formation de bulles d''azote quand la sursaturation dépasse le seuil tolérable (Henry)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-001', 'b', 'Le blocage de l''hémoglobine par le CO', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-001', 'c', 'La dilatation de l''air pulmonaire à la remontée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-001', 'd', 'Le passage de plasma dans les alvéoles', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-002', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'laccident-de-désaturation--cinétique-des-bulles', 'Où naissent d''abord les bulles de désaturation, et que se passe-t-il normalement ?', 'Les bulles naissent d''abord dans le compartiment veineux, généralement silencieuses et filtrées par les poumons. Elles deviennent pathogènes en grossissant, en bloquant la circulation ou en déclenchant une cascade inflammatoire.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-002', 'a', 'Dans le compartiment veineux ; elles sont généralement silencieuses et filtrées par les poumons', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-002', 'b', 'Dans les artères ; elles gagnent aussitôt le cerveau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-002', 'c', 'Dans les poumons ; elles sont expirées', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-002', 'd', 'Dans l''estomac ; elles sont éliminées', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-003', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'add--formes-cliniques-et-symptômes', 'Quelle forme d''ADD est la plus fréquente en plongée loisir ?', 'Les formes neurologiques médullaires sont les plus fréquentes en plongée loisir : fourmillements, engourdissement, faiblesse ou paralysie, troubles urinaires. C''est une urgence absolue.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-003', 'a', 'La forme neurologique médullaire (fourmillements, faiblesse, troubles urinaires)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-003', 'b', 'La forme cutanée bénigne', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-003', 'c', 'La forme ostéo-articulaire isolée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-003', 'd', 'La forme respiratoire', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-004', 'n4-accidents', 'n4', 'physiologie', 'vrai-faux', 'add--formes-cliniques-et-symptômes', 'Tout symptôme anormal après une plongée doit être considéré comme un ADD jusqu''à preuve du contraire.', 'Vrai : même léger, même différé, même après une plongée « dans les clous », tout symptôme post-plongée est un ADD jusqu''à preuve médicale du contraire. On met sous oxygène et on alerte sans attendre de voir si « ça passe ».', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-004', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-004', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-005', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'add--formes-cliniques-et-symptômes', 'Dans quel délai apparaissent le plus souvent les signes d''un ADD ?', 'Les signes surviennent le plus souvent dans l''heure suivant la sortie, parfois immédiatement, parfois différés jusqu''à 24 h. Ce caractère retardé impose une surveillance prolongée après la plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-005', 'a', 'Le plus souvent dans l''heure suivant la sortie, parfois jusqu''à 24 h', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-005', 'b', 'Toujours pendant la plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-005', 'c', 'Uniquement plusieurs jours après', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-005', 'd', 'Jamais avant une semaine', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-006', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'la-surpression-pulmonaire--mécanisme-alvéolaire', 'Quel est le mécanisme de la surpression pulmonaire ?', 'La surpression pulmonaire relève de Mariotte : à la remontée, l''air pulmonaire se dilate ; s''il ne peut sortir (glotte fermée, zone piégée), le volume emprisonné fait monter la pression et déchire les parois alvéolaires. C''est l''accident mécanique le plus grave.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-006', 'a', 'L''air pulmonaire bloqué se dilate à la remontée (Mariotte) et déchire les alvéoles', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-006', 'b', 'Des bulles d''azote se forment dans les tissus', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-006', 'c', 'Le plasma envahit les alvéoles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-006', 'd', 'L''azote bloque l''hémoglobine', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-007', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'la-surpression-pulmonaire--mécanisme-alvéolaire', 'Quelle est la forme la plus redoutée de la surpression pulmonaire ?', 'L''air passant dans les capillaires pulmonaires déchirés gagne la circulation artérielle et provoque une aéroembolie cérébrale, forme la plus redoutée. La déchirure peut aussi ouvrir sur la plèvre (pneumothorax) ou le médiastin (emphysème sous-cutané).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-007', 'a', 'L''aéroembolie cérébrale (bulles gagnant le cerveau par la circulation artérielle)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-007', 'b', 'Un simple emphysème sous-cutané isolé', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-007', 'c', 'Une toux passagère', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-007', 'd', 'Une douleur d''oreille', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-008', 'n4-accidents', 'n4', 'physiologie', 'vrai-faux', 'la-surpression-pulmonaire--mécanisme-alvéolaire', 'La surpression pulmonaire ne peut survenir qu''en plongée profonde.', 'Faux : la surpression peut survenir même à faible profondeur, une remontée paniquée de 3 m poumons bloqués suffit. La prévention tient en une règle intangible : ne jamais bloquer sa respiration à la remontée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-008', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-008', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-009', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'la-surpression-pulmonaire--mécanisme-alvéolaire', 'Quelle est la règle de prévention essentielle de la surpression pulmonaire ?', 'La prévention repose sur une règle intangible : ne jamais bloquer sa respiration à la remontée, expirer, respecter la vitesse de remontée. Toute pathologie pulmonaire (asthme non contrôlé) écarte de la plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-009', 'a', 'Ne jamais bloquer sa respiration à la remontée, expirer, respecter la vitesse', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-009', 'b', 'Descendre très vite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-009', 'c', 'Retenir sa respiration au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-009', 'd', 'Gonfler ses poumons au maximum avant de remonter', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-010', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'lœdème-pulmonaire-dimmersion', 'Quel est le mécanisme de l''œdème pulmonaire d''immersion (OPI) ?', 'L''OPI n''est ni barotraumatique ni lié à l''azote : l''immersion redistribue le sang vers le thorax, le froid provoque une vasoconstriction qui augmente la pression pulmonaire, et du plasma passe dans les alvéoles. Les poumons « se noient » de l''intérieur.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-010', 'a', 'Redistribution du sang vers le thorax + froid + effort → passage de plasma dans les alvéoles', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-010', 'b', 'Dilatation de l''air pulmonaire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-010', 'c', 'Formation de bulles d''azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-010', 'd', 'Blocage de l''hémoglobine par le CO', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-011', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'lœdème-pulmonaire-dimmersion', 'Quels signes évoquent un œdème pulmonaire d''immersion ?', 'L''OPI se manifeste par un essoufflement inexpliqué et disproportionné, une toux, des crachats mousseux parfois rosés et une oppression qui ne cèdent pas au repos et s''aggravent. C''est une urgence médicale : sortir, oxygène, position demi-assise, réchauffer, alerter.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-011', 'a', 'Essoufflement disproportionné, toux, crachats mousseux parfois rosés, oppression', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-011', 'b', 'Douleur articulaire isolée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-011', 'c', 'Fourmillements d''un membre', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-011', 'd', 'Simple fatigue qui cède au repos', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-012', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'accidents-biochimiques--narcose-hyperoxie-hypercapnie-co', 'Quel accident biochimique menace au-delà d''une $P_pO_2$ d''environ 1,6 bar ?', 'Au-delà d''une $P_pO_2$ d''environ 1,6 bar, l''hyperoxie expose à une crise convulsive de type épileptique, dramatique sous l''eau (noyade, surpression à la remontée). Elle concerne surtout le nitrox mal géré et la plongée à l''air au-delà de 60 m.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-012', 'a', 'L''hyperoxie, avec risque de crise convulsive', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-012', 'b', 'La narcose à l''azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-012', 'c', 'L''hypercapnie', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-012', 'd', 'L''intoxication au CO', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-013', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'accidents-biochimiques--narcose-hyperoxie-hypercapnie-co', 'Quel est l''effet de la narcose à l''azote et sa conduite à tenir ?', 'Au-delà d''une $P_pN_2$ d''environ 3,2 bar (≈ 30 m), l''azote altère le système nerveux (euphorie ou angoisse, troubles du jugement). Le danger est indirect (comportement inadapté) ; remonter de quelques mètres fait régresser les signes rapidement.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-013', 'a', 'Altération du jugement au-delà de ~30 m ; remonter de quelques mètres fait régresser les signes', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-013', 'b', 'Déchirure des alvéoles ; expirer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-013', 'c', 'Bulles dans la moelle ; caisson', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-013', 'd', 'Blocage de l''hémoglobine ; oxygène', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-014', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'accidents-biochimiques--narcose-hyperoxie-hypercapnie-co', 'D''où provient une intoxication au monoxyde de carbone en plongée ?', 'Le CO provient d''un air de gonflage pollué, lorsque la prise d''air du compresseur aspire des gaz d''échappement. Le CO bloque l''hémoglobine ; la prévention passe par la qualité de l''air, la filtration et le contrôle du compresseur.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-014', 'a', 'D''un air de gonflage pollué (CO issu d''un moteur près de la prise d''air du compresseur)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-014', 'b', 'De la dilatation des poumons', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-014', 'c', 'D''un excès d''azote dissous', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-014', 'd', 'Du froid', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-015', 'n4-accidents', 'n4', 'physiologie', 'vrai-faux', 'accidents-biochimiques--narcose-hyperoxie-hypercapnie-co', 'L''hypercapnie (excès de CO₂) aggrave la narcose et l''hyperoxie.', 'Vrai : l''excès de CO₂, issu d''une ventilation inefficace ou d''un effort, aggrave à la fois la narcose et l''hyperoxie. La prévention passe par une ventilation ample et l''absence d''effort au fond.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-015', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-015', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-016', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'conduite-à-tenir-et-cadre-réglementaire-du-secours', 'Quel est le geste qui sauve en priorité face à un accident de désaturation ou de surpression ?', 'L''oxygène à 100 % au débit maximal (15 L/min) est le geste qui sauve : il accélère l''élimination de l''azote et oxygène les tissus. Il s''accompagne d''une alerte précoce, ces deux gestes conditionnant le pronostic.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-016', 'a', 'L''oxygénothérapie normobare à 100 %, le plus tôt possible, au débit maximal (15 L/min)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-016', 'b', 'Faire boire de l''alcool', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-016', 'c', 'Réimmerger la victime', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-016', 'd', 'La laisser se reposer seule', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-017', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'conduite-à-tenir-et-cadre-réglementaire-du-secours', 'Quels numéros alerter en France en cas d''accident de plongée ?', 'On alerte le 15 (SAMU) ou le 196 (CROSS pour le secours en mer), qui coordonne l''évacuation vers un caisson hyperbare. On transmet le profil de plongée pour orienter la prise en charge.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-017', 'a', 'Le 15 (SAMU) ou le 196 (CROSS pour le secours en mer)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-017', 'b', 'Le 17 uniquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-017', 'c', 'Le 118', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-017', 'd', 'Aucun, on gère seul', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-018', 'n4-accidents', 'n4', 'physiologie', 'vrai-faux', 'conduite-à-tenir-et-cadre-réglementaire-du-secours', 'On ne réimmerge jamais un accidenté de plongée.', 'Vrai : la réimmersion est un interdit absolu, elle aggrave l''état de la victime et le risque de noyade. On sort la victime, on oxygène, on allonge, on alerte et on surveille.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-018', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-018', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-019', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'conduite-à-tenir-et-cadre-réglementaire-du-secours', 'Que doit contenir le matériel de secours imposé au directeur de plongée par le Code du sport ?', 'Le Code du sport impose un moyen d''alerte et un plan de secours, une oxygénothérapie de capacité adaptée avec masque et détendeur, de l''eau douce non gazeuse, une couverture isothermique, une trousse de secours et une fiche d''évacuation. La rapidité de l''oxygène et de l''alerte conditionne le pronostic.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-019', 'a', 'Moyen d''alerte, oxygénothérapie, eau douce, couverture isothermique, trousse de secours, fiche d''évacuation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-019', 'b', 'Uniquement une trousse de premiers soins', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-019', 'c', 'Seulement un téléphone', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-019', 'd', 'Rien n''est imposé', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-020', 'n4-accidents', 'n4', 'physiologie', 'qcm', 'laccident-de-désaturation--cinétique-des-bulles', 'Quels facteurs favorisent l''accident de désaturation ?', 'Les facteurs favorisants cumulent leurs effets : profondeur et durée importantes, remontée rapide, paliers écourtés, effort et froid, déshydratation, foramen ovale perméable, avion ou altitude trop tôt. Le guide les réduit en planifiant prudemment.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-020', 'a', 'Profondeur/durée, remontée rapide, palier omis, effort, froid, déshydratation, FOP, avion précoce', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-020', 'b', 'Une bonne hydratation et un profil prudent', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-020', 'c', 'Un palier de principe systématique', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-020', 'd', 'Une remontée lente et contrôlée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-021', 'n4-accidents', 'n4', 'physiologie', 'vrai-faux', 'lœdème-pulmonaire-dimmersion', 'L''œdème pulmonaire d''immersion touche plus volontiers le plongeur d''un certain âge ou hypertendu, en eau froide.', 'Vrai : l''OPI est plus fréquent chez le plongeur âgé ou hypertendu et en eau froide. La prévention passe par un bilan cardiologique au moindre doute, en évitant surlestage et surmenage.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-021', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-021', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-001', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'cadre-de-validité-et-arrondis', 'Que représente la DTR d''une plongée ?', 'La DTR est la durée totale de remontée, comprenant la remontée, les paliers et les inter-paliers. Elle sert à calculer l''heure de sortie à partir du début de la remontée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-001', 'a', 'La durée totale de remontée : remontée + paliers + inter-paliers', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-001', 'b', 'La durée de la plongée au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-001', 'c', 'La profondeur maximale atteinte', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-001', 'd', 'Le groupe de plongée successive', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-002', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'plongée-simple--lecture-complète', 'Plongée à 28 m pendant 25 min. Quels arrondis de table ?', 'On arrondit toujours au-dessus : 28 m → table 30 m, 25 min reste sur la ligne 25 min. La table 30 m / 25 min donne un palier de 9 min à 3 m et un GPS G.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-002', 'a', 'Table 30 m, ligne 25 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-002', 'b', 'Table 28 m, ligne 25 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-002', 'c', 'Table 25 m, ligne 25 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-002', 'd', 'Table 30 m, ligne 30 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-003', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'plongée-simple--lecture-complète', 'Table 30 m / 25 min : palier de 9 min à 3 m, immersion à 10 h 00, remontée à 10 h 25. Heure de sortie approximative ?', 'DTR ≈ remontée de 28 à 3 m (≈ 1,7 min) + 9 min de palier + retour surface (≈ 0,5 min) ≈ 11 min ; heure de sortie = 10 h 25 + 11 min = 10 h 36. On part toujours du début de la remontée pour ajouter la DTR.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-003', 'a', '≈ 10 h 36', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-003', 'b', '≈ 10 h 25', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-003', 'c', '≈ 10 h 45', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-003', 'd', '≈ 11 h 00', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-004', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'plongée-simple--lecture-complète', 'Quel est le GPS d''une plongée à 20 m pendant 30 min ?', 'La table 20 m / 30 min donne un GPS F, sans palier obligatoire. Le GPS code l''azote résiduel utilisé pour une éventuelle plongée successive.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-004', 'a', 'F', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-004', 'b', 'G', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-004', 'c', 'H', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-004', 'd', 'E', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-005', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'cadre-de-validité-et-arrondis', 'Comment s''arrondissent l''azote résiduel et la profondeur de la seconde plongée au tableau III ?', 'L''azote résiduel et la profondeur de successive s''arrondissent à la valeur immédiatement supérieure du tableau III, dans le sens de la sécurité. Seul l''intervalle de surface s''arrondit vers le bas.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-005', 'a', 'À la valeur immédiatement supérieure', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-005', 'b', 'À la valeur immédiatement inférieure', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-005', 'c', 'À la valeur la plus proche', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-005', 'd', 'On n''arrondit pas', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-006', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'plongées-successives--méthode-des-deux-tableaux', 'Première plongée 30 m / 25 min (GPS G), intervalle 2 h 30. À quel intervalle lit-on le tableau II ?', '150 min s''arrondit à la valeur immédiatement inférieure du tableau II, soit 120 min. Cet arrondi de l''intervalle vers le bas va dans le sens de la sécurité.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-006', 'a', '120 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-006', 'b', '150 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-006', 'c', '180 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-006', 'd', '90 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-007', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'plongées-successives--méthode-des-deux-tableaux', 'GPS G, intervalle 120 min : azote résiduel 0,94. Seconde plongée à 20 m. Quelle majoration au tableau III ?', 'On arrondit 0,94 à la ligne 0,95 et on croise la profondeur 20 m : majoration = 11 min. Cette majoration, temps fictif, s''ajoute à la durée réelle pour lire la table de la seconde plongée.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-007', 'a', '11 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-007', 'b', '15 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-007', 'c', '6 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-007', 'd', '20 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-008', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'plongées-successives--méthode-des-deux-tableaux', 'Seconde plongée à 20 m, durée réelle 30 min, majoration 11 min. Quelle table et quel palier ?', 'Durée fictive = 30 + 11 = 41 min, arrondie à la table 20 m / 45 min : palier de 4 min à 3 m, GPS I. La majoration sert à lire la table, mais ne compte ni dans l''air ni dans l''heure de sortie réelle.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-008', 'a', 'Table 20 m / 45 min : 4 min à 3 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-008', 'b', 'Table 20 m / 30 min : aucun palier', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-008', 'c', 'Table 20 m / 11 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-008', 'd', 'Table 20 m / 41 min : 9 min à 3 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-009', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'plongées-successives--méthode-des-deux-tableaux', 'Quelle est la bonne séquence de calcul d''une successive ?', 'On lit le GPS (table I), l''azote résiduel (tableau II, intervalle arrondi en dessous), la majoration (tableau III, arrondis au-dessus), puis la table I avec la durée réelle plus la majoration. La majoration s''ajoute, elle ne se soustrait jamais.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-009', 'a', 'GPS → tableau II (intervalle en dessous) → azote résiduel → tableau III (au-dessus) → majoration → table I (durée réelle + majoration)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-009', 'b', 'Table I directement avec la durée réelle', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-009', 'c', 'Tableau III → tableau II → GPS', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-009', 'd', 'GPS → majoration soustraite de la durée réelle', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-010', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'procédures-de-rattrapage', 'Comment traite-t-on une plongée consécutive (intervalle inférieur à 15 min) ?', 'En consécutive, les deux immersions comptent pour une seule : durée = somme des durées, profondeur = maximale des deux. Les tissus n''ayant presque rien restitué en moins de 15 min, on ne passe pas par les tableaux II et III.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-010', 'a', 'Durée = somme des durées, profondeur = maximale des deux', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-010', 'b', 'Comme deux plongées simples', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-010', 'c', 'Avec le tableau III', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-010', 'd', 'On additionne les profondeurs', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-011', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'procédures-de-rattrapage', 'Plongée à 30 m ; à la 20e minute, remontée incontrôlée en surface, redescente en 1 min à 15 m puis 5 min. Quelle durée et quelle table ?', 'Durée retenue = 20 + 1 + 5 = 26 min, arrondie à la table 30 m / 30 min : palier de 17 min à 3 m, GPS H. On redescend à la mi-profondeur (15 m) dans les 3 min et on y reste 5 min, toute la palanquée.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-011', 'a', '26 min → table 30 m / 30 min', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-011', 'b', '20 min → table 30 m / 20 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-011', 'c', '5 min → table 15 m / 5 min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-011', 'd', '25 min → table 30 m / 25 min', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-012', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'procédures-de-rattrapage', 'Que faire d''un palier interrompu (plongeur envoyé en surface) ?', 'On redescend dans les 3 minutes à la profondeur du palier et on le recommence intégralement, le temps déjà fait étant perdu. Un palier interrompu non rattrapé est une décompression incomplète.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-012', 'a', 'Redescendre dans les 3 min à la profondeur du palier et le recommencer intégralement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-012', 'b', 'Reprendre là où il s''est arrêté', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-012', 'c', 'Supprimer le reste du palier', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-012', 'd', 'Descendre au fond', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-013', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'vrai-faux', 'procédures-de-rattrapage', 'En cas de remontée lente, le temps de remontée s''ajoute à la durée de plongée.', 'Vrai : le temps de remontée lente s''ajoute à la durée de plongée jusqu''à la reprise d''une vitesse normale, et la profondeur retenue reste la profondeur maximale. Ignorer ce temps sous-estimerait la charge en azote.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-013', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-013', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-014', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'la-plongée-en-altitude', 'Pourquoi la plongée en altitude est-elle plus exigeante en décompression ?', 'En altitude, la pression atmosphérique est inférieure à 1 bar : à la sortie, le gradient de sursaturation est plus grand pour une même profondeur réelle, donc le risque d''ADD augmente. Les tables MN90, bâties pour 1 bar de surface, ne se lisent pas avec la profondeur réelle.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-014', 'a', 'La pression de surface est réduite, donc la sursaturation à la sortie est plus forte à profondeur réelle égale', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-014', 'b', 'La pression de surface est plus élevée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-014', 'c', 'L''eau est plus dense', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-014', 'd', 'L''azote se dissout moins', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-015', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'la-plongée-en-altitude', 'À 2000 m d''altitude (P ≈ 0,8 bar), à quelle profondeur fictive correspond une plongée réelle à 20 m ?', '$profondeur_{fictive}=profondeur_{réelle}\times P_{mer}/P_{altitude}=20\times 1/0{,}8=25$ m. On lit alors la table à 25 m, nettement plus exigeante que la lecture directe à 20 m.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-015', 'a', '≈ 25 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-015', 'b', '≈ 16 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-015', 'c', '≈ 20 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-015', 'd', '≈ 40 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-016', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'notions-de-nitrox-et-de-désaturation', 'Quel est l''effet du nitrox sur la décompression, à profondeur et durée égales ?', 'Le nitrox réduit la fraction d''azote respirée : à profondeur égale la $P_pN_2$ est plus faible, les tissus se chargent moins et le temps sans palier s''allonge. La contrepartie est la limite d''hyperoxie qui impose une profondeur maximale.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-016', 'a', 'Moins d''azote respiré, donc désaturation facilitée et temps sans palier allongé', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-016', 'b', 'Plus d''azote, donc paliers rallongés', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-016', 'c', 'Aucun effet sur la décompression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-016', 'd', 'Il supprime tout palier quelle que soit la profondeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-017', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'vrai-faux', 'notions-de-nitrox-et-de-désaturation', 'L''emploi du nitrox relève d''une qualification spécifique.', 'Vrai : les procédures nitrox (tables nitrox ou profondeur équivalente air, limite d''hyperoxie) relèvent d''une qualification spécifique. Le Niveau 4 en retient le principe : moins d''azote respiré, désaturation facilitée, au prix d''une contrainte oxygène.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-017', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-017', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-018', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'méthode-dexamen--enchaîner-sans-erreur', 'Quelle discipline évite les erreurs dans un problème d''examen multi-plongées ?', 'On pose d''abord un schéma de profil, on traite chaque plongée dans l''ordre chronologique en notant profondeur, durée, paliers, DTR, GPS et heures, on vérifie chaque arrondi et on ne mélange jamais durée réelle et durée fictive. C''est sur les arrondis que se perdent les points.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-018', 'a', 'Poser un schéma de profil, traiter chaque plongée dans l''ordre, vérifier chaque arrondi, ne pas mélanger durée réelle et fictive', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-018', 'b', 'Calculer tout de tête sans écrire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-018', 'c', 'Traiter les plongées dans le désordre', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-018', 'd', 'Ignorer les arrondis', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-019', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'calcul', 'plongée-simple--lecture-complète', 'Plongée à 40 m pendant 15 min. Quels paliers donne la table du site ?', 'La table 40 m / 15 min donne un palier de 7 min à 3 m, GPS F. À 40 m les paliers apparaissent tôt : dès 10 min il y a déjà 2 min à 3 m.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-019', 'a', '7 min à 3 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-019', 'b', '2 min à 3 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-019', 'c', 'aucun palier', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-019', 'd', '5 min à 6 m et 19 min à 3 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-020', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'vrai-faux', 'méthode-dexamen--enchaîner-sans-erreur', 'La majoration entre dans le calcul de décompression mais ne compte ni dans l''air consommé ni dans l''heure de sortie réelle.', 'Vrai : la majoration est un temps fictif servant uniquement à lire la table de la seconde plongée. Elle ne se comptabilise ni dans l''air réellement consommé ni dans l''heure de sortie.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-020', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-020', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-021', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'qcm', 'cadre-de-validité-et-arrondis', 'Combien de plongées par 24 h les tables MN90 autorisent-elles au maximum ?', 'Les tables MN90 sont valides pour deux plongées par 24 h au maximum, à l''air et au niveau de la mer, jusqu''à 60 m. Au-delà de deux plongées, on sort du cadre de validité des tables.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-021', 'a', 'Deux', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-021', 'b', 'Trois', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-021', 'c', 'Une seule', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-021', 'd', 'Illimité', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-001', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'le-cadre--code-du-sport-et-rôles', 'Quel est le rôle du directeur de plongée (DP) ?', 'Le directeur de plongée organise l''activité, constitue les palanquées, désigne les guides, définit les paramètres, assure la sécurité surface et déclenche les secours. Il est présent sur le site pendant toute l''activité.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-001', 'a', 'Organiser l''activité, constituer les palanquées, fixer les paramètres, assurer la sécurité surface et déclencher les secours', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-001', 'b', 'Guider une seule palanquée en immersion', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-001', 'c', 'Enseigner obligatoirement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-001', 'd', 'Piloter le bateau uniquement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-002', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'le-cadre--code-du-sport-et-rôles', 'Quel est le niveau minimal du directeur de plongée en exploration ?', 'En exploration, le DP est au minimum Niveau 5 (ou équivalent) ; en enseignement, il est au minimum E3 (moniteur). Le DP a autorité sur l''ensemble de la plongée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-002', 'a', 'Niveau 5 (ou équivalent)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-002', 'b', 'Niveau 3', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-002', 'c', 'Niveau 4', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-002', 'd', 'MF1 obligatoirement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-003', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'composition-des-palanquées-et-espaces-dévolution', 'Combien de plongeurs compte au maximum une palanquée encadrée (hors guide) ?', 'Une palanquée encadrée compte au maximum 4 plongeurs encadrés, hors guide. Une palanquée autonome en compte au maximum 3. Le guide adapte toujours à la baisse selon les conditions.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-003', 'a', '4', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-003', 'b', '3', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-003', 'c', '5', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-003', 'd', '2', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-004', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'composition-des-palanquées-et-espaces-dévolution', 'Combien de plongeurs compte au maximum une palanquée autonome ?', 'Une palanquée autonome compte au maximum 3 plongeurs. La conformité réglementaire est un plafond, pas un objectif : le guide réduit l''effectif selon la visibilité, le courant ou l''expérience réelle.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-004', 'a', '3', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-004', 'b', '4', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-004', 'c', '2', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-004', 'd', '5', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-005', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'composition-des-palanquées-et-espaces-dévolution', 'Quelle est la profondeur maximale de la plongée à l''air en France ?', 'La profondeur maximale de la plongée à l''air en exploration est de 60 m. Elle correspond à l''espace d''évolution 0-60 m, où les PA60 plongent en autonomie et les PE60 sont encadrés par un moniteur.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-005', 'a', '60 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-005', 'b', '40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-005', 'c', '50 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-005', 'd', '70 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-006', 'n4-reglementation', 'n4', 'reglementation', 'vrai-faux', 'composition-des-palanquées-et-espaces-dévolution', 'La composition d''une palanquée dépend des aptitudes de ses membres et de l''espace d''évolution.', 'Vrai : la composition suit les aptitudes (PE, PA suivis de la profondeur) et l''espace d''évolution (0-6, 0-20, 0-40, 0-60 m). Le guide adapte toujours à la baisse aux conditions réelles.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-006', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-006', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-007', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'documents-obligatoires-et-aptitude-médicale', 'Quels documents un plongeur doit-il pouvoir justifier ?', 'Chaque plongeur doit justifier de son aptitude (brevet ou attestation de niveau), de sa licence fédérale et d''un certificat médical à jour. Le guide s''assure avant l''immersion que chaque membre dispose des documents requis.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-007', 'a', 'Brevet ou attestation de niveau, licence, certificat médical à jour', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-007', 'b', 'Uniquement la licence', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-007', 'c', 'Seulement le carnet de plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-007', 'd', 'Aucun document', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-008', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'matériel-obligatoire-des-plongeurs-et-de-la-sécurité', 'Quel matériel supplémentaire distingue le plongeur autonome de l''encadré ?', 'Le plongeur autonome doit disposer de deux sorties de bloc indépendantes et de deux détendeurs complets (second étage de secours), et la palanquée d''un parachute de palier. L''encadré n''a pas cette obligation de redondance.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-008', 'a', 'Deux sorties de bloc indépendantes et deux détendeurs complets, plus un parachute par palanquée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-008', 'b', 'Une simple lampe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-008', 'c', 'Un tuba plus long', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-008', 'd', 'Aucune différence', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-009', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'matériel-obligatoire-des-plongeurs-et-de-la-sécurité', 'Que comprend la sécurité surface sous la responsabilité du DP ?', 'La sécurité surface comprend un plan de secours et un moyen d''alerte, une trousse de secours, une oxygénothérapie de capacité adaptée, de l''eau douce non gazeuse, une couverture isothermique et une fiche d''évacuation. Ce dispositif conditionne la légalité de la sortie.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-009', 'a', 'Plan de secours et moyen d''alerte, trousse, oxygénothérapie, eau douce, couverture isothermique, fiche d''évacuation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-009', 'b', 'Uniquement un téléphone', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-009', 'c', 'Seulement une bouée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-009', 'd', 'Rien de particulier', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-010', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'responsabilité-civile-et-pénale', 'Que vise la responsabilité civile ?', 'La responsabilité civile vise à réparer un dommage causé à autrui, par une indemnisation versée en pratique par l''assurance. La licence fédérale inclut une assurance en responsabilité civile.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-010', 'a', 'Réparer un dommage causé à autrui, via une indemnisation (couverte par l''assurance)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-010', 'b', 'Sanctionner une infraction par une peine', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-010', 'c', 'Retirer le brevet', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-010', 'd', 'Interdire la plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-011', 'n4-reglementation', 'n4', 'reglementation', 'vrai-faux', 'responsabilité-civile-et-pénale', 'L''assurance ne couvre jamais les sanctions pénales.', 'Vrai : l''assurance prend en charge la réparation civile (indemnisation) mais jamais les sanctions pénales, qui sont personnelles. Assurance n''égale pas irresponsabilité : encadrer impose la rigueur.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-011', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-011', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-012', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'lobligation-de-moyens', 'Quelle est la nature de l''obligation qui pèse sur le guide de palanquée ?', 'Le guide est tenu d''une obligation de moyens, non de résultat : il ne garantit pas l''absence d''accident (l''activité comporte des risques), mais il doit mettre en œuvre tous les moyens raisonnables de sécurité. On apprécie la conformité de sa conduite aux règles de l''art.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-012', 'a', 'Une obligation de moyens : mettre en œuvre tous les moyens raisonnables de sécurité', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-012', 'b', 'Une obligation de résultat : garantir qu''aucun accident ne survienne', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-012', 'c', 'Aucune obligation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-012', 'd', 'Une obligation de moyens uniquement en enseignement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-013', 'n4-reglementation', 'n4', 'reglementation', 'vrai-faux', 'lobligation-de-moyens', 'Respecter le cadre réglementaire et les bonnes pratiques est à la fois un devoir de sécurité et une protection juridique.', 'Vrai : briefing, vérification du matériel et des niveaux, choix de paramètres adaptés et surveillance continue assurent la sécurité et prouvent la diligence. À l''inverse, une faute caractérisée expose pleinement l''encadrant.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-013', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-013', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-014', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'le-cadre--code-du-sport-et-rôles', 'Quel est le niveau minimal du directeur de plongée en enseignement ?', 'En enseignement, le DP est au minimum E3 (moniteur : MF1, BEES1 ou équivalent), alors qu''en exploration il est au minimum Niveau 5. Le niveau requis dépend donc de la nature de l''activité.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-014', 'a', 'E3 (moniteur, MF1/BEES1 ou équivalent)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-014', 'b', 'Niveau 4', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-014', 'c', 'Niveau 5', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-014', 'd', 'Niveau 3', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-015', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'composition-des-palanquées-et-espaces-dévolution', 'Qu''est-ce qu''une palanquée ?', 'Une palanquée est un groupe de plongeurs qui évoluent ensemble, à des paramètres identiques, et ne se quittent pas. Sa composition dépend des aptitudes et de l''espace d''évolution.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-015', 'a', 'Un groupe de plongeurs évoluant ensemble, à des paramètres identiques, qui ne se quittent pas', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-015', 'b', 'L''ensemble des plongeurs d''un club', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-015', 'c', 'Un plongeur seul et son matériel', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-015', 'd', 'Le bateau et son équipage', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-regl-016', 'n4-reglementation', 'n4', 'reglementation', 'qcm', 'responsabilité-civile-et-pénale', 'Qu''est-ce que la responsabilité pénale sanctionne ?', 'La responsabilité pénale sanctionne une infraction (mise en danger d''autrui, blessures ou homicide involontaires) par des peines personnelles (amende, voire emprisonnement). Elle peut viser le guide, le DP ou l''organisateur et n''est pas assurable.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-016', 'a', 'Une infraction à la loi (mise en danger, blessures ou homicide involontaires), par une peine personnelle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-016', 'b', 'Un dommage réparé par indemnisation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-016', 'c', 'Un simple manquement administratif sans conséquence', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-regl-016', 'd', 'La perte de matériel', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-001', 'n4-materiel', 'n4', 'materiel', 'qcm', 'le-détendeur--principe-de-la-détente-en-deux-étages', 'Comment un détendeur réduit-il la pression de l''air ?', 'Le premier étage abaisse la haute pression du bloc à une moyenne pression fixe au-dessus de l''ambiante ; le second étage l''abaisse à la pression ambiante, seulement quand le plongeur inspire (détente à la demande). Cette réduction se fait en deux étapes reliées par un tuyau moyenne pression.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-001', 'a', 'En deux étages : 1er étage HP bloc → moyenne pression, 2e étage → pression ambiante à la demande', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-001', 'b', 'En un seul étage direct', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-001', 'c', 'En chauffant l''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-001', 'd', 'En comprimant l''air', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-002', 'n4-materiel', 'n4', 'materiel', 'qcm', 'le-détendeur--principe-de-la-détente-en-deux-étages', 'À quelle pression le détendeur délivre-t-il l''air au plongeur ?', 'Le détendeur délivre l''air à la pression ambiante, donc de plus en plus dense en profondeur (Mariotte). L''effort ventilatoire augmente avec la profondeur, d''où l''intérêt d''un détendeur performant pour limiter l''essoufflement.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-002', 'a', 'À la pression ambiante, donc de plus en plus dense en profondeur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-002', 'b', 'À la pression du bloc', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-002', 'c', 'À 1 bar constant quelle que soit la profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-002', 'd', 'À la moyenne pression', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-003', 'n4-materiel', 'n4', 'materiel', 'qcm', 'premier-étage--piston-et-membrane', 'Quel est l''avantage d''un premier étage à membrane sur un premier étage à piston ?', 'Le premier étage à membrane interpose une membrane souple entre l''eau et le mécanisme, ce qui protège du froid, du sable et de la corrosion — un atout en eau froide ou chargée. Le piston, lui, est robuste et simple mais expose des pièces au contact de l''eau.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-003', 'a', 'La membrane isole le mécanisme de l''eau, protégeant du froid, du sable et de la corrosion', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-003', 'b', 'Il est toujours moins cher', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-003', 'c', 'Il délivre plus de pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-003', 'd', 'Il ne nécessite aucun entretien', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-004', 'n4-materiel', 'n4', 'materiel', 'qcm', 'compensé-ou-non--leffet-de-la-pression-du-bloc', 'Quel est l''intérêt d''un premier étage compensé ?', 'Sur un premier étage compensé, la pression du bloc s''exerce de façon équilibrée sur le clapet : la moyenne pression reste stable du début à la fin de la plongée et à toute profondeur. Le plongeur bénéficie d''un débit et d''un confort constants, précieux en plongée profonde et par froid.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-004', 'a', 'La moyenne pression reste stable quelle que soit la pression du bloc et la profondeur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-004', 'b', 'Il augmente la pression du bloc', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-004', 'c', 'Il supprime le second étage', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-004', 'd', 'Il refroidit l''air', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-005', 'n4-materiel', 'n4', 'materiel', 'vrai-faux', 'compensé-ou-non--leffet-de-la-pression-du-bloc', 'Sur un premier étage non compensé, le confort respiratoire change entre un bloc plein et un bloc presque vide.', 'Vrai : sur un premier étage non compensé, la haute pression du bloc agit sur le clapet dans un sens qui varie avec la pression du bloc, donc la moyenne pression dérive légèrement à mesure que le bloc se vide. Le compensé supprime cette dérive.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-005', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-005', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-006', 'n4-materiel', 'n4', 'materiel', 'qcm', 'bloc-robinetterie-et-réglementation', 'Quelles obligations réglementaires pèsent sur un bloc de plongée ?', 'Le bloc est un équipement sous pression soumis à une épreuve hydraulique périodique (requalification par un organisme agréé) et à une inspection visuelle annuelle par un TIV habilité. Un bloc hors validité ne doit pas être gonflé.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-006', 'a', 'Épreuve hydraulique périodique (requalification) et inspection visuelle annuelle par un TIV', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-006', 'b', 'Aucune, s''il fonctionne', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-006', 'c', 'Un simple rinçage annuel', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-006', 'd', 'Un changement de robinet tous les ans', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-007', 'n4-materiel', 'n4', 'materiel', 'vrai-faux', 'bloc-robinetterie-et-réglementation', 'Un bloc dont la validité d''épreuve ou de TIV est dépassée ne doit pas être gonflé.', 'Vrai : un bloc hors validité d''épreuve ou de TIV est interdit au gonflage. Le guide vérifie la validité du bloc avant emploi, et ne plonge jamais avec une robinetterie ou un marquage douteux.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-007', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-007', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-008', 'n4-materiel', 'n4', 'materiel', 'qcm', 'compresseur-et-filtration', 'Pourquoi un compresseur comprime-t-il l''air en plusieurs étages ?', 'La compression échauffe l''air : on procède par étages successifs, chaque étage suivi d''un refroidisseur et d''un purgeur qui évacue eau et huile condensées. On passe ainsi de la pression atmosphérique à 200-300 bar de façon plus efficace et moins chaude.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-008', 'a', 'Parce que la compression échauffe l''air ; des étages avec refroidisseurs sont plus efficaces et moins chauds qu''une compression unique', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-008', 'b', 'Pour aller moins vite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-008', 'c', 'Pour ajouter de l''oxygène', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-008', 'd', 'Pour économiser les filtres', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-009', 'n4-materiel', 'n4', 'materiel', 'qcm', 'compresseur-et-filtration', 'Où doit être placée la prise d''air d''un compresseur ?', 'La prise d''air doit être placée au vent, loin de tout échappement, car aspirer des gaz d''échappement contaminerait l''air en monoxyde de carbone — cause d''intoxication grave. Une cartouche de filtration retient eau, huile et vapeurs en fin de chaîne.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-009', 'a', 'Au vent, loin de tout échappement de moteur', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-009', 'b', 'Près du moteur pour gagner de la place', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-009', 'c', 'Sous le compresseur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-009', 'd', 'Peu importe', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-010', 'n4-materiel', 'n4', 'materiel', 'qcm', 'instruments-et-matériel-obligatoire', 'Quel instrument permet le contrôle permanent de l''air restant dans le bloc ?', 'Le manomètre indique la pression restante du bloc, permettant le contrôle permanent de l''air. Le profondimètre et la montre (ou l''ordinateur) gèrent la profondeur, le temps et la décompression.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-010', 'a', 'Le manomètre', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-010', 'b', 'La boussole', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-010', 'c', 'Le profondimètre', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-010', 'd', 'Le parachute de palier', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-011', 'n4-materiel', 'n4', 'materiel', 'vrai-faux', 'instruments-et-matériel-obligatoire', 'Le parachute de palier est obligatoire à raison d''un par palanquée en autonomie.', 'Vrai : le parachute de palier, qui signale et sécurise la remontée, est obligatoire à raison d''un par palanquée en autonomie. Le guide vérifie que sa palanquée en est équipée avant l''immersion.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-011', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-011', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-mat-012', 'n4-materiel', 'n4', 'materiel', 'qcm', 'le-détendeur--principe-de-la-détente-en-deux-étages', 'À quoi sert le bouton de surface (ou de purge) du second étage ?', 'Le bouton de surface (ou de purge) permet d''ouvrir manuellement le clapet du second étage pour libérer de l''air, par exemple pour purger l''eau. En fonctionnement normal, c''est la dépression de l''inspiration qui bascule le levier et ouvre le clapet.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-012', 'a', 'À ouvrir manuellement le clapet pour libérer de l''air', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-012', 'b', 'À gonfler le gilet', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-012', 'c', 'À régler la moyenne pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-mat-012', 'd', 'À mesurer la profondeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-001', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'le-rôle-du-guide-de-palanquée', 'Quelle est la mission prioritaire du guide de palanquée, dans l''ordre ?', 'La mission du guide tient en trois mots dans cet ordre : sécurité, plaisir, découverte. Il encadre l''exploration sous l''autorité du directeur de plongée et adapte le projet au plus faible du groupe et aux conditions réelles.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-001', 'a', 'Sécurité, plaisir, découverte', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-001', 'b', 'Découverte, plaisir, sécurité', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-001', 'c', 'Plaisir, découverte, sécurité', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-001', 'd', 'Performance, profondeur, records', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-002', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'le-briefing-type', 'Que couvre un briefing de palanquée complet ?', 'Un briefing complet couvre le site et le parcours, les paramètres et la décompression, la gestion de l''air, les signes, la sécurité (perte, assistance, remontée), les binômes et l''organisation. Il se termine par la vérification mutuelle du matériel : on ne se met à l''eau qu''après ce contrôle.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-002', 'a', 'Site et parcours, paramètres et déco, gestion de l''air, signes, sécurité, binômes, vérification mutuelle du matériel', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-002', 'b', 'Uniquement la profondeur maximale', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-002', 'c', 'Seulement les points d''intérêt', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-002', 'd', 'La météo du lendemain', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-003', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'gérer-lair-dune-palanquée', 'Sur quel plongeur le guide raisonne-t-il pour gérer l''air de la palanquée ?', 'Le guide raisonne sur le plus gros consommateur et le plus petit bloc, pas sur lui-même. Il fixe une pression de demi-tour pour que chacun rentre avec sa réserve et déclenche le retour sur le premier qui atteint le seuil.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-003', 'a', 'Le plus gros consommateur et le plus petit bloc', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-003', 'b', 'Lui-même', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-003', 'c', 'Le plus économe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-003', 'd', 'La moyenne du groupe', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-004', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'gérer-lair-dune-palanquée', 'En quoi consiste la règle des tiers en exploration ?', 'La règle des tiers réserve un tiers de l''air pour l''aller, un tiers pour le retour et un tiers de réserve, particulièrement adaptée quand le retour se fait par le même chemin. Le guide déclenche le demi-tour sur le premier qui atteint le seuil.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-004', 'a', '1/3 de l''air pour l''aller, 1/3 pour le retour, 1/3 de réserve', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-004', 'b', '1/2 aller, 1/2 retour', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-004', 'c', 'Tout l''air pour l''exploration', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-004', 'd', '1/3 réserve, 2/3 aller', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-005', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'orientation-et-surveillance-en-immersion', 'Quels moyens le guide combine-t-il pour orienter la palanquée ?', 'Le guide combine la boussole (cap aller et retour), les repères naturels (relief, sable ridé, tombant, lumière, courant), la profondeur et le temps. Il adapte le parcours pour finir la plongée face au point de sortie, avec l''air et la déco compatibles.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-005', 'a', 'Boussole (cap aller/retour), repères naturels, profondeur et temps', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-005', 'b', 'Uniquement la chance', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-005', 'c', 'Seulement le GPS de surface', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-005', 'd', 'La couleur de l''eau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-006', 'n4-guide-palanquee', 'n4', 'environnement', 'vrai-faux', 'orientation-et-surveillance-en-immersion', 'Le guide maintient sa palanquée rassemblée, car un équipier isolé est un équipier en danger.', 'Vrai : le guide surveille en permanence, compte régulièrement ses équipiers et maintient le groupe rassemblé. Il ralentit ou remonte à la moindre difficulté (essoufflement, froid, stress, problème de matériel).', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-006', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-006', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-007', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'sécurité-surface-et-remontée-protégée', 'Comment le guide protège-t-il la remontée de sa palanquée ?', 'Le guide protège la remontée en envoyant un parachute de palier depuis le fond ou le palier, qui signale la palanquée aux embarcations et matérialise l''axe de remontée. On remonte en tournant sur soi et en levant la tête, car sous l''eau on entend un bateau sans pouvoir le localiser.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-007', 'a', 'En envoyant un parachute de palier qui signale la palanquée et matérialise l''axe de remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-007', 'b', 'En remontant le plus vite possible', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-007', 'c', 'En se fiant à l''oreille pour situer les bateaux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-007', 'd', 'En dispersant les plongeurs', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-008', 'n4-guide-palanquee', 'n4', 'environnement', 'vrai-faux', 'sécurité-surface-et-remontée-protégée', 'Le guide n''est déchargé de sa responsabilité qu''une fois toute la palanquée à bord ou à terre en sécurité.', 'Vrai : les derniers mètres et la surface concentrent les risques (bateaux, houle, fatigue). Le guide regroupe et signale son groupe en surface, compte à nouveau ses équipiers et ne relâche sa vigilance qu''une fois tout le monde en sécurité.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-008', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-008', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-009', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'matelotage-météo-et-marées', 'Quand le courant de marée est-il le plus faible ?', 'Le courant de marée est le plus fort à mi-marée et faible aux étales (de pleine mer et de basse mer), moments souvent choisis pour plonger en sécurité. Le coefficient de marée renseigne sur l''amplitude et donc l''intensité des courants.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-009', 'a', 'Aux étales de pleine mer et de basse mer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-009', 'b', 'À mi-marée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-009', 'c', 'Toujours au maximum', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-009', 'd', 'Il ne varie jamais', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-010', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'matelotage-météo-et-marées', 'Que signale le pavillon Alpha ?', 'Le pavillon Alpha (ou pavillon de plongée) signale des plongeurs immergés et impose aux navires de s''écarter et de réduire leur vitesse. Le guide connaît cette signalisation liée à la plongée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-010', 'a', 'La présence de plongeurs immergés, imposant aux navires de s''écarter et de réduire leur vitesse', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-010', 'b', 'Un danger de tempête', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-010', 'c', 'La fin de la plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-010', 'd', 'Un mouillage interdit', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-011', 'n4-guide-palanquee', 'n4', 'environnement', 'qcm', 'matelotage-météo-et-marées', 'Comment organiser une plongée dérivante par rapport au courant ?', 'On organise la plongée pour éviter de lutter contre le courant au retour : descendre face au courant, revenir porté par lui. Lutter contre le courant au retour, fatigué et à court d''air, est un piège classique.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-011', 'a', 'Descendre face au courant et revenir porté par lui', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-011', 'b', 'Descendre porté et revenir face au courant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-011', 'c', 'Ignorer le courant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-011', 'd', 'Plonger toujours à mi-marée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-gp-012', 'n4-guide-palanquee', 'n4', 'environnement', 'vrai-faux', 'le-rôle-du-guide-de-palanquée', 'Le guide de palanquée est un encadrant d''exploration, il n''enseigne pas.', 'Vrai : le guide conduit un groupe en exploration, il n''est pas moniteur et n''enseigne pas. Il assure la sécurité, l''orientation, la gestion de l''air et de la décompression du groupe qu''il encadre.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-012', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-gp-012', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-acc-022', 'n4-accidents', 'n4', 'physiologie', 'vrai-faux', 'laccident-de-désaturation--cinétique-des-bulles', 'Un foramen ovale perméable ou un effort à glotte fermée peut artérialiser les bulles veineuses vers le cerveau ou la moelle.', 'Vrai : les bulles veineuses, normalement filtrées par les poumons, peuvent passer en artériel via un foramen ovale perméable ou un effort à glotte fermée. Elles gagnent alors le cerveau ou la moelle et provoquent un ADD neurologique.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-022', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-acc-022', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-tables-022', 'n4-tables-tous-cas', 'n4', 'tables-deco', 'vrai-faux', 'cadre-de-validité-et-arrondis', 'La durée de plongée retenue court de l''immersion jusqu''au début de la remontée à vitesse normale.', 'Vrai : la durée de plongée va de l''immersion au début de la remontée, et la profondeur retenue est la profondeur maximale atteinte. Ces définitions conditionnent la lecture correcte de la table.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-022', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-tables-022', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-flot-020', 'n4-flottabilite-optique-acoustique', 'n4', 'physique', 'vrai-faux', 'le-théorème-darchimède', 'Un corps dont le poids réel est inférieur à la poussée d''Archimède remonte (flottabilité positive).', 'Vrai : si la poussée l''emporte sur le poids réel, le poids apparent est négatif et le corps remonte. S''ils sont égaux il reste entre deux eaux, si le poids l''emporte il coule.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-020', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-flot-020', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('n4-vent-018', 'n4-anatomie-ventilation', 'n4', 'physiologie', 'vrai-faux', 'anatomie-de-lappareil-respiratoire', 'Les voies aériennes de conduction (trachée, bronches) réchauffent, humidifient et filtrent l''air mais ne réalisent aucun échange gazeux.', 'Vrai : les voies de conduction amènent l''air en le réchauffant, l''humidifiant et le filtrant, sans réaliser d''échange. Les échanges gazeux ne commencent qu''au niveau des alvéoles.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-018', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('n4-vent-018', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-001', 'mf1-decompression', 'mf1', 'tables-deco', 'vrai-faux', 'les-compartiments-et-la-saturation-exponentielle', 'La **période** (temps de demi-saturation) d''un compartiment est le temps au bout duquel il comble la moitié de l''écart restant entre sa tension actuelle et la tension qu''il atteindrait à saturation complète.', 'C''est la définition exacte de la période dans le modèle de Haldane : à chaque période, le compartiment comble la moitié du gradient restant, jamais un pourcentage fixe. Un compartiment court (5 min) atteint donc vite l''équilibre, un compartiment long (120 min) le fait lentement.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-001', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-001', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-002', 'mf1-decompression', 'mf1', 'tables-deco', 'qcm', 'les-compartiments-et-la-saturation-exponentielle', 'Selon la lecture par périodes successives du modèle de Haldane, quel pourcentage du gradient un compartiment a-t-il comblé après **3 périodes** ?', 'Après chaque période on comble la moitié du chemin restant : 50 % (1 période), 75 % (2), puis 87,5 % (3). La valeur 93,75 % correspond à 4 périodes et 99 % à environ 6 périodes, seuil de saturation pratiquement complète.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-002', 'a', '75 %', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-002', 'b', '87,5 %', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-002', 'c', '93,75 %', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-002', 'd', '99 %', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-003', 'mf1-decompression', 'mf1', 'tables-deco', 'calcul', 'les-compartiments-et-la-saturation-exponentielle', 'Un plongeur stabilise à 20 m ; la pression partielle d''azote respirée passe d''environ $0{,}8$ bar (surface) à $2{,}4$ bars. Pour le compartiment de **période 20 min**, quelle est la tension d''azote après **40 minutes** (2 périodes) ?', 'Le gradient à combler est $2{,}4 - 0{,}8 = 1{,}6$ bar. Après 2 périodes, 75 % du gradient est comblé : $T = 0{,}8 + 0{,}75 \times 1{,}6 = 2{,}00$ bars. La réponse 1,60 bar correspond à 1 période (50 %), 2,20 bars à 3 périodes (87,5 %) et 2,40 bars à la saturation complète, non atteinte en 40 min.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-003', 'a', '1,60 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-003', 'b', '2,00 bars', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-003', 'c', '2,20 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-003', 'd', '2,40 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-004', 'mf1-decompression', 'mf1', 'tables-deco', 'calcul', 'les-compartiments-et-la-saturation-exponentielle', 'Même situation (compartiment période 20 min, tension initiale $0{,}8$ bar, tension imposée $2{,}4$ bars). Quelle est la tension après **20 minutes** (1 période) ?', 'Après 1 période, le compartiment comble 50 % du gradient de $1{,}6$ bar : $T = 0{,}8 + 0{,}50 \times 1{,}6 = 1{,}60$ bar. On n''ajoute jamais un pourcentage fixe à la tension : on comble la moitié de l''écart restant à chaque période, ce qui donne une progression exponentielle vers 2,40 bars.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-004', 'a', '1,20 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-004', 'b', '1,60 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-004', 'c', '2,00 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-004', 'd', '2,40 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-005', 'mf1-decompression', 'mf1', 'tables-deco', 'qcm', 'le-gradient-et-le-coefficient-de-sursaturation-critique', 'La condition de remontée admissible d''un compartiment s''écrit $T_{N_2} \le Sc \times P_{abs}$. Que représente le coefficient $Sc$ ?', '$Sc$ est le coefficient de sursaturation critique : il fixe la tension d''azote maximale tolérée par un compartiment pour une pression absolue donnée. Il est propre à chaque compartiment (les tissus rapides tolèrent une sursaturation plus forte que les tissus lents), ce qui distingue les modèles modernes du rapport unique 2:1 de Haldane.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-005', 'a', 'La période du compartiment', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-005', 'b', 'Le coefficient de sursaturation critique, propre à chaque compartiment', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-005', 'c', 'La vitesse de remontée en m/min', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-005', 'd', 'La durée totale de remontée (DTR)', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-006', 'mf1-decompression', 'mf1', 'tables-deco', 'calcul', 'le-gradient-et-le-coefficient-de-sursaturation-critique', 'Un compartiment présente une tension d''azote $T_{N_2} = 2{,}4$ bars et un coefficient $Sc = 2{,}0$. Quelle est la **pression absolue minimale** ($P_{abs}^{\min}$) qu''il autorise, et à quelle profondeur cela correspond-il ?', 'On applique $P_{abs}^{\min} = T_{N_2} / Sc = 2{,}4 / 2{,}0 = 1{,}2$ bar. La profondeur correspondante est $(1{,}2 - 1) \times 10 = 2$ m : le compartiment n''autorise donc pas encore la surface, d''où un palier. Le distracteur « 12 m » confond pression relative et profondeur (il faut retrancher la pression atmosphérique avant de convertir).', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-006', 'a', '1,2 bar, soit 2 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-006', 'b', '1,2 bar, soit 12 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-006', 'c', '4,8 bars, soit 38 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-006', 'd', '0,4 bar, soit la surface', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-007', 'mf1-decompression', 'mf1', 'tables-deco', 'qcm', 'compartiment-directeur-et-construction-dune-table', 'Qu''appelle-t-on le **compartiment directeur** (ou pilote) à un instant donné de la remontée ?', 'Le compartiment directeur est celui qui, à cet instant, exige la pression absolue minimale la plus élevée : c''est lui qui commande le palier le plus profond ou le plus long. Ce n''est pas toujours le plus lent : il change au cours de la plongée (tissus rapides pour les plongées courtes et profondes, tissus lents pour les plongées longues).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-007', 'a', 'Le compartiment de plus longue période', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-007', 'b', 'Le compartiment le plus contraignant, qui impose la remontée la moins profonde', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-007', 'c', 'Le compartiment le plus rapide à se désaturer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-007', 'd', 'Le compartiment dont la tension est la plus faible', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-008', 'mf1-decompression', 'mf1', 'tables-deco', 'vrai-faux', 'compartiment-directeur-et-construction-dune-table', 'Pour une plongée courte et profonde, ce sont les **tissus lents** (60, 80, 120 min) qui jouent le rôle de compartiment directeur et imposent les paliers.', 'C''est l''inverse : une plongée courte et profonde charge surtout les tissus rapides (5, 10, 20 min), qui deviennent directeurs et imposent les premiers paliers. Les tissus lents prennent le relais pour les plongées longues, ce qui explique que deux profils de charge en azote différents ne donnent pas les mêmes paliers.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-008', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-008', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-009', 'mf1-decompression', 'mf1', 'tables-deco', 'qcm', 'le-gradient-et-le-coefficient-de-sursaturation-critique', 'Dans sa formulation d''origine, Haldane exprimait la sursaturation tolérée par un **rapport critique**. Quel était ce rapport approximatif ?', 'Haldane admettait qu''un compartiment tolérait une tension d''azote jusqu''à environ **deux fois** la pression absolue ambiante, soit un rapport 2:1. Les modèles ultérieurs ont remplacé ce rapport unique par un coefficient $Sc$ propre à chaque compartiment. Le distracteur 1,6:1 évoque le seuil d''hyperoxie ($P_pO_2 = 1{,}6$), sans rapport avec la décompression.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-009', 'a', '1:1', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-009', 'b', '2:1', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-009', 'c', '3:1', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-009', 'd', '1,6:1', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-010', 'mf1-decompression', 'mf1', 'tables-deco', 'qcm', 'limites-du-modèle-et-apports-modernes', 'Les **M-values** (Workman, puis Bühlmann avec les séries ZH-L), utilisées par la plupart des ordinateurs, remplacent le rapport critique unique par :', 'Les M-values expriment la tension tolérée comme une fonction affine de la pression ambiante, $T_{tol} = a + P_{abs}/b$, avec des coefficients propres à chaque compartiment. C''est la formulation retenue par la plupart des ordinateurs de plongée. Interdire toute sursaturation serait faux : la sursaturation modérée est normale et constitue même le moteur de la désaturation.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-010', 'a', 'une constante identique pour tous les compartiments', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-010', 'b', 'une droite reliant la tension tolérée à la pression ambiante, propre à chaque compartiment ($T_{tol}=a+P_{abs}/b$)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-010', 'c', 'l''interdiction de toute sursaturation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-010', 'd', 'un calcul fondé uniquement sur la profondeur maximale atteinte', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-011', 'mf1-decompression', 'mf1', 'tables-deco', 'vrai-faux', 'limites-du-modèle-et-apports-modernes', 'Le modèle haldanien est un modèle de gaz dissous : il suppose qu''aucune bulle ne se forme tant que la sursaturation critique n''est pas franchie, hypothèse commode mais prise en défaut par les **bulles circulantes silencieuses** observées même après des plongées respectant les tables.', 'Le modèle de gaz dissous ignore la formation de micro-bulles tant que le seuil critique n''est pas atteint, alors que des bulles silencieuses apparaissent en pratique même après une plongée conforme. Il néglige aussi l''asymétrie charge/décharge et des facteurs individuels (froid, effort, FOP), ce qui rappelle que les tables restent une approche statistique prudente, non une garantie.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-011', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-011', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-012', 'mf1-decompression', 'mf1', 'tables-deco', 'qcm', 'enseigner-la-désaturation', 'Pour expliquer la désaturation à un public **N2**, quel niveau d''abstraction le moniteur privilégie-t-il ?', 'À un N2, on reste sur l''image : l''azote se dissout comme le gaz d''une bouteille de soda et il faut remonter lentement pour le laisser s''échapper sans faire mousser. Les compartiments, périodes et la lecture par moitiés successives sont réservés au N4, et les M-values au niveau expert : adapter l''abstraction au public est le cœur du geste pédagogique.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-012', 'a', 'La formule exponentielle complète $T(t)=T_f+(T_0-T_f)e^{-t\ln2/T}$', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-012', 'b', 'L''image concrète (l''azote dissous comme le gaz d''un soda, remonter doucement et faire les paliers)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-012', 'c', 'Le calcul des M-values compartiment par compartiment', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-012', 'd', 'La démonstration du compartiment directeur avec toutes les périodes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-deco-013', 'mf1-decompression', 'mf1', 'tables-deco', 'qcm', 'le-problème-posé-par-la-désaturation', 'Pourquoi un bon modèle de décompression doit-il représenter **plusieurs compartiments** de vitesses différentes plutôt qu''un tissu unique ?', 'L''organisme n''est pas homogène : un tissu très vascularisé (sang, cerveau) sature et désature vite, un tissu peu irrigué (graisses, articulations) le fait lentement. Un modèle à compartiments multiples reproduit cette diversité et prédit, à chaque instant, si la remontée reste tolérable pour le tissu le plus contraignant.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-013', 'a', 'Parce que l''azote se dissout plus vite que l''oxygène', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-013', 'b', 'Parce que les tissus de l''organisme n''échangent pas l''azote à la même vitesse selon leur vascularisation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-013', 'c', 'Parce que la pression varie pendant la plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-deco-013', 'd', 'Parce que la température du corps n''est pas homogène', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-001', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'la-régulation-de-la-ventilation', 'Quel est le **stimulus principal** qui règle la ventilation via les centres respiratoires du tronc cérébral ?', 'Ce sont les chémorécepteurs centraux sensibles au CO₂ et au pH qui déclenchent l''augmentation de la ventilation dès que la $P_pCO_2$ s''élève ; l''oxygène n''est un stimulus déterminant qu''en hypoxie marquée. Cette hiérarchie explique l''essoufflement : c''est l''accumulation de CO₂, non le manque d''O₂, qui emballe la ventilation.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-001', 'a', 'La baisse de la pression partielle d''oxygène', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-001', 'b', 'L''élévation de la pression partielle de gaz carbonique (CO₂)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-001', 'c', 'La fréquence cardiaque', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-001', 'd', 'La température du sang', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-002', 'mf1-physiologie', 'mf1', 'physiologie', 'vrai-faux', 'la-régulation-de-la-ventilation', 'L''essoufflement du plongeur est d''abord un problème d''**inspiration** insuffisante ; le bon réflexe est donc d''inspirer plus fort et plus vite.', 'L''essoufflement est un problème d''**expiration** insuffisante : une ventilation superficielle ne renouvelle que l''espace mort et n''élimine plus assez de CO₂. Inspirer plus fort et plus vite aggrave la rétention de CO₂ et entretient le cercle vicieux ; la correction est de souffler longuement, ralentir, voire s''immobiliser et faire signe.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-002', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-002', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-003', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'circulation-shunts-et-foramen-ovale-perméable', 'Quel rôle le **poumon** joue-t-il vis-à-vis des micro-bulles d''azote formées au retour veineux pendant la décompression ?', 'Le filtre pulmonaire piège normalement les micro-bulles veineuses et permet d''éliminer l''azote par la ventilation ; tant qu''elles restent du côté veineux, elles sont le plus souvent silencieuses. C''est précisément ce filtre qu''un shunt droite-gauche (comme le foramen ovale perméable) court-circuite, faisant passer les bulles en artériel.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-003', 'a', 'Il les amplifie et les envoie vers le cerveau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-003', 'b', 'Il les filtre et permet leur élimination avant qu''elles ne gagnent la circulation artérielle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-003', 'c', 'Il n''a aucun effet sur les bulles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-003', 'd', 'Il les transforme en oxygène', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-004', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'circulation-shunts-et-foramen-ovale-perméable', 'Le **foramen ovale perméable (FOP)** est reconnu comme mécanisme d''accidents de désaturation immérités. Quelle proportion d''adultes est concernée par une perméabilité résiduelle, et par quel geste s''ouvre-t-il ?', 'Le FOP reste partiellement perméable chez environ un adulte sur quatre ; au repos il est fermé par la différence de pression entre oreillettes. Un effort à glotte fermée (Valsalva, port de charge, toux) inverse transitoirement le gradient et peut l''ouvrir, laissant passer des micro-bulles veineuses en artériel — d''où la consigne d''éviter tout effort violent après la plongée.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-004', 'a', 'Environ 1 adulte sur 4 ; un effort à glotte fermée (Valsalva, port de charge)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-004', 'b', 'Environ 1 adulte sur 100 ; un simple mouvement de palmage', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-004', 'c', 'La totalité des adultes ; l''expiration normale', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-004', 'd', 'Environ 1 adulte sur 4 ; il reste toujours ouvert au repos', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-005', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'le-système-nerveux-et-la-plongée', 'Quel est le mécanisme de la **narcose à l''azote** et sa caractéristique clé pour la conduite à tenir ?', 'La narcose résulte de l''action des gaz inertes dissous sur les membranes des cellules nerveuses, ralentissant la transmission synaptique ; elle apparaît au-delà de 30 m et s''aggrave avec la profondeur, le froid et le stress. Elle est **totalement réversible** : son danger tient au comportement inadapté qu''elle induit, d''où la consigne de remonter de quelques mètres au moindre signe.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-005', 'a', 'Une lésion définitive des neurones par les bulles ; irréversible', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-005', 'b', 'Une action des gaz inertes dissous sur les membranes nerveuses, ralentissant la transmission ; totalement réversible à la remontée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-005', 'c', 'Un manque d''oxygène au cerveau ; corrigé par l''apnée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-005', 'd', 'Une intoxication au CO₂ ; corrigée en accélérant la ventilation', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-006', 'mf1-physiologie', 'mf1', 'physiologie', 'vrai-faux', 'le-système-nerveux-et-la-plongée', 'Tout signe neurologique apparaissant après une plongée (trouble moteur, sensitif, visuel, vertige, confusion) doit être considéré comme une **urgence** jusqu''à preuve du contraire.', 'Le tissu nerveux récupère mal, ce qui rend tout signe neurologique post-plongée potentiellement grave : on ne « laisse pas passer » un symptôme. La conduite associe oxygène normobare à 100 %, alerte et surveillance, qu''il s''agisse d''un ADD neurologique ou d''une aéroembolie par surpression pulmonaire.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-006', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-006', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-007', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'loreille-interne-en-détail', 'Quelle structure de l''oreille contient la **cochlée** (audition) et le **vestibule** (équilibre), et communique avec l''oreille moyenne par les fenêtres ovale et ronde ?', 'La cochlée et le vestibule (avec ses canaux semi-circulaires) sont logés dans l''oreille interne, au sein du rocher, remplis de liquide. L''oreille moyenne, cavité aérienne équilibrée par la trompe d''Eustache, en est séparée par les deux fenêtres membraneuses ; c''est la rupture d''une de ces fenêtres qui provoque un barotraumatisme de l''oreille interne.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-007', 'a', 'L''oreille externe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-007', 'b', 'L''oreille moyenne', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-007', 'c', 'L''oreille interne', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-007', 'd', 'La trompe d''Eustache', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-008', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'loreille-interne-en-détail', 'Comment distinguer un **vertige alternobarique** d''un **accident de désaturation de l''oreille interne** ?', 'Le vertige alternobarique naît d''une trompe qui « passe » et l''autre non, créant un déséquilibre de pression entre les deux oreilles : il est barotraumatique et transitoire. L''ADD de l''oreille interne est d''origine bullaire (et non barotraumatique) et associe vertiges, acouphènes et surdité après une plongée avec décompression : distinguer les deux oriente l''urgence et la conduite à tenir.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-008', 'a', 'Le premier est d''origine bullaire, le second barotraumatique', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-008', 'b', 'Le premier vient d''un déséquilibre de pression entre les deux oreilles (barotraumatique, transitoire), le second est d''origine bullaire (désaturation)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-008', 'c', 'Les deux sont strictement identiques', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-008', 'd', 'Le premier survient uniquement à la descente, le second jamais en plongée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-009', 'mf1-physiologie', 'mf1', 'physiologie', 'vrai-faux', 'loreille-interne-en-détail', 'Un Valsalva trop violent sur une trompe d''Eustache bloquée peut provoquer une **rupture de fenêtre** (fistule périlymphatique) avec vertiges et surdité brutale, constituant une urgence ORL.', 'C''est un barotraumatisme de l''oreille interne : la surpression transmise par un Valsalva forcé sur une trompe bloquée peut rompre la fenêtre ovale ou ronde, provoquant une fistule périlymphatique. Le tableau associe vertiges et surdité brutale, ce qui en fait une urgence ORL ; d''où la consigne d''équilibrer tôt et doucement, sans jamais forcer.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-009', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-009', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-010', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'des-physiopathologies-au-message-pédagogique', 'Pour un moniteur, quelle traduction pédagogique correspond correctement à chaque notion physiologique ?', 'La valeur d''un moniteur est de relier mécanisme, prévention et geste : l''essoufflement renvoie à l''expiration, le FOP et l''ADD immérité aux efforts post-plongée et à l''humilité face aux tables, l''oreille à l''équilibrage précoce et au renoncement en cas de rhume. Les autres propositions inversent les consignes de sécurité (forcer le Valsalva, plonger enrhumé, attendre devant un signe neurologique) et sont dangereuses.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-010', 'a', 'Essoufflement → inspirer plus fort ; FOP → forcer le Valsalva après la plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-010', 'b', 'Essoufflement → expiration ample ; FOP/ADD immérité → pas d''effort après la plongée et humilité face aux tables ; oreille → équilibrage précoce', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-010', 'c', 'Narcose → accélérer la remontée sans limite ; oreille → plonger même enrhumé', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-010', 'd', 'ADD neurologique → attendre la disparition spontanée des signes', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-011', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'la-régulation-de-la-ventilation', 'Un phénomène d''**hypercapnie** en plongée peut être favorisé par :', 'L''hypercapnie (excès de CO₂) est favorisée par un espace mort ajouté — tuba trop long, mauvaise ventilation — ou par une rétention volontaire de CO₂ chez le « profond respirateur ». L''air dense en profondeur augmente aussi le travail respiratoire ; la prévention repose sur une ventilation ample et complète plutôt que superficielle.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-011', 'a', 'une expiration trop ample', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-011', 'b', 'un espace mort ajouté (tuba trop long) ou une rétention volontaire de CO₂', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-011', 'c', 'une descente trop lente', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-011', 'd', 'une hydratation excessive', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-physio-012', 'mf1-physiologie', 'mf1', 'physiologie', 'qcm', 'le-système-nerveux-et-la-plongée', 'La **surpression pulmonaire** peut provoquer un tableau neurologique brutal dès la sortie de l''eau. Par quel mécanisme ?', 'La surpression pulmonaire projette des bulles d''air dans la circulation, notamment cérébrale : c''est l''aéroembolie, responsable d''un tableau neurologique brutal survenant dès la sortie de l''eau. Le moniteur relie ce mécanisme à l''ADD neurologique par une même chaîne de secours : reconnaître vite, oxygène 100 % à 15 L/min, alerte et position adaptée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-012', 'a', 'Une accumulation de CO₂ dans les alvéoles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-012', 'b', 'Le passage de bulles d''air dans la circulation cérébrale (aéroembolie)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-012', 'c', 'Une narcose résiduelle à l''azote', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-physio-012', 'd', 'Un spasme des artères coronaires', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-001', 'mf1-physique-expert', 'mf1', 'physique', 'calcul', 'pression--la-confusion-fondatrice', 'Un élève affirme : « à 20 m, la pression est de 2 bars ». Quelle est la **pression absolue** réelle à 20 m, et quelle est l''erreur commise ?', 'La pression absolue vaut $P_{abs} = 1 + \frac{profondeur}{10} = 1 + \frac{20}{10} = 3$ bars. L''élève a donné les 2 bars **relatifs** (la seule colonne d''eau) en oubliant la pression atmosphérique : c''est la confusion relative/absolue, à l''origine de la majorité des erreurs de calcul. Tout calcul de gaz (Mariotte, Dalton, Henry) utilise l''absolue.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-001', 'a', '2 bars ; aucune erreur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-001', 'b', '3 bars ; l''élève a donné la pression relative au lieu de l''absolue', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-001', 'c', '2 bars ; il a oublié la pression relative', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-001', 'd', '1 bar ; il a confondu profondeur et pression', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-002', 'mf1-physique-expert', 'mf1', 'physique', 'qcm', 'pression--la-confusion-fondatrice', 'Comment démontre-t-on simplement la règle du « 1 bar par 10 m d''eau » ?', 'Une colonne de 10 m d''eau sur une base de 1 cm² pèse environ 1 kg, ce qui exerce une pression d''environ 1 bar : d''où l''ajout d''1 bar tous les 10 m. Cette démonstration par le poids d''eau est indépendante des lois des gaz et sert de socle concret pour introduire la notion de pression absolue en cours.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-002', 'a', 'Par la loi de Dalton sur les pressions partielles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-002', 'b', 'Par le poids d''une colonne d''eau : 10 m d''eau sur 1 cm² pèsent environ 1 kg, soit ≈ 1 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-002', 'c', 'Par la poussée d''Archimède', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-002', 'd', 'Par la compressibilité de l''air', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-003', 'mf1-physique-expert', 'mf1', 'physique', 'calcul', 'boyle-mariotte--démonstration-et-cas-limites', 'Quelle est la **capacité en air** (volume détendu à la pression atmosphérique) d''un bloc de 12 L gonflé à 200 bars, selon Boyle-Mariotte ?', 'La capacité est le produit volume × pression : $12 \times 200 = 2\,400$ L d''air ramené à 1 bar. On néglige ici la fraction déjà présente à 1 bar dans le bloc, convention d''enseignement usuelle ; le distracteur 1 200 L correspond à une pression de 100 bars, et 24 000 L à une erreur d''un facteur 10.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-003', 'a', '212 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-003', 'b', '1 200 L', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-003', 'c', '2 400 L', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-003', 'd', '24 000 L', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-004', 'mf1-physique-expert', 'mf1', 'physique', 'qcm', 'boyle-mariotte--démonstration-et-cas-limites', 'Selon Boyle-Mariotte, où la **détente volumique** d''une bulle d''air est-elle la plus importante, ce qui fonde la dangerosité de la surpression pulmonaire ?', 'De 10 m à la surface, la pression absolue est divisée par deux (2 bars → 1 bar), donc le volume double : la détente est maximale près de la surface. De 40 m à 30 m (5 bars → 4 bars), le volume ne varie que d''un quart. C''est pourquoi les derniers mètres sont les plus dangereux pour la surpression pulmonaire et qu''il faut y expirer et ralentir.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-004', 'a', 'Dans les derniers mètres, près de la surface', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-004', 'b', 'À la profondeur maximale', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-004', 'c', 'Entre 40 m et 30 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-004', 'd', 'Elle est identique à toute profondeur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-005', 'mf1-physique-expert', 'mf1', 'physique', 'vrai-faux', 'boyle-mariotte--démonstration-et-cas-limites', 'La loi de Boyle-Mariotte suppose une **température constante** ; un bloc gonflé qui chauffe verra donc sa pression lue à chaud surestimer le remplissage réel une fois refroidi.', 'Mariotte ($P_1V_1 = P_2V_2$) n''est valable qu''à température constante : le gonflage échauffe l''air, et la pression lue à chaud est plus élevée que celle observée après refroidissement. C''est un cas limite classique — oublier cette condition conduit à croire un bloc « plein » alors qu''il perdra de la pression en refroidissant.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-005', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-005', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-006', 'mf1-physique-expert', 'mf1', 'physique', 'calcul', 'dalton--pressions-partielles-et-démonstration', 'À 40 m ($P_{abs} = 5$ bars), avec de l''air ($F_{O_2} \approx 21\,\%$), quelle est la **pression partielle d''oxygène** $P_pO_2$ ?', 'On applique Dalton : $P_pO_2 = P_{abs} \times F_{O_2} = 5 \times 0{,}21 = 1{,}05$ bar. La valeur 0,21 bar correspond à la surface (1 bar), et 3,95 bars est la pression partielle d''azote ($5 \times 0{,}79$). On raisonne toujours sur la pression **absolue**, jamais la relative.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-006', 'a', '0,21 bar', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-006', 'b', '1,05 bar', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-006', 'c', '3,95 bars', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-006', 'd', '5 bars', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-007', 'mf1-physique-expert', 'mf1', 'physique', 'calcul', 'dalton--pressions-partielles-et-démonstration', 'En raisonnant par calcul inverse, à quelle **profondeur** l''oxygène de l''air atteint-il le seuil d''hyperoxie $P_pO_2 = 1{,}6$ bar ?', 'On cherche d''abord la pression absolue : $P_{abs} = 1{,}6 / 0{,}21 \approx 7{,}6$ bars, soit une profondeur de $(7{,}6 - 1) \times 10 \approx 66$ m. C''est ce calcul qui justifie la limite réglementaire de 60 m à l''air, avec une marge. Le distracteur 76 m oublie de retrancher la pression atmosphérique, et 30 m correspond au nitrox 40 %.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-007', 'a', 'environ 30 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-007', 'b', 'environ 66 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-007', 'c', 'environ 76 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-007', 'd', 'environ 160 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-008', 'mf1-physique-expert', 'mf1', 'physique', 'calcul', 'dalton--pressions-partielles-et-démonstration', 'Quelle est la **profondeur maximale d''utilisation (MOD)** d''un nitrox 40 % au seuil $P_pO_2 = 1{,}6$ bar ?', 'On calcule la pression absolue admissible : $P_{abs} = 1{,}6 / 0{,}40 = 4$ bars, soit une profondeur de $(4 - 1) \times 10 = 30$ m. Plus la fraction d''oxygène est élevée, plus la profondeur limite est faible : le nitrox 40 % ne dépasse pas 30 m au seuil de 1,6 bar. Le distracteur 66 m correspond à l''air, dont la fraction d''O₂ est bien plus basse.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-008', 'a', '20 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-008', 'b', '30 m', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-008', 'c', '40 m', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-008', 'd', '66 m', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-009', 'mf1-physique-expert', 'mf1', 'physique', 'qcm', 'henry--dissolution-saturation-gradient', 'Un élève croit que la dissolution de l''azote dans les tissus est **instantanée**. Quelle est la correction exacte à apporter ?', 'La loi de Henry décrit la quantité de gaz dissous **à l''équilibre**, proportionnelle à la pression partielle, mais ne dit rien de la vitesse pour l''atteindre. Cette vitesse dépend des tissus et fait l''objet du modèle de Haldane (compartiments, périodes) : confondre équilibre et cinétique est une erreur classique à corriger sur la cause, pas seulement sur le résultat.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-009', 'a', 'C''est vrai, Henry décrit une dissolution immédiate', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-009', 'b', 'Henry décrit l''état d''équilibre, pas la vitesse pour l''atteindre, qui dépend des tissus (modèle de Haldane)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-009', 'c', 'La dissolution ne dépend que de la température', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-009', 'd', 'L''azote ne se dissout pas dans les tissus', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-010', 'mf1-physique-expert', 'mf1', 'physique', 'vrai-faux', 'henry--dissolution-saturation-gradient', 'Le terme « sursaturation » signifie nécessairement qu''un accident de désaturation est en train de se produire.', 'La sursaturation est normale et tolérée dans une certaine limite : c''est même elle qui crée le gradient moteur de la désaturation à la remontée. C''est son **excès**, au-delà du coefficient critique, qui provoque la formation de bulles et l''accident ; assimiler sursaturation et accident est une confusion à lever.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-010', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-010', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-011', 'mf1-physique-expert', 'mf1', 'physique', 'qcm', 'archimède--démonstration-et-lestage', 'Pourquoi un plongeur en combinaison humide **s''alourdit-il en descendant**, ce qui impose d''ajuster le gilet ?', 'La poussée d''Archimède égale le poids du volume déplacé ; en descendant, la combinaison se comprime, son volume diminue, donc la poussée baisse et le plongeur devient plus lourd. Le poids réel ne change pas (seul le volume varie), d''où la nécessité d''ajouter de l''air au gilet en descendant et d''en retirer en remontant.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-011', 'a', 'Parce que l''eau devient plus dense en profondeur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-011', 'b', 'Parce que la combinaison se comprime : son volume diminue, la poussée d''Archimède baisse', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-011', 'c', 'Parce que son poids réel augmente avec la pression', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-011', 'd', 'Parce que l''azote dissous alourdit les tissus', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-012', 'mf1-physique-expert', 'mf1', 'physique', 'qcm', 'archimède--démonstration-et-lestage', 'Un objet a une masse de 15 kg et un volume de 5 L. Immergé en eau de mer (masse volumique ≈ 1,03 kg/L), son **poids apparent** est approximativement :', 'La poussée d''Archimède vaut le poids du volume d''eau déplacé : $5 \times 1{,}03 \approx 5{,}15$ kg. Le poids apparent est le poids réel moins la poussée : $15 - 5{,}15 \approx 9{,}85$ kg dans le sens du fond, donc l''objet coule. Confondre masse et poids, ou négliger la masse volumique de l''eau de mer, fausse ce type de calcul de lestage.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-012', 'a', 'négatif d''environ 9,85 kg (il coule)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-012', 'b', 'positif d''environ 5 kg (il flotte)', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-012', 'c', 'nul', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-012', 'd', 'négatif d''environ 15 kg', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-phys-013', 'mf1-physique-expert', 'mf1', 'physique', 'qcm', 'le-catalogue-des-erreurs-et-la-posture-du-moniteur', 'Face à un élève qui se trompe régulièrement en physique, quelle **posture** le moniteur adopte-t-il en priorité ?', 'L''approche diagnostique consiste à faire verbaliser le raisonnement pour localiser la faute, corriger sa **cause** (souvent une confusion conceptuelle comme relative/absolue) et non seulement le résultat, puis ancrer par un exercice de même famille. Un élève qui comprend pourquoi il s''est trompé ne refait pas l''erreur, contrairement à celui à qui l''on a seulement donné la bonne réponse.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-013', 'a', 'Donner directement la bonne réponse pour gagner du temps', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-013', 'b', 'Faire verbaliser le raisonnement de l''élève, corriger la cause (souvent conceptuelle) puis proposer un exercice de même famille', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-013', 'c', 'Multiplier les formules à mémoriser', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-phys-013', 'd', 'Changer de sujet pour éviter de le décourager', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-001', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'le-détendeur--rappel-du-principe-à-deux-étages', 'Dans un détendeur à deux étages, quel est le rôle du **premier étage** ?', 'Le premier étage, fixé au robinet, réduit la haute pression (200-300 bars) à une moyenne pression d''environ 8 à 12 bars au-dessus de l''ambiante. C''est le deuxième étage, tenu en bouche, qui délivre ensuite l''air à la pression ambiante exacte, à la demande, quand le plongeur inspire.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-001', 'a', 'Délivrer l''air à la pression ambiante, à la demande', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-001', 'b', 'Abaisser la haute pression du bloc à une moyenne pression (typiquement 8 à 12 bars au-dessus de l''ambiante)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-001', 'c', 'Mesurer la pression restante dans le bloc', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-001', 'd', 'Gonfler le gilet stabilisateur', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-002', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'détendeurs-compensés-et-surcompensés', 'Qu''apporte la **compensation** d''un premier étage de détendeur ?', 'Dans un premier étage compensé, la haute pression du bloc n''agit pas sur le clapet (surface équilibrée par un piston creux ou une chambre de compensation) : la moyenne pression reste constante que le bloc soit à 200 ou à 60 bars, donc le confort respiratoire ne se dégrade pas quand le bloc se vide. Un premier étage non compensé, lui, durcit l''inspiration à mesure que la pression chute.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-002', 'a', 'La moyenne pression reste constante quelle que soit la pression restante dans le bloc', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-002', 'b', 'Le bloc se vide plus lentement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-002', 'c', 'L''air délivré est plus chaud', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-002', 'd', 'La réserve mécanique se déclenche automatiquement', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-003', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'détendeurs-compensés-et-surcompensés', 'En quoi un détendeur **surcompensé** se distingue-t-il d''un simple détendeur compensé ?', 'Le surcompensé est agencé pour que la moyenne pression monte légèrement plus vite que la pression ambiante à la descente : la surpression disponible au deuxième étage est accrue en profondeur. Cela compense l''augmentation de densité de l''air (Mariotte) et facilite l''inspiration profonde, là où le travail respiratoire devient limitant.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-003', 'a', 'Il fonctionne sans premier étage', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-003', 'b', 'Sa moyenne pression augmente un peu plus vite que la pression ambiante en profondeur, facilitant l''inspiration là où l''air est le plus dense', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-003', 'c', 'Il supprime totalement le travail respiratoire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-003', 'd', 'Il n''a pas besoin d''être asservi à l''ambiante', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-004', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'le-givrage--mécanisme-et-prévention', 'Quel phénomène physique est à l''origine du **givrage** d''un détendeur en eau froide ?', 'La détente d''un gaz s''accompagne d''un refroidissement (effet Joule-Thomson) : au premier étage, la chute de plusieurs centaines de bars refroidit fortement le mécanisme, et en eau froide ce froid gèle l''humidité présente. Le givre peut alors bloquer le clapet, le plus souvent en position ouverte.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-004', 'a', 'La compression de l''air, qui le réchauffe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-004', 'b', 'La détente du gaz, qui refroidit le mécanisme (effet Joule-Thomson) et gèle l''humidité présente', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-004', 'c', 'La corrosion des pièces métalliques', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-004', 'd', 'L''électrolyse de l''eau de mer', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-005', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'le-givrage--mécanisme-et-prévention', 'Quand le givre bloque le clapet en position ouverte, le détendeur part en **débit continu**. Quelle est la conduite à tenir correcte ?', 'Le givrage produit une fuite continue d''air, pas une coupure : l''air reste respirable. Le réflexe correct est donc de garder l''embout, respirer sur le débit, signaler et remonter avec la palanquée en mettant fin à la plongée — éventuellement en fermant/rouvrant le robinet. C''est un incident géré, pas une privation d''air ; lâcher l''embout ou paniquer serait dangereux.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-005', 'a', 'Lâcher immédiatement l''embout et remonter seul en urgence', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-005', 'b', 'Garder le détendeur en bouche, respirer sur le débit, signaler et remonter avec la palanquée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-005', 'c', 'Fermer définitivement le robinet et rester au fond', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-005', 'd', 'Purger le deuxième étage jusqu''à vider le bloc', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-006', 'mf1-materiel-avance', 'mf1', 'materiel', 'vrai-faux', 'le-givrage--mécanisme-et-prévention', 'Pour prévenir le givrage, il faut utiliser un air sec et propre, employer des détendeurs spécifiés eau froide et éviter de purger inutilement le détendeur à sec par grand froid.', 'La prévention du givrage est multiple : air sec et propre (compresseur bien entretenu, filtres), détendeurs à membrane/chambres sèches spécifiés eau froide, et ne pas purger ni respirer le détendeur à l''air libre par grand froid. On évite aussi les débits importants prolongés, comme gonfler le gilet et inspirer profondément simultanément.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-006', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-006', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-007', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'les-recycleurs-notions', 'Dans un recycleur, comment est traité le **CO₂** du gaz expiré ?', 'Le recycleur recycle le gaz expiré : le CO₂ est capté par une cartouche de **chaux sodée**, tandis que l''oxygène consommé est réinjecté. Si la chaux est saturée ou mal montée, le CO₂ n''est plus absorbé, ce qui provoque une hypercapnie — l''un des risques spécifiques justifiant une formation dédiée.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-007', 'a', 'Il est rejeté sous forme de bulles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-007', 'b', 'Il est absorbé par une cartouche de chaux sodée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-007', 'c', 'Il est reconverti en oxygène par les cellules O₂', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-007', 'd', 'Il est comprimé dans une bouteille dédiée', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-008', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'les-recycleurs-notions', 'Quels sont les **risques spécifiques** d''un recycleur qui justifient une formation dédiée ?', 'Les recycleurs exposent à l''hypoxie ou l''hyperoxie en cas de défaillance de la régulation de l''oxygène, et à l''hypercapnie si la chaux sodée est saturée ou mal montée. S''y ajoutent la complexité technique et la dépendance à l''électronique. Le MF1 en retient le principe et les dangers, sans prétendre les enseigner : cette pratique relève de qualifications spécialisées.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-008', 'a', 'Uniquement le froid', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-008', 'b', 'Hypoxie ou hyperoxie si la régulation de l''O₂ défaille, et hypercapnie si la chaux est saturée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-008', 'c', 'Une autonomie réduite', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-008', 'd', 'L''impossibilité de plonger en eau douce', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-009', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'blocs-tiv-et-requalification--la-réglementation-précise', 'Qu''est-ce que le **TIV** dans la réglementation des blocs ?', 'Le TIV (Technicien d''Inspection Visuelle) est une inspection **visuelle annuelle**, organisée par la FFESSM et réalisée en club : on ouvre le bloc, on examine l''intérieur et l''extérieur (corrosion, chocs, col, robinet), et une pastille atteste l''inspection. L''épreuve hydraulique par organisme agréé relève, elle, de la requalification périodique, dispositif complémentaire et distinct.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-009', 'a', 'Une épreuve hydraulique réalisée par un organisme agréé', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-009', 'b', 'Une inspection visuelle annuelle réalisée par un technicien qualifié en club (FFESSM)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-009', 'c', 'Le marquage poinçonné du fabricant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-009', 'd', 'La pression de service de la bouteille', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-010', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'blocs-tiv-et-requalification--la-réglementation-précise', 'En quoi consiste la **requalification périodique** (anciennement « réépreuve hydraulique ») d''un bloc ?', 'La requalification est un contrôle **réglementaire** effectué par un organisme agréé : elle comprend une épreuve hydraulique (mise en pression à la pression d''épreuve, supérieure à la pression de service) et une inspection approfondie, avec poinçonnage de la date sur le col. Elle est complémentaire du TIV (inspection visuelle annuelle fédérale) ; un bloc hors date ne doit pas être gonflé.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-010', 'a', 'Un simple contrôle visuel annuel en club', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-010', 'b', 'Un contrôle réglementaire par un organisme agréé, incluant une épreuve hydraulique à la pression d''épreuve et une inspection approfondie', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-010', 'c', 'Le rinçage du bloc à l''eau douce', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-010', 'd', 'Le remplacement obligatoire du robinet', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-011', 'mf1-materiel-avance', 'mf1', 'materiel', 'vrai-faux', 'blocs-tiv-et-requalification--la-réglementation-précise', 'Il est recommandé de vider complètement un bloc après la plongée afin de préserver le robinet.', 'Au contraire, il ne faut **jamais** vider complètement un bloc : on garde une pression résiduelle pour empêcher l''entrée d''humidité et la corrosion interne. Le message d''entretien à transmettre inclut aussi le rinçage à l''eau douce, la révision périodique des détendeurs et la vérification des dates de validité (TIV et requalification).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-011', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-011', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-mat-012', 'mf1-materiel-avance', 'mf1', 'materiel', 'qcm', 'du-technique-au-pédagogique', 'Comment un moniteur adapte-t-il l''enseignement du matériel selon le public (un N2 par rapport à un futur N4) ?', 'La technicité n''a d''intérêt pédagogique que reliée à une consigne enseignable, adaptée au niveau : un N2 retient des messages simples (compensé = confort stable, bloc à jour de TIV), un futur N4 approfondit les mécanismes. Le moniteur maîtrise, lui, l''ensemble pour répondre à toute question et transmettre le bon geste, sans jamais faire l''impasse sur la sécurité.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-012', 'a', 'Il donne exactement le même niveau de détail à tous', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-012', 'b', 'Il retient l''essentiel pour un N2 (« détendeur compensé = confort stable », « bloc à jour de TIV ») et approfondit les mécanismes pour un futur N4, tout en maîtrisant lui-même l''ensemble', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-012', 'c', 'Il n''enseigne le matériel qu''aux futurs moniteurs', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-mat-012', 'd', 'Il évite les consignes de sécurité pour ne pas inquiéter', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-001', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'lorganisation-de-la-ffessm', 'Quel est le rôle de la **Commission Technique Nationale (CTN)** de la FFESSM ?', 'La CTN est au cœur de l''enseignement : elle définit les cursus, les contenus (le Manuel de Formation Technique), les prérogatives et les modalités d''examen. Son déclinaison régionale, la CTR, organise concrètement formations et examens et désigne les jurys ; l''aptitude médicale relève, elle, de la Commission Médicale et de Prévention (CMPN).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-001', 'a', 'Fixer uniquement les règles d''aptitude médicale', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-001', 'b', 'Définir les cursus, les contenus de formation (MFT), les prérogatives et les modalités d''examen des brevets', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-001', 'c', 'Organiser matériellement chaque examen dans les régions', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-001', 'd', 'Délivrer les licences aux clubs', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-002', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'lorganisation-de-la-ffessm', 'Qui organise concrètement les **examens de MF1 et de N4** à l''échelle d''un comité régional ?', 'C''est la Commission Technique Régionale (CTR) qui organise les formations et examens à l''échelle du comité régional et désigne les jurys, dont ceux de N4 et de MF1. La CTN définit le cadre national (cursus, contenus, prérogatives), mais la mise en œuvre concrète relève de la CTR.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-002', 'a', 'La CTN', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-002', 'b', 'La CTR (Commission Technique Régionale)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-002', 'c', 'La CMPN', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-002', 'd', 'Le club du candidat', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-003', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'vrai-faux', 'licence-certificat-médical-et-assurances', 'La licence fédérale inclut une assurance en **responsabilité civile** qui couvre les dommages que le licencié pourrait causer à autrui, mais pas les dommages qu''il subit lui-même.', 'La licence atteste l''affiliation et inclut une assurance en responsabilité civile couvrant les dommages causés à autrui. Elle ne couvre en revanche pas les dommages corporels subis par le plongeur lui-même ni l''assistance-rapatriement, qui relèvent d''une assurance individuelle accident complémentaire, vivement recommandée.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-003', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-003', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-004', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'licence-certificat-médical-et-assurances', 'Quels sont les **trois documents** indissociables du pratiquant, dont l''un est facultatif mais fortement recommandé ?', 'Le trio est : la licence (affiliation + responsabilité civile), le certificat médical de non-contre-indication (aptitude, règles CMPN) et — fortement recommandée mais facultative — une assurance individuelle accident couvrant les dommages subis par soi-même. La RC de la licence protège contre les dommages causés à autrui, pas ceux qu''on subit.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-004', 'a', 'Licence, carte de niveau, carnet de plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-004', 'b', 'Licence (affiliation + RC), certificat médical de non-contre-indication, et assurance individuelle accident (recommandée)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-004', 'c', 'Passeport, licence, contrat d''assurance habitation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-004', 'd', 'Certificat médical, TIV du bloc, carte d''identité', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-005', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'le-cadre-réglementaire-de-lenseignement', 'Le **MF1** est un diplôme fédéral. Quelle est sa principale limite en matière d''enseignement ?', 'Le MF1 est un diplôme **fédéral** : il autorise à enseigner et encadrer **bénévolement** dans le cadre associatif de la FFESSM, à préparer des candidats aux brevets et à participer aux jurys. Il ne permet pas, à lui seul, d''enseigner contre rémunération : cela exige un diplôme professionnel (BPJEPS, DEJEPS).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-005', 'a', 'Il ne permet pas de participer aux jurys', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-005', 'b', 'Il autorise l''enseignement bénévole en club mais pas, à lui seul, l''enseignement contre rémunération', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-005', 'c', 'Il n''autorise pas à préparer des candidats aux brevets', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-005', 'd', 'Il ne permet d''encadrer qu''en piscine', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-006', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'le-cadre-réglementaire-de-lenseignement', 'Quel est le rôle du **directeur de plongée** défini par le Code du sport ?', 'Le directeur de plongée est responsable de l''organisation et de la sécurité sur le site : il fixe les paramètres, veille au matériel obligatoire et aux moyens de secours (oxygène, plan de secours, moyen d''alerte). Le moniteur, souvent directeur de plongée en club, engage à ce titre sa responsabilité, d''où l''importance de respecter les procédures.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-006', 'a', 'Il délivre les licences', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-006', 'b', 'Il est responsable de l''organisation et de la sécurité sur le site de plongée', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-006', 'c', 'Il effectue le TIV des blocs', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-006', 'd', 'Il fixe les règles d''aptitude médicale', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-007', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'le-cadre-réglementaire-de-lenseignement', 'Sur le plan juridique, quelles responsabilités l''encadrant peut-il engager ?', 'L''encadrant engage une responsabilité **civile** (réparer un dommage causé) et peut engager une responsabilité **pénale** en cas de faute (mise en danger, blessure involontaire). C''est pourquoi le respect des procédures et la traçabilité de l''organisation sont essentiels ; la licence couvre la RC mais n''exonère jamais de la responsabilité pénale.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-007', 'a', 'Uniquement une responsabilité morale', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-007', 'b', 'Une responsabilité civile (réparer un dommage) et, en cas de faute, une responsabilité pénale', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-007', 'c', 'Aucune, la licence l''exonère de tout', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-007', 'd', 'Seulement une responsabilité pénale', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-008', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'lorganisation-des-examens-n4-et-mf1', 'Aux épreuves écrites du **Niveau 4 / Guide de Palanquée**, qu''appelle-t-on une note « éliminatoire » ?', 'Aux écrits du N4, chaque domaine est noté séparément et une note trop basse (typiquement en dessous de 5/20) est éliminatoire : elle fait échouer le candidat même si la moyenne générale est atteinte. C''est pourquoi le moniteur repère et travaille le domaine faible avant l''échéance, par des examens blancs dans les conditions réelles.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-008', 'a', 'Une note supérieure à la moyenne dans un domaine', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-008', 'b', 'Une note basse (typiquement en dessous de 5/20) dans un domaine, qui fait échouer malgré la moyenne', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-008', 'c', 'La note attribuée par le seul président du jury', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-008', 'd', 'Une note qui double automatiquement le score', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-009', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'lorganisation-des-examens-n4-et-mf1', 'Quelles épreuves sont **caractéristiques** de l''examen MF1, en plus des épreuves théoriques et techniques ?', 'Le MF1 est un examen de **cadre** centré sur les compétences pédagogiques : on y trouve une pédagogie préparatoire (préparer et conduire un cours théorique), une pédagogie pratique (conduire un atelier en milieu naturel) et une pédagogie organisationnelle, en plus des épreuves techniques et théoriques. La réussite atteste que le candidat sait préparer, conduire et évaluer un enseignement en sécurité.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-009', 'a', 'Uniquement un examen écrit de physique', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-009', 'b', 'Des épreuves pédagogiques en situation : pédagogie préparatoire, pratique et organisationnelle', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-009', 'c', 'Une épreuve de natation avec palmes seulement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-009', 'd', 'Un entretien sur la biologie marine', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-010', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'vrai-faux', 'lorganisation-des-examens-n4-et-mf1', 'Le jury d''un examen MF1 est composé de cadres (MF2, instructeurs), désignés par la CTR ou la CTN selon le niveau de l''examen.', 'Le jury du MF1 réunit des cadres de niveau supérieur — MF2, instructeurs — désignés par la CTR ou la CTN selon le niveau de l''examen. La composition exacte des épreuves et du jury est fixée par le Manuel de Formation Technique en vigueur, qui peut évoluer.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-010', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-010', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-011', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'cursus-fédéral-et-cursus-professionnel-notions', 'Pour enseigner la plongée **contre rémunération**, quel type de diplôme faut-il, à la différence du MF1 ?', 'Le MF1 est fédéral et bénévole ; l''enseignement rémunéré relève de diplômes d''État inscrits au Code du sport : le BPJEPS mention plongée subaquatique (premier niveau professionnel) puis le DEJEPS (niveau supérieur, prérogatives élargies). Des équivalences existent entre cursus fédéral et professionnel, définies par les textes.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-011', 'a', 'Un second MF1', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-011', 'b', 'Un diplôme professionnel d''État : BPJEPS puis, à un niveau supérieur, DEJEPS', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-011', 'c', 'Uniquement une licence à jour', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-011', 'd', 'Un certificat médical spécial', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-012', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'qcm', 'lorganisation-de-la-ffessm', 'Comment est structurée la FFESSM, de la base au sommet ?', 'La FFESSM, fédération délégataire, s''organise en clubs (associations) et structures commerciales agréées (SCA), regroupés en comités départementaux, puis régionaux (interdépartementaux), coiffés par le Comité directeur national. Les commissions thématiques (technique, médicale, biologie…) traversent cette structure ; la CTN et ses CTR pilotent l''enseignement.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-012', 'a', 'Clubs/SCA → Comités départementaux → Comités régionaux → Comité directeur national', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-012', 'b', 'Comité national → régions → clubs, sans échelon départemental', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-012', 'c', 'Uniquement des structures commerciales agréées', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-012', 'd', 'Clubs → CTN → CMPN', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-regl-013', 'mf1-reglementation-structures', 'mf1', 'reglementation', 'vrai-faux', 'cursus-fédéral-et-cursus-professionnel-notions', 'La voie fédérale bénévole conduit du MF1 au MF2 puis aux instructeurs, dans le cadre associatif.', 'La voie fédérale (bénévole) mène du MF1 au MF2 (moniteur fédéral 2ᵉ degré) puis aux instructeurs, au sein du cadre associatif. La voie professionnelle (rémunérée), distincte, repose sur le BPJEPS et le DEJEPS ; le MF1 doit expliquer clairement cette distinction aux élèves qui envisagent d''en faire leur métier.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-013', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-regl-013', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-001', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'analyser-la-tâche-avant-de-préparer', 'Par quoi commence la préparation d''un cours théorique, selon la pédagogie par objectifs ?', 'La préparation ne commence jamais par les supports mais par l''**analyse de la tâche** : à qui s''adresse-t-on (public, prérequis), quel contenu réel transmettre (ni trop, ni trop peu) et quelles difficultés anticiper. Cette analyse débouche sur une hiérarchisation — indispensable, utile, accessoire — qui rend le cours priorisé plutôt qu''exhaustif.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-001', 'a', 'Par la réalisation des diapositives', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-001', 'b', 'Par l''analyse de la tâche : public, prérequis, contenu délimité, difficultés attendues', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-001', 'c', 'Par le choix de la salle', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-001', 'd', 'Par la rédaction de l''examen final', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-002', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'vrai-faux', 'analyser-la-tâche-avant-de-préparer', 'Un bon cours doit être exhaustif : le moniteur y aborde tout ce qu''il sait sur le sujet.', 'Un bon cours n''est pas exhaustif, il est **priorisé** : l''analyse de la tâche débouche sur une hiérarchisation entre ce qui est indispensable, utile et accessoire. Vouloir tout dire provoque une surcharge cognitive ; le moniteur transmet l''essentiel dans le temps imparti et renvoie le reste à plus tard.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-002', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-002', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-003', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'formuler-des-objectifs-opérationnels', 'Quels sont les **trois éléments** d''un objectif opérationnel bien formulé ?', 'Un objectif opérationnel comporte une **performance** (verbe d''action observable : calculer, identifier…), une **condition** (le contexte : « à partir des tables MN90 ») et un **critère de réussite** (le niveau attendu : « sans erreur d''arrondi »). Ces trois éléments rendent l''objectif mesurable, ce qui permet de vérifier son atteinte par un exercice.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-003', 'a', 'Une accroche, un exemple, une synthèse', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-003', 'b', 'Une performance (verbe d''action observable), une condition (contexte) et un critère de réussite', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-003', 'c', 'Un titre, une durée, un support', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-003', 'd', 'Un prérequis, un contenu, une évaluation', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-004', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'formuler-des-objectifs-opérationnels', 'Quels verbes faut-il **bannir** dans la formulation d''un objectif opérationnel, car non observables ?', 'Les verbes « comprendre », « connaître », « savoir » désignent des états mentaux qu''on ne peut ni voir ni évaluer directement : ils sont à bannir. On leur préfère des verbes d''action observables — citer, calculer, expliquer, résoudre, distinguer, appliquer — dont on peut constater la réalisation par une tâche concrète.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-004', 'a', 'Calculer, citer, expliquer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-004', 'b', 'Comprendre, connaître, savoir', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-004', 'c', 'Résoudre, distinguer, appliquer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-004', 'd', 'Identifier, énoncer, corriger', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-005', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'formuler-des-objectifs-opérationnels', 'Parmi ces formulations, laquelle est un **objectif opérationnel** correct ?', 'Seule la proposition c est opérationnelle : elle énonce une performance (calculer la majoration), une condition (à partir des tables MN90) et un critère (sans erreur d''arrondi), ce qui la rend vérifiable par un exercice. Les autres reposent sur des verbes non observables (comprendre, connaître, être sensibilisé) qu''on ne peut pas évaluer objectivement.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-005', 'a', '« L''élève comprendra les plongées successives »', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-005', 'b', '« L''élève connaîtra les tables MN90 »', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-005', 'c', '« À l''issue de la séance, l''élève sera capable de calculer la majoration d''une successive à partir des tables MN90, sans erreur d''arrondi »', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-005', 'd', '« L''élève sera sensibilisé à la décompression »', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-006', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'structurer-la-séance--les-quatre-temps', 'Quelle est la structure en **quatre temps** d''une séance théorique efficace ?', 'La séance suit quatre temps : l''introduction (accroche, rappel des prérequis, annonce de l''objectif), le développement (du simple au complexe, apport + exemple + application), la synthèse (reformulation par les élèves, points clés, fiche) et l''évaluation (vérifier l''atteinte de l''objectif). Cette architecture crée l''intention d''apprendre puis vérifie l''acquisition.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-006', 'a', 'Accroche, monologue, questions, examen', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-006', 'b', 'Introduction, développement, synthèse, évaluation', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-006', 'c', 'Théorie, fosse, milieu naturel, débriefing', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-006', 'd', 'Prérequis, objectifs, supports, jury', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-007', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'vrai-faux', 'structurer-la-séance--les-quatre-temps', 'Dans le développement, il suffit que le moniteur expose clairement la matière ; l''application par l''élève peut être reportée à la toute fin de la séance.', 'Le développement n''est pas un déversement : un adulte décroche après quelques minutes d''écoute passive. Il faut rythmer par des questions et des applications toutes les cinq à dix minutes, en alternant apport et application, pour vérifier la compréhension **en continu** et non seulement à la fin.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-007', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-007', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-008', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'structurer-la-séance--les-quatre-temps', 'Quel est le rôle de l''**évaluation** dans la structure d''une séance théorique ?', 'En fin de séance, l''évaluation vérifie l''atteinte des objectifs par quelques questions, un exercice ou un QCM ; elle est ici **formative**, informant l''élève et le moniteur sur ce qui est acquis. Elle permet d''ajuster ou de reprendre un point avant de clore, et non de sanctionner : c''est un outil de régulation de l''apprentissage.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-008', 'a', 'Sanctionner et classer les élèves', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-008', 'b', 'Vérifier l''atteinte des objectifs de façon formative, pour ajuster ou reprendre un point mal compris', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-008', 'c', 'Occuper le temps restant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-008', 'd', 'Remplacer la synthèse', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-009', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'choisir-les-supports', 'Quelle est la règle d''or dans le choix d''un support pédagogique ?', 'Le support **sert** le message, il ne le remplace pas : il doit être lisible (peu de texte), porter un seul message, rester cohérent avec le discours et être manipulable quand c''est possible (vraies tables, détendeur démonté). On évite la diapositive surchargée qu''on lit au lieu de l''expliquer ; le meilleur support laisse à l''élève une trace (fiche, schéma).', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-009', 'a', 'Le support remplace le discours du moniteur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-009', 'b', 'Le support sert le message : lisible, un message par support, cohérent avec le discours, manipulable si possible', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-009', 'c', 'Plus un support est chargé, plus il est complet', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-009', 'd', 'Multiplier les effets visuels pour capter l''attention', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-010', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'choisir-les-supports', 'Pour enseigner un **mécanisme dynamique** (saturation, fonctionnement d''un détendeur), quel support est le plus adapté ?', 'Un mécanisme dynamique se prête à une animation simple ou à un tableau blanc construit **en direct** avec les élèves, car il suit le rythme du raisonnement. Un schéma ou une coupe conviennent mieux à l''anatomie ou au matériel, un tableau/profil aux tables : on choisit le support selon l''objectif, en gardant un message par support.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-010', 'a', 'Un long texte à lire', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-010', 'b', 'Une animation simple, ou un tableau construit en direct qui suit le rythme du raisonnement', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-010', 'c', 'Une seule photographie fixe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-010', 'd', 'Un tableau de chiffres', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-011', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'qcm', 'un-plan-de-cours-n2-complet', 'Dans le plan de cours N2 sur les successives, à quoi sert l''**accroche** de l''introduction (« Vous enchaînez deux plongées — pourquoi la seconde est-elle plus contraignante ? ») ?', 'L''accroche capte l''attention et motive : une question concrète crée l''intention d''apprendre, car un élève qui sait où il va et pourquoi apprend mieux. Elle précède le rappel des prérequis (l''azote résiduel reste dans les tissus) et l''annonce de l''objectif, complétant les trois fonctions de l''introduction.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-011', 'a', 'À évaluer les élèves d''emblée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-011', 'b', 'À capter l''attention et créer l''intention d''apprendre avant d''annoncer l''objectif', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-011', 'c', 'À remplir le temps d''installation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-011', 'd', 'À noter la participation', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedp-012', 'mf1-pedagogie-preparatoire', 'mf1', 'pedagogie', 'vrai-faux', 'un-plan-de-cours-n2-complet', 'Dans un plan de cours structuré, la synthèse doit faire **reformuler** l''essentiel par les élèves eux-mêmes, et pas seulement par le moniteur.', 'La synthèse récapitule l''essentiel en faisant reformuler par les élèves — pas seulement par le moniteur — ce qui vérifie et consolide l''acquisition. Elle dégage les points clés et la méthode, fournit un support de mémorisation (fiche, schéma) et relie la séance à la suivante ; dans le plan N2, les élèves reformulent la méthode en quatre étapes.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-012', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedp-012', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-001', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'décomposer-le-geste--la-notion-déducatif', 'Qu''est-ce qu''un **éducatif** en pédagogie pratique ?', 'Un éducatif est un exercice intermédiaire qui isole une **composante** du geste, la fait maîtriser, puis on assemble. On construit ainsi une progression du plus simple au geste complet, en validant chaque étape avant la suivante : décomposer rend franchissable ce qui paraissait impossible.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-001', 'a', 'Le geste technique complet réalisé d''emblée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-001', 'b', 'Un exercice intermédiaire qui isole une composante du geste et la fait réussir avant de passer à la suivante', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-001', 'c', 'Une évaluation certificative', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-001', 'd', 'Un briefing de sécurité en surface', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-002', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'vrai-faux', 'décomposer-le-geste--la-notion-déducatif', 'On peut demander un vidage de masque complet à un élève qui n''accepte pas encore l''eau sur le visage, pour le mettre plus vite en situation.', 'La règle d''or est un éducatif à la fois, du plus facile au plus complet, en validant chaque étape : on ne demande jamais un vidage complet à un élève qui n''accepte pas encore l''eau sur le visage. Brûler les étapes expose à l''échec et à la panique ; la progressivité conditionne la réussite et la sécurité.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-002', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-002', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-003', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'des-critères-de-réussite-observables', 'Qu''est-ce qui distingue un bon **critère de réussite** observable ?', 'Un bon critère est directement **observable** par l''encadrant, binaire ou quasi-binaire (réussi / non réussi) et relié à l''objectif de l''éducatif ; « L''élève est à l''aise » n''en est pas un, car ce n''est pas observable. « Il garde le détendeur en bouche et expire des bulles pendant que l''eau entre » en est un : on le définit à l''avance pour éviter de juger « au ressenti ».', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-003', 'a', '« L''élève est à l''aise »', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-003', 'b', 'Un fait visible et objectif, binaire ou quasi-binaire, relié à l''objectif de l''éducatif', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-003', 'c', 'L''impression générale du moniteur', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-003', 'd', 'Le ressenti déclaré par l''élève', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-004', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'la-progression-complète-du-vidage-de-masque', 'Dans la progression du vidage de masque, quel est le geste **moteur clé** enseigné à l''étape 3 ?', 'Le geste moteur clé est l''expiration nasale franche et continue, tête légèrement en arrière, avec appui sur le **haut** de la jupe du masque : c''est ce qui chasse l''eau. Inspirer par le nez ferait entrer l''eau et provoquerait une fausse route ; on peut d''abord entraîner ce geste masque vide avant de l''appliquer masque rempli.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-004', 'a', 'Retirer complètement le masque', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-004', 'b', 'Expirer par le nez, tête légèrement en arrière, en appuyant sur le haut du masque', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-004', 'c', 'Inspirer par le nez pour chasser l''eau', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-004', 'd', 'Retenir sa respiration', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-005', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'diagnostiquer-et-remédier-aux-difficultés-types', 'Un élève **inspire par le nez** au lieu d''expirer pendant le vidage de masque et avale de l''eau. Quelle remédiation est adaptée ?', 'La cause est souvent la panique : la remédiation consiste à revenir à l''étape 3 masque vide, faire sentir la différence entre inspirer et expirer par le nez, ralentir et rassurer. On agit sur la **cause**, pas en répétant la consigne ; insister ou augmenter la difficulté aggraverait la gêne et le risque.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-005', 'a', 'Insister pour qu''il recommence immédiatement le vidage complet', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-005', 'b', 'Revenir à l''étape 3 masque vide, faire sentir la différence inspiration/expiration nasale, ralentir et rassurer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-005', 'c', 'Augmenter la profondeur de travail', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-005', 'd', 'Lui demander de retenir sa respiration plus longtemps', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-006', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'diagnostiquer-et-remédier-aux-difficultés-types', 'Le masque d''un élève **ne se vide pas** malgré une expiration nasale. Quelle est la cause la plus probable et la remédiation ?', 'Si l''expiration est correcte mais que le masque ne se vide pas, l''eau rentre par le haut faute d''appui : la remédiation est de corriger la position (tête en arrière, appui sur le **haut** de la jupe) et de montrer où presser. Le diagnostic porte sur le geste, pas sur le matériel ni sur la ventilation ; on identifie pourquoi ça ne marche pas avant d''agir.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-006', 'a', 'Il souffle trop fort ; lui demander de souffler moins', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-006', 'b', 'Mauvais appui : l''eau rentre par le haut ; corriger la position (tête en arrière, appui sur le haut de la jupe)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-006', 'c', 'Le masque est défectueux ; le remplacer systématiquement', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-006', 'd', 'Il manque d''air ; remonter en urgence', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-007', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'vrai-faux', 'diagnostiquer-et-remédier-aux-difficultés-types', 'Face à un élève en blocage psychologique sur un exercice aquatique, la bonne réponse est d''insister fermement pour qu''il surmonte sa peur le jour même.', 'Il ne faut **jamais** forcer un élève en blocage : un élève contraint peut paniquer, remonter en catastrophe (risque de surpression pulmonaire) ou développer une aversion durable. La bonne réponse est de **redescendre d''une étape**, dédramatiser, progresser lentement et valoriser chaque micro-progrès ; la sécurité prime toujours sur la progression du jour.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-007', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-007', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-008', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'la-progression-complète-du-vidage-de-masque', 'Quel cycle le moniteur applique-t-il à chaque étape d''un apprentissage moteur en milieu naturel ?', 'Le cycle est : démontrer le geste (l''élève voit ce qu''on attend), faire exécuter, observer le critère de réussite, puis corriger. En plongée on ne parle pas : la communication est gestuelle et se prépare en surface au briefing ; une démonstration muette bien placée vaut mieux qu''une longue explication.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-008', 'a', 'Expliquer longuement, puis évaluer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-008', 'b', 'Démontrer → faire faire → observer le critère → corriger', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-008', 'c', 'Noter → classer → sanctionner', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-008', 'd', 'Faire faire → attendre → recommencer sans correction', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-009', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'sécurité-et-organisation-de-latelier', 'Sous l''eau, comment le moniteur doit-il se **placer** pendant un atelier ?', 'Le placement de l''encadrant est décisif : il se positionne pour voir **tous** ses élèves, à portée d''intervention immédiate de celui qui travaille, sans jamais tourner le dos aux autres. Il maîtrise la profondeur, surveille l''air et le temps, et garde la capacité de stopper l''atelier à tout moment : ce sont des compétences pédagogiques évaluées à l''examen.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-009', 'a', 'Derrière le groupe, pour surveiller les retardataires', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-009', 'b', 'De façon à voir tous ses élèves, à portée d''intervention immédiate de celui qui travaille, sans tourner le dos aux autres', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-009', 'c', 'Au fond, à distance, pour laisser de l''autonomie', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-009', 'd', 'En surface, en observant depuis le bateau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-010', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'sécurité-et-organisation-de-latelier', 'Pourquoi travaille-t-on les **gestes anxiogènes** (vidage de masque, lâcher d''embout) d''abord à faible profondeur ?', 'On travaille les gestes anxiogènes à faible profondeur d''abord parce qu''une remontée y reste possible sans danger si l''élève panique. Cela réduit le risque de surpression pulmonaire lié à une remontée réflexe ; on augmente la profondeur seulement une fois le geste maîtrisé et l''élève en confiance.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-010', 'a', 'Pour économiser l''air', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-010', 'b', 'Parce qu''une remontée reste possible sans danger si l''élève panique', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-010', 'c', 'Parce que la visibilité y est meilleure', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-010', 'd', 'Parce que la réglementation l''impose à tout niveau', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-011', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'vrai-faux', 'sécurité-et-organisation-de-latelier', 'L''effectif d''un atelier en milieu naturel doit rester compatible à la fois avec la capacité de surveillance du moniteur et avec les prérogatives réglementaires d''encadrement.', 'Le nombre d''élèves d''un atelier doit être compatible avec la capacité de surveillance de l''encadrant **et** avec les prérogatives réglementaires d''encadrement. Le moniteur choisit aussi un site adapté (profondeur maîtrisée, fond visible, à l''abri du courant) et fait un briefing clair : sécurité, placement et communication sont des compétences pédagogiques à part entière.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-011', 'a', 'Vrai', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-011', 'b', 'Faux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedpra-012', 'mf1-pedagogie-pratique', 'mf1', 'pedagogie', 'qcm', 'diagnostiquer-et-remédier-aux-difficultés-types', 'Quelle est la posture générale de **remédiation** attendue d''un moniteur face à l''échec d''un élève ?', 'La remédiation est bienveillante et **diagnostique** : on identifie pourquoi ça ne marche pas, on agit sur la cause et l''on revient en arrière sans dramatiser. Répéter la même consigne ne corrige pas la cause ; forcer un élève en difficulté est contre-productif et dangereux, la progressivité est la clé.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-012', 'a', 'Répéter la consigne à l''identique, plus fort', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-012', 'b', 'Diagnostiquer pourquoi ça ne marche pas, agir sur la cause, revenir en arrière sans dramatiser', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-012', 'c', 'Passer immédiatement à l''élève suivant', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedpra-012', 'd', 'Retirer l''élève de la formation', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-001', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'organiser-une-formation-sur-une-saison', 'Comment planifie-t-on une formation de niveau sur une saison, selon le principe exposé ?', 'On planifie **à rebours** : on part des objectifs de fin de formation (les prérogatives du niveau visé), qu''on décompose en séances successives du simple au complexe en respectant les prérequis. On articule les trois milieux (théorie, fosse, milieu naturel), on garde des marges pour rattrapages et météo, et on ajuste grâce à un suivi régulier des acquis.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-001', 'a', 'En improvisant séance après séance', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-001', 'b', 'À rebours : partir des prérogatives visées, décomposer en séances respectant les prérequis, articuler théorie/fosse/milieu naturel', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-001', 'c', 'En commençant par l''autonomie avant les fondamentaux', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-001', 'd', 'En traitant toute la théorie avant toute pratique', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-002', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'vrai-faux', 'organiser-une-formation-sur-une-saison', 'Une progression de formation, une fois établie, ne doit plus être modifiée en cours de saison.', 'Une progression n''est jamais figée : on évalue régulièrement pour ajuster au rythme réel du groupe. Le moniteur tient un suivi de chaque élève (acquis, points à retravailler) qui guide la suite, et garde des marges pour les rattrapages et les aléas météo.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-002', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-002', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-003', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'gérer-un-groupe-hétérogène', 'Qu''est-ce que la **différenciation pédagogique** face à un groupe hétérogène ?', 'La différenciation adapte l''enseignement à la diversité des élèves : varier les modalités, proposer des tâches de difficulté graduée, constituer des sous-groupes ou favoriser le tutorat entre pairs, ajuster le temps. Caler le cours sur le plus lent ennuie les autres, le caler sur le plus rapide en fait décrocher : on vise l''essentiel commun puis on différencie les approfondissements.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-003', 'a', 'Caler le cours sur l''élève le plus lent', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-003', 'b', 'Adapter l''enseignement à la diversité des niveaux et rythmes sans laisser personne de côté ni freiner les plus rapides', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-003', 'c', 'Exclure les élèves les plus faibles', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-003', 'd', 'Ne s''adresser qu''aux plus rapides', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-004', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'gérer-un-groupe-hétérogène', 'Comment le moniteur entretient-il la **motivation** des élèves les plus fragiles dans un groupe hétérogène ?', 'Le moniteur valorise les progrès de chacun **par rapport à lui-même**, et non par comparaison au groupe, ce qui entretient la motivation des plus fragiles. Comparer au meilleur découragerait ; gérer l''hétérogénéité est une compétence de moniteur à part entière, souvent révélatrice de sa maîtrise pédagogique.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-004', 'a', 'En comparant chacun au meilleur du groupe', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-004', 'b', 'En valorisant les progrès de chacun par rapport à lui-même, non par comparaison au groupe', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-004', 'c', 'En supprimant toute évaluation', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-004', 'd', 'En accélérant le rythme pour tous', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-005', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'trois-fonctions-de-lévaluation', 'Quelle est la fonction de l''**évaluation formative** ?', 'L''évaluation formative a lieu **pendant** l''apprentissage : elle informe l''élève et le moniteur sur ce qui est acquis et ce qui reste à travailler, pour réguler la progression. Elle n''est pas sanctionnante — c''est un outil d''apprentissage (exercice corrigé ensemble, question en séance) — et c''est la plus utile au quotidien.', 1);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-005', 'a', 'Délivrer un brevet officiel', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-005', 'b', 'Informer élève et moniteur pendant l''apprentissage sur ce qui est acquis, pour réguler la progression, sans sanctionner', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-005', 'c', 'Faire le bilan final d''une séquence', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-005', 'd', 'Classer les élèves entre eux', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-006', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'trois-fonctions-de-lévaluation', 'Comment distingue-t-on l''évaluation **sommative** de l''évaluation **certificative** ?', 'L''évaluation sommative fait le **bilan** d''une séquence (test de fin de module, examen blanc) et situe l''élève par rapport aux objectifs. L''évaluation certificative est une sommative particulière qui **délivre un brevet** : c''est l''examen officiel, avec jury, barème et note éliminatoire, où le moniteur engage sa responsabilité de certificateur.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-006', 'a', 'Elles sont identiques', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-006', 'b', 'La sommative fait le bilan d''une séquence ; la certificative est une sommative particulière qui délivre un brevet ou une qualification', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-006', 'c', 'La sommative délivre le brevet, la certificative régule l''apprentissage', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-006', 'd', 'La certificative n''a pas de barème', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-007', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'la-taxonomie-de-bloom-appliquée', 'La **taxonomie de Bloom** hiérarchise les opérations mentales du plus simple au plus complexe. Quel est l''ordre correct ?', 'La taxonomie de Bloom va du plus simple au plus complexe : mémoriser (restituer), comprendre (expliquer avec ses mots), appliquer (utiliser une règle), analyser (décomposer, distinguer), évaluer (juger, critiquer), créer (produire du nouveau). Cet ordre sert à calibrer objectifs et questions au bon niveau cognitif.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-007', 'a', 'Créer → évaluer → analyser → appliquer → comprendre → mémoriser', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-007', 'b', 'Mémoriser → comprendre → appliquer → analyser → évaluer → créer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-007', 'c', 'Comprendre → mémoriser → créer → appliquer → analyser → évaluer', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-007', 'd', 'Appliquer → mémoriser → comprendre → créer → analyser → évaluer', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-008', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'la-taxonomie-de-bloom-appliquée', 'En appliquant Bloom, à quel niveau cognitif situe-t-on typiquement les objectifs d''un **N1**, et à quel niveau ceux d''un **MF1** ?', 'Un N1 se situe surtout sur mémoriser/comprendre/appliquer (citer les barotraumatismes, expliquer l''équilibrage, appliquer une consigne), un N4 monte vers analyser et évaluer, et un MF1 va jusqu''à **créer** (concevoir une séance). Calibrer le niveau évite de demander à un débutant une opération mentale hors de portée ou de sous-évaluer un cadre.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-008', 'a', 'N1 : créer ; MF1 : mémoriser', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-008', 'b', 'N1 : surtout mémoriser/comprendre/appliquer ; MF1 : jusqu''à créer (concevoir une séance)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-008', 'c', 'N1 et MF1 : uniquement mémoriser', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-008', 'd', 'N1 : évaluer ; MF1 : appliquer', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-009', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'grilles-dévaluation-et-biais', 'Quel est l''intérêt d''une **grille d''évaluation** construite à partir de critères observables ?', 'Une grille liste les critères attendus, chacun observable, avec un barème ou des niveaux de maîtrise : elle rend l''évaluation transparente (l''élève sait ce qui est attendu), reproductible (deux évaluateurs aboutissent au même résultat) et juste (on évalue les mêmes choses pour tous). Elle découle directement des objectifs opérationnels et de leurs critères de réussite.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-009', 'a', 'Elle accélère la notation sans justification', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-009', 'b', 'Elle rend l''évaluation transparente, reproductible et juste (deux évaluateurs aboutissent au même résultat)', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-009', 'c', 'Elle permet de noter au ressenti', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-009', 'd', 'Elle dispense de définir des objectifs', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-010', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'grilles-dévaluation-et-biais', 'Un examinateur laisse une bonne impression générale sur un candidat déteindre sur tous les critères qu''il évalue. De quel **biais** s''agit-il, et quel est le remède ?', 'C''est l''**effet de halo** : une impression générale (bonne ou mauvaise) déteint sur l''ensemble des critères. Le remède est d''évaluer chaque critère **séparément**, en revenant à la grille. Les autres biais (contraste, complaisance/sévérité, stéréotype, ordre/fatigue) appellent leurs propres remèdes : retour à la grille, étalonnage, faits observables, pauses.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-010', 'a', 'Effet de contraste ; changer de candidat', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-010', 'b', 'Effet de halo ; évaluer chaque critère séparément', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-010', 'c', 'Effet de fatigue ; faire une pause', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-010', 'd', 'Biais de stéréotype ; s''étalonner', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-011', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'vrai-faux', 'grilles-dévaluation-et-biais', 'Lors d''une évaluation certificative, la bienveillance peut justifier de délivrer le brevet à un candidat qui ne maîtrise pas encore toutes ses prérogatives.', 'Une évaluation certificative engage la **sécurité** : délivrer un brevet à un candidat qui ne maîtrise pas ses prérogatives, c''est l''autoriser à se mettre en danger. La bienveillance ne doit jamais conduire à la complaisance ; on s''en tient aux critères et aux faits observables, avec la grille comme garde-fou contre les biais.', 2);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-011', 'a', 'Vrai', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-011', 'b', 'Faux', true);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-012', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'trois-fonctions-de-lévaluation', 'Une même notion de tables peut être évaluée aux trois fonctions. Laquelle correspond à l''**épreuve de tables de l''examen N4** ?', 'L''épreuve de tables de l''examen N4 est **certificative** : elle participe à la délivrance du brevet. La même notion peut être évaluée en formative (exercice corrigé en séance pour voir où en est l''élève) et en sommative (test de validation du module) : le moniteur choisit la fonction selon son intention — réguler, faire le bilan ou certifier.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-012', 'a', 'Formative', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-012', 'b', 'Sommative simple de module', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-012', 'c', 'Certificative', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-012', 'd', 'Aucune, ce n''est pas une évaluation', false);
insert into public.questions (id, module_slug, level_slug, domain, question_type, section_anchor, prompt, explanation, difficulty) values ('mf1-pedo-013', 'mf1-pedagogie-organisation', 'mf1', 'pedagogie', 'qcm', 'synthèse--le-moniteur-organisateur-et-évaluateur', 'Selon la synthèse du module, qu''est-ce qui définit avant tout le moniteur ?', 'Le moniteur ne se contente pas de préparer et conduire une séance : il inscrit son enseignement dans la durée (progression, suivi, différenciation) et le valide avec rigueur (fonctions d''évaluation, taxonomie, grilles, vigilance aux biais). C''est cette **cohérence d''ensemble** — rendre l''élève capable de pratiquer en sécurité et pouvoir le démontrer objectivement — plus qu''une épreuve isolée, qui le définit.', 3);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-013', 'a', 'La performance sur une épreuve isolée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-013', 'b', 'La cohérence d''ensemble : préparer, conduire, organiser et évaluer pour rendre l''élève capable de pratiquer en sécurité et pouvoir le démontrer', true);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-013', 'c', 'Le seul niveau technique en plongée', false);
insert into public.question_options (question_id, option_id, option_text, is_correct) values ('mf1-pedo-013', 'd', 'La quantité de connaissances théoriques accumulées', false);
